// main/fa_view.c —— 《去远方》界面实现
//
// 版面（竖屏 240x320，从上到下）：
//
//   0 ..  26   三叶草 / 电量 / 校时点 —— **没有底色条**，直接压在底图的天空上
//  26 .. 292   场景 —— 两种形态二选一，见下面「主页面风景」那一节：
//               【家】一整幅 240x320 的底图 fa_res_home（素材侧 agent="scene-bg"，
//                     1:1 铺满不缩放），猫叠在上面；
//               【别处的风景】那张 176x220 的明信片放大到 1.5 倍铺满整屏，
//                     家的底图和猫**一起收起来**（见 cat_sync）。
//  292 .. 320   时长选择器（5 档 + 「收集」，一共 6 格）
//
// ★ 2026-09-19（第五次）用户逐条提的，全部落地：
//   ① 首页底图换成**像素-白天**那张（红瓦白墙 + 树 + 栅栏花圃），并加太阳与云。
//      ★ 那张画里**自己就画着那栋房子**，所以素材里那个独立的精灵小屋
//        （fa_res_house）整条下线 —— 再叠一个精灵就是两栋房子重影。
//      同时下线的还有它旁边那 13 件「小院道具」（见下条）。
//   ② 「布置小院」连同 13 件道具**整块删除**：收集册里没有入口、代码里没有模式、
//      图集里也没有那 14 张图。这是用户明确要求的减法，不是「先藏起来」。
//   ③ 顶栏那条不透明的状态条删了 —— 三叶草、电量、校时点直接压在天空上。
//      配套：旅行遮罩压上去时这三处文字自动换成暖白（否则深灰字糊在暗膜里）。
//   ④ 收集册从此**只有两样东西**：明信片 + 家。家被当成「第一张明信片」，
//      排在序列最前面，和明信片一起上下翻。一个页面、一套键位 ——
//      没有菜单页、没有纪念品合集页、也没有那五块程序化兜底色块。
//   ⑤ 本档明信片全拿到之后再出行，不再只给一句「又见旧地」——
//      照样抽一张本档**已有过**的明信片，把画面显示出来
//      （见 fa_game.c 的 fa_finish 与下面的 card_fill）。
//
// ★ 2026-09-19（第四次）这一版是**大改版**，用户逐条提的：
//   ① 首页不再用色块搭 —— 换成一张真渲染的整图（「不要再用色块了，类似明信片的
//      风格」）。原来那套 sky/sun/cloud/hill/farbank/tree/river/ripple/nearbank/
//      nearedge/grass/bush 十二组对象全删，见 build_scene()。
//   ② 风景回到**铺满整屏**（第三次曾经退成「挂一张小画」，见下面的历史）。
//      配套的两个后果都按用户的说法处理掉了：
//        · 「换成别的明信片时，去掉动态小猫」→ 猫只在「风景 = 家」时出面；
//        · 顺手把小屋和小院道具也一起收起来 —— 它们和猫一样是「家」的东西，
//          留在别人家的风景上就是一层贴纸。
//          ★ 第五次起，这一条里「小屋」和「小院道具」两样都整体下线了，
//            这条判据下**只剩猫**（cat_sync 的注释也同步改过）。
//   ③ 旅行中**不再换夜景**，只压一层半透明遮罩。N_* 那 14 个夜色常量、
//      以及那套「每个地景都要配一个夜间色」的对应关系全部删除，见 travel_mask()。
//   ④ 收集册重做：
//        · 末尾两格从「布置小院 / 更换风景」换成「家 / 纪念品」；
//        · 「更换风景」改成**在明信片页上长按 ●** —— 看着哪张就往家里换哪张；
//        · 「布置小院」挪进「家」那一页（那里是「家」的菜单：回家 / 布置小院 / 返回）；
//        · 纪念品不再一件一件翻，改成**一页合集**（12 格小图 + 名字）。
//   ⑤ 明信片页的键位定死：↑/↓ 翻动、**短按 ● 返回**、**长按 ● 换为主页风景**。
//
// ★ 2026-09-19（第三次）这一版的改动（用户实机截图逐条提的）：
//   ① 「下面那条绿色」—— 那不是贴图错误，是底栏的**草地底衬**（bar_under）。
//      底栏在出发/归来/旅行中会整条收起，收起之后露出的就是它。程序化场景下它
//      和近岸草地同色，看不见；可风景一旦**铺满整屏**，它就在照片上压出一条
//      毫不相干的平直绿带。→ 第四次改版把底栏底衬整个删掉了：底图自己铺到
//      屏幕最下沿，底栏收起来时露出来的就是它，不需要再垫一层。
//   ② 「背景加小猫有俩猫」—— 明信片那 24 张画**里本来就画着一只猫**
//      （「小猫替你去了远方，寄张明信片回来」），放大铺满之后，画里那只猫
//      和我们的主角猫同框，一眼就是「俩猫」。
//      第三次的解法是把风景缩成墙角一张小画；第四次用户重新要求铺满，
//      于是改用另一个解法：**换风景之后我们的猫就不出面了**（见 cat_sync）。
//   ③ 收集册里的纪念品**显示不出图** → 接上 souvenir_a 那套 12 件图标，
//      并把 SOUV_NAME 改成画上真正画的东西（见 fa_game.c）。
//   ④ 电量那一格：标签宽度不够 + 失败后**永久关掉**（读一次没读到就再也不读了）。
//      见 build_hud() 和 fa_view_tick() 里的说明。
//
// ★ 2026-09-19（第二次）这一版的改动：
//   ① 收集册末尾从一格变两格：「布置小院」（0xFD）+「更换风景」（0xFC）；
//   ② 新增**布置模式** —— 把解锁的场景道具摆进小院的 4 个位置。
//      这是一个**不上盖板**的模式：收集册一关，直接在主页画面上操作，
//      按一下就能看见东西落地（所以它不能用收集册那种整屏白卡来承载）。
//      见下面「小院（摆放）」那一节。
//      ★ 第五次改版把这一整块**删除**（用户原话「去掉道具及布置家的这个功能」）——
//        下面那一节已经不存在了，这一条只作历史留档。
//
// ★ 2026-09-19 这一版的改动（用户逐条提的）：
//   ① 去掉屏幕亮度调整格 —— 收集册从此没有任何「设置」，只剩「看」和「换风景」；
//   ② 收藏册末尾那一格从「指定下一站」改成**「更换风景」**：
//      主页和旅行页的背景可以换成任何一个**去过**的地方；
//   ③ 主页那个程序化的方块小屋换成素材里的真房子（fa_res_house，茅草顶 + 暖黄窗）。
//      ★ 第五次这间精灵屋也下线了 —— 新底图画里自带房子（见上面的第五次说明）。
//
// ★ 2026-09-17 这一版把「上轻下重」扳回来：
//   实机反馈「整体偏向左下、上面的水系和远方占地方太多、小屋和猫要往上、
//   远山要高、水要变成小溪、对比要强、底栏要大字」。
//   这一版的构图数字（天空 52 / 远山 54 / 远岸 20 / 溪 18 / 近岸 124）在第四次
//   改版之后已经不作数了 —— 那张底图是按「天空 0~83 / 远山 84~160 / 远岸 144~162 /
//   小溪 164~173 / 草地 174~320」画的，正好和版面常量对得上，所以
//   屋子(188~272)、猫(200~264)、四个落地点(68/150/258) 一个数都没动。
//
// 性能纪律（C3 无 PSRAM，只有内部 SRAM）：
//   * 每个实体都是定长对象，创建一次，之后只改属性，绝不销毁重建；
//   * 文本**变了才** lv_label_set_text —— 每帧无条件 set 会让 LVGL 反复重排，
//     实测在无 PSRAM 的 C3 上会明显掉帧；
//   * 进度条用两条纯色矩形，不用 lv_bar（省掉每帧一次主题样式解析）；
//   * 全屏遮罩能不叠就不叠 —— 唯一一层（旅行遮罩）是一块纯色矩形，
//     平时整块 HIDDEN，一行 alpha 混合都不算。

#include "fa_view.h"

#include <stdio.h>
#include <string.h>

#include "lvgl.h"

#include "bsp_battery.h"

#include "fa_game.h"
#include "fa_sprites.h"
#include "fa_fonts.h"
#include "fa_talk.h"     // ★ 第十八轮：猫咪对我说的话（290 句，只在气泡里用 16px 显示）
#include "tb_clock.h"
// ★★ 第四十三轮（排障）：只为了天气那两行内存账。
//   为什么值得为「两行日志」加两个头文件：LVGL 的堆是一个**独立静态池**
//   （CONFIG_LV_MEM_SIZE_KILOBYTES），用尽时的症状不是崩溃、不是重启，
//   是**整屏定格**（见 wx_mem_log 的说明）—— 不打日志根本分不清是
//   LVGL 池子炸了、还是 IDF 系统堆炸了、还是压根不是内存问题。
#include "esp_log.h"
#include "esp_system.h"
// ★ 2026-09-19 移除的两条依赖，都不是「坏了」而是「不需要了」：
//   fa_music.h —— 背景音乐整条线下线（用户反馈「不好听」），音量调整格随之取消；
//   tb_prefs.h —— 屏幕亮度调整格一并取消，界面层再没有要写偏好设置的地方。
//   模块本身都还在（tb_prefs 还管着屏幕朝向，开机照旧 tb_prefs_apply()），
//   只是界面不再碰它们。详见 04-工具脚本/IDF环境搭建/README.md。
// ★★★ 2026-09-21（第四十五轮）：**tb_prefs.h 加回来**。
//   上面那条「界面层再没有要写偏好设置的地方」的前提消失了 ——
//   设置页本轮恢复（收藏册「设置」那一格按 ● 进去），它要读 tb_bright()、
//   写 tb_bright_set()（见 build_set 那一节）。
//   ⚠ 别顺手把 tb_screen_deg* 也用上：用户同轮明确「屏幕方向不加，没必要」。
//     方向仍然只在主界面长按 ↓（main.c 的 on_long）。
#include "tb_prefs.h"

// ------------------------------------------------------------------ 配色

#define C_TRANS     0xFFFFFF

// ★ 2026-09-19（第四次）：这一节原来有二十多个色号 —— 天空 / 太阳 / 月亮 /
//   云的两种白 / 三道远山 / 远岸 / 小溪 / 波纹 / 近岸 / 岸沿 / 树干 / 两种树冠 /
//   屋子 / 屋顶，**每个还有一个 N_ 开头的夜色孪生兄弟**。
//   它们全都只服务于「程序化搭出来的天地溪岸」和「换色成夜」这两件事；
//   第四次改版把地景换成一张真图、把夜色换成一层遮罩之后，一个都不需要了。
//   ⚠ 别照着旧版再抄回来：现在只有一层半透明遮罩（见 C_MASK），
//     没有「每加一处地景就要配一个夜间色」的对应关系了。
#define C_HUD       0xEDE9E2
#define C_TEXT      0x3A3833
// ★ 2026-09-19（第五次）：顶栏**没有底色**了，文字直接压在天空上。
//   底图那片天空是浅蓝，深灰字读得清；可旅行遮罩一压上去整屏变暗，
//   深灰字就糊没了 —— 所以遮罩期间这一套换成暖白（见 hud_paint）。
#define C_HUD_LT    0xFFF6EC
// C_HUD_WT：顶栏文字现在的正式字色。用户原话（第十二轮）：
//   「把顶上猫罐头数量和电量的字体放大，调整为白色」。
//   ★ 它和 C_HUD_LT 是两个用途，别合并：C_HUD_LT 是**旅行遮罩下**那一档暖白
//     （hud_paint 用），C_HUD_WT 是纯白本身。现在两者数值接近，
//     但语义不同 —— 哪天要调遮罩下的字色，不会误伤平时那档。
//   ⚠ 白字必须配 hud_chip() 那层淡衬底，否则压在浅蓝天空上等于没写。
#define C_HUD_WT    0xFFFFFF
#define C_DIM       0x7A756B
#define C_CARD      0xFFFDF8
#define C_LOCKED    0xDCD5C8
#define C_LOCK_TXT  0xA79E8E
#define C_ACCENT    0xE08A3C
#define C_CLOVER    0x7FB069
#define C_PANEL     0x3A3630
#define C_PILL_BG   0xDFD8CC
#define C_INTRO_BG  0xF4EFE6      // 开场用的暖纸色

// ★ 2026-09-19（第九轮）新增三条 —— 圆角与外壳遮挡带来的。
//
// C_DARK：**屏幕底色**。屏幕外壳是带弧度的，底图要做圆角裁切，裁掉之后露出来的
//   就是这一层。原来这里没有这个位置（底图铺满整屏，看不到底色），
//   所以 fa_view_init 里设的是 C_HUD（米白）—— 那样四角会发白、像图没铺满。
//   换成暖黑，四角看起来才像「屏幕自己的圆角」而不是漏底。
#define C_DARK      0x1B1917

// C_BAR_TXT：底栏那排按钮上的浅字（未选中）。底栏改成半透黑底之后，
//   原来压在米白底上的 C_DIM(0x7A756B) 直接糊没了 —— 必须换成反白系。
#define C_BAR_TXT   0xDCD4C6

// R_CORNER：底图 / 明信片的圆角半径。2026-09-19 用户拍板 **26**（我给 16/26/36 三档）。
#define R_CORNER    26

// CVR_B：四角角标的边框宽（第十三轮，见 build_corners）。
//
// ★ 它有一个硬下界，改 R_CORNER 就必须重算：**CVR_B >= R_CORNER * (√2 - 1)**。
//   推导一句话：要被盖住的「最外点」是屏幕角 (0,0)，圆心在 (R_CORNER, R_CORNER)，
//   距离 = R_CORNER * √2 ≈ 36.77；角标能盖到的最大半径 = R_CORNER + CVR_B。
//   两者相减 ⇒ CVR_B >= 26 * 0.4142 ≈ **10.77**。
//   取 14 是留了 3.2px 余量（圆角是离散栅格化的，边界那一下要留余地）。
#define CVR_B       14

// ★★★ 2026-09-19（第十四轮）**明信片自己那一圈圆角**的两个数。
//   和上面 CVR_B 是**同一套技巧、不同的对象**：CVR_B 管的是「整屏四角」，
//   这两个管的是「收藏册/到达卡上那张明信片自己的四角」。
//   IMG_CORNER = 图上真正看得见的圆角半径（8px —— 和第十三轮之前 clip_corner
//                那版给 `dex_art` 的 radius 8 同一个量级，用户说「之前好像是
//                圆角」，就是照它恢复的）。
//   IMG_CVR_B  = 角标对象向外扩多少（= 边框宽度）。
//
// ★★★ 2026-09-19（第十七轮）**4 -> 10**。用户原话：
//   「获得明信片的时候，要把明信片四角变成弧形，现在有时候切的不够准确，
//     留有残余边框，都去干净。」
//   「有时候」+「去干净」两个词，指的就是**余量不足**：
//     · 要遮的最外点是**图的角**，它到角圆弧心的距离 = IMG_CORNER * √2 = 11.31；
//     · 角标能盖到的最大半径 = IMG_CORNER + IMG_CVR_B；
//     · ⇒ **覆盖余量 = IMG_CORNER + IMG_CVR_B - IMG_CORNER*√2
//                    = IMG_CVR_B - IMG_CORNER*(√2 - 1) = IMG_CVR_B - 0.414*IMG_CORNER**。
//       取 4 时只有 4 - 3.31 = **0.69px** —— 坐标一舍入、边缘一抗锯齿就露。
//
//   ⚠⚠ **「IMG_CVR_B 只能取 4」这条旧结论已被推翻**，别再照它改回去。
//     旧理由是「图位距卡片上沿只有 4px，取 5 就会把卡片色的白边画到卡片外面」。
//     错的。重读 `lv_refr.c:143-153`：
//         obj_coords = OVERFLOW_VISIBLE ? obj_coords_ext : obj->coords;
//         clip_coords_for_children = layer->_clip_area ∩ obj_coords;
//     而 `obj_coords_ext` 只比 `obj->coords` 多一个 **ext_draw_size**，
//     它由 `lv_obj_calculate_ext_draw_size()`（`lv_obj_draw.c:353`）算，
//     **只含 shadow / outline / drop_shadow / transform** —— `mk_box` 把这四样
//     全设成 0（`border_width` 也清 0），所以 `ext_draw_size == 0`，
//     `obj_coords_ext == obj->coords`：**OVERFLOW_VISIBLE 在这个对象上是空操作**。
//     ⇒ 角标的可绘区**被硬裁到图位 dex_art 的框**（176x208）。
//     ⇒ 外扩出去的那几圈**根本画不出来**，也就不可能「糊到卡片外面」。
//     ⇒ IMG_CVR_B 想取多大取多大，唯一效果就是**把四角那道箍加厚**。
//   ⚠ 留痕（铁律 17）：旧注释写「外扩那一圈真的被画出来」——
//     那半句同样不成立；真正让圆角生效的是「**四个角的弧本来就落在图位之内**」
//     （弧在 y∈[4,12] / y∈[200,208]、x∈[4,12] / x∈[158,166]，全在框内），
//     与外扩无关。旧结论「开不开 OVERFLOW 圆角都盖得住」**是对的**，
//     但理由写错了，一并订正。
//
//   取值 10：余量 10 - 3.31 = **6.69px**（约 10 倍），切深不变
//     （切深 = 图上被切掉的那一圈，只由 IMG_CORNER 决定，与 IMG_CVR_B 无关）
//     ⇒ **圆角大小一个像素都没变，只是从「勉强盖住」变成「盖得死死的」。**
//   ⚠ 上限：角标左沿（卡片坐标）= 20 + 4 - IMG_CVR_B，不能越过卡片自己的圆角区
//     （半径 12，即 x∈[0,12]×y∈[0,12]）⇒ 24 - IMG_CVR_B >= 12 ⇒ **IMG_CVR_B <= 12**。
//     取 10 留 2px。到达卡那边同一个约束、同一个值（见各自的调用点）。
//   ⚠ 定义必须放在 build_card **之前** —— 到达卡那边的角标用同一对常量。
#define IMG_CORNER   8
#define IMG_CVR_B    10

// 猫罐头图标（HUD 左上，20x20）用到的四个色。取值来自第九轮候选图 D 的绘制参数，
// 与候选图逐像素对得上 —— 改这里之前先看一眼那张图，别凭印象调。
#define C_CAN_STEEL 0xC6CCD4      // 罐身银
#define C_CAN_LID   0xEAEEF2      // 顶盖亮银
#define C_CAN_EDGE  0x646A72      // 描边（深灰）
