//        挂着风景            -> fa_res_nocat_<景点>（那张**无猫**底图）
//        挂着风景 **且旅行中** -> 同上，一模一样
//   用户原话：「旅行中也换成无猫版吧，跟小猫在家的时候一样，把小猫的动态效果放上面。」
//
// ★ 第十轮删掉的是「旅行中铺 176x220 带猫明信片 ×1.5」那一路（连同 SCENE_SCALE）。
//   它当年存在的理由是「画里那只猫就是替你去远方的那只」——
//   实机看下来结论是**不好看**：放大的明信片和底图不是一套画风，
//   而且那只猫是死的。现在换成自己的猫，走停动作都在，画面才活。
//
// ★ 换来的一条硬性质：**同一时刻只有一张全屏图在渲染**。
//   旧版靠 `card = has && away` / `want_bg = !card` 这对互斥判据维持，
