// ------------------------------------------------------------------ 小游戏「接猫罐头」
//
// ★★ 2026-09-19 新增。用户原话：
//   「设计一个小游戏，放在收藏，跟明信片一样，可以让人选，小游戏就使用用户选择的
//     背景，游戏方式就是从上面掉下来猫罐头，让小猫去接，使用上下键，每局15秒，
//     接到超过一定数量，就给1-3个猫罐头，让人旅行等待的时候能有的玩。」
//
// ★ 操控为什么是「↑↓ 当左右用」（已跟用户确认过这一条）：
//   板子上只有 ↑ ↓ ● 三颗键（main.c 的 K_UP / K_DOWN / K_OK），**没有左右键**。
//   接落物这个玩法必须能做水平位移，否则罐头横向随机落、猫只能站在原地挨砸。
//   所以 ↑ = 往左，↓ = 往右 —— 三键硬件上做这类小游戏的通行做法。
//   ⚠ 别在别处再给这个游戏加一套「上下移动」，两套坐标会打架。
//
// ★ 奖励档位（用户选的那一档）：
//     接到 0-3 个 -> 0；  4-6 -> 1 个；  7-9 -> 2 个；  10+ -> 3 个
//   落空也**不算罚** —— 扣分制的挫败感跟「旅行等待时有的玩」这个定位相冲。
#define MINI_SECS        15       // 每局时长
// ★ 第十八轮：开局提示那块半透面板自己的显示时长。原来是「用本局剩余时间算」的，
//   记忆翻牌改成 30 秒之后那个算式就不成立了（见 mini_tick）。
#define MINI_TIP_MS      2500
#define MINI_CAT_W       56       // 游戏里的猫比主页那只小一号：56 而不是 64。
#define MINI_CAT_H       56       //   底部要留出走位空间，64 就贴边了。
#define MINI_CAT_Y       (SCR_H - MINI_CAT_H - 16)   // 脚下留 16px
#define MINI_CAT_X0      ((SCR_W - MINI_CAT_W) / 2)
#define MINI_CAT_MIN_X   6
#define MINI_CAT_MAX_X   (SCR_W - MINI_CAT_W - 6)
#define MINI_CAT_SPEED   138      // px/s —— 按住方向键时的速度

#define MINI_MAX_CANS    5        // 屏幕上最多同时几个罐头（**对象池**，不是动态建）
// 罐头尺寸 = **和 HUD 左上角那只图标完全一样**的 20x20。
// ★★ 2026-09-19（第十二轮）从 22x24 改成 20x20，就是为了这一件事：
