//   改小之后下落速度与生成间隔都不动 —— 它们是以「穿越全屏的秒数」定的，
//   罐头矮了 4px 只让穿越快一点点，手感反而是更利落的那一侧。
#define MINI_CAN_W       20
#define MINI_CAN_H       20       //   它**里面**的子对象 —— 移动时只动容器这一个。
