#define MINI_FALL_RAND   72       //   上面再加 0..71
#define MINI_SPAWN_MIN   1050     // 生成间隔 ms
#define MINI_SPAWN_RAND  620

// 奖励门槛。改这里就是改经济，改完记得同步 05-交付物 里那份测算页的说法。
