// ================================================================== 小游戏总表（第十六轮）
//
// ★★ 2026-09-19（第十六轮）用户原话：
//   「我想每获得 6 张明信片，就解锁一个小游戏，第一个接罐子是一开始就有的，
//     到获得第 6 张明信片的时候解锁打兔子……第 3 个小游戏是剪刀石头布……
//     第三个小游戏记忆力的小游戏，你帮我设计一下，用之前访客的其他动物素材就行。」
//
//   4 个游戏 + 三道解锁门槛，全部落在这张表上：
//     0  接猫罐头    0 张    （上手就能玩，第十轮就有的那个）
//     1  打兔子      6 张
//     2  剪刀石头布  12 张
//     3  记忆翻牌    18 张
//   第 24 张（全收齐）另外给一句「恭喜你，解锁了全部明信片」（见 card_fill）。
//
//   ⚠ 顺序即解锁顺序，GAME_NEED **必须单调不减** —— 选择页按这个顺序排，
//     游标默认落在第一个「已解锁」的游戏上，这条前提一乱整个入口就会指错。
//   ⚠ 表长 = GAME_COUNT(4)。往表里加游戏必须同时改六处：
//       ① GAME_COUNT  ② 这一节的几何  ③ U 结构体里那一组对象
//       ④ build_menu / build_mini 里那两段  ⑤ 各游戏的 tick  ⑥ main.c 的按键分派
//     漏一处的后果：要么编译期报错（好事），要么对象建了却不显示（静默，靠点名器抓）。
#define GAME_CAN      0       // 接猫罐头
#define GAME_RABBIT   1       // 打兔子
#define GAME_RPS      2       // 剪刀石头布
#define GAME_MEMORY   3       // 记忆翻牌
#define GAME_COUNT    4

// 三道门槛 + 全解锁那一个数。★ 24 是 FA_DEST_COUNT，不是另取的数。
#define GAME_NEED_RABBIT   6
#define GAME_NEED_RPS      12
#define GAME_NEED_MEMORY   18
#define GAME_NEED_ALL      24

// ---- 小游戏选择页（第十六轮新增，第十七轮重做成 2x2）----
//
// ★★★ 2026-09-19（第十七轮）用户原话：
//   「现在小游戏主界面跟之前设定的不一样，要与之前一样，<设计稿截图>
//     按照这里面的来。」+「小游戏主界面要写"长按返回"。」
//   ⇒ 按设计稿那版**2x2 棋盘**重做。同时**推翻第十六轮两条**：
//
//   ~~★ 用户原话：「小游戏里面，没解锁的要显示未解锁，不要显示出来是什么游戏，
//     要给人一些神秘感。」⇒ 未解锁的行只写「未解锁」+ 还差几张，游戏名不出现。~~
//   ★ 第十七轮订正：**未解锁的卡片现在照设计稿写游戏名**，只把整张卡压暗。
//     设计稿上四格（接猫罐头/打兔子/剪刀石头布/记忆翻牌）名字都看得见，
//     后两格是灰的 —— 那才是「之前设定」的样子。所以 GAME_NAME[] 恢复在
//     未解锁那一支也使用，副行写「N 张解锁」（N = 门槛总数，与设计稿一致）。
//     ⚠ 留痕：第十六轮那条「神秘感」要求**仍然记在上面**，因为它是真的提过；
//       如果哪天用户又要神秘感，照着上面那段把名字换回「未解锁」即可。
//
//   ~~★ 为什么是竖排 5 行而不是 2x2 棋盘：板子上只有 ↑↓● 三颗键，
//     2x2 要让 ↑↓ 在四个格之间绕圈，玩家按两下 ↓ 才走到第二格，和「上下」
//     这个字面直接冲突。~~
//   ★ 第十七轮订正：**还是做成了 2x2**（用户点名要设计稿那版）。
//     ↑↓ 在这四个格里走**蛇形/线性序（0→1→2→3→0）**：
//       按一下 ↓ 从左上走到右上，再一下到左下，再一下到右下，再一下绕回左上。
//     ⚠ 这条「线性序」是这一版唯一的妥协 —— 2x2 的天然顺序本该是上下左右，
//       但只有两颗方向键，做不到。**线性序至少保证「按一下必换一格」**，
//       而「按两下才动」那种绕圈走法在实机上会让人以为按键失灵。
//
//   ~~★ 第 5 行是「返回收藏册」。★ 为什么不做成「长按 ● 返回」：
//     第十轮已经定过「用户不喜欢长按返回」。~~
//   ★ 第十七轮订正：**第 5 行删掉，返回改成长按 ●**。理由：
//     ① 用户这一轮点名「不需要小游戏再多一层才能进入」—— 那一行正是「多出来的一层」；
//     ② 设计稿上底部写的是「长按出册」，本来就没有第 5 行；
//     ③ 这里和收藏册**不冲突**：收藏册的返回仍是 ● 短按（那条没变），
//        只有**选择页**因为 ● 短按已经被「开始游戏」占掉了，才把返回挪到长按。
//     ⇒ 实现落在 main.c 的 on_long（原来那一支是空的）+ fa_view_menu_back()。
#define MENU_CELL_N    4                              // 4 个游戏，没有第 5 格了
#define MENU_CELL_GAMES GAME_COUNT                    // 4
#define MENU_CELL_W    96
#define MENU_CELL_H    96
#define MENU_CELL_X0   20                             // 左列 x；右列 = 20+104 = 124
#define MENU_CELL_DX   104                            // 列距 ⇒ 右列右沿 220 = 240-20，左右对称
#define MENU_CELL_Y0   80
#define MENU_CELL_DY   110                            // 行1 80..175 / 行2 190..285
#define MENU_CELL_X(i) (MENU_CELL_X0 + ((i) % 2) * MENU_CELL_DX)
#define MENU_CELL_Y(i) (MENU_CELL_Y0 + ((i) / 2) * MENU_CELL_DY)
// 卡片里的三段版式（**实测墨迹**，不是按框高估的 —— 铁律 16）：
//   图标       y 4..48              （44x44，x 26..70 —— 卡宽 96，居中）
//   游戏名     框顶 50 → 墨迹 53..65   （fa_font_ui 16px：墨迹 = 框顶+3..+15）
//   副行       框顶 70 → 墨迹 71..83   （fa_font_tiny 13px：墨迹 = 框顶+1..+13）
//   ⇒ 三段合计 4..83，卡片 96 高，上下各留 4 / 13。
// ★★ 第十八轮：加图标之前这里是「两行字居中」（26 / 54）。加图标之后两行字
//   必须整体下移 —— **这三个数是一组**，只动其中一个必撞（撞了不报错，只是压字）。
#define MENU_CELL_LB_Y 50
#define MENU_CELL_SB_Y 70
// 选中态**用橙色描边，不用填充** —— 照设计稿（那一格就是描边）。
// ⚠ mk_box 内部把 border_width 清成 0，所以描边必须在 mk_box 之后单独设。
#define MENU_CELL_SEL_BW 3
// 已解锁但未选中的卡片浓度。
// ★★ 2026-09-19：这一处原本写的是 85%，而 **LVGL 根本没有 LV_OPA_85** ——
//   它的档位只有 10 的整数（0/10/…/90/100，外加 COVER / TRANSP），
//   写 85 是编译期 `undeclared`，三处一起炸（build 直接停）。
//   ⇒ 统一收敛到 LV_OPA_80（204/255）。它和「锁着 70%」「选中 100%」
//     之间的三档差仍然一眼分得开。
#define MENU_ROW_OPA  LV_OPA_80

// ---- 卡片里的图标（★★ 2026-09-20 第十八轮新增）----
//   用户原话：「小游戏界面要图标。」+「未解锁的不显示名称，比如『剪刀石头布』
//     改为『未解锁』，但是保留图标。」
//   ⇒ 四张卡各加一枚 44x44 的图标（卡宽 96 ⇒ x 26..70 居中）。
//   ★ 四枚图标**全部用现有素材与图元拼出来**，一个新素材字节都没有：
//       接猫罐头   照 HUD 那只罐头的 7 块图元再拼一遍（坐标 ×2 放大到 32x32）
//       打兔子     bee_a 帧 0（就是游戏里那只兔子，48 缩到 44 ⇒ scale 234）
//       剪刀石头布 三张小牌（石 / 剪 / 布），中间那张是橙的
//       记忆翻牌   三张小牌，一张翻开（蝴蝶）+ 两张扣着（？）
//   ⚠ 卡片里三段的坐标是**一起定的**，见 MENU_CELL_LB_Y 那一段。
#define MENU_IC_SIZE   44
#define MENU_IC_X      26
#define MENU_IC_Y      4
// 锁着时把图标压暗一半。★ 走**逐件设 opa**，不给容器挂 style_opa ——
//   后者会让 LVGL 为这个对象再开一层 draw layer（44x44x4 ≈ 7.7 KB），
