#define MENU_IC_DIM    LV_OPA_50

// ---- 打兔子（第十六轮新增）----
//   6 个洞，2 行 x 3 列；↑ 打上排、↓ 打下排。
//   ★★ 兔子必须**从洞里钻出来**，不能「站在洞上面」—— 用户原话：
//     「打兔子游戏，兔子要在洞里面出来，不要在洞上面出来。」
//   LVGL 只做**矩形裁切**，所以「从洞里冒出」是两件事叠加出来的：
//     ① 兔子装在一个 44x42 的**裁切容器**里（容器默认裁子对象），
//        48x48 的兔子在里面只露出一部分；
//     ② **洞口椭圆建在兔子之后**（建序 = 图层序），把兔子下截连同容器下沿
//        一起盖住 —— 于是切口是**椭圆弧**，读起来才是「钻出来」。
//   只做①会得到一条平的切口（兔子像站在洞口上沿），那正是用户不要的那种。
//   ⚠ ②那一步是这一节的全部价值，删掉它游戏就做错了，而且**不报错**。
#define RAB_COLS      3
#define RAB_ROWS      2
#define RAB_N         6                               // = RAB_COLS * RAB_ROWS
#define RAB_CX(i)     (46 + ((i) % RAB_COLS) * 74)    // 洞心 x：46 / 120 / 194
#define RAB_CY(i)     (150 + ((i) / RAB_COLS) * 86)   // 洞心 y：150 / 236
#define RAB_HOLE_RX   28                              // 洞口椭圆半宽
#define RAB_HOLE_RY   11                              // 洞口椭圆半高
#define RAB_BOX_W     44                              // 兔子裁切容器宽
#define RAB_BOX_H     42                              //   …高
#define RAB_BOX_DY    4                               // 容器底边 = 洞心 + 4（落在椭圆内部）
// 兔子在容器里的 y：RAB_BOX_H = 完全藏住；0 = 完全冒出。
//   ⚠ 「冒出位置」取的是兔子顶部对齐容器顶部 ⇒ 露出来的是兔子最上面那 42px。
//     bee_a 帧 0 画的是**只有头和耳朵**的正面兔，正好对上这个裁法。
#define RAB_RISE_MS   220                             // 升起用时
#define RAB_HOLD_MS   750                             // 停留（可打的窗口）
#define RAB_FALL_MS   170                             // 缩回用时
#define RAB_GAP_MIN   250                             // 两只之间的最短间隔
#define RAB_GAP_RAND  260
#define RAB_SECS      15                              // 一局时长
#define RAB_HURT_MS   300                             // 空挥「手酸」冷却
#define RAB_FLASH_MS  180                             // 命中时洞口亮一下
// 奖励门槛。★ 与接罐头同一套档位（用户只给了「根据打到的兔子给 1-3 个猫罐头」）——
//   不另造一套数，两个游戏的手感才是可比的。
#define RAB_TIER_1    4                               // >= 4  给 1 个
