// ------------------------------------------------------------------ 播放器

typedef struct {
    const fa_anim_t *anim;
    uint8_t  frame;
    uint32_t acc;
} fa_play_t;

// 换动画。★ 同一条就不动 —— 否则每帧重置帧号，动画会卡死在第一帧。
static void play_set(fa_play_t *p, const char *id)
{
    const fa_anim_t *a = fa_anim_find(id);
    if (!a) return;
    if (p->anim == a) return;
    p->anim  = a;
    p->frame = 0;
    p->acc   = 0;
}

static void play_tick(fa_play_t *p, uint32_t dt, lv_obj_t *img, uint32_t frame_ms)
{
    if (!p->anim) return;
    p->acc += dt;
    while (p->acc >= frame_ms) {
        p->acc -= frame_ms;
        p->frame = (uint8_t)((p->frame + 1) % p->anim->frames);
    }
    const void *want = (const void *)&p->anim->dsc[p->frame];
    if (lv_image_get_src(img) != want) lv_image_set_src(img, want);
}

