//   整段已删除（含 fa_visitor_t / VIS_POOL / vis_img[] / s_vis[] / 每帧推进）。
//   精灵图集里那 8 条 visitor 动画（8 条 × 4 帧 × 48×48×4B ≈ 288KB）
