// ============================================================ 天气（第四十二轮）常量
//
// ★★ 用户 2026-09-20 拍板：
//   「给主界面还有旅行界面，加一个天气的图层，大概就是下雨呀之类的，弄三四种天气，
//     然后随机叠加一会儿，再为每个天气加 10 句话，让小猫在所属天气的时候说一下。」
//   四条设定逐条定死（用户原话，别再自己改）：
//     ① 四种天气**一次做完**：雨 / 雪 / 雾 / 星光
//     ② **全局随机**（不跟地点走 —— 在哪儿都可能下雨）
//     ③ 间隔 90~240 秒随机、每次持续 25 秒
//     ④ 粒子在**镜头前**（盖过猫）
//
// ⚠ 常量放在这里而不是和实现放在一起（实现在 place() 之后、build_scene 之前）：
//   因为 struct ui 要用 WX_P_MAX 开数组。这个文件里「常量在前、结构体在中、
//   实现按建序排」是既有格局，别为了把一节写全就打破它。

// 七种天气。**顺序即 s_wx_kind 的取值**，也是 fa_talk.c 里 FA_TALK_WX 的行号 ——
//   两边必须一致（那边是 _dl/_talk45.py 生成的，改这里的顺序要回去改那 7 组句子）。
//
// ★★ 2026-09-21（第四十五轮）：4 种 -> **7 种**。用户原话：
//     「雾和星光按照你说的调整，雪再调小一些。雨再重新画个雨点的动态效果…」
//     「给我画个小飞机…再做气球…再做肥皂泡泡…以上都跟天气一样」。
//   逐条的变更（连同素材换没换）：
//     WX_RAIN    雨   —— 素材 fx_rain -> **fx_drop**（重画成 1px 细斜雨丝）
//     WX_SNOW    雪   —— 素材不变（fx_snow），只是显示尺寸调小
//     WX_FOG     雾   —— **不再用素材**，改 LVGL 图元画 5 条横长柔边白带（见 WX_FOG_N）
//     WX_FIREFLY 萤火 —— 原 WX_STAR。素材 fx_sparkle -> **fx_firefly**
//     WX_PLANE   小飞机  —— 新增，素材 fx_plane
//     WX_BALLOON 热气球  —— 新增，素材 fx_balloon
//     WX_SOAP    肥皂泡泡 —— 新增，素材 fx_soap
//   ⚠ 用户拍的是「改成萤火」——所以 WX_STAR 这个名字**必须一起改掉**：
//     留着旧名字会让下一个人以为这里还是「星光」，而素材早就换成萤火了。
#define WX_RAIN     0
#define WX_SNOW     1
#define WX_FOG      2
#define WX_FIREFLY  3
#define WX_PLANE    4
#define WX_BALLOON  5
#define WX_SOAP     6
#define WX_KIND_N   7

// 「没有天气」——s_wx_kind 的空值。★ 特意取 0xFF 而不是一个负数：
//   s_wx_kind 是 uint8_t，负数会被回卷成一个合法下标（比如 -1 -> 255，
//   正好等于 0xFF，又撞上）。用 0xFF 是「合法值只有 0..6」这个事实的直接表达。
#define WX_NONE     0xFF

// 粒子池上限。★ 取 **24** = 七种天气里用得最多的那个（雨 22）再留一点余量，
//   池子开一次就够。
//   ⚠ 改大这个数 = 改 struct ui 的大小 = 每次开机的静态内存，想清楚再动。
//     第四十五轮 18 -> 24：+6 个指针（48 B）+ 6 份 wx_p_t（约 120 B）+
//     6 份 fa_play_t，合计不到 400 B —— 换来的是一整种天气的密度上限。
#define WX_P_MAX    24

// 素材本身的像素边长（**七条 fx 里凡是用素材的都是 24x24**）。★ 这只是**基准值**：
//   真正显示多大由 WX_SCALE / WX_SIDE 决定 —— 七种天气都要放大，见那一段。
//   这个宏只在两处用得上：建池时给对象一个初始大小、以及换算倍率时的基数。
#define WX_CELL     24

// ==================================================================== 雾（图元）
//
// ★★ 2026-09-21（第四十五轮）：**雾不再用素材，改用 LVGL 图元画横长的柔边白带**。
//
// 为什么 —— 原来用的是 fx_steam，而那条素材画的是「一缕升起的水汽」：
//   一格里是几根**竖直**的白柱子（本来就是给烟囱、水壶嘴准备的）。
//   12 根竖条铺在屏幕上，读起来是「屏幕上有几缕烟」，不是雾。
// 用户原话：「我感觉天气还得再调整调整、星星呀、雾之类的，都不太行」。
//
// 换成图元之后有三个好处：
//   ① **形状对了**：雾是一层贴地/贴山的横向白带，不是竖条；
//   ② **更省**：5 个圆角矩形 vs 12 个缩放过的 image。缩放 image 每个每帧都要
//      一块变换缓冲（见第四十三轮那条内存账），图元一个字节都不用；
//   ③ 尺寸可以**每条都不一样**（宽度 150~230 随机）—— 素材做不到这一点，
//      只能靠缩放，而缩放又要变换缓冲。
//
// ⚠ 代价要诚实写在这里：**LVGL 没有高斯模糊**，所以这几条带是**硬边**的。
//   补偿手段只有一个 —— 圆角取满（radius = 高/2，两端变成半圆）＋ 低透明度，
//   读起来是「一条淡云带」而不是「一个白方块」。这是当前能做的最接近的等价物。
//   真要柔边只有两条路：给每条带叠三层不同 alpha 的副本（对象数 x3），
//   或者做一张柔边素材（又回到素材的老路）。都不值得，先上机看效果。
#define WX_FOG_N      5          // 5 条
#define WX_FOG_H_MIN  20         // 每条带的高度（随机区间）
#define WX_FOG_H_MAX  30
#define WX_FOG_W_MIN  150        // 每条带的宽度（随机区间）
#define WX_FOG_W_MAX  230
#define WX_FOG_TOP    48         // 第 0 条的中心 y
#define WX_FOG_STEP   50         // 相邻两条的中心间距 ⇒ 48/98/148/198/248（±抖动）
#define WX_FOG_JIT    8          // 上下抖动幅度（±8）

// 时间（用户第③条）：两次天气之间 90~240 秒、每次持续 25 秒。
#define WX_GAP_MIN   90000u      // 至少 90 秒
#define WX_GAP_RAND 150000u      // …再加 0~150 秒 ⇒ 90~240 秒
#define WX_LAST_MS   25000u      // 一次天气持续 25 秒
#define WX_FIRST_MS  30000u      // 开机后第一场：30 秒（先让人看清主界面）

// ================================================================== 设置页（第四十五轮）
//
// ★★ 用户 2026-09-21 原话：
//   「设置页面不是之前都做好了？就是这个呀。」（附一张旧版固件截图）
//   —— 查证：那个设置页在「第五次」那轮随 tb_prefs 的界面一起被删掉了
//      （见本文件开头那段说明的第 ①条），收藏册从此**没有任何设置项**。
//      本轮照截图**恢复**它。
//   「2，不加，没必要」 —— 同轮用户明确否掉了「把屏幕方向也放进来」。
//      ⇒ 这一页**只有亮度一项**。方向仍然只在主界面**长按 ↓**（见 main.c 的 on_long），
//        别顺手搬进来 —— 那是用户点名不要的。
//
// ★ 为什么是**独立一层浮层**（U.ov_set），而不是收藏册卡片里的一页：
//   收藏册那一套是「一张 216x290 的白卡 + 一个图位 + 四行字」的固定骨架
//   （见 build_dex / dex_refresh），而设置页是一整张**表的版式**
//   （标题 / 分隔线 / 标签行 / 5 格条 / 按键表 / 底部三行）。
//   硬塞进那个骨架只有两种下场：要么把图位撑变形，要么在 dex_refresh 里
//   加一堆「只有这一页才显示」的开关 —— 那种开关迟早会漏一个（静默）。
//
// ⚠ 建序：U.ov_set 必须**建在 U.ov_dex 之后** —— 它是盖在册子上面的**第二层**。
//   建序即图层序，反了就永远被册子压住（肉眼看得见，但很容易往别处查）。
//   ⚠ 它不是小游戏那条链（册子 → 选择页 → 游戏）的一环，两者互不相干：
//     选择页从「小游戏」那一格进，设置页从「设置」那一格进。
//
// 版面（相对**卡片**，卡片本身在 SET_CARD_*）。
//
// ★★ 2026-09-21（第四十六轮）**整块重排**。原来是「亮度 + 4 行表 + 底部三行提示」，
//   现在是一张卡**只装三块按键表**——用户给了三张表，要求逐条上屏：
//
//       【设置页面】 电源键 开关机 / 上下键 调节屏幕亮度 / ● 键 返回
//       【主页页面】 电源键 开关机 / 上下键 选择 / ● 键 短按为确认 / 长按为关闭屏幕
//       【旅游页面】 电源键 开关机 / 上下键 关闭屏幕 / ● 键 短按为进入收藏 / 长按为快速回家
//
//   ⚠ 用户手写的是 `○`，他自述「键盘不好打出来这个」；实际按**实心圆 `●`**
//     （U+25CF）做 —— 和全工程其它地方的按键符号统一。
//   ★ 行数账：3 个分组标题 + 9 个键名行 + 2 个「长按…」续行 = **14 行**。
//     续行是因为「短按/长按」各占一行（挤一格会折行，14 行变 15 行，卡片就爆了）。
//     ⚠ 两列**行数必须相等**：每列是一个 label 装全部 14 行，错一行整块错位。
//
//   y 布局（卡内坐标）：
//     y    8   「设置」24px 居中
//     y   38   分隔线 ①
//     y   43   「屏幕亮度」左 + 五格条右（条 x 106..212）
//     y   70   分隔线 ②
//     y   77   三块表 14 行 × 16px ⇒ 末行墨迹到 300，卡高 309 ⇒ 下留 9
//
//   ★ 第四十六轮撤掉的三样（都别加回来）：
//     · 右上角那个「4/5」—— 五格本身就把档位说清了，而且它和第一格**压在一起**了
//       （13px 下字长到 x140，而格子从 x98 起）。
//     · 「按上下键调节」那一行 —— 表格第一块里「上下键 / 调节屏幕亮度」说完了同一件事。
//     · 底部三行提示 —— 它们写的三件事现在**逐条进了上面三张表**，一个字都没丢。
//   ⚠ 代价诚实记着：关屏之后「按哪个键唤醒」现在只写在表里（主页·长按为关闭屏幕 /
//     旅游·上下键 关闭屏幕）。真机上关屏后任意键都能亮，这条没有单独的提示行了。
#define SET_CARD_X    8
#define SET_CARD_Y    5
#define SET_CARD_W    224
#define SET_CARD_H    309

// 亮度 5 档。用户截图上是「五格条，前四格亮」。
//   ★ 5 档落在 tb_prefs 的 10..100 里取 20/40/60/80/100 ——
//     最低一档写 20 而不是 10：10% 是 tb_bright_set 的**安全下限**
//     （防「背光关到看不见自己调到了几」，见 tb_prefs.c），
//     不是给人当「最暗一档」用的；这一页摆的是「五档」，20 起才像个刻度。
//   ⚠ 每格 20%：SET_LV_STEP 一改，set_bright_lv() 的取整也要跟着想一遍。
//   ★ 第四十六轮格宽 32 -> 18：卡片 212 -> 224 之后，五个 32 的格子会把「屏幕亮度」
//     顶到没有缝。18 宽 + 4 缝 ⇒ 右沿 106+5*18+4*4 = 212 = 卡宽 224 - 12。
#define SET_LV_N      5
#define SET_LV_STEP   20
#define SET_BAR_X     106
#define SET_BAR_Y     46
#define SET_BAR_W     18
#define SET_BAR_H     13
#define SET_BAR_GAP   4

// 三块按键表 14 行的起点、行高、列位。
//   ★ 行高按**实测行高 + 行距**算，不是按字号：
//     fa_font_small（12px）的 line_height 实测 = **15**，加 text_line_space = 1 ⇒ 每行 16px。
//     ⚠ 12px 和 13px（fa_font_tiny）的 line_height **一模一样是 15** ——
//       缩字号**不省高度**，这张表能塞进 14 行靠的是卡片加高 + 行距只给 1。
//       想再加行之前先算：77 + n*16 + 15 ≤ 309。
//   ★ 两列的 x/w：左列从 12 起、宽 80（最长「【设置页面】」= 6 字符 × 12 = 72px）；
//     右列从 100 起、宽 112（最长「长按为关闭屏幕」= 7 字 = 84px，还有富余）。
//     ⚠ 键名行在左列里**再缩进一个字**（见 build_set 的 ROWS），
//       所以左列真正要的是 12 + 12 + 72 = 96 < 100，两列之间还留着 4px 缝。
#define SET_FONT_LH   15          // fa_font_small 的**实测**行高（12px 也是 15，别按字号猜！）
#define SET_TAB_LS    1           // text_line_space：每行多出来的那点呼吸感（0 会贴成一块）
#define SET_TAB_STEP  (SET_FONT_LH + SET_TAB_LS)
#define SET_TAB_Y     77
#define SET_TAB_ROWS  14          // ⚠ 必须等于 SET_TAB_L_TXT / SET_TAB_R_TXT 的行数
#define SET_TAB_H     232         // 14 行需 13*16+15 = 223，余 9px 留白
#define SET_TAB_LX    12
#define SET_TAB_LW    80
#define SET_TAB_RX    100
#define SET_TAB_RW    112
#define SET_RULE_Y1   38          // 标题下的分隔线
#define SET_RULE_Y2   70          // 亮度那一段下的分隔线
// ★ 原来还有第三条（SET_RULE_Y3 = 228）和它下面的底部三行提示。第四十六轮**删了**：
//   那三句的内容已经逐条进了上面三张表 —— 再画一条线只会把版面切成两半。
#define SET_RULE_N    2           // ⚠ 和上面两条线、以及 set_rule[] 的长度是同一个数

// ---- 纪念品图鉴（2026-09-21 第四十七轮）----
//
// 版面：一页 3 列 x 4 行 = **12 格**，24 件分**两页**。
//   格区相对**卡片**（卡片 = (12, 24, 216, 290)，见 build_dex）：
//     x 12..204（宽 192 = 3 x 64）
//     y  6..266（高 260 = 4 x 65）
//
// ★ 44 这个图标尺寸是**先算体积再定的**，不是先定版面：
//     24 帧 x 64x64 x 3B = 288 KB，而 app 分区只剩 259 KB —— 原始尺寸**装不下**。
//     44x44 只要 139,392 B ≈ 136 KB。格高 65 又正好是 44 + 上缝 2 + 名字行高 15
//     + 下余 4 ⇒ 两边同时卡死 44，不是挑的。
//   ⚠ 名字那一行用 fa_font_small 的**实测**行高 15（12px 也是 15，别按字号猜）——
//     和设置页那条 SET_FONT_LH 是同一个坑。
//
// ⚠ 底沿 266 是**躲出来的**：dex_hint 在卡片内 y272，中间只剩 6px。
//   往格子里加东西（图、字、间距）之前先回头看这一行。
//
// ⚠ 两页要 24 个 lv_image + 24 个 lv_label —— 这里**只建 12 格**，
//   翻页时重画那 12 格（见 souv_refresh）。建 24 格要多 24 个常驻对象，
//   而 LVGL 池只有 80 KB。
#define SOUV_COLS      3
#define SOUV_ROWS      4
#define SOUV_PER_PAGE  (SOUV_COLS * SOUV_ROWS)                                 // 12
#define SOUV_PAGES     ((FA_SOUV_COUNT + SOUV_PER_PAGE - 1) / SOUV_PER_PAGE)   // 2
#define SOUV_GX        12         // 格区左沿（卡片内）
#define SOUV_GY        6          // 格区顶沿（卡片内）
#define SOUV_CW        64         // 每格宽（192 / 3）
#define SOUV_CH        65         // 每格高（260 / 4）
#define SOUV_ICON      44         // 图标边长
#define SOUV_ICON_DY   2          // 图标在格内的 y
#define SOUV_NAME_DY   48         // 名字在格内的 y
#define SOUV_NAME_H    15

// ------------------------------------------------------------------ 界面对象

struct ui {
    lv_obj_t *scr;

    // ---- 场景两件（2026-09-19 第十轮定型）----
    // ★★ 第九轮曾把「一张底图」拆成「两个圆角容器 + 两张底图 + 一层明信片」，
    //   第十轮又把那层明信片收回去了。现在只剩两件：
    //
    //     bg_cv    —— 底图层的圆角容器（240x320，贴满屏幕，四角裁 26px）
    //     bg_img   —— 里面的图，**同一个对象换 src**：
    //                    没挂风景 -> fa_res_home（家的底图，画里有房子）
    //                    挂着风景 -> fa_res_nocat_<id>（那张**没有猫**的底图）
    //                    **旅行中也是这一张** —— 第十轮起旅行不再换画法
    //     travel   —— 旅行中的一层半透明遮罩
    //
    //   建序 = 图层序：bg_cv → cat → travel。
    //
    // ★ 为什么家底图 / 无猫底图 / 旅行中那张共用一个对象：三者尺寸完全一样
    //   （240x320、scale 256），换 src 零风险，还省掉一处「谁显谁隐」的双写。
    //   纪律照旧：值没变就不 set_src。
    //
    // ★ 圆角（用户 2026-09-19：「这个屏幕外壳是带弧度的，把图片都切割圆角」）：
    //   lv_image 自己**不吃 radius** —— 必须套一层容器 + clip_corner，
    //   build_card 里的 art 那层早就是这么做的，这里照抄同一套。
    //   切掉之后露出来的是屏幕底色 C_DARK（见 fa_view_init 里设的那一行）。
    lv_obj_t *bg_cv;      // 圆角容器（底图层）
    lv_obj_t *bg_img;     // 240x320：家的底图 或 某张无猫底图
    // ★★ 2026-09-19（第十轮）从这里删掉的两个字段：scene_cv / scene。
    //   它们是「旅行中把 176x220 的**带猫**明信片放大 1.5 倍铺满屏」那一层。
    //   用户原话：「本来想着旅行中用有猫图，但是感觉效果不是很好，旅行中也换成
    //   无猫版吧，跟小猫在家的时候一样，把小猫的动态效果放上面。」
    //   —— 于是旅行中改铺**无猫**底图 + 我们自己的猫，和「挂风景但不旅行」
    //   彻底变成同一套画法（见 scene_apply），这层再没有任何状态能点亮它。
    //   ⚠ 明信片那张 176x220 的**带猫**图没被废掉：收藏册和到达卡照旧用它
    //     （DEST_ART[].card），所以 DEST_ART 的两张图都还留着。
    lv_obj_t *travel;

    lv_obj_t *cat;

    // ---- 天气（第四十二轮）----
    // ★ 建序 = 图层序 ⇒ 这两件在 cat **之后**、travel **之前**被立起来
    //   （建对象的地方是 build_weather()，调用点在 build_scene 里）。
    //   「镜头前」= 要盖过猫，所以必须在 cat 之后；
    //   又必须在 travel 遮罩 / HUD / 底栏 / 旅行面板之前 ——
    //   那几个是读数和按钮，雨点糊在上面就没法看了。
    lv_obj_t *wx_cv;                    // 粒子容器（也是「这场天气在不在」的总开关）
    lv_obj_t *wx_obj[WX_P_MAX];         // 粒子池：一次建满，运行期只切显隐
    // ★★ 2026-09-21（第四十五轮）：雾专用的一组图元（不是 image！）。
    //   ⚠ 它们是**同一批子对象**、和 wx_obj[] **互斥使用**：雾那一场只亮这 5 条、
    //     把 wx_obj[] 全部按下去；别的天气反过来。两组的显隐都收在 wx_begin /
    //     wx_end 两处，别在 weather_tick 里临时切（那会变成每帧几十次重排）。
    //   ⚠ 尺寸**每条都不一样**（见 wx_fog_seed），所以每一次雾开场都要重设
    //     size / radius / opa —— 不能像 wx_obj[] 那样「建一次就够」。
    lv_obj_t *wx_fog[WX_FOG_N];

    // ---- 小游戏「接猫罐头」（2026-09-19 第十轮新增）----
    // ★ 整层**建在 ov_dex 之后、ov_intro 之前**：游戏是从收藏册里按进去的，
    //   所以游戏画面必须压住册子；而开场剧情要压住一切（含游戏）。
    // ★ 罐头那 15 个图元（5 个 × 罐身/顶盖/标签带）是**定长对象池** ——
    //   进游戏时建一次，之后一局里只改 x/y 和显隐。相比「每个罐头 create
    //   再 delete」，省掉的是 LVGL 反复分配/回收对象的堆抖动
    //   （C3 没有 PSRAM，这条比省几个对象更值钱）。
    lv_obj_t *ov_mini;
    lv_obj_t *mini_cv;                              // 圆角容器（和 bg_cv 同一套参数）
    lv_obj_t *mini_bg;                              // 240x320：当前挂的风景 / 家的底图
    lv_obj_t *mini_cat;                             // 小猫 56x56（帧和主页那只共用）
    // ★★ 2026-09-19（第十二轮）：下落的罐头从「3 个图元」改成「和 HUD 左上角
    //   那只一模一样的 7 个图元」—— 用户原话：「下落的猫罐头，与之前主界面
    //   使用的猫罐头要是同一张图」。形状逐块照抄 build_hud()，只是坐标整体
    //   减去 HUD 图标原点 (15,5)，落进一个 20x20 的容器里。
    //   （原来那版只有罐身/顶盖/标签带三块，没有描边、没有内盖、没有爪印，
    //     小屏上一比就是两只不一样的东西。）
    lv_obj_t *mini_can       [MINI_MAX_CANS];       // 容器（每帧只动这一个）
    lv_obj_t *mini_can_body  [MINI_MAX_CANS];       // 罐身
    lv_obj_t *mini_can_lid   [MINI_MAX_CANS];       // 顶盖
    lv_obj_t *mini_can_lid_in[MINI_MAX_CANS];       // 内盖
    lv_obj_t *mini_can_label [MINI_MAX_CANS];       // 标签带
    lv_obj_t *mini_can_pad   [MINI_MAX_CANS];       // 爪印掌垫
    lv_obj_t *mini_can_toe   [MINI_MAX_CANS][3];    // 爪印三个脚趾点
    // ★★ 2026-09-19（第十二轮）顶栏重排：左 = 猫罐头（图标 + 数量），
    //   右 = 剩余时间 —— 两处都用和主页 HUD **同一个字号、同一个字色**。
    //   原来左边那格是倒计时、右边是「接住 N」；现在接住数退成中间一行小字。
    lv_obj_t *mini_cnt_ic;                          // 顶栏左上的猫罐头图标（7 个图元）
    lv_obj_t *mini_ic_body, *mini_ic_lid, *mini_ic_lid_in, *mini_ic_label;
    lv_obj_t *mini_ic_pad, *mini_ic_toe[3];
    lv_obj_t *mini_cnt, *mini_score, *mini_time;    // 猫罐头数 / 接住数 / 倒计时
    lv_obj_t *mini_tipbox, *mini_tip;               // 开局提示（半透面板 + 文字）
    lv_obj_t *mini_over;                            // 结算面板
    lv_obj_t *mini_over_t, *mini_over_d, *mini_over_h;

    // ---- 4 个游戏各自的容器（第十六轮）----
    // ★ 每局只显示一个：`pane[g]` 里装着那个游戏的**全部**专属对象。
    //   切换游戏只要一次 add/remove HIDDEN，不用挨个对象管显隐
    //   （那种写法迟早漏一个，而且漏了是静默的）。
    //   ★ 接罐头的猫与罐头池也挪进了 pane[GAME_CAN] —— 统一口径，
    //     免得「三个新游戏按 pane 走、老游戏按裸对象走」两套纪律并存。
    //   ⚠ 四个 pane 全是 0,0 全屏透明容器，所以里面的坐标**和原来一样**，
    //     搬进来的时候一个数都没改。
    lv_obj_t *pane[GAME_COUNT];

    // ---- 打兔子（第十六轮）----
    // ★ 每洞三件，顺序就是建序、也就是图层序，**不能乱**：
    //     rab_box[i]  兔子裁切容器（44x42，默认裁子对象）
    //     rab_img[i]  兔子（bee_a 帧 0，48 缩到 44 ⇒ scale 234）
    //     rab_hole[i] 洞口椭圆 —— **建在兔子之后**，靠它把兔子的下截盖成椭圆弧
    //   ⚠ 这三件的顺序是本轮最容易被「顺手整理」搞坏的一处：
    //     把 rab_hole 挪到 rab_box 前面，兔子就会踩在洞口上沿 —— 正是用户不要的那种。
    lv_obj_t *rab_box [RAB_N];
    lv_obj_t *rab_img [RAB_N];
    lv_obj_t *rab_hole[RAB_N];

    // ---- 剪刀石头布（第十六轮，第十八轮照设计稿重做）----
    lv_obj_t *rps_cat_img;                          // 左边那只猫（64x64，cat_idle）
    lv_obj_t *rps_cat_cv;                           // 「猫出了X」黑框（128x58）
    lv_obj_t *rps_cat_k, *rps_cat_lb;               //   框里的小字（猫出了/猫在想…）+ 大字
    lv_obj_t *rps_card   [3];                       // 三张牌（石 / 剪 / 布）
    lv_obj_t *rps_card_lb[3];
    lv_obj_t *rps_res, *rps_tip;                    // 结果行 / 提示行「▼ 你出什么？」
    lv_obj_t *rps_sub;                              // 副行（5 局后按赢的局数给 1~3 个）
    lv_obj_t *rps_bar, *rps_hint;                   // 底栏通栏条 + 上面那行提示

    // ---- 记忆翻牌（第十六轮）----
    lv_obj_t *mem_cv [MEM_N];                       // 牌底（背面色 / 配对后的正面底色）
    lv_obj_t *mem_img[MEM_N];                       // 牌面图（只在翻开与配对后显示）
    lv_obj_t *mem_cur;                              // 光标框（**只有边框**、无填充）

    // ---- 小游戏选择页（第十六轮新增）----
    //   ★ 它是**独立的一层**（ov_menu），不是 ov_mini 里的一屏：
    //     游戏层进来时要把整个菜单收掉，而且菜单自己带背景图与四行文字；
    //     混进游戏层会让「游戏内顶栏 / 结算面板」在菜单上一起显出来。
    //   建序：ov_dex -> ov_menu -> ov_mini -> ov_intro
    //     （菜单压住册子；游戏压住菜单；开场剧情压住一切）
    lv_obj_t *ov_menu, *menu_bg, *menu_dim;
    lv_obj_t *menu_title, *menu_prog, *menu_hint;
    lv_obj_t *menu_row   [MENU_CELL_N];             // 卡片底
    lv_obj_t *menu_row_lb[MENU_CELL_N];             // 主行：游戏名（未解锁那格写「未解锁」）
    lv_obj_t *menu_row_sb[MENU_CELL_N];             // 副行：解锁状态（已解锁 / N 张解锁）
    // ---- 卡片图标（第十八轮）----
    //   ★ 每张卡一个 44x44 的**透明容器**（menu_ic[i]），四枚图标的所有子件
    //     都挂在自己那个容器里。好处有两个：
    //       ① 压暗只需要递归走容器（menu_icon_dim），不用逐游戏写清单；
    //       ② 将来卡片挪位置（MENU_CELL_X/Y），图标跟着走，一个数都不用改。
    lv_obj_t *menu_ic[MENU_CELL_N];
    lv_obj_t *menu_ic_can[8];                       //   接猫罐头：罐头那 8 块图元
                                                    //   ★★ 必须是 **8**，不是 7：
                                                    //     罐身/顶盖/内盖/标签带/掌垫 5 块 +
                                                    //     三个脚趾点 3 块 = 8。写成 7 的话
                                                    //     k=2 那一轮写到下标 7 就是**越界写**，
                                                    //     GCC 会报 -Waggressive-loop-optimizations
                                                    //     （第一次编译就报了，别忘了看 warning）。
    lv_obj_t *menu_ic_rab;                          //   打兔子：bee_a 帧 0
    lv_obj_t *menu_ic_rps[3], *menu_ic_rps_lb[3];   //   猜拳：三张小牌 + 牌上的字
    lv_obj_t *menu_ic_mem_cv[3], *menu_ic_mem[3];   //   翻牌：三张小牌 + （一张图/两个问号）

    // ---- 「新获得」闪字 + 全解锁横条（第十六轮）----
    //   ★ 两者都建在 **U.ov_card** 上（到达卡内部），不是 ov_dex ——
    //     用户点名的是「收到明信片的图片上」，而那张图在到达卡里。
    //   ⚠ nb_bg / nb_in 两层是**假描边**：外层深棕、内层橙。
    //     位图字库做不出真描边（见常量块那一段的 ⚠）。
    lv_obj_t *nb_bg, *nb_in, *nb_lb, *nb_star[3];
    lv_obj_t *allbar, *allbar_lb;

    // ★ 2026-09-19（第五次）从这里删掉的字段：
    //   house（精灵小屋）、yard[4] 与 yard_mark / yard_panel / yard_title /
    //   yard_hint（小院与小院模式）、hud（那条不透明状态条的底板）。
    //   三叶草 / 电量 / 校时点现在**直接建在 U.scr 上** —— 没有底板，
    //   它们就压在底图的天空上，这正是用户要的。
    //
    // ---- HUD 左上的猫罐头图标（2026-09-19 第九轮）----
    // ★ 原来是三个圆拼一片三叶草（clover_dot[3]）。用户原话：「把三叶草换成猫罐头」。
    //   这里**仍然不走素材** —— 与图集无关、不占一个字节 flash：20x20 的图标用
    //   六个图元拼出来（罐身 / 顶盖 / 内盖 / 标签带 / 掌垫 / 三个脚趾点）。
    //   形状取自第九轮那张候选图里的 **D（矮胖+爪印）** —— 四个候选里小屏轮廓最清楚的。
    // ★ 对象数 3 -> 7，全是建一次就不再动的定长对象，符合本文件开头的性能纪律。
    lv_obj_t *can_body, *can_lid, *can_lid_in, *can_label, *can_pad;
    lv_obj_t *can_toe[3];
    // ★★ 2026-09-19（第十二轮）新增 batt_ic：电量从「一行文字」变成
    //   「一张三态图 + 一行文字」（用户：「电量做三张图…然后根据情况更换」）。
    lv_obj_t *batt_ic;
    // ★★ 第十三轮删掉 wifi_dot（校时状态点）—— 见 build_hud 末尾那段说明。
    lv_obj_t *lb_clover, *lb_batt;

    // ★ 多一格：最后一格是「收集」，不是时长
    // ★ 第四次改版删掉了 bar_under（底栏草地底衬）—— 底图铺到屏幕最下沿之后，
    //   底栏收起来露出的就是照片本身，不需要再垫一层同色矩形。
    lv_obj_t *bar, *pill[FA_SLOT_COUNT + 1], *pill_lb[FA_SLOT_COUNT + 1];

    lv_obj_t *ov_away, *away_title, *away_time, *away_hint;
    lv_obj_t *away_bar_bg, *away_bar_fg;

    lv_obj_t *ov_card;
    lv_obj_t *card_img;              // ★ 真明信片（176x220 素材原图）
    lv_obj_t *card_sky, *card_sun, *card_water, *card_hill_box, *card_hill[2];
    lv_obj_t *card_name, *card_verse, *card_gain, *card_souv, *card_hint;
    // ★ 第十四轮：到达卡那张明信片的四角角标（和收藏册同款，见 build_card）。
    lv_obj_t *card_art_cv;

    // 收集册 = 一台「明信片浏览器」，一次看一件。
    // ★★ 2026-09-19 版面重做：整页就是**一张和「到达卡」一样的白卡**
    //   （白底圆角 + 176x220 真明信片 + 地名 + 题词 + 序号），
    //   实测反馈「地点到达的时候，那种卡片处理方式就比较好」——
    //   那就让收集册直接用同一套版式，两边看起来是同一件东西。
    //   原来的 36 颗进度点阵（5px 一颗）已下线：它有名字没画面、又挤在屏幕最底，
    //   实际看不清；总量改成顶栏一行字（明信片 x / 24）。
    //   ★ 第五次整册只剩「家 + 明信片」，顶栏那行也就只剩明信片一个数
    //     （见 dex_progress_text）—— 「纪念品 y / 12」没了，因为展示页没了。
    // ★★ 2026-09-19（第十二轮）收藏册顶栏改了两处：
    //   ① 底色 C_HUD(米白) -> C_DARK(暖黑)，并且补上圆角 + clip_corner；
    //   ② 右上角那颗橙色「● 返回」**去掉**，换成电量（图标 + 数字）。
    //   用户原话：「收藏界面的底色调整为黑色。」「收藏界面右上角的返回去掉，电量。」
    //   —— 怎么退没有变：● 短按本来就是出册（fa_view_dex_ok），
    //     原来那颗胶囊只是把这件事写在脸上，现在让位给电量。
    //   ⚠ dex_back / dex_back_lb 两个字段连同各页对它的 set_text 一起删了，
    //     别只删 build 不删 dex_refresh —— 那样是编译期报错（字段没了），
    //     反而好；怕的是有人「先补一个字段让它编过」，那就留下一个永不显示的鬼。
    lv_obj_t *ov_dex, *dex_card, *dex_title, *dex_hint;
    lv_obj_t *dex_batt_ic, *dex_batt;          // 顶栏右上：电量图标 + 数字
    // ★★ 2026-09-19 第十三轮：dex_over（封面位图）换成 dex_mask + 两行文字。
    // ★★★ 第十四轮：标题改成**两段不同字号**，见 build_dex。
    //   dex_mask_t1 「接罐头」24px 黑体 Bold（fa_font_game）
    //   dex_mask_t2 「小游戏」16px 黑体 Bold（fa_font_ui，跟底栏时长选择同一支）
    //   ⚠ 第十四轮本来排的是一个横排 flex 容器（dex_mask_t）来自动居中，
    //     但这份固件的 LVGL 把 **CONFIG_LV_USE_FLEX 关掉了**，编译期就报
    //     `lv_obj_set_flex_flow` undeclared ⇒ 容器这个字段已经删掉，
    //     改成两个 label 各自 place()。**别再把它加回来。**
    lv_obj_t *dex_art, *dex_img, *dex_mask, *dex_mask_r;
    lv_obj_t *dex_mask_t1, *dex_mask_t2;
    // ★★★ 第十四轮：**明信片自己的四角角标。**
    //   第十三轮把全工程的 clip_corner 删干净（它把 LVGL 的 64KB 堆压爆了，
    //   见 build_scene 里那段长注释），副作用是收藏册里的明信片**变回了方角**
    //   —— 用户这一轮点名：「收藏中的明信片，之前好像是圆角，都改为圆角吧，
    //   方角太突兀了。」
    //   ⚠ 恢复圆角**不能**再把 clip_corner 加回来：那正是卡死的根因。
    //     这里用的是和 build_corners 完全同款的「零图层角标」技巧 ——
    //     一个比图位大一圈、只画边框不填充的圆角矩形，边框落在图位内的那部分
    //     恰好就是四个直角。完整推导（含为什么 B 只能取 4）见 build_dex。
    lv_obj_t *dex_art_cv;
    lv_obj_t *dex_name, *dex_verse, *dex_idx, *dex_empty;

    // ---- 2026-09-20（第二十轮）：「小游戏 / 设置」上下两格 ----
    //   ★ 只在 DEX_ENTRY_PLAY 那一格显示，所以和 dex_mask 用**完全相同的收放纪律**：
    //     收在 dex_refresh() 开头一处、放在 PLAY 分支一处（谁亮谁灭只有两个点）。
    //   ⚠ 这两格**不能**和 U.dex_img 同时露脸 —— 它们盖的是同一个图位。
    //     PLAY 分支必须把 U.dex_img 收起来，别的地方由 dex_show_bg / dex_show_card
    //     自己 remove_flag（那两个函数本来就在做这件事）。
    lv_obj_t *dex2_up_cv,  *dex2_up_img,  *dex2_up_cv2, *dex2_up_dim;
    lv_obj_t *dex2_up_t1,  *dex2_up_t2;                 // 「小游戏」/「收集明信片 解锁更多小游戏」
    lv_obj_t *dex2_dn_cv,  *dex2_dn_img,  *dex2_dn_dim, *dex2_dn_cv2;
    lv_obj_t *dex2_dn_t1;                               // 「设置」
    lv_obj_t *dex2_up_cat, *dex2_dn_cat;                // 两只猫（第二十三轮起：56x56，cat_read / cat_write 动画）

    // ---- 2026-09-21（第四十七轮）：**纪念品图鉴**（收藏册里的一格，两页 3x4）----
    //   ★ 和 dex2 那两格**同一套收放纪律**：收在 dex_refresh() 开头一处、
    //     放在 SOUV 分支一处。谁亮谁灭永远只有两个点。
    //   ⚠ 只建 **12 格**（= 一页），两页共用、翻页时重画 —— 见 SOUV_PER_PAGE 那段。
    //   ⚠ 网格盖的是**整个卡片**（含图位和 dex_name/verse/idx 那三行字所在的位置），
    //     所以 SOUV 分支要把 U.dex_img、U.dex_art_cv 一起收掉，
    //     并把 dex_name/verse/idx 三行**清空**（不是 HIDDEN，理由同 PLAY 页）。
    lv_obj_t *souv_grid;                    // 12 格的容器（收放只认它一个）
    lv_obj_t *souv_img[SOUV_PER_PAGE];      // 12 个图标
    lv_obj_t *souv_name[SOUV_PER_PAGE];     // 12 个名字（未获得时 HIDDEN + 空串）

    // ---- 2026-09-21（第四十五轮）：**设置页**（从上面「设置」那一格按 ● 进来）----
    //   ★ 一整层独立浮层，不是收藏册卡片里的一页 —— 完整理由见 SET_CARD_X 那段常量块。
    //   ⚠ 只有亮度这一项：用户同轮明确「屏幕方向不加，没必要」。
    //     （方向仍在主界面**长按 ↓**，见 main.c 的 on_long。别顺手搬进来。）
    //   ★ 那一排 5 格亮度条：只存 5 个对象，颜色在 set_refresh() 里现改 ——
    //     不去建「亮格 / 空格」两套再切显隐，5 个地方各一个判据更容易漏。
    lv_obj_t *ov_set, *set_card, *set_title;
    lv_obj_t *set_rule[SET_RULE_N];        // 两条分隔线（第四十六轮由 3 条减到 2 条）
    lv_obj_t *set_br_lb;                   // 「屏幕亮度」
    lv_obj_t *set_bar[SET_LV_N];           // 亮度 5 格
    lv_obj_t *set_key_rows;                // 14 行键名（左列，**一个 label 装全部行**）
    lv_obj_t *set_key_vals;                // 14 行说明（右列，同上）
    // ★ 第四十六轮从这里删掉的四个字段（都别再回来）：
    //     set_br_val   —— 右上角的「4/5」（和第一格压在一起）
    //     set_br_hint  —— 「按上下键调节」（和表里的「上下键」重复）
    //     set_key_lb   —— 「按键」这个小标题（三块表自己带【】标题了）
    //     set_foot     —— 底部三行提示（三件事都进表了）

    // ★ 2026-09-19（第五次）这里删掉了三组字段：
    //   dex_sky / dex_sun / dex_hill_box / dex_hill[2] / dex_water
    //     —— 那五块程序化兜底小风景；
    //   dex_grid 与 souv_img[12] / souv_lb[12]
    //     —— 纪念品那一页合集。
    //   理由：收集册只剩「家 + 明信片」两样，而这两样**每一页都有真图**，
    //   兜底色块和合集格子都没有要出现的场合了。

    lv_obj_t *ov_intro, *intro_title, *intro_body, *intro_img, *intro_hint;
    lv_obj_t *intro_dot[3];

    lv_obj_t *toast, *toast_lb;

    // ---- 猫咪对我说的话（第十八轮）----
    //   ★ 建在 U.scr 上（不是 ov_dex/ov_mini 里）：它只在「在家且没有任何浮层」
    //     时出现，而那个判据集中在 talk_gate() 一处。挂进某一层反而要多想一件事。
    lv_obj_t *talk, *talk_lb;
    // ~~★ 第二十五轮：气泡下头那个尖角（尾巴），`lv_obj_t *talk_tip;`~~
    //   **第二十六轮撤掉了**（用户：「没有尾巴的」）⇒ 气泡又变回**单个对象**，
    //   不再有「先建尾巴、z 序压在气泡下」那一套。留痕的理由：
    //   只看到新代码的人会以为这里本来就该有个尾巴字段。
    //   ⚠ 别顺手把它加回来 —— 加回来还要连带恢复 TIP_* 常量、建/收/放/换边四处，
    //     以及「旋转会临时分配 3KB layer」那条代价（见 build_talk 的注释）。
    // ★★ 2026-09-19（第十三轮）四角角标。见 build_corners —— 它必须**最后建**，
    //   是全屏 z 序最高的一层。整个工程的四角只由这一个对象负责，
    //   任何新加的全屏层都不需要再自己管圆角。
    lv_obj_t *corners;
};

static struct ui U;

typedef enum {
    SEQ_NONE = 0,
    SEQ_PACK,      // 收拾行李
    SEQ_WALKOUT,   // 向右走出画面右侧
    SEQ_WALKIN,    // 从左侧走回原位
    SEQ_GREET,     // 站定、放下包
    // ★ 下面两个是「在家闲着」的两种姿态，不是出发/归来的一环：
    //   溜达到另一边、到了坐下歇一会儿。
    SEQ_STROLL,    // 在家左右溜达
    SEQ_SIT,       // 到了地方，坐下歇着
} fa_seq_t;

static fa_play_t   s_cat_play;
static int         s_seq;
static uint32_t    s_seq_ms;
static int32_t     s_cat_x;
static int32_t     s_stroll_tx;  // 本次溜达的目的地 x
static uint32_t    s_sit_ms;     // 这次坐下要坐多久
static uint8_t     s_seen_state;
static bool        s_card_up;
static uint32_t    s_idle_ms;
static uint32_t    s_toast_ms;
static int         s_sel;        // 底部选择器：0..FA_SLOT_COUNT-1 = 时长，FA_SLOT_COUNT = 收集
static int         s_intro_page; // 开场剧情当前页
static fa_play_t   s_intro_play;

// HUD 缓存 —— 只有值真的变了才写 label
static uint16_t s_last_clover = 0xFFFF;
static uint32_t s_last_wifi   = 0xFFFFFFFF;
static int      s_last_batt   = -2;
// ★ 2026-09-19（第三次）：这个标志的含义从「电量计可用」改成「**上次读到了没有**」。
//   旧写法是「读不到就 s_batt_ok = false」并且**再也不读** —— 一次失败就永久关掉。
//   CW2017 刚切到正常模式时 SOC 还没算完，开机那一下读到 0xFF 是很正常的，
//   结果整机运行期间电量那一格就永远是空的。现在失败只是把重试间隔放长。
static bool     s_batt_ok;
static uint32_t s_batt_ms;
// ★ 2026-09-19（第五次）新增的两个 HUD 状态（顶栏没有底色之后才需要）：
//   s_batt_soc —— 最近一次读到的电量，-1 = 没读到。hud_paint() 要拿它决定
//     低电量那档红字，但不能自己去读 I2C（那是阻塞的，而 hud_paint 会在
//     旅行状态翻转时被顺手调一下）。
//   s_hud_dark —— 底下是暗的吗（旅行遮罩压着）。真 = 顶栏文字换暖白。
static int      s_batt_soc = -1;
static bool     s_hud_dark;
// 快速返回的价钱缓存。初值 -2 而不是 0/-1：那两个都是合法值（免费 / 不能召回），
// 用它们当「还没算过」的哨兵，第一帧就不会去更新那行字。
static int      s_last_recall_cost = -2;

// ★★ 2026-09-19（第十六轮）：「新获得」闪字的三态。
//   s_nb_on —— 这一张卡上有没有那三个字（判据 = got_flags bit0，见 card_fill）。
//   s_nb_ph —— 当前处在「亮」还是「暗」那半拍。
//   闪烁**不做在 card_fill 里**：card_fill 是「画一次」的地方，它只把这颗
//   相位**复位成「亮着」**；翻拍靠 fa_view_tick 里每 NB_BLINK_MS 翻一次。
//   ⚠ 不复位的话会出现「这张明明是新的，字却是暗的」—— 相位是从上一张卡
//     带过来的，看着像漏了一半动画。
static bool     s_nb_on;
static bool     s_nb_ph = true;
static uint32_t s_nb_ms;

// 前向声明：底部选择器那一节（fa_view_sel_move）要调 bar_refresh，
// 但它的定义排在文件更靠后的位置。static 函数也要先声明再用。
static void bar_refresh(void);
static void hud_paint(void);   // 顶栏配色：只写样式、不读硬件（见 batt_show 旁边）
// ★★ 2026-09-19（第十六轮）新增：小游戏的结算函数**被四个游戏各自的 tick 调用**
//   （rab_tick / rps_tick / mem_tick / can_tick），而它的定义在它们**之后**。
//   不声明就是 `implicit declaration of function 'mini_finish'`，
//   紧接着还有一条更绕的 `static declaration follows non-static declaration` ——
//   两条一起报会让人以为是定义写错了，其实是**顺序**问题。
//   ⚠ 以后往这一族里加「先被调用、后定义」的函数，都往这里放一条。
static void mini_finish(void);

// ★★ 「忙」= 只有出发/归来那四个序列。
//   这个判断被按键派发（fa_view_busy）、底栏显隐（bar_refresh）、
//   选择器与收集册的入口守卫共用，所以必须只有一个定义。
//   ⚠ 千万别写成 s_seq != SEQ_NONE：猫在家溜达（SEQ_STROLL/SEQ_SIT）
//     会有一半时间是「非 NONE」状态，那样猫一走开，玩家就选不了档位、
//     也开不了收集册 —— 界面看着一切正常，只是按键全被吞掉。
static bool seq_departing(void)
{
    return s_seq == SEQ_PACK || s_seq == SEQ_WALKOUT ||
           s_seq == SEQ_WALKIN || s_seq == SEQ_GREET;
}

// ------------------------------------------------------------------ 小工具

static lv_obj_t *mk_box(lv_obj_t *parent, int x, int y, int w, int h,
                        uint32_t color, int radius, lv_opa_t opa)
{
    lv_obj_t *o = lv_obj_create(parent);
    lv_obj_remove_flag(o, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_pos(o, x, y);
    lv_obj_set_size(o, w, h);
    lv_obj_set_style_pad_all(o, 0, 0);
    lv_obj_set_style_border_width(o, 0, 0);
    lv_obj_set_style_radius(o, radius, 0);
    // ★ bg_color 一律显式写死，哪怕这层是透明的。
    //   反过来（透明时省掉 bg_color）埋了个雷：以后任何地方把这层 opacity
    //   改成 COVER，露出来的是 LVGL 主题默认底色（近白），而你以为是自己设的颜色。
    lv_obj_set_style_bg_color(o, lv_color_hex(color), 0);
    lv_obj_set_style_bg_opa(o, (opa == LV_OPA_TRANSP) ? LV_OPA_TRANSP : opa, 0);
    return o;
}

static lv_obj_t *mk_label(lv_obj_t *parent, const lv_font_t *font,
                          uint32_t color, const char *text)
{
    lv_obj_t *l = lv_label_create(parent);
    lv_obj_set_style_text_font(l, font, 0);
    lv_obj_set_style_text_color(l, lv_color_hex(color), 0);
    lv_label_set_text(l, text);
    return l;
}

static void place(lv_obj_t *o, int x, int y, int w, int h)
{
    lv_obj_set_pos(o, x, y);
    lv_obj_set_size(o, w, h);
}

// ★★ 2026-09-19（第十三轮）**hud_chip() 已整块删除**，别再加回来。
//   它原来给顶栏那几个字各垫一小块 40% 暖黑（padding 3/1、圆角 5px），
//   用来让白字在浅蓝天空上立得住。第十二轮上线，第十三轮用户实机否掉：
//   「主页面上面的猫罐头的数字和电量的数字后面的黑色背景，太丑了，去掉。」
//   ⇒ 衬底一律取消：HUD / 收藏册顶栏 / 小游戏顶栏三处**都不再有黑底**。
//   ⚠ 代价诚实记在这里：白字压在底图那片浅蓝天空（实测 RGB 约 168,216,232）
//     上对比度最低。补偿手段只剩「把字做大」这一条 ——
//     所以第十三轮把这三处的字号从 fa_font_tiny(11) 提到了 fa_font_ui(15)，
//     并且**不要再把字色改回 C_TEXT**：用户要的就是白的。
//   ⚠ 真正能根治的做法是给底图顶部那条天空留出更暗的渐变（素材侧的事），
//     不是在这儿重新加一层底。

// ================================================================== 天气图层（第四十二轮）
//
// ★ 一句话：把早就画好、一直躺在下线名单里的四条特效素材接上线，
//   在主界面和旅行界面之上飘一层**镜头前**的天气粒子。
//
// ★ 素材不是这一轮画的。fx_rain / fx_snow / fx_steam / fx_sparkle 这四条
//   从建表起就在 tools/gen_fa_sprites.py 的 OFFLINE 名单里躺着，那条注释的原话是
//   「fx_* 8 条 —— 特效一次都没接」。本轮把 4 条取回来（另 4 条继续线下：
//   fx_flag 是一面旗，fx_burst / fx_halo / fx_bubble 都是 64x64 的大特效）。
//   开工前我把这 4 条逐帧放大 5 倍数过可见像素，结论直接决定了下面的参数：
//     fx_rain     4 帧   55~ 66 px   —— 一格 24x24 里是**好几道斜雨丝**
//     fx_snow     4 帧  149~157 px   —— 一格里是**好几片雪花**
//     fx_steam    4 帧   51~124 px   —— 一缕竖直上升的水汽
//     fx_sparkle  8 帧    7→138→9    —— **一炸一收**的爆发循环（不是常亮的小星）
//   ⇒ 两个推论：
//     ① 雨和雪的一格**本身就含多道 / 多片**，所以粒子数不用堆到几十个 ——
//        18 格雨铺在 240x320 上，视觉上已经是「一片雨」而不是「18 根棍」。
//     ② sparkle 是爆发循环 ⇒ 它一个粒子就是「一闪」。要星空感，靠的是
//        **把十几颗的相位错开**（见 wx_begin 里那句随机帧），不是加数量。
//
// ★ 静默期**零成本**：不活跃时容器 HIDDEN、粒子也各自 HIDDEN，一个像素都不混合。
//   这一屏任何时刻最多只有一种天气在跑。
//
// ⚠⚠ 这一节有两条硬件约束必须守住（都是踩过的）：
//   ① **绝对不许给容器或粒子加 radius / clip_corner**。
//      第十三轮那次「收藏卡死」的根因就是它：圆角每次重绘都要为上下两段各建一层
//      ARGB8888 临时缓冲，按本容器 240x320 的尺寸算，单对象峰值远超 64 KB 堆
//      （CONFIG_LV_MEM_SIZE_KILOBYTES=64，且 EXPAND_SIZE=0，涨不了）。而 LVGL
//      爆堆之后走 LV_ASSERT_HANDLER，本机**没配 handler** ⇒ 取默认值 `while(1);`
//      —— **不是崩溃、不是重启，是原地死循环**，表现是屏幕定格在画到一半的那一帧。
//      完整推导见 build_scene 里那一段长注释。
//   ② **粒子池一次建满、只切显隐**，不在运行期 malloc/free。
//      64 KB 的堆经不起每 90 秒一轮「建 18 个对象 / 拆 18 个对象」的碎片化 ——
//      那种 bug 要跑几小时才现形，而且现象是随机的。

// 一个粒子。坐标是**屏幕坐标**：容器 place 在 (0,0)，所以「相对容器」就是「相对屏幕」。
typedef struct {
    int16_t  bx;    // 摆动**基准** x —— 真正落位的 x 是 bx + wx_swing()
    int16_t  y;
    int16_t  vx;    // 像素 / 秒（可正可负）
    int16_t  vy;
    uint8_t  amp;   // 横向摆动幅度（像素），0 = 不摆。只有雪用得上。
    uint16_t ph;    // 摆动相位 0..1999（一整周 = 2 秒）
} wx_p_t;

// 一条雾带。★ **故意不复用 wx_p_t** —— 两者要的字段几乎不重叠：
//   雾带是「一条固定高度、宽度可变、只横向飘」的矩形，没有摆动相位、
//   没有纵向速度、也不需要帧相位（它不是动画）。
//   硬塞进 wx_p_t 会变成「一半字段永远是 0」，那种结构不用多久就没人敢改。
typedef struct {
    int16_t x;      // 左端 x（雾带用**左上角**存，不是中心 —— 宽度是变的）
    int16_t y;      // 上沿 y（整场天气里不变）
    uint8_t w;      // 宽度
    int8_t  vx;     // 横向速度（像素/秒，恒正 = 一直往右飘）
} wx_fog_t;

static wx_p_t    s_wx_p[WX_P_MAX];
// ★ 每个粒子**各自**一个播放器 —— 这样帧相位互相独立。
//   共用一个播放器的话，18 个粒子会永远同步在同一帧上（看着像一块布在抖）。
static fa_play_t s_wx_play[WX_P_MAX];
// 雾那 5 条带的状态。★ 和 U.wx_fog[] 是**成对**的（U 里存指针、这里存状态），
//   所以 fa_view_init 里必须和 s_wx_p / s_wx_play 一起 memset —— 见那边的注释。
static wx_fog_t  s_wx_fogp[WX_FOG_N];
static uint8_t   s_wx_n;                    // 这次天气放出来几个粒子
static uint8_t   s_wx_kind = WX_NONE;       // 当前天气号（WX_NONE = 没有天气）
static uint32_t  s_wx_left;                 // 这次天气还剩多少毫秒
static uint32_t  s_wx_wait = WX_FIRST_MS;   // 距下一次天气还有多少毫秒

// ★ 有待说的天气句吗（-1 = 没有，否则 = 天气号）。
//   ★★ 这个变量定义在**天气这一节**、而不是 talk 那一节，是因为 wx_begin() 要写它
//      （本节的代码在前面），读它的是 talk_tick / talk_pick。
//   语义：天气一起来就挂个号；猫把那句说掉之后归 -1（**只说一句**，不反复说）。
static int       s_wx_talk_kind = -1;

// ★★ 2026-09-20（第四十三轮，实机故障排障）：**浮层开着吗** —— 只用来抓「开合的那一帧」。
//   这一轮实机反馈：「主界面只要操作了收集，或者去旅行的时间，立马就被卡死」。
//   根因见 wx_mem_log 上面那段；这里存的是**上一帧**的 busy 值，
//   因为开合那一刻要做两件一次性的事（打日志 + 收起 / 放回整层天气），
//   而不是每帧都做一遍。
//   ⚠ 别拿它当 overlay_busy() 用：浮层**开着期间换页**（册子→选择页）它不会变。
static bool      s_wx_ov;

// 每种天气：播哪条动画 / 放几个粒子 / 多少毫秒翻一帧。
//   ★ 粒子数是按素材的**像素密度**反推的，不是拍脑袋：
//     雨一格约 60 px（很疏，全是细线），要 22 格才铺得开；
//     雪一格 150 px（密），16 格就够；
//     萤火一格只有一个点（最疏），靠数量 + 相位错开才有「一片萤火」的感觉；
//     飞机 / 热气球是**大件**（38~42 px），2 个已经是「偶尔飞过一架」的密度，
//     再多就变成机场了；泡泡介于中间，8 个。
//   ★ 帧间隔按「动感强度」定：雨丝要抖得急（80），螺旋桨要转得快（60）。
//     太快像闪、太慢像贴纸。
//
// ★★ 2026-09-21（第四十五轮）7 种。逐条的取值理由：
//     WX_RAIN    22 个 —— 旧版 18 个。用户嫌旧素材「是色块」，新素材改成了
//                        1px 细线（单格像素数没变，但**读起来更疏**），
//                        所以数量从 18 加到 22 把密度补回来。
//     WX_SNOW    16 个 —— 数量不动，只是显示尺寸 27 -> 22（用户要「调小」）。
//     WX_FOG      5 条 —— 图元，不是粒子。**WX_ANIM 那一格写 NULL**。
//     WX_FIREFLY 18 个 —— 原来星光 14 个，现在萤火的点更小，加一点数量。
//     WX_PLANE    2 个 —— 横穿屏幕的大件。
//     WX_BALLOON  2 个 —— 同上。
//     WX_SOAP     8 个 —— 从天上往下飘。
//
//   ⚠ WX_ANIM 里那个 **NULL 是雾的位置**，play_set 拿到 NULL 是安全的
//     （fa_anim_find(NULL) 直接返回 NULL，见 fa_sprites.c）——但那一路
//     本来就不会被走到：wx_begin 里雾走的是独立分支。
static const char *const WX_ANIM[WX_KIND_N] = {
    "fx_drop", "fx_snow", NULL /* 雾走图元 */, "fx_firefly",
    "fx_plane", "fx_balloon", "fx_soap",
};
static const uint8_t  WX_USE[WX_KIND_N]  = { 22, 16,  5, 18,  2,  2,  8 };
static const uint16_t WX_FMS[WX_KIND_N]  = { 80, 150, 0, 220, 60, 140, 130 };

// ★★★ 2026-09-21（第四十五轮）：**天气号直接当 FA_TALK_WX 的行号用**
//   （见 talk_pick 里那句 `FA_TALK_WX[k][s_talk_ord_wx[...]]`，k = s_wx_kind）。
//   所以 WX_KIND_N 和 FA_TALK_WX_GROUPS **必须相等**。
//   不等就是**越界读**：那边是按行号取字符串指针，多出来的行号会读到
//   FA_TALK_WX 数组后面的东西（大概率是 FA_TALK_SCENE 或 BASE 的表头）——
//   症状是「起了雾，猫却说了一句通用台词」，看着完全不像数组越界，
//   而且**编译期一个字都不会提示**。
//   ⇒ 在这里卡死。生成器 _dl/_talk45.py 里也有一条同样的对账（改数据时先报错）。
//   ⚠ 加天气 / 减天气时，这两处（还有 FA_TALK_WX 本身）必须一起动。
_Static_assert(WX_KIND_N == FA_TALK_WX_GROUPS,
               "WX_KIND_N 必须等于 FA_TALK_WX_GROUPS（天气号=台词行号）");

// ★★ 放大倍数 / 显示边长。这两列不是调着玩的，是照「看得见吗」量出来的。
//   第一版一律 1:1（scale 256）时，四种天气在实机上几乎都看不见：
//     · 雨——一格 24x24 里只有约 60 个像素是雨丝（占 10%），1:1 铺在 240x320 上
//            就是一层若有若无的小白点；· 雾——完全看不见；· 雪、星光偏稀。
//   放大之后才立住（对照图在交付报告里）。
//   ⚠ 倍率是按**素材各自的内容**定的，不是统一一个数：
//     雨丝本来就细长，放大过头就晕；雪片是大团的，放太多像屋顶糊了块污渍；
//     萤火的点是圆的，放大反而失去「一点微光」的锐度。
//   ⚠ **边长 = ceil(24 * scale / 256)**，这个数**必须和 scale 同时改** ——
//     对象框比图小的话，图会被裁掉一圈（inner_align 那条纪律见 build_weather）。
//     实际对照表（第四十五轮，七种）：
//       scale 234 -> 21.94 -> ceil **22**   雨、雪
//       scale   0 ->  ——                    雾（不走素材，这一格是占位）
//       scale 170 -> 15.94 -> ceil **16**   萤火
//       scale 448 -> 42.00 ->      **42**   小飞机
//       scale 405 -> 37.97 -> ceil **38**   热气球
//       scale 277 -> 25.97 -> ceil **26**   肥皂泡泡
//   ⚠ 雨 / 雪取 234 而不是 235：235 算出来是 22.03，ceil 之后是 23，
//     会白白把粒子撑大一圈，还可能让 22 个粒子在横向上更容易挤在一起。
static const uint16_t WX_SCALE[WX_KIND_N] = { 234, 234,   0, 170, 448, 405, 277 };
static const uint8_t  WX_SIDE [WX_KIND_N] = {  22,  22,   0,  16,  42,  38,  26 };

// 带符号的随机（闭区间 [lo, hi]）。
//   ★ 这不是「包装一下更好看」，是**必须**：LVGL 的 lv_rand 形参是 uint32_t，
//     喂负数是未定义行为 —— 传 -24 会被当成 4294967272，回来的东西完全不是
//     我们想要的。本节的坐标、速度到处是负值（雨往左下飞），所以这一层不能省。
static int wx_rand(int lo, int hi)
{
    if (hi <= lo) return lo;
    return lo + (int)lv_rand(0, (uint32_t)(hi - lo));
}

// 横向摆动量。
//   ★ 用**三角波**而不是 sin：纯整数、无浮点、无查表。C3 是 160MHz 单核、
//     还没开 LVGL 的汇编优化，每帧十几二十次这种乘除是可以忽略的开销；
//     而为了一个左右各几像素的摆动去引浮点 sin，不值得也不必要。
//   相位 0..1999 → 先折成 0..1000..0 的三角，再映射到 -amp..+amp。
static int wx_swing(const wx_p_t *p)
{
    if (!p->amp) return 0;
    const int t   = (int)(p->ph % 2000u);
    const int tri = (t < 1000) ? t : (2000 - t);        // 0..1000..0
    return (tri - 500) * (int)p->amp / 500;             // -amp..+amp
}

// 这个粒子跑出画面了吗。★ 判定**随天气不同** —— 七种天气的运动方向分成四类：
//     往下落：雨（还带横向风）、雪、肥皂泡泡
//     往上飘：萤火
//     横着穿：小飞机、热气球（左右两个方向都算）
//     不走这里：雾（它是图元、走 wx_fog_* 那一套）
//   判据只写这一处，调用点也只有一个（weather_tick 里），不会两处走样。
static bool wx_out(const wx_p_t *p)
{
    // 用的是**当前天气的放大后边长**（WX_SIDE），不是素材原始那 24 ——
    //   粒子放大之后，"完全离开画面"的那条线也跟着往外挪了。
    const int side = (int)WX_SIDE[s_wx_kind];
    switch (s_wx_kind) {
    case WX_RAIN:    return (p->y > SCR_H + side) || (p->bx + wx_swing(p) < -side);
    case WX_SNOW:    return (p->y > SCR_H + side);
    case WX_SOAP:    return (p->y > SCR_H + side);
    case WX_FIREFLY: return (p->y < -side);                 // 一路往上，飘出顶
    // ★ 横穿的两种：**左右两侧都要判**。只判一侧的话，反向的那一架会
    //   永远卡在屏幕外那一侧（它再也不会被 wx_seed 复活），
    //   表现是「飞机偶尔出现，然后就没有了」——静默、只在反向时出现。
    case WX_PLANE:
    case WX_BALLOON: return (p->bx < -side) || (p->bx > SCR_W + side);
    default:         return true;                           // WX_FOG / WX_NONE
    }
}

// 给第 i 个粒子一次新生命。
//   anywhere = true  —— 天气**刚开始**：位置就散落在画面各处，一上来就「已经在下」，
//                       而不是先看到十几根雨丝整整齐齐从顶上掉下来。
//   anywhere = false —— 刚才跑出画面了：从**对应那一条边**重新进场，
//                       绝不凭空出现在画面中间。
static void wx_seed(int i, bool anywhere)
{
    wx_p_t *p = &s_wx_p[i];
    // ★ 用的都是**放大后**的边长（WX_SIDE），不是素材原始那 24 ——
    //   不然新生粒子会停在画面外一整格的地方才开始飘进来。
    const int side = (int)WX_SIDE[s_wx_kind];

    switch (s_wx_kind) {
    case WX_RAIN:
        // 往左下斜落。速度**逐粒子不同**（380~560 px/s）—— 齐步走的下落
        // 看着像一块布在平移，速度一散开才像雨。
        p->bx  = (int16_t)wx_rand(-side, SCR_W);
        p->y   = (int16_t)(anywhere ? wx_rand(-40, SCR_H) : wx_rand(-70, -side));
        p->vx  = (int16_t)wx_rand(-110, -70);
        p->vy  = (int16_t)wx_rand(380, 560);
        p->amp = 0;
        break;
    case WX_SNOW:
        // 慢慢飘，边走边左右摆 —— 这是雪和雨最大的区别。
        p->bx  = (int16_t)wx_rand(0, SCR_W - side);
        p->y   = (int16_t)(anywhere ? wx_rand(-40, SCR_H) : wx_rand(-70, -side));
        p->vx  = (int16_t)wx_rand(-8, 8);
        p->vy  = (int16_t)wx_rand(30, 56);
        p->amp = (uint8_t)wx_rand(3, 9);
        break;
    case WX_SOAP:
        // 肥皂泡泡：比雪快一点、摆动大一点 —— 泡泡比雪花轻、更飘。
        //   用户原话「从天上往下飘落」，所以方向和雪一样（往下）。
        p->bx  = (int16_t)wx_rand(0, SCR_W - side);
        p->y   = (int16_t)(anywhere ? wx_rand(-40, SCR_H) : wx_rand(-70, -side));
        p->vx  = (int16_t)wx_rand(-10, 14);
        p->vy  = (int16_t)wx_rand(24, 46);
        p->amp = (uint8_t)wx_rand(4, 12);
        break;
    case WX_FIREFLY:
        // 萤火：一路**往上飘**，边走边轻轻摆。
        //   ★ 为什么是往上而不是像雪一样往下：萤火虫是「从草里升起来的光点」，
        //     往下落会读成「金色的雪」。用户拍的是「改成萤火」，那就要有升的势。
        p->bx  = (int16_t)wx_rand(0, SCR_W - side);
        p->y   = (int16_t)(anywhere ? wx_rand(0, SCR_H) : wx_rand(SCR_H, SCR_H + 30));
        p->vx  = (int16_t)wx_rand(-6, 8);
        p->vy  = (int16_t)wx_rand(-26, -12);
        p->amp = (uint8_t)wx_rand(4, 10);
        break;
    case WX_PLANE:
        // 小飞机：横穿屏幕**上部**的两条航道。
        //   ★ 方向**逐粒子随机**（用户点名要「由右到左，由左到右」两种都有）——
        //     素材只画了朝右的一套，左飞时在下面补一次水平镜像（scale_x 取负）。
        //   ★ anywhere=false（飞出去了要重生）时**方向重新随机**：
        //     读起来是「这一架飞走了，过一会儿从另一边又来一架」，比
        //     让同一架从原侧折返自然。
        {
            const bool right = (lv_rand(0, 1) != 0);
            const int  sp    = wx_rand(40, 70);
            p->vx  = (int16_t)(right ? sp : -sp);
            p->vy  = 0;
            p->y   = (int16_t)wx_rand(34, 120);
            p->bx  = (int16_t)(anywhere ? wx_rand(-side, SCR_W)
                                        : (right ? -side - wx_rand(0, 60)
                                                 : SCR_W + wx_rand(0, 60)));
            p->amp = 0;
        }
        break;
    case WX_BALLOON:
        // 热气球：同飞机，但**慢得多、低得多** —— 气球是「飘」，飞机是「飞」。
        {
            const bool right = (lv_rand(0, 1) != 0);
            const int  sp    = wx_rand(20, 32);
            p->vx  = (int16_t)(right ? sp : -sp);
            p->vy  = 0;
            p->y   = (int16_t)wx_rand(56, 150);
            p->bx  = (int16_t)(anywhere ? wx_rand(-side, SCR_W)
                                        : (right ? -side - wx_rand(0, 40)
                                                 : SCR_W + wx_rand(0, 40)));
            p->amp = 0;
        }
        break;
    default:
        // WX_FOG（走图元，到不了这里）/ WX_NONE。什么都不做，直接返回 ——
        //   ★ 不能让它掉到下面那句 lv_obj_set_pos：那时候 WX_SIDE 是 0、
        //     坐标全是没初始化过的值，会把一个粒子甩到不知道哪里去。
        return;
    }
    p->ph = (uint16_t)wx_rand(0, 1999);

    // ★ 横穿的两种按方向补一次**水平镜像**。
    //   素材只画了朝右的一套（见 _gen_fx45b.py），左飞就得把图翻过来。
    //   ⚠ 用 set_scale_x 传**负值** —— LVGL 的形参是 uint32_t，
    //     但内部 scale_update 收的是 int32_t，负值绕一圈回来还是负的
    //     （GCC 上是实现定义行为，不是 UB；LVGL 自己的镜像用法就是这么写的）。
    //   ⚠ 只在**重生/开场**时设一次，绝不挪进 weather_tick ——
    //     那会变成每帧每架飞机两次重排 + 一次重绘。
    //   ⚠ 负 scale 会让这个 image 走**变换绘制**路径（每帧要一块临时缓冲）——
    //     这正是第四十三轮那次「浮层卡死」的来源。这里敢用，是因为
    //     横穿的两种天气**一共只有 2 个粒子**（WX_USE 里写死的 2），
    //     代价是常数级的两个，和当年 18 个粒子的量级完全不同。
    if (s_wx_kind == WX_PLANE || s_wx_kind == WX_BALLOON) {
        const int sc = (int)WX_SCALE[s_wx_kind];
        lv_image_set_scale_x(U.wx_obj[i], (uint32_t)(int32_t)(p->vx < 0 ? -sc : sc));
    }

    lv_obj_set_pos(U.wx_obj[i], p->bx + wx_swing(p), p->y);
}

// ------------------------------------------------------------------ 雾（图元那一支）
//
// ★★ 2026-09-21（第四十五轮）：雾**不是粒子**，它有自己的两个函数。
//   为什么不硬塞进 wx_seed / 粒子循环：
//     · 字段不一样（雾只有 x / y / w / vx，见 wx_fog_t）；
//     · 它**没有帧动画**（不是素材），wx_play / play_tick 那一套用不上；
//     · 它整场天气里 y **一变不变**，只有 x 在动。
//   硬塞的结果是满篇 `if (s_wx_kind == WX_FOG)` 的补丁，读的人很快就不敢碰了。

// 给第 i 条雾带一次新生命。
//   anywhere = true  —— 天气刚开始：5 条**各自散落**在画面上，一上来就有雾。
//   anywhere = false —— 飘出右边了：从**左侧外面**整条重新进场。
//                       （雾只往右飘，所以永远从左边回来 —— 见 wx_fog_tick）
static void wx_fog_seed(int i, bool anywhere)
{
    wx_fog_t *f = &s_wx_fogp[i];
    const int h = wx_rand(WX_FOG_H_MIN, WX_FOG_H_MAX);
    const int w = wx_rand(WX_FOG_W_MIN, WX_FOG_W_MAX);

    f->w  = (uint8_t)w;
    f->vx = (int8_t)wx_rand(4, 13);          // 很慢：横穿 240px 要 20~60 秒
    // ★ y 用「第 i 条的轨道中心 − 半高」算左上角。轨道是**均匀分布**的
    //   （WX_FOG_TOP + i*WX_FOG_STEP），只加一点抖动 —— 让 5 条像五层雾，
    //   而不是随机撒在屏幕上的五块白斑。
    f->y  = (int16_t)(WX_FOG_TOP + i * WX_FOG_STEP
                      - h / 2 + wx_rand(-WX_FOG_JIT, WX_FOG_JIT));
    // ★ 允许带子有一部分在屏幕外：整条雾从画面外面飘进来比凭空出现在
    //   画面中间自然得多（和 wx_seed 的 anywhere 是同一个道理）。
    f->x  = (int16_t)(anywhere ? wx_rand(-(w / 2), SCR_W - w / 2)
                               : -w - wx_rand(0, 60));

    lv_obj_t *o = U.wx_fog[i];
    lv_obj_set_size(o, w, h);
    // ★ 圆角取满 = 两端半圆。**这是这一版唯一能做的「柔边」补偿** ——
    //   LVGL 没有高斯模糊，硬边矩形会读成「一块白板」；
    //   两端圆起来之后加上低透明度，才像一条云带。见 WX_FOG_N 上面那段。
    lv_obj_set_style_radius(o, h / 2, 0);
    // 每条的透明度略有不同 —— 五条一模一样的白带会看出「复制的痕迹」。
    lv_obj_set_style_bg_opa(o, (lv_opa_t)wx_rand(48, 104), 0);
    lv_obj_set_pos(o, f->x, f->y);
}

// 雾一帧的推进。★ 只有 x 在动。
static void wx_fog_tick(uint32_t dt)
{
    for (int i = 0; i < WX_FOG_N; i++) {
        wx_fog_t *f = &s_wx_fogp[i];
        // 速度和粒子那套一样是「像素/秒」，乘 dt 再除 1000 ⇒ **与帧率无关**。
        f->x = (int16_t)((int32_t)f->x + ((int32_t)f->vx * (int32_t)dt) / 1000);
        // 整条飘出右沿（左端越过 SCR_W + 20 时，最窄的 150px 带也已完全出去）
        if (f->x > SCR_W + 20) { wx_fog_seed(i, false); continue; }
        lv_obj_set_x(U.wx_fog[i], f->x);      // 只有 x 变 —— y 整场不变
    }
}

// 打一行内存账。
//
// ★★ 2026-09-20（第四十三轮）为什么加它 —— 实机故障：
//   用户原话「主界面只要操作了收集，或者去旅行的时间，立马就被卡死了」。
//   查下来是**内存**这一类问题，而这一屏的内存有三个互不相干的口袋：
//     ① LVGL 的堆 = 一个**独立静态池**，CONFIG_LV_MEM_SIZE_KILOBYTES=64（KB），
//        而且 LVGL 9 里**没有** pool 扩容这回事（lv_mem.c 里搜不到 POOL_EXPAND）
//        ⇒ 池子满了就是满了，涨不了。
//     ② LVGL 池子用尽的症状**不是**崩溃、不是重启、也没有任何串口输出
//        （LV_USE_LOG 没开）：`LV_ASSERT_MALLOC` -> `LV_ASSERT_HANDLER` -> 默认 `while(1);`
//        ⇒ 渲染任务停在半路，**整屏定格在画到一半的那一帧**。看上去像死机，
//          其实是原地死循环。完整推导见 build_scene 里那段长注释。
//     ③ 系统堆（WiFi / 任务栈用）。调 LV_MEM_SIZE 就是在 ① 和 ③ 之间搬内存，
//        搬多了 WiFi 那边会不够 ⇒ **两个数必须一起看**。
//   所以：不打印就永远只能猜。
//
// ★ 三个字段怎么读：
//     free / biggest —— 池子还剩多少、**最大连续块**多大（碎片看 biggest 而不是 free）
//     maxused        —— **开机至今的峰值**。这一项才是「离炸还有多远」的判据；
//                       只看 free 会被「平时很空、峰值很挤」骗过去。
//     sys            —— IDF 系统堆剩余。
// ⚠ free_biggest_size 才是能不能分配成功的判据：free 有 4 KB 但 biggest 只有 200 B
//   一样会炸。所以这一行里五个数一个都不能省。
static void wx_mem_log(const char *why)
{
    lv_mem_monitor_t m;
    lv_mem_monitor(&m);
    ESP_LOGW("fa_wx", "%-12s LVGL free=%u biggest=%u frag=%u%% maxused=%u | sys=%u",
             why, (unsigned)m.free_size, (unsigned)m.free_biggest_size,
             (unsigned)m.frag_pct, (unsigned)m.max_used,
             (unsigned)esp_get_free_heap_size());
}

// 「现在画面安不安静」。
// ★★ 气泡（talk_gate）和天气（weather_tick）**共用这一份判据** ——
//   这两处必须一致：气泡弹在浮层上、天气在浮层底下下雨，都算闹鬼。
//   各留一份的话，将来加一个新浮层就必然漏掉其中一处，而症状是**静默的**
//   （多下一场雨 / 多弹一句话，不报错、只在实机上看出来）。
//   ⚠ 这里用 fa_view_mini_open() 这个**公开接口**、而不是 s_mini_on 那个 static 变量：
//     后者定义在文件靠后（3.1k 行），而本节在它前面。公开接口在 fa_view.h 里
//     声明过，摆在哪都能调 —— 这也正是「对外只暴露函数」的好处。
static bool overlay_busy(void)
{
    if (g_fa.state != FA_HOME && g_fa.state != FA_AWAY) return true;
    if (s_card_up)              return true;   // 到达卡
    if (seq_departing())        return true;   // 出发 / 归来序列
    if (fa_view_dex_open())     return true;   // 收藏册
    if (fa_view_menu_open())    return true;   // 小游戏选择页
    if (fa_view_mini_open())    return true;   // 游戏里
    if (fa_view_intro_active()) return true;   // 开场剧情
    return false;
}

// 建粒子池。★ 只建不显 —— 显隐由 wx_begin / wx_end 管。
//   ⚠ 调用点在 build_scene() 里，位置在 U.cat **之后**、U.travel **之前**。
static void build_weather(void)
{
    // ---- 容器：和屏幕一样大、全透明、**没有圆角**（见本节开头那两条约束）----
    U.wx_cv = lv_obj_create(U.scr);
    lv_obj_remove_flag(U.wx_cv, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(U.wx_cv, 0, 0);
    lv_obj_set_style_border_width(U.wx_cv, 0, 0);
    // ★ bg_color 照 mk_box 的纪律**显式写死**（哪怕现在整块是透明的）：
    //   省掉它的话，将来任何一处把这层 opacity 改成 COVER，露出来的是
    //   LVGL 主题默认底色（近白），而你以为是自己设的颜色。
    lv_obj_set_style_bg_color(U.wx_cv, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(U.wx_cv, LV_OPA_TRANSP, 0);
    place(U.wx_cv, 0, 0, SCR_W, SCR_H);
    lv_obj_add_flag(U.wx_cv, LV_OBJ_FLAG_HIDDEN);

    // ---- 粒子池：一次建满，全部先 HIDDEN ----
    for (int i = 0; i < WX_P_MAX; i++) {
        lv_obj_t *o = lv_image_create(U.wx_cv);
        lv_obj_remove_flag(o, LV_OBJ_FLAG_SCROLLABLE);
        // ★ inner_align 钉 CENTER —— 第四十轮立下的纪律（那段长注释在 dex_show_bg 上面）：
        //   图一旦比框大，**默认对齐是 TOP_LEFT**，会贴左上、只裁右下。
        //   这一句在这一轮**真的用得上了**：四种天气的粒子都要放大到 27~36 px
        //   （见 WX_SCALE / WX_SIDE），"图比框大"是这个池子的常态。
        //   ⚠ 不能删 —— 删了粒子会被裁掉右下角一圈，而且那看起来不像"被裁"，
        //     只像"这张图没画全"，很难往回查。
        lv_image_set_inner_align(o, LV_IMAGE_ALIGN_CENTER);
        // 建的时候先按素材原尺寸（24x24、1:1）立起来。**真正的尺寸与倍率在
        // wx_begin() 里按当场天气设** —— 四种天气的倍率不一样，而池子是公用的。
        lv_image_set_scale(o, 256);
        lv_obj_set_size(o, WX_CELL, WX_CELL);
        lv_obj_add_flag(o, LV_OBJ_FLAG_HIDDEN);
        U.wx_obj[i] = o;
    }

    // ---- 雾那 5 条带：**建的是图元，不是 image** ----
    //   ★ 这是本工程里天气第一次用图元画（其余六种都走素材）。
    //     为什么放在**同一个容器** U.wx_cv 里：显隐 / 「浮层一开整层收起」
    //     这两件事就都不用改 —— 收容器的时候雾跟着一起收。
    //   ★ 建的时候用**最小尺寸**占位（WX_FOG_W_MIN x WX_FOG_H_MIN）：
    //     真正的大小每一次开场由 wx_fog_seed 定（每条都不一样）。
    //   ⚠ 这里**只建一次**，绝不每场天气建一次 —— 那就是 5 个对象
    //     每 1~4 分钟建了拆、拆了建，62KB 的 LVGL 堆经不起这种碎片化。
    //     （和粒子池「一次建满、只切显隐」是同一条纪律。）
    for (int i = 0; i < WX_FOG_N; i++) {
        lv_obj_t *o = mk_box(U.wx_cv, 0, 0, WX_FOG_W_MIN, WX_FOG_H_MIN,
                             0xFFFFFF, WX_FOG_H_MIN / 2, LV_OPA_30);
        lv_obj_add_flag(o, LV_OBJ_FLAG_HIDDEN);
        U.wx_fog[i] = o;
    }
}

// 起一场天气。
static void wx_begin(void)
{
    s_wx_kind = (uint8_t)lv_rand(0, WX_KIND_N - 1);
    s_wx_n    = WX_USE[s_wx_kind];
    s_wx_left = WX_LAST_MS;

    // ★★ 2026-09-21（第四十五轮）：**雾在这一行就分岔了**，不进粒子那一套。
    //   它要的三件事和粒子完全不搭：不是 image（是图元）、没有帧动画
    //   （WX_FMS 那一格是 0）、整场只有 x 在动（见 wx_fog_tick）。
    //   ⚠ 两条路必须**各自把对方的对象收干净**（这里按池子、下面那一支收雾），
    //     否则会出现「上一场是雨、这一场是雾，雨的粒子还挂在屏幕上」——
    //     静默、而且只在特定的天气切换顺序下出现。
    if (s_wx_kind == WX_FOG) {
        for (int i = 0; i < WX_P_MAX; i++)
            lv_obj_add_flag(U.wx_obj[i], LV_OBJ_FLAG_HIDDEN);
        for (int i = 0; i < WX_FOG_N; i++) {
            wx_fog_seed(i, true);
            lv_obj_remove_flag(U.wx_fog[i], LV_OBJ_FLAG_HIDDEN);
        }
        lv_obj_remove_flag(U.wx_cv, LV_OBJ_FLAG_HIDDEN);
        // ★ 给猫挂一句这个天气的话（和下面那一支同一件事，不能漏）。
        s_wx_talk_kind = (int)s_wx_kind;
        return;
    }

    // ---- 其余六种：先把雾那几条收掉，再走粒子那一套 ----
    for (int i = 0; i < WX_FOG_N; i++)
        lv_obj_add_flag(U.wx_fog[i], LV_OBJ_FLAG_HIDDEN);

    for (int i = 0; i < s_wx_n; i++) {
        // ★ 尺寸与倍率：见 WX_SCALE / WX_SIDE 那段。**两件必须一起设** ——
        //   只改 scale 不重设 size 的话，对象框还是建池时那 24x24、而图已经是
        //   30x30 了，会被裁掉一圈（第四十轮那条 inner_align 纪律）。
        //   ⚠ 这俩会失效布局与绘制区域，所以只在**每场天气开头**调一次，
        //     不能挪进 weather_tick 的每帧循环（那就成了每帧 18 次重排）。
        lv_image_set_scale(U.wx_obj[i], WX_SCALE[s_wx_kind]);
        lv_obj_set_size(U.wx_obj[i], WX_SIDE[s_wx_kind], WX_SIDE[s_wx_kind]);

        play_set(&s_wx_play[i], WX_ANIM[s_wx_kind]);
        // ★ 帧相位**随机起步**。同一场天气里十几个粒子播的是同一条动画，
        //   如果都从第 0 帧开始，就是十几份完全同步的拷贝 —— 看着像一块布在抖。
        //   ⚠ 必须写在 play_set **之后**：play_set 的纪律是「同一条就不动」，
        //     而这里是刚换上去的一条，它必然会把 frame 归零。
        if (s_wx_play[i].anim)
            s_wx_play[i].frame = (uint8_t)lv_rand(0, s_wx_play[i].anim->frames - 1);
        wx_seed(i, true);
        lv_obj_remove_flag(U.wx_obj[i], LV_OBJ_FLAG_HIDDEN);
    }
    lv_obj_remove_flag(U.wx_cv, LV_OBJ_FLAG_HIDDEN);

    // ★ 给猫挂一句这个天气的话。这里**只挂号**，真正「把下一句提前」在 talk_tick 里
    //   —— 那边才看得见 TALK_GAP_MIN；本节在它前面（见 s_wx_talk_kind 的说明）。
    s_wx_talk_kind = (int)s_wx_kind;
}

// 收一场天气。
static void wx_end(void)
{
    // ★ 收的时候**把整个池子都收掉**，不是只收这次用到的 s_wx_n 个：
    //   上一场用了 18 个、这一场只用 10 个，差的那 8 个如果没被收过，就会停在
    //   上一场结束时的位置上 —— 因为它们是 HIDDEN 的所以当场看不出来，
    //   等到**再下一场**雨里突然冒出来。这类「跨场次残留」错了不报错，很难查。
    for (int i = 0; i < WX_P_MAX; i++)
        lv_obj_add_flag(U.wx_obj[i], LV_OBJ_FLAG_HIDDEN);
    // ★★ 2026-09-21（第四十五轮）：**雾那 5 条也要收**。它们和粒子池在同一个容器
    //   里、却走另一条路（见 wx_begin 的分岔），所以这里必须**两条都收**。
    //   只收容器 U.wx_cv 其实当下也看不见（整棵子树一起不画），但那样
    //   s_wx_fogp 里还留着上一场的 x/y —— 下次起雾时 wx_fog_seed(i,true)
    //   虽然会把 x/y 重算一遍，可万一将来有人加了「雾只重铺一部分」的玩法，
    //   残留状态就会以「一条雾带停在屏幕中央」的形式冒出来。状态要跟着对象一起复位。
    for (int i = 0; i < WX_FOG_N; i++)
        lv_obj_add_flag(U.wx_fog[i], LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_flag(U.wx_cv, LV_OBJ_FLAG_HIDDEN);
    s_wx_n    = 0;
    s_wx_kind = WX_NONE;
    s_wx_wait = WX_GAP_MIN + (uint32_t)lv_rand(0, WX_GAP_RAND);
}

// 天气一帧的推进。★ 由 fa_view_tick 调，位置紧跟在 talk_tick 之后
//   （天气起时给猫挂了一句话，先天气后气泡，下一帧那句就轮到了）。
static void weather_tick(uint32_t dt)
{
    // ★ 画面不安静时**整个冻住**：既不倒计时、也不动粒子。
    //   为什么是「暂停」而不是「照跑」：「一次天气持续 25 秒」应当指**看得见的**
    //   25 秒。在收藏册底下闷头下完 25 秒再自己收掉，玩家一出来发现天晴了，
    //   只会觉得莫名其妙。
    //   （fa_view_tick 里「开场剧情」和「小游戏」两条路本来就提前 return 了，
    //     这里再挡一道是为了收藏册 / 选择页 / 到达卡 / 出发序列那几种。）
    //
    // ★★ 2026-09-20（第四十三轮，实机故障排障）：**浮层开合的那一帧还要多走两步**。
    //
    //   故障：打开收藏册 / 开始旅行 → **整屏定格**。
    //   根因：LVGL 那 64 KB 的池子（CONFIG_LV_MEM_SIZE_KILOBYTES，涨不了）
    //         被这一层天气吃掉了约 5 KB 常驻（19 个对象：1 容器 + 18 粒子），
    //         而「打开收藏册 / 开始旅行」正好是**全屏重绘**、瞬时需求最高的一帧
    //         ⇒ 分配失败 ⇒ LV_ASSERT_MALLOC ⇒ `while(1);` ⇒ 定格。
    //         和第十三轮那次「收藏卡死」是**同一类**故障，只是这次的入口是
    //         「常驻对象变多」而不是 clip_corner。诊断日志见 wx_mem_log()。
    //
    //   对策一（本函数，零内存代价、当场见效）：浮层一起来就把**整层天气收起来**。
    //     原来只是「冻住」——粒子仍然可见，于是收藏册那一帧还得把这 18 个
    //     缩放过的 image 一并画掉（每个都要一次 draw task + 一块 2~4 KB 的
    //     变换缓冲）。收起来就等于把 18 个对象从**最挤的那一帧**里摘掉。
    //     顺带也是对的视觉效果：收藏册 / 旅行面板底下本来就不该下雨。
    //     注意收的是**容器**（U.wx_cv）—— 一整棵子树一起不画，
    //     不必去动那 18 个粒子各自的 HIDDEN 标志。
    //   对策二（不在本函数）：把 LVGL 的池子从 64 KB 提到 80 KB，
    //     见 sdkconfig.defaults 的 CONFIG_LV_MEM_SIZE_KILOBYTES。
    const bool busy = overlay_busy();
    if (busy != s_wx_ov) {                 // ★ 只在**开合的那一刻**做，不是每帧
        s_wx_ov = busy;
        wx_mem_log(busy ? "overlay-ON" : "overlay-OFF");
        if (s_wx_kind != WX_NONE) {        // 没有天气时容器本来就是 HIDDEN，不用管
            if (busy) lv_obj_add_flag(U.wx_cv, LV_OBJ_FLAG_HIDDEN);
            else      lv_obj_remove_flag(U.wx_cv, LV_OBJ_FLAG_HIDDEN);
        }
    }
    if (busy) return;

    // ---- 静默期：只倒数，不画 ----
    if (s_wx_kind == WX_NONE) {
        if (s_wx_wait > dt) { s_wx_wait -= dt; return; }
        s_wx_wait = 0;
        wx_begin();
        return;
    }

    // ---- 活跃期 ----
    if (s_wx_left <= dt) { wx_end(); return; }
    s_wx_left -= dt;

    // ★★ 2026-09-21（第四十五轮）：**雾在这一行就分岔了**，和 wx_begin 那头对称。
    //   为什么必须在这里就 return、不能往下走到粒子那套：
    //   ① WX_FMS[WX_FOG] 是 **0**（雾没有帧动画，那一格本来就是个占位），
    //      喂进 play_tick 会是「每帧都翻一帧」——虽然雾根本没有 image 对象、
    //      U.wx_obj[] 全是 HIDDEN，走一趟也是空转，但那是靠「碰巧没副作用」兜住的，
    //      不该依赖。② s_wx_n 对雾是 WX_USE[WX_FOG]=5（雾的条数），
    //      下面的循环会当成「有 5 个粒子」去读 s_wx_p[] —— 那是**另一条数据结构**，
    //      读到的是一堆 0，然后对 HIDDEN 的 U.wx_obj[0..4] 反复 set_pos。
    //      ⚠ 这两条都**不会报错**，只会在实机上表现为「雾不动」或「雾起来后
    //        雨那一路的粒子被 reset」——所以必须显式分岔，不靠巧合。
    if (s_wx_kind == WX_FOG) { wx_fog_tick(dt); return; }
    //   ⚠ 顺序：这一句要写在 s_wx_left 递减**之后** —— 雾也要正常计时，
    //     否则一场雾会永远不结束（s_wx_left 不减，wx_end 那一行永远不成立）。

    const uint16_t fms = WX_FMS[s_wx_kind];

    for (int i = 0; i < s_wx_n; i++) {
        wx_p_t *p = &s_wx_p[i];

        // ① 翻帧
        play_tick(&s_wx_play[i], dt, U.wx_obj[i], fms);

        // ② 位移。速度单位是「像素/秒」，乘 dt 再除 1000 ⇒ **与帧率无关**：
        //    30fps 和 20fps 下走的是同样的距离，掉帧时天气不会忽然变慢。
        //    ⚠ 中间量用 int32：vy 最大 560、dt 通常 33，乘积才 1.8 万其实放得下
        //      int16；但 bx 是**长期累积**的，而且将来调速度时没人会回来重算这个。
        p->y  = (int16_t)((int32_t)p->y  + ((int32_t)p->vy * (int32_t)dt) / 1000);
        p->bx = (int16_t)((int32_t)p->bx + ((int32_t)p->vx * (int32_t)dt) / 1000);
        p->ph = (uint16_t)((p->ph + dt) % 2000u);

        if (wx_out(p)) { wx_seed(i, false); continue; }

        // ③ 落位。★ lv_obj_set_x / set_y 内部有「值没变就直接 return」的短路，
        //    所以位置真的没变的那一帧不会白白失效重绘 —— 这里不必自己判断。
        lv_obj_set_pos(U.wx_obj[i], p->bx + wx_swing(p), p->y);
    }
}

// ------------------------------------------------------------------ 建场景

static void build_scene(void)
{
    // ================= 「家」：一整幅底图（2026-09-19 第四次改版）=================
    // ★★ 用户原话：「首页再重新渲染一张图片，不要再用色块了。类似明信片的风格。」
    //   原来这里用 12 组圆角矩形搭了一片天/云/山/岸/溪/草（连同每次实机反馈
    //   反复调过的那一堆坐标），现在全删了 —— 换成一张真渲染出来的 240x320 整图
    //   （素材侧 agent="scene-bg"，见 03-素材流水线 的 gen_manifest.py）。
    //
    // ★ 1:1 摆放（scale 256），一个像素都不缩 —— 尺寸就是屏幕尺寸。
    // ★ 图里**没有猫、也没有小屋**：那两样是游戏自己的精灵，要能单独动、
    //   单独收。底图只提供「没有人站在里面的院子」。
    // ---- 底图层：圆角容器 + 一张 240x320 的图 ----
    // ★ 底色 C_DARK = 屏幕底色：四角被切掉之后露出来的就是它。
    //   ⚠ 但**只有 bg_cv 自己**的四角是它 —— 下面那张 bg_img 是铺满全屏的
    //     矩形子对象，子对象不吃 radius。这正是「必须有一个角标盖在所有东西之上」
    //     的物理原因，不是多此一举。
    //
    // ★★★ 2026-09-19（第十三轮）**全工程的 clip_corner 一律删除，别再打开。**
    //   四角现在由一个**独立的角标对象**统一遮掉（见 build_corners）。
    //
    //   为什么推倒重来 —— 实机故障「收藏直接用不了了，卡在小游戏那一页，
    //   翻不动也进不去」的根因就在 clip_corner 上。读到 lv_refr.c 的
    //   lv_obj_redraw（第 104-267 行）才看清，同时更正我上一轮写错的两条判断：
    //
    //   ① 代价不是「一层」，是**每个对象两层**。第 200-241 行：
    //      先取 rout = min(radius, short_side/2) = R_CORNER = 26，然后
    //      **上半 rout 行建一层、下半 rout 行再建一层**；中间那段
    //      （y ∈ [rout, H-rout]）是直接改 layer->_clip_area 透传的，不建层。
    //      每层 240 x 26 x ARGB8888(4B) = **24,960 B** ⇒ **单对象峰值 49,920 B**。
    //      ⚠ 更正：上一轮我在本段写过「clip_corner 只切上两角、下两角一直是漏的」
    //        —— 那是错的。上下两层都会走 lv_draw_mask_rect，**四个角都切**；
    //        中间那段不切也**不是漏**，圆角本来就够不到那里。
    //   ② LVGL 的堆只有 **64 KB**（CONFIG_LV_MEM_SIZE_KILOBYTES=64，
    //      LV_MEM_POOL_EXPAND_SIZE=0，涨不了），而界面常驻对象已经吃掉约 30 KB。
    //   ③ 建层的条件是「该对象的这 26 行**与本次脏区相交**」，而脏区就是
    //      「这一帧变了哪儿」——底栏一按、电量一变、猫一走都可能命中上/下 26 行。
    //      所以这不是「开机付一次」，是**每次刷新都可能付**。
    //   ④ 最要命的是**多层会同时存在**：小游戏的 ov_mini 是盖在册子 ov_dex 上的
    //      （进游戏时册子并没有关，见 fa_view_mini_close），两个都是「全屏 + 圆角」，
    //      底下还有 bg_cv —— 三层叠起来最坏 49,920 x 3 > 64 KB，**必定爆堆**。
    //      ★ 爆堆之后到底发生什么 —— 这段我第十二轮凭印象写成「直接 abort」，
    //        现在按 sdkconfig + LVGL 源码重新钉一遍：
    //        · CONFIG_LV_USE_ASSERT_MALLOC=y ⇒ 分配失败走 LV_ASSERT_MSG
    //          → LV_LOG_ERROR("Out of memory") → LV_ASSERT_HANDLER（lv_assert.h:72）
    //        · 而 sdkconfig 里**没有** CONFIG_LV_ASSERT_HANDLER（只有 INCLUDE 那条），
    //          于是取 lv_conf_internal.h 的默认值 —— **`while(1);`**。
    //          **不是 abort，是原地死循环。**
    //        ⇒ LVGL 任务停在重绘中途，屏幕定格在最后画到一半的那一帧：
    //          上半幅已经是新界面、下半幅还留着旧界面 —— 用户那张照片正是这样。
    //          ⚠ 别看门狗：TWDT 只盯 IDLE 任务（CHECK_IDLE_TASK_CPU0=y），
    //            而 lvgl_port 的渲染任务并没有注册进 TWDT；就算真被 WDT 打断，
    //            也只是重启后回到同一屏，看上去还是「卡住」。
    //        · 还有一条更阴的路：lv_draw_layer_create 分配 lv_layer_t 失败时
    //          只返回 NULL（lv_draw.c:430-438），而**调用方没判空**就往这个 NULL
    //          层里 lv_obj_refr —— 侥幸没断言成，就是「安静地画错」，比停住更难查。
    //        第十二轮给 ov_dex 补 clip_corner 是压垮的那一根稻草。
    //
    //   新方案（build_corners）：**一个对象、零中间图层、零素材开销**。
    //   原理：一个比屏幕大一圈、radius = R_CORNER + CVR_B 的圆角矩形，
    //   用 CVR_B 宽的**边框**在四角画出一圈深色环；环落在屏幕内的部分
    //   恰好就是四个角要遮掉的那块（完整推导见 build_corners）。
    //   ⚠ 它盖出来的四角是**硬边**（无抗锯齿过渡）—— 这是对的，不是偷工：
    //     屏幕外面就是外壳，硬边正是外壳的边。clip_corner 那种羽化反而多余。
    U.bg_cv = mk_box(U.scr, 0, 0, SCR_W, SCR_H, C_DARK, R_CORNER, LV_OPA_COVER);
    lv_obj_remove_flag(U.bg_cv, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    U.bg_img = lv_image_create(U.bg_cv);
    lv_obj_remove_flag(U.bg_img, LV_OBJ_FLAG_SCROLLABLE);
    place(U.bg_img, 0, 0, SCR_W, SCR_H);
    lv_image_set_src(U.bg_img, &fa_res_home);
    lv_image_set_scale(U.bg_img, 256);

    // ================= 别处的风景：**同一个对象换 src**，不再另建一层 =================
    // ★★ 2026-09-19（第十轮）从这里删掉的一整层：一个同样铺满整屏的圆角容器
    //   scene_cv + 一张 176x220 放大 1.5 倍的**带猫**明信片，只在「旅行中且挂着
    //   风景」时出现。用户看过实机之后改了口径（原话见文件上方 SCENE_SCALE 那段），
    //   旅行中改走**和挂风景完全相同**的那条路 —— 底图换 src + 我们自己的猫。
    //
    //   ★ 于是「换风景 / 旅行中 / 在家」三种情况共用 bg_img 一个对象，
    //     「同一时刻只有一张全屏图在渲染」从一条需要维持的判据变成了结构性质。

    // ★ 2026-09-19（第五次）：这里原来还有两段 ——
    //   ① 「家（素材屋）」：把 fa_res_house 缩 0.75 摆到 (2,188)。底图换成
    //      一张自己画着房子的场景之后，它就变成画面里的第二栋房子，整段删除；
    //   ② 「小院：4 个可摆放的位置」：四个 lv_image 图层，交给 yard_apply()
    //      决定摆什么。道具功能整个下线，这段跟着删。
    //   建序仍然是「底图 → 风景 → 猫 → 旅行遮罩」：位置即图层。
    //   访客本来就已下线（见文件上方说明）。

    // 猫建在旅行遮罩之前 —— 遮罩要能把它一起压暗
    U.cat = lv_image_create(U.scr);
    lv_obj_remove_flag(U.cat, LV_OBJ_FLAG_SCROLLABLE);
    place(U.cat, CAT_X, CAT_Y, CAT_W, CAT_H);

    // ---- 天气（第四十二轮）----
    // ★★ 位置钉死在**猫之后、旅行遮罩之前**，三条理由就是它的全部依据：
    //   ① 在猫之后 ⇒ 粒子盖过猫。用户第④条要的「镜头前」就是这个意思。
    //   ② 在旅行遮罩之前 ⇒ 旅行时天气跟着画面一起被压暗。遮罩的语义是
    //      「整个画面暗下来，表示你在路上」，天气属于画面，不该例外；
    //      反过来把天气摆在遮罩之上，旅行中就会有一片亮得突兀的雨挂在暗屏上。
    //   ③ 最要紧的一条：它在 **HUD / 底栏 / 旅行面板**之前建 ⇒ 那三样永远压在
    //      天气之上。它们是读数和按钮（三叶草数、电量、校时点、出发键），
    //      雨点糊上去就没法看了。
    //   ⚠ 别图省事挪到 fa_view_init 里去建：那样它会盖住 HUD 和底栏。
    //   ⚠ 也别往后挪到 travel 之后：那样旅行中的雨是亮的（见 ②）。
    build_weather();

    // ---- 旅行遮罩（2026-09-19 第四次改版）----
    // ★★ 建在最后 = 图层最高：压住底图 / 风景 / 猫。
    //   它**不会**盖住 HUD、底栏、旅行面板和提示气泡 —— 那四样建得比它晚。
    //   （HUD 不压暗是对的：那是「你现在有多少三叶草」，不是画面的一部分。）
    // ★ 平时整块 HIDDEN，一行 alpha 混合都不算 —— 全屏半透明混合是每帧成本最高的
    //   一类绘制，能不用就不用。只有 FA_AWAY 这一种状态会把它放出来。
    // ★★ 2026-09-19（第十二轮）：这块遮罩**也要自己切圆角**。
    //   实机反馈「旅行中界面好像四个角没变成圆角，背景不是黑色，还在透光」——
    //   根因就在这里：遮罩原来是一个**直角**的 240x320 半透明矩形，
    //   它压在已经切好圆角的底图**之上**，于是四个角被它填上了「半透明的蓝灰」，
    //   看起来既不是圆角、也不是黑，正是用户说的「透光」。
    //   （底图 bg_cv 自己的圆角一直是好的，四角露的是屏幕底色 C_DARK；
    //     被这层直角盖住之后才破了相。）
    //   ⚠ 它没有子对象，clip_corner 在这里只是为了让它**自己**按圆角画 ——
    //     radius 一给，背景矩形本身就带圆角了，clip_corner 是给将来加内容留的一致性。
    U.travel = mk_box(U.scr, 0, 0, SCR_W, SCR_H, C_MASK, R_CORNER, MASK_OPA);
    // ★ 第十三轮：clip_corner 删除（它本来就没有子对象，纯属白留一个开关）。
    lv_obj_remove_flag(U.travel, LV_OBJ_FLAG_OVERFLOW_VISIBLE);
    lv_obj_add_flag(U.travel, LV_OBJ_FLAG_HIDDEN);
}

// 顶栏：三叶草 / 电量 / 校时点。
//
// ★★ 2026-09-19（第五次）把那条**不透明状态条整个删了**。
//   用户原话：「也不要最上面显示电量和三叶草的栏，能直接显示在背景上」。
//   原来 U.hud 是一块 240x24 的 C_HUD 纯色矩形，这三样东西都挂在它上面；
//   现在它们直接挂在 U.scr 上，压在底图那片天空上 —— 坐标一个数没变
//   （原来就是按 U.hud 的相对 (0,0) 写的，而 U.hud 本身就在 (0,0)）。
//
// ★ 两个跟随而来的细节，改这块之前先看一眼：
//   ① 底图顶部那约十分之一条天空**必须保持干净**（见素材侧 manifest 里
//      home 那条 job 的 note），否则太阳、云、水印会从字缝里穿出来；
//   ② 字色是深灰（C_TEXT），压在浅蓝天空上读得清；可旅行遮罩一压上去整屏
//      变暗，深灰字就糊没了 —— 所以遮罩期间换成 C_HUD_LT 暖白，见 hud_paint()。
static void build_hud(void)
{
    // ---- 猫罐头（2026-09-19 第九轮：取代原来的「三个圆拼一片叶子」）----
    // ★ 用户原话：「把三叶草换成猫罐头」。
    // ★ 形状按第九轮那张候选图的 **D（矮胖+爪印）** 逐块复刻 ——
    //   下面每一组坐标都能在那张 20x20 的绘制稿里指出对应的一笔，别凭印象改。
    //   图标原点落在 (15,5)，所以绝对坐标 = (15,5) + 绘制稿里的相对坐标。
    // ★ 为什么用图元拼而不是出素材：这个图标只有 20px，做进图集要占一张图的位置
    //   外加一次生成调用；而它整个是纯色块构成的，图元拼出来是**矢量级**的清晰，
    //   将来要换颜色也不用重出图。
    // ★★ 相对原来的三叶草整体**右移 8px**（7 -> 15）。用户原话：
    //   「把猫罐头和电量的标识往中间稍微移动一点儿，现在容易被屏幕外壳挡住」。
    //   外壳四角是弧形的，R_CORNER(26) 那一档在 y=5 这行会吃掉 x<11 的一段，
    //   原来的 x=7 正落在里面；往内让 8px 就完全出来了。
    //   ⚠ 改 R_CORNER 的话，这几个数要跟着重算（判据：在 y=5 处 x 必须 > 11）。
    //
    // ★ 建序即图层序：罐身 → 顶盖 → 内盖 → 标签带 → 掌垫 → 三个脚趾点。
    //   和白底稿上的绘制顺序一致，倒过来会被上层盖掉。
    U.can_body = mk_box(U.scr, 18, 10, 14, 13, C_CAN_STEEL, 2, LV_OPA_COVER);
    lv_obj_set_style_border_width(U.can_body, 1, 0);
    lv_obj_set_style_border_color(U.can_body, lv_color_hex(C_CAN_EDGE), 0);

    U.can_lid = mk_box(U.scr, 17, 7, 16, 7, C_CAN_LID, LV_RADIUS_CIRCLE, LV_OPA_COVER);
    lv_obj_set_style_border_width(U.can_lid, 1, 0);
    lv_obj_set_style_border_color(U.can_lid, lv_color_hex(C_CAN_EDGE), 0);

    U.can_lid_in = mk_box(U.scr, 20, 9, 10, 4, 0xD8DDE4, LV_RADIUS_CIRCLE, LV_OPA_COVER);

    U.can_label = mk_box(U.scr, 18, 15, 14, 5, C_CAN_LABEL, 0, LV_OPA_COVER);
    lv_obj_set_style_border_width(U.can_label, 1, 0);
    lv_obj_set_style_border_color(U.can_label, lv_color_hex(C_CAN_EDGE), 0);

    // 爪印：一枚掌垫 + 三个脚趾点（奶白）。这是「猫」的那一笔，
    // 没有它就只是个罐头，认不出是**猫**罐头。
    U.can_pad = mk_box(U.scr, 23, 17, 5, 3, 0xFFF6EC, LV_RADIUS_CIRCLE, LV_OPA_COVER);
    for (int i = 0; i < 3; i++)
        U.can_toe[i] = mk_box(U.scr, 22 + i * 3, 15, 2, 2, 0xFFF6EC,
                              LV_RADIUS_CIRCLE, LV_OPA_COVER);

    // ★★ 第十三轮：hud_chip() 取消（用户：「数字后面的黑色背景太丑了，去掉」）。
    //   ⚠ 框高 18 -> 20：fa_font_ui 从 15px 提到 **16px**（line_height 19），
    //     18px 高的框会把字的**下缘**切掉 1px。这一格和下面电量那格一起调。
    U.lb_clover = mk_label(U.scr, &fa_font_ui, C_HUD_WT, "0");
    // ★★ 第十五轮：框顶 5 -> 6。用户原话：「猫罐头、猫罐头数量、电量标识、电量，
    //   纵向对齐一下」。
    //   实测（tools/_fx.py 从字库生成物直读，不是估的）：label **没有隐式垂直居中**，
    //   墨迹是从**框顶**往下算的 —— 16px 字模的墨迹 = 「框顶+3 .. 框顶+15」。
    //     · 两个图标：罐头 7..21、电池 8..21 ⇒ 中心都是 **14.5**；
    //     · 数字框顶 5 ⇒ 墨迹 8..19 ⇒ 中心 **13.5** —— 高了整整 1px，这就是
    //       肉眼看到的「不齐」。
    //   框顶挪到 6 ⇒ 墨迹 9..20 ⇒ 中心 14.5，与两个图标**完全重合**。
    //   ⚠⚠ 别再照「框高 20、字面 19」去推「本来就居中了」——那个推法不成立，
    //     本项目在这一脚上踩过一次（见铁律：label 没有隐式垂直居中）。
    place(U.lb_clover, 38, 6, 46, 20);

    // ★ 2026-09-19 去掉时钟（用户要求）。这一格原来是 hh:mm，由 tb_clock 驱动；
    //   去掉的只是「显示」，校时本身照旧 —— fa_game 靠 time(NULL) 算行程，
    //   右上角那颗点仍然是校时状态（长按 ↑ 也会报一次）。
    //   顺便把计数往右挪一点，让左边这组不那么贴边。
    // ---- 电量（2026-09-19 第三次改）----
    // ★ 原来这一格是 place(190, 6, **28**, 13)：28px 宽装不下「100%」四个字符时，
    //   LVGL 标签的默认折行模式（WRAP）会把它折成两行，而框只有 13px 高 ——
    //   屏幕上就只剩「100」或者半截字。实机反馈「电量显示错误」有一半是这里。
    //   现在：框放宽到 36px，并且**显式**改成 CLIP（宁可右边被切一像素，也不要折行）。
    // ★★ 2026-09-19（第十二轮）用户原话：
    //   「电量做三张图，一个满电，一个一半电，一个只剩下一点点电。然后根据情况更换。」
    //   于是这一格从「一行文字」变成「一张图 + 一行文字」：
    //     图标 = fa_res_batt_full / batt_half / batt_low（24x14，素材侧出图）
    //     数字 = 百分比，与猫罐头数量**同一个字号、同一个字色**
    //   ⚠ 三张图是同一张画布上的三种填充（外壳 / 正极 / 描边完全一致，
    //     只有内部电量条的长度与颜色不同）⇒ 换的时候只 set_src，
    //     位置和尺寸一个像素都不动，否则切换瞬间会「跳一下」。
    U.batt_ic = lv_image_create(U.scr);
    lv_obj_remove_flag(U.batt_ic, LV_OBJ_FLAG_SCROLLABLE);
    // ★★ 第十五轮：x 146 -> 150。用户原话：「电量标识和电量的数字继续往右一些，
    //   要尽量和猫罐头与侧边的距离一致」。
    //   往右让 4px，好把「图标右沿 -> 数字」的间距在常见的三位百分数（「86%」）
    //   下从 21px 收到 14px。**不能再往右**：右沿 176 是「100%」那条硬上限 ——
    //   右对齐到 223 时「100%」（实测 42 宽）起笔在 181，图标右沿必须留在它左边。
    //   ★★★ 2026-09-19（第十七轮）**图标与数字交换位置**。用户原话：
    //     「电量标识和电量数字交换一下位置。」
    //     ~~旧：图标 150..176 在左，数字框 177..223（右对齐）在右~~
    //     ⇒ 现在：**数字在左、图标在右**。
    //   口径（整组占位一个像素都没动，只是组内左右对调）：
    //     · 组右沿仍是 **223**（离屏幕右沿 17px = 猫罐头最左一笔离左沿的距离，
    //       第十五轮定的，别动）；
    //     · 图标宽 26 ⇒ 图标 197..223（`197 + 26 = 223` ✓）；
    //     · 数字框右沿 = 图标左沿 - 2 = **195**，宽 46 ⇒ 框 (149, 6, 46, 20)。
    //       留 2px 是让「100%」的右沿不至于顶死在电池壳上。
    //     ⚠ 46 宽仍是「100%」（实测 42px）的下限，再窄会被 CLIP 成「10」。
    //     ⚠ 右对齐**保持不变**：只有右对齐能让「离右边那个参照物的距离」
    //       对每一位数都成立（见下面那段旧推导）。
    place(U.batt_ic, 197, 8, BATT_IC_W, BATT_IC_H);
    lv_image_set_src(U.batt_ic, &fa_res_batt_full);

    // ★ 字号 11px -> 15px（fa_font_ui），字色 -> 纯白，与左边那格完全一致。
    //   ⚠ 框仍然要显式 CLIP：15px 字下「100%」比 11px 时宽出约三分之一，
    //     一旦折成两行，18px 高的框会把它切成半截（这个坑第三次改版踩过一次）。
    // ★★ 第十三轮：**38 -> 52 宽、18 -> 20 高**。实测（tools/_measure_fonts.py）：
    //   「100%」在 Bold 16px 下要 **42px**，38 的框必然被 CLIP 掉尾巴变成「10」。
    //   右边到 226，正好和收藏册顶栏那条对齐，也还在角标弧线内侧（y=5 处到 229）。
    U.lb_batt = mk_label(U.scr, &fa_font_ui, C_HUD_WT, "");
    // ★★ 第十五轮：框 (174,5,52,20) -> **(177,6,46,20)**，仍然是右对齐。
    //   用户原话：「继续往右一些，要尽量和猫罐头与侧边的距离一致」。
    //   口径：**右沿 = 223**，即离屏幕右沿 17px —— 正好等于猫罐头最左那一笔
    //   （can_lid 的 x=17）离屏幕左沿的距离。177 + 46 = 223 ✓
    //   ★ 为什么仍然**右对齐**（而不是左对齐）：只有右对齐能让「离侧边 17px」
    //     对每一位数都成立。改成左对齐的话，位数一变右沿就跟着跑 —— 而用户要的
    //     恰恰是「和侧边的距离一致」。
    //   ⚠ 46 宽是「100%」的下限：实测 42px，再窄就会被 CLIP 掉尾巴变成「10」。
    //   ⚠ 框左沿 177 = 电池图标右沿（150+26=176）+1 ⇒ 任何位数下数字都落在图标
    //     右侧。最宽的那一种（「100%」）起笔在 223-42=181，离图标 5px。
    //   ⚠ 223 仍在屏幕右上圆角内侧：y=9 那一行圆弧留到 x≈233.7。
    //   ★★★ 2026-09-19（第十七轮）框 **(177,6,46,20) -> (149,6,46,20)**：
    //     与上面 batt_ic 一并对调（数字挪到左、图标挪到右）。
    //     右沿 149 + 46 = **195**，正好在图标左沿 197 前 2px。
    //     ⚠ 别再把左沿改回 177 —— 那样数字会压在电池图标上（图 197..223）。
    //   ⚠ 旧推导（右沿 223 = 离屏右沿 17px）那是**图标**现在的口径，
    //     数字这一格不再承担「离侧边一致」这件事，它对的是**左边的电池图标**。
    //   ⚠ 223 仍在屏幕右上圆角内侧：y=9 那一行圆弧留到 x≈233.7。
    place(U.lb_batt, 149, 6, 46, 20);
    lv_obj_set_style_text_align(U.lb_batt, LV_TEXT_ALIGN_RIGHT, 0);
    lv_label_set_long_mode(U.lb_batt, LV_LABEL_LONG_CLIP);
    // ★★ 2026-09-19（第十三轮）：**联网点 U.wifi_dot 整块删除**。
    //   用户原话：「另外电量旁边有个点，是什么，去掉。」
    //   它原来是「校时状态点」：颜色随 tb_clock 的状态变（见 fa_view_tick 里
    //   写 bg_color 的那一处），用来告诉玩家「时间校没校上」。
    //   问题是**它长得像个脏点**：9x9 的圆、颜色是灰米（0xBFB6A6），
    //   位置又紧挨着电量数字，玩家根本读不出它在说什么 —— 一个不解释自己的
    //   指示器就是噪声。信息本身没有丢：校时状态仍然可以长按 ↑ 报一次
    //   （main.c 的 toast_clock_state()），那条是有文字的。
    //   ⚠ 不要为了「把信息补回来」再加第二个点/图标，那会把顶栏又塞满。
}

static void build_bar(void)
{
    // ★★ 这里原来有一层「底栏草地底衬」（U.bar_under，永不隐藏的纯色矩形）。
    //   它的来历：旅行中 bar_refresh() 会把 U.bar 整条 HIDDEN，底下那 28px 就露出
    //   屏幕底色（近白亮带），所以垫一层和近岸草地同色的矩形把它填上。
    //   2026-09-19 第四次改版**整层删除** —— 首页换成铺满整屏的底图之后，
    //   底栏收起来露出的就是那张照片自己的草地，不需要也不该再垫一层纯色：
    //   垫上去反而会在照片下沿压出一条和画面无关的平直色带（这正是第三次改版
    //   实机反馈「下面那条绿色是怎么回事」的根因）。
    // ★★ 2026-09-19（第九轮）：整条底带的**底色取消了**。
    //   用户原话：「选择几分钟以及设置的按钮为与旅行中的框一样，黑底带一些透明度
    //   反白字，压在背景图上」。所以：
    //     · U.bar 只剩一个**透明容器**（不再画那条不透明的米白带）；
    //     · 每一格 pill 自己是「黑底 + 半透明 + 反白字」（见下面两处 mk_box）。
    //   这两条必须一起做：容器要是不透明，pill 的透明度就白设了 —— 底下压的是
    //   米白带而不是风景，看不出「压在背景图上」。
    //   ⚠ 容器设成 TRANSP 之后，「底栏收起来」露出的是照片本身，这一条和第四次
    //     改版删掉 bar_under 是同一个道理，别再把底色加回来。
    //
    // ★★★ 2026-09-19（第十五轮）：**上面那条「透明容器」的口径被推翻了**。
    //   用户原话：「直接黑色遮罩横条吧，别每个都一个单独遮罩了，看起来会不舒服」，
    //   外加「长方形通栏一直延长至左右两侧的边上」。所以现在是：
    //     · U.bar 从透明容器改成**可见的**遮罩本身：C_PANEL + LV_OPA_80、
    //       **radius = 0（长方形）**、x = 0、w = SCR_W ⇒ 一条从左沿贯到右沿的暖黑条；
    //     · 六格 pill 的底色**一律取消**（TRANSP）—— 「格与格之间露出风景」正是
    //       用户觉得不舒服的那件事。有了通栏，格子只是**定位用的空框**；
    //     · 只有**选中那一格**才是实心橙胶囊，见 bar_refresh()。
    //   ⚠ 通栏（x=0 / w=SCR_W）必然让两端探到屏幕圆角之外 —— 这由 build_corners()
    //     那个暖黑角标**最后建**来遮掉（z 序 = 建序），所以看到的是「横条顺着
    //     圆角收边」。**别为了「保险」把 x 往内缩**，那就又不是通栏了。
    //   ⚠ 这层压在**照片**上：底图是 240x320 铺满的，所以 OPA_80 底下一定是那片
    //     草地，不会像第四次改版那样露出屏幕底色。
    U.bar = mk_box(U.scr, 0, BAR_Y, SCR_W, BAR_H, C_PANEL, 0, LV_OPA_80);

    // 5 个时长 + 1 个「收集」，一共 6 格。总宽 = 6*36 + 4*2 + 8 = 232，居中。
    // ★ 为什么把收集册塞进这一条：手柄只有 ↑ / ↓ / ● 三个键。
    //   收藏页原来挂在「长按 ●」上，用户反馈根本找不到、而且不喜欢长按。
    //   放进选择器之后，进册就是「按两下 ↓ 再按 ●」，全程可见、可预期。
    //
    // ★ 2026-09-17 整条放大：格子 30x18 → 36x22，字号 11px → 15px。
    //   实机反馈「下面选择太小、字太小要放大」，并主动授权「不够就去掉 10 分钟」。
    //   算一下就知道必须二选一：240px 塞 7 格时每格只有 30px，15px 字宽的
    //   「试玩」「收集」正好 30px，一点余量都没有；删掉一档变 6 格，
    //   每格能有 36px，最宽的「12时」（31px）也留得下 2px 边距。
    //   底栏本身也从 24 高加到 28，不然 22 高的圆角格子会顶到屏幕下沿。
    //
    // ★ 2026-09-19（第九轮）：pill 的底色从 C_PILL_BG（米白）换成 C_PANEL（暖黑）
    //   并加了 LV_OPA_80 的透明度 —— 和旅行面板（build_away 里那块 C_PANEL/OPA_90）
    //   是同一套观感。字色随之从 C_DIM 换成 C_BAR_TXT（反白系）：
    //   深灰字压在黑底上等于没写。选中那一格仍然是实心橙 + 奶白字（见 bar_refresh）。
    // ★★ 2026-09-19（第十五轮）：**六格改成等宽 + 等间距**。
    //   用户原话：「彼此之间距离要保持一致」。所以：
    //     · 格宽 36 -> **35**，格间距 g = 2 不变，但**取消了 dex_gap = 8**
    //       —— 那个 8 是特意把「收集」和 5 个时长隔开的，会让 4时|12时|收集 之间
    //       凭空多出 6px，正是「距离不一致」的来源；
    //     · 于是六格一体：total = 6*35 + 5*2 = **220** ⇒ x0 = (240-220)/2 = **10**，
    //       相邻格一律差 2px，两端各留 10px。
    //   为什么格宽只能到 35：最宽的字是「12时」= **34px**（tools/_fx.py 量的，
    //   不是估的），35 恰好留 0.5px 边距；要 36 就得 total = 226、两端只剩 7px，
    //   呼吸感不够 —— 所以选 35。
    //   ⚠ x0=10 也刚好避开屏幕左下圆角：格底 y=317 那一行，圆角的可见边界在
    //     x≈13.9，而格子（radius=11 的胶囊）的左边界在 21 —— 稳稳在内侧。
    const int w = 35, g = 2, h = 22, y = 3;
    const int total = (FA_SLOT_COUNT + 1) * w + FA_SLOT_COUNT * g;
    const int x0 = (SCR_W - total) / 2;

    // 六格连「收集」一起建（原来「收集」是单独建、坐标另算）。底色**一律透明**：
    // 通栏遮罩已经在底下铺满了，格子之间不该再有任何一块自己的底。
    // 选中态的橙色由 bar_refresh() 刷进来。
    for (int i = 0; i <= FA_SLOT_COUNT; i++) {
        int x = x0 + i * (w + g);
        U.pill[i] = mk_box(U.bar, x, y, w, h, C_ACCENT, h / 2, LV_OPA_TRANSP);
        U.pill_lb[i] = mk_label(U.pill[i], &fa_font_ui, C_BAR_TXT,
                                (i < FA_SLOT_COUNT) ? fa_slot_label(i) : "收集");
        lv_obj_center(U.pill_lb[i]);
    }
}

static void build_away(void)
{
    // ★ 2026-09-19（第九轮）：面板 108 -> 126 高，提示从 1 行变 2 行。
    //   用户原话：「旅行中的时候，不写（不给三叶草）这句话，改为
    //   长按 花 X 个猫罐头回来，短按进入收藏」。
    //   两行 11px 小字 + 5px 行距要 40px，原来的面板装不下（82 + 40 > 108）。
    //
    // ★★ 2026-09-19（第十轮）：**y 从 108 提到 44**。
    //   用户原话：「把旅行中的文字框往上放，尽量让小猫显示出来」。
    //   一算就知道为什么非提不可：面板高 126，y=108 时底沿到 **234**，
    //   而猫的身体占 y **200..264** —— 面板原来把猫**整个盖住**了。
    //   第九轮之前看不出这个问题，因为那会儿旅行中铺的是带猫明信片、
    //   我们自己的猫是藏着的（cat_sync 的旧判据）。
    //   第十轮**猫在场了**，它就立刻变成一道硬约束：面板底沿必须留在 200 之上。
    //
    //   现在：面板 44..180，猫 200..264，中间留 20px 空当；
    //   上面离 HUD（y 3..25）还有 19px，下面离底栏（292）更远 —— 三样都不打架。
    //   ⚠ 改这个 y 之前先确认 CAT_Y 没变，这两个数是一对。
    //   ★★ 第十二轮再把高度 126 -> **136**：提示第二行从「短按进入收藏」变成了
    //     「短按进入收藏，打小游戏获得猫罐头」（17 个字，11px 下约 187px）。
    //     200px 的框本来勉强装得下，但再没有余量 —— 万一字宽算多了折成两行，
    //     40px 的提示区就会被切掉半截。加到 136 之后即使折行也还剩一行位置。
    //     底沿 44+136 = 180，离猫的顶（CAT_Y=200）仍有 20px，这条约束没破。
    U.ov_away = mk_box(U.scr, 20, 44, 200, 136, C_PANEL, 14, LV_OPA_90);

    // ★★ 第四十六轮：内容整体上移 4px，让上下留白拉平。
    //   用户原话：「旅行页用原高」+「整体文字最好统一往上移动一点儿，
    //   让上下的空余间距一致」。原来是 上 12 / 下 4 —— 明显头重。
    //   新的一组 y：标题 8 / 时刻 32 / 进度条 60 / 提示 76（高 54）⇒ 上留白 8、下留白 7。
    //   ⚠ 面板**高度没动**（还是 136）：腾出来的这 4px 靠内部间距收紧，
    //     不是把框做大 —— 底沿 180 那条「不许压到猫的顶（CAT_Y=200）」的约束没破。
    U.away_title = mk_label(U.ov_away, &fa_font_ui, 0xFFF6EC, "旅行中");
    place(U.away_title, 0, 8, 200, 20);
    lv_obj_set_style_text_align(U.away_title, LV_TEXT_ALIGN_CENTER, 0);

    U.away_time = mk_label(U.ov_away, &fa_font_ui, C_ACCENT, "00:00");
    place(U.away_time, 0, 32, 200, 20);
    lv_obj_set_style_text_align(U.away_time, LV_TEXT_ALIGN_CENTER, 0);

    U.away_bar_bg = mk_box(U.ov_away, 24, 60, BAR_W, 8, 0x5A544A, 4, LV_OPA_COVER);
    U.away_bar_fg = mk_box(U.ov_away, 24, 60, 0,    8, C_ACCENT, 4, LV_OPA_COVER);

    // ★ 三行（第四十六轮由 2 行变 3 行）：
    //     ① 「长按 ● 花 X 个猫罐头回来」—— 价钱每帧在变，见 fa_view_tick
    //     ② 「短按进收藏，打小游戏赚猫罐头」—— 固定
    //     ③ 「↑↓ 键关闭屏幕」—— 固定，第四十六轮新加（用户点名要的一句）
    //   用显式 \n 换行，不依赖自动折行：200px 宽里三行都塞得下，
    //   自动折行只会在奇怪的地方断开。
    // ★ 高度记账（**这一格唯一会静默出错的地方**）：
    //   tiny 13px 的 line_height = 15 ⇒ 3 行 + 2 × 行距(4) = 45 + 8 = **53px**。
    //   给 54 刚好装下。⚠ 行距若回到 5 ⇒ 55 > 54，**第 3 行会被切掉半行**。
    //   ⇒ 行距 4 和高度 54 是一对，改一个必须回头看另一个。
    //   （同样的坑第十三轮踩过：当时面板 52 高、三行要 55，第三行被裁。）
    U.away_hint = mk_label(U.ov_away, &fa_font_tiny, 0xC8C0B2, "");
    place(U.away_hint, 0, 76, 200, 54);
    lv_obj_set_style_text_align(U.away_hint, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_set_style_text_line_space(U.away_hint, 4, 0);
    // ★ 这行文案不再是常量：快速返回按**剩余时长**计价，价钱每秒钟都在变，
    //   所以由 fa_view_tick() 每帧算一次再决定要不要重写（见那边的 s_last_recall_cost）。

    lv_obj_add_flag(U.ov_away, LV_OBJ_FLAG_HIDDEN);
}

// 明信片小风景的六套配色，按景点色档取
static const uint32_t HUE_SKY[6]   = { 0xDCEBF2, 0xF6E6D2, 0xE3E9F5, 0xE8F1E4, 0xF5E4E8, 0xE9E4F2 };
static const uint32_t HUE_HILL[6]  = { 0xA8C398, 0xD9B98A, 0x9FB3D4, 0x9CC49A, 0xD3A8B4, 0xAFA3CE };
static const uint32_t HUE_HILL2[6] = { 0x8FAE7E, 0xC2A070, 0x8597BC, 0x82AC80, 0xBC8C99, 0x958AB8 };
static const uint32_t HUE_WATER[6] = { 0xA9CEDD, 0x9FC0C9, 0xB0C4DE, 0x9ECBB4, 0xC3B0C9, 0xB2B6D8 };
static const uint32_t HUE_SUN[6]   = { 0xF7D08A, 0xF2A65A, 0xEFE9D8, 0xE9C46A, 0xF2A9A0, 0xC9B8E8 };

static void build_card(void)
{
    // ★★ 2026-09-19 版面重排：这张卡原来画的是**程序化的抽象小风景**
    //   （五个色块拼出来的天/山/水），跟收集册里那张真明信片是两码事。
    //   实机反馈「到了地方要能直接看到明信片」——
    //   跑了五个小时回来，看到的却是一块和收藏册里对不上的色块，
    //   等于白跑。现在这里直接贴素材原图（按 scale 243 缩到 167x208，等比不变形）。
    //   程序化小风景降级成兜底：只有「又见旧地」（没拿到新明信片）时才露出来。
    U.ov_card = mk_box(U.scr, 12, 12, 216, 296, C_CARD, 12, LV_OPA_COVER);

    // ---- 明信片位 176x208（素材 176x220，按 scale 243 缩到 167x208 再居中）----
    lv_obj_t *art = mk_box(U.ov_card, 20, 6, 176, 208, C_TRANS, 8, LV_OPA_TRANSP);
    // ★★ 第十三轮：176x220 -> 176x208（理由见 build_dex 里 dex_art 那一段）。
    // ★ 第十三轮：clip_corner 删除（176x8x4 = 5,632 B 的中间图层）。
    //   代价是这张明信片的四角由圆角变直角 —— 8px 半径，肉眼几乎看不出来，
    //   但它是「一次分配 5.6KB」换来的，不值。要圆角就回 build_corners 那套思路。
    lv_obj_remove_flag(art, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    // 兜底那套程序化小风景——建在 image 之前，所以永远压在它下面。
    // ★★ 第十三轮：**这六块已经到不了了**（card_fill 的两支都在 set_src，
    //   图片层永远盖在它上面），所以它们的坐标**没有**跟着图位 208 一起改。
    //   真要去掉，请连着 U 结构体里那 5 个字段一起删，别只删这里。
    U.card_sky  = mk_box(art, 0, 0, 176, 140, HUE_SKY[0], 0, LV_OPA_COVER);
    U.card_sun  = mk_box(art, 118, 16, 34, 34, HUE_SUN[0], LV_RADIUS_CIRCLE, LV_OPA_COVER);
    U.card_hill_box = mk_box(art, 0, 72, 176, 40, C_TRANS, 0, LV_OPA_TRANSP);
    U.card_hill[0] = mk_box(U.card_hill_box, -26, 10, 120, 120, HUE_HILL[0],  LV_RADIUS_CIRCLE, LV_OPA_COVER);
    U.card_hill[1] = mk_box(U.card_hill_box,  70,  2, 140, 140, HUE_HILL2[0], LV_RADIUS_CIRCLE, LV_OPA_COVER);
    U.card_water = mk_box(art, 0, 140, 176, 80, HUE_WATER[0], 0, LV_OPA_COVER);

    U.card_img = lv_image_create(art);
    lv_obj_remove_flag(U.card_img, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_align(U.card_img, LV_ALIGN_TOP_MID, 0, 0);   // 顶对齐，见 build_dex 那段
    // ★★ 2026-09-19（第十七轮）：**补一句显式 set_size**，和 dex_img 那边对齐。
    //   为什么必须补：`lv_obj_align(TOP_MID)` 算的是 `x = (父宽 - 对象宽)/2`，
    //   而对象宽来自 `lv_image` 的 self_size —— 缩放过的大小。**它必须是个确定的数**，
    //   角标（下面那道箍）却按「图恰好 167 宽、左沿恰好 4」硬算。
    //   两边一旦差 1px，图上就会露出一条竖直的方边 —— 那正是用户说的
    //   「切的不够准确，留有残余边框」。显式写死 167x208 之后，
    //   `x = (176-167)/2 = 4` 是整数除法，与角标的内轮廓 (4,0)-(170,207)
    //   **逐像素重合**，不再有取整的余地。
    //   ⚠ 顺序：`set_size` 放在 `set_scale` **之前**也成立（两者互不覆盖，
    //     理由见 build_dex 里 dex_img 那三行注释），这里跟着 dex_img 的写法走。
    lv_obj_set_size(U.card_img, 167, 208);
    // ★★ 第十三轮：**到达卡也必须自己设一次 scale**。dex_img 那边每次 set_src
    //   都要显式写回缩放，是因为它要在家底图(167)和明信片(243)之间来回切；
    //   这张卡的图**永远是明信片**，所以在建的时候设一次就够，card_fill 不用管。
    //   ⚠ 别漏这一句：漏了就是 256（1:1 = 176x220）塞进 208 的图位，底部被切一刀。
    lv_image_set_scale(U.card_img, 243);

    // ---- 到达卡明信片的四角角标（2026-09-19 第十四轮）----
    // ★ 用户这一轮点名的是「**收藏中的**明信片」，但到达卡上贴的是同一张明信片、
    //   同一个 167x208 的尺寸 —— 只圆一处，翻到最后会发现「收下这张」的卡是方的、
    //   收藏册里那张是圆的，两处对不上。所以这里用**同一套常量、同一个几何**一起做。
    //   几何推导（为什么圆心要对齐图的角、IMG_CVR_B 为什么从 4 提到 10）
    //   完整写在常量块与 build_dex 的角标那一段，这里不重复。
    //   ★★ 第十七轮订正：~~「角标 y = 6 - 4 = 2，上沿离卡片边还有 2px 余量」~~
    //     这个「必须留在卡片内」的前提**不成立** —— 角标的可绘区被硬裁到 art 的框，
    //     超出 art 的部分根本画不出来（推导见常量块 IMG_CVR_B 那一段）。
    //     现在 y = 6 - 10 = **-4**，那 4px 落在 art 框外，被裁掉，什么也看不见。
    //   ⚠ 和收藏册一样：art 开 OVERFLOW_VISIBLE。但**它不是圆角生效的原因**
    //     —— 见 build_dex 那一段的订正说明（旧注释把这一点记反了）。
    lv_obj_add_flag(art, LV_OBJ_FLAG_OVERFLOW_VISIBLE);
    U.card_art_cv = mk_box(art, 4 - IMG_CVR_B, -IMG_CVR_B,
                           167 + 2 * IMG_CVR_B, 208 + 2 * IMG_CVR_B,
                           C_CARD, IMG_CORNER + IMG_CVR_B, LV_OPA_COVER);
    lv_obj_set_style_bg_opa(U.card_art_cv, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(U.card_art_cv, IMG_CVR_B, 0);
    lv_obj_set_style_border_color(U.card_art_cv, lv_color_hex(C_CARD), 0);
    lv_obj_set_style_border_opa(U.card_art_cv, LV_OPA_COVER, 0);
    // ★ 它建在 card_img **之后** —— 建序即图层序，早于图就被图盖住。
    //   （下面那五块程序化兜底小风景建在 card_img **之前**，所以它们会被
    //     这个角标一起切圆 —— 那一支「又见旧地」的小风景也跟着圆角了，正好。）

    // ★★ 第十三轮：下面这五行的 y/高全部重排过一次，因为两支字库都变大了
    //   （ui 15->16 Bold、tiny 11->13 Medium）且图位缩了 12px。可用区间是硬的：
    //     卡片内 0..295，图位占到 213 ⇒ 只剩 214..295 共 82px 放四行。
    //   新的分配（相对卡片）：地名 217..234 / 题词 240..254 / 收支 259..273 /
    //   提示 278..292。**加行之前先算这个 82**，算不下就得先动图位。
    //   （墨迹高度实测：ui 18px、tiny 15px；上面的 y 按「行间留 3~5px」摆。）
    U.card_name  = mk_label(U.ov_card, &fa_font_ui,   C_TEXT, "");
    place(U.card_name, 16, 217, 184, 19);
    lv_obj_set_style_text_align(U.card_name, LV_TEXT_ALIGN_CENTER, 0);

    U.card_verse = mk_label(U.ov_card, &fa_font_tiny, C_DIM, "");
    place(U.card_verse, 12, 240, 192, 16);
    lv_obj_set_style_text_align(U.card_verse, LV_TEXT_ALIGN_CENTER, 0);

    // 三叶草与纪念品并排一行 —— 竖着排的话卡片高度不够，
    // 176x220 的明信片本来就吃掉 220px 里的绝大部分。
    U.card_gain  = mk_label(U.ov_card, &fa_font_tiny, C_CLOVER, "");
    place(U.card_gain, 8, 259, 110, 16);
    lv_obj_set_style_text_align(U.card_gain, LV_TEXT_ALIGN_CENTER, 0);

    U.card_souv  = mk_label(U.ov_card, &fa_font_tiny, C_ACCENT, "");
    place(U.card_souv, 118, 259, 90, 16);
    lv_obj_set_style_text_align(U.card_souv, LV_TEXT_ALIGN_CENTER, 0);

    // ★ 2026-09-19（第九轮）：高度 14 -> 24，因为这一行**曾经是两行**
    //   （「● 收下　长按设背景」+「这张已经有了」，见 card_fill）。
    // ★★ 第十三轮：**两行取消了**，而且这一行的 y 从 282 提到 278。
    //   tiny 从 11px 提到 13px 之后两行要 2 x 15 + 行距 = 30px，
    //   而图位下面只剩 82px 放四行 —— 差 7px 装不下（见上）。
    //   ⇒ 「又见旧地」那一句从换行版改成**一行**（「…（已有）」），见 card_fill。
    //   于是这一格回到单行，高度 18 -> 16：tiny 的墨迹是 15px，16 刚好。
    //   ⚠ 旧值 282 会让墨迹落到卡片下沿**外面**（282+15-1 = 296 > 295）——
    //     切掉的是最后一行字的下缘，实机上就是「字被削了一刀」。
    //   ★★ 2026-09-19（第十六轮）文案改口径：用户原话「在明信片选择背景的时候，
    //     然后别写"长按设背景"，写"长按去游玩"，然后更换背景后，写"已经到XX"」。
    //     ⇒ 「设背景」这个说法整条线取消（card_hint 两处 + dex_hint 两处 +
    //       两条 toast，见下面各自的位置）。「去游玩」才是那一按真正的去处。
    //   ⚠ 字数没变（还是 9 个字），所以 place() 的数字一个都不用动。
    U.card_hint  = mk_label(U.ov_card, &fa_font_tiny, 0xB0A896, "● 收下　长按去游玩");
    place(U.card_hint, 16, 278, 184, 16);
    lv_obj_set_style_text_align(U.card_hint, LV_TEXT_ALIGN_CENTER, 0);

    // ---- 「新获得」闪字（2026-09-19 第十六轮）----
    // ★ 四件套：外层深棕胶囊（假描边）+ 内层橙胶囊 + 24px 暖白大字 + 三颗小星。
    //   ⚠ 位图字库做不出真描边（铁律 8：text_outline_stroke_* 只对 FreeType
    //     矢量渲染生效），所以「字外面有一圈深色」是靠**两层胶囊**堆出来的 ——
    //     外层比内层四周各大 3px，露出来的那一圈就是描边。
    //   ⚠ 四件都必须建在 card_art_cv **之后**（建序 = 图层序）——
    //     晚于角标，才不会被那道 4px 的白色边框啃掉一圈。
    //   ⚠ 位置是**相对 ov_card**（那张白卡），不是屏幕坐标。图位中心 x = 108，
    //     所以 NB_X = 108 - NB_W/2 = 56（见常量块那一节）。
    U.nb_bg = mk_box(U.ov_card, NB_X - 3, NB_Y - 3, NB_W + 6, NB_H + 6,
                     0x3A2412, 17, LV_OPA_COVER);
    U.nb_in = mk_box(U.ov_card, NB_X, NB_Y, NB_W, NB_H, C_ACCENT, 14, LV_OPA_COVER);

    // 「新获得」= 3 个字。视觉宽按铁律 15 算：**每个字后面各加一份字距**
    //   ⇒ 3*24 + 3*6 = 90（不是 2*6）。标签框给满 NB_W 更保险，居中靠 text_align。
    // 墨迹高度：**实测**（tools/_measure_fonts.py 的姊妹脚本 fm16.py 读生成物）
    //   fa_font_game 24px：line_height 24 / base_line 3，
    //   「接」box_h 24 ofs_y -3 ⇒ 墨迹 = **框顶 + 0 .. 框顶 + 23**（正好 24 高）。
    //   ⇒ 要让它在 40 高的胶囊里上下居中：框顶 = (40-24)/2 = **8**。
    //     ⚠ 别凭「基线 = 框顶 + 21」去推——那是基线，不是墨迹顶；
    //       按基线推会得到 11，墨迹就落 11..34，上余 11 下余 5，肉眼明显偏下。
    U.nb_lb = mk_label(U.ov_card, &fa_font_game, 0xFFF6EC, "新获得");
    place(U.nb_lb, NB_X, NB_Y + 8, NB_W, 24);
    lv_obj_set_style_text_letter_space(U.nb_lb, 6, 0);
    lv_obj_set_style_text_align(U.nb_lb, LV_TEXT_ALIGN_CENTER, 0);

    // 三颗暖白小星（就是三个圆点图元）横排在胶囊**上方**。
    //   ★ 为什么不塞进胶囊里：大字一个人就占掉 8..31，40 高的胶囊里再没有位置。
    //   ★ 三个点的总宽 3*8 + 2*8 = 40，起始 NB_X + 32 ⇒ 覆盖 88..128，正中 108 ——
    //     正好是图位中心，和胶囊同心。
    for (int i = 0; i < 3; i++) {
        U.nb_star[i] = mk_box(U.ov_card, NB_X + 32 + i * 16, NB_Y - 13,
                              8, 8, 0xFFE9C0, LV_RADIUS_CIRCLE, LV_OPA_COVER);
    }

    // ---- 全解锁横条（同一轮）----
    // ★ 贴在明信片图位顶部的一条橙带（176 = 图位宽，与 IMG_CVR_B 那套几何同源）。
    //   ⚠ 它和「新获得」**可能同时出现**（收下的正好是最后一张），所以 y 必须错开：
    //     横条 14..38 / 三颗星 49..57 / 闪字胶囊 59..105 —— 三块互不重叠。
    //   墨迹：**实测** fa_font_tiny 13px：line_height 15 / base_line 3，
    //   汉字多为 box_h 13 / ofs_y -2 ⇒ 墨迹 = **框顶 + 1 .. 框顶 + 13**（13 高）。
    //   ⇒ 要让它在 24 高的带子里居中：框顶 = 4（墨迹落 5..17，上余 5 下余 6）。
    U.allbar = mk_box(U.ov_card, ALLBAR_X, ALLBAR_Y, ALLBAR_W, ALLBAR_H,
                      C_ACCENT, 12, LV_OPA_90);
    U.allbar_lb = mk_label(U.ov_card, &fa_font_tiny, 0xFFF6EC, "全部明信片到手了");
    place(U.allbar_lb, ALLBAR_X, ALLBAR_Y + 4, ALLBAR_W, 16);
    lv_obj_set_style_text_align(U.allbar_lb, LV_TEXT_ALIGN_CENTER, 0);

    lv_obj_add_flag(U.ov_card, LV_OBJ_FLAG_HIDDEN);
}

// 收集册纵向版面（2026-09-19 第五次：整册只剩「家 + 明信片」一种页面；
//                  第十三轮：图位 220 -> 208、卡片 286 -> 290、整块下移 2px）：
//   顶栏 6..20：左「明信片 x / 24」+ 右电量（都在暖黑底上，无衬底）
//   白卡 24..313（216x290，居中 x=12）：
//       图     28..235（176x208 容器；图本身 167x208，左右各留 4px）
//       地名   239..256      题词 260..274
//       序号   278..292      提示 296..310
#define DEX_CARD_Y   24
#define DEX_CARD_H   290

// ================================================================== 「小游戏 / 设置」两格入口
//
// ★★★ 2026-09-20（第二十轮）用户原话：
//   「就是这个界面，我感觉不够好看，帮我改一改……变成上下两部分，上部分占 2/3，
//     下部分占 1/3，上下两部分都是图片，上部分图片里面写的文字是『小游戏，
//     收集明信片，解锁更多小游戏』，下半部分图片里面写的文字是设置。两张图片的
//     猫咪一左一右，设计的类似明信片的风格的图片。」
//   +「用第一种（A · 白框双拼），然后外框四角都变成圆弧的。」+「要圆角 10。」
//   +「向上翻接最后一张明信片，向下翻是家，把圆角 10 做进去吧，改源码吧，不编译。」
//
//   ⇒ 收藏册「小游戏」那一格（DEX_ENTRY_PLAY）的图位，从**一整张风景 + 黑遮罩**
//     改成**上下两张小照片**（明信片风）：上 2/3 是「小游戏」入口，下 1/3 是「设置」。
//     两格各自圆角 10，两只猫一左一右。
//
// 几何（**第二十三轮再压一档**；下列坐标全是**卡片内**；卡片 mk_box(12,24,216,290)）：
//     上格 y10 + 152 + 6px 白缝 + 下格 76 = 234 —— 底沿 y244，到 hint(y272) **留白 28px**
//     宽 = 155，x = 30（居中于白卡：左右各 30 / 31）
//   ★★ 2026-09-20（第二十二轮）用户原话：「现在整个页面下方空白还很大，
//      可以整体高度都调整搞高一些呀。」
//      旧几何 127 + 6 + 63 = 202 是挂在**图位**(176x208)里的，底沿只到 y202，
//      图位下方到 hint 之间还空着一大条 —— 加高就是把这一条填掉。
//   ★★ 2026-09-20（第二十三轮）用户原话：「我要两格猫 56，然后把高度压缩一些，
//      只要不压着字，就往上提一些，给下面留点儿空白，现在太挤了。」
//      ⇒ 上一轮加高到 258 之后底沿(268)离 hint(272) 只剩 4px —— **填过头了**。
//        这一轮从下面收回 24px：168 + 6 + 84 = 258 → **152 + 6 + 76 = 234**，
//        底沿 268 → **244**，下方留白 4px → **28px**。上:下 仍是精确 2:1。
//   ⚠ **父对象从 dex_art 换成了 dex_card**：GX / UP_Y / DN_Y 现在是卡片内坐标，
//     不是图位内坐标（旧值是 6 / 6 / 139，别照着抄）。
//     换父的理由：① 图位只有 208 高，装不下 234 的两格；
//                 ② 这一格的底图早被 dex_show_pair() 收掉了（dex_img HIDDEN），
//                    两格之外露出来的本来就是**白卡**，不必再为了「盖住底图」
//                    把两格撑到图位那么宽 —— 所以宽度仍是 155、而不是 176。
//   ⚠ 上 : 下 = 2:1（用户说的 2/3 : 1/3）是**硬约束**：改 UP_H 必须同时改 DN_H
//     （DN_H = UP_H / 2），否则比例就不是 2:1。DN_Y 是表达式（UP_Y+UP_H+PAD），不用手改。
//   ⚠ 两格高度的**下限由字决定，不由感觉决定**：上格第二行小字「解锁更多小游戏」
//     墨迹下沿 = y77，猫实体顶 = UP_H − DEX2_CAT·31/32 ⇒
//         UP_H ≥ 77 + 1 + 56·31/32 ≈ **132.3**（按 DEX2_CAT = 56 算）
//     本轮取 152，离这道墙还有 19.7px。想再压就照这个式子算 —— 别凭眼睛估，
//     压过 132 就是「猫压住『解锁』俩字」那个老问题原样回来。
#define DEX2_GX       30         // 两格在卡片内的 x
#define DEX2_PAD      6          // 两格之间的白缝（不再兼作「白边」）
#define DEX2_W        155
#define DEX2_UP_Y     10
#define DEX2_UP_H     152        // ★ 第二十三轮：168 → 152（DN_H 必须同步 = UP_H/2）
#define DEX2_DN_Y     (DEX2_UP_Y + DEX2_UP_H + DEX2_PAD)      // = 168，写成表达式免得改一个忘一个
#define DEX2_DN_H     76         // ★ 第二十三轮：84 → 76（= UP_H/2，精确 2:1）
#define DEX2_CORNER   10         // ★ 用户点名：圆角 10（不是图位原来的 IMG_CORNER=8）
//   圆角用「零图层角标」实现（和 U.dex_art_cv 同款，见 build_dex 里那段推导）：
//   对象外扩 B、radius = DEX2_CORNER + B、border_width = B
//   ⇒ 外圆角圆心 = (-B + CORNER + B) = (CORNER, CORNER) —— 正好落在照片自己的角上；
//     内边界 = (-B + B) = 0 —— 正好是照片那一块。
//   ⚠ B 有下限：要遮的最远点（照片的角 (0,0)）到圆心 (10,10) 的距离 = 10*√2 ≈ 14.14，
//     环带是 [10, 10+B] ⇒ **B ≥ 4.14**。取 10（与 IMG_CVR_B 同值），余量 20 - 14.14 = 5.86px。
#define DEX2_CVR_B    10
//   图的缩放：素材是 240x320，要**宽度填满 155** ⇒ scale = 155/240*256 ≈ 165.33 -> 165
//   缩完 154.7 x 206.25 -> 取 155 x 206，比两个格子都高（168 / 84）⇒ 上下各溢出，**居中裁切**。
//   ⚠ 这和预览脚本里的 cover() 是同一个算法（等比填满 + 居中裁），别改成顶部对齐 ——
//     顶部对齐会把画面往上顶 40px，长城那张的天空就全没了。
#define DEX2_IMG_SCALE 165
#define DEX2_IMG_H     206
//   两格的**暗底**：都是「整格一层 60% 的实心暗底」，同一个规格。
//   ★ 2026-09-20 用户拍板（上一轮抛出的二选一）：「顶部暗底，不用渐变，
//     都用暗底 60% 透明，统一就行，不要又分成两块。」
//     ⇒ 上格从「只盖文字那 84px」改成**整格** DEX2_UP_H，
//       下格也补一层同规格的 DEX2_DN_H —— 两格不再一块一块。
//   ⚠ 预览稿（PNG）里画的是**自上而下渐变**（顶部 alpha 170 → 底部 0），
//     但 LVGL 的 bg_grad 只有「两个颜色 + 整体一个 opa」，**做不出两端不同透明度**
//     ⇒ 真机只能是实心块。这一轮用户点名「不用渐变」，正好把这个差异抹平了。
//   ⚠ 建序（＝图层序）必须是：图 → **暗底** → 文字 → 猫。
//     早于图会被图整个盖住（暗底白做）；晚于猫会把猫也压暗一层
//     （猫是这一页的装饰主体，压暗了就不像贴纸了）。
#define DEX2_DIM_OPA  LV_OPA_60
//   两只猫的**尺寸**：56x56 —— 两格同值；比主页那只（CAT_W / CAT_H = 64）小一号。
//   ★★ 2026-09-20（第二十二轮）用户原话：「我要小游戏和设置的猫咪大小一样，
//      设置的猫要小一些，可以跟主界面的猫大小一致。」⇒ 当时两格统一到 **64**。
//   ★★ 2026-09-20（第二十三轮）用户原话：「我要两格猫 56……」
//      ⇒ 64 → **56**。这一轮「猫变小」和「两格压低」是**同一个视觉目标**的两个面：
//        格子里塞的东西少一点、下方让出一点白来，所以两个数要一起看。
//   ⚠ **56 不是 1:1 了 ⇒ `set_scale` / `set_size` 两句必须补回来（上下两格都要）**：
//        lv_image_set_scale(U.dex2_up_cat, DEX2_CAT * 256 / 64);   // 56*256/64 = 224
//        lv_obj_set_size   (U.dex2_up_cat, DEX2_CAT, DEX2_CAT);
//      这是一对「必须成对」的语句：只 set_scale 不 set_size 的话，64x64 的对象
//      会把图缩到框正中 ⇒ 猫脚离容器底 8px（看着浮起来），
//      而且**编译期一点提示都没有**（铁律 20 那一类）。
//   ★ 为什么 56 在这两格里放得下（几何账，别凭感觉）：
//     猫实体像素在 64 格里占 (9,2)-(55,63)；缩到 S、框底贴容器底时
//         实体顶 = (UP_H − S) + 2·S/64 = UP_H − S·31/32
//     S = 56 ⇒ 实体顶 = UP_H − 54.25
//     上格 152 ⇒ 实体顶 97.75，离第二行小字下沿(y77) 还有 **19.7px** ✓
//     下格  76 ⇒ 实体顶 21.75 —— 猫在格里上方留 21px，与左侧「设置」同一行。
//   ⚠ 别按「脚底在 48/64」补 y 偏移 —— 那是早先预览脚本里的错算
//     （实测 cat_idle / cat_read / cat_write 帧 0 的脚底都在 63/64），照它会往下沉。
#define DEX2_CAT      56
//   上格那只猫的**上提量**（下格不动）—— 用户 2026-09-20（第二十四轮）原话：
//       「A 吧，小游戏的猫可以再往上一些，上不压字，下面别把脚压住看不到了。」
//   ⇒ 上格猫的对齐由 `BOTTOM_LEFT, 4, 0`（框底 = 格底）改成 `BOTTOM_LEFT, 4, -LIFT`。
//   ★ 这个数和 DEX2_CAT 一起管住「上缝」（猫顶↔字）与「脚下」（脚↔格底）两件事。
//     全按**实测**算（cat_read 帧 0 缩到 56 后可见像素 bbox = (8,1)-(48,55)）：
//         框底贴格底时 实体顶 = 152 − 56 + 1 = **97**、脚底 = 152 − 1 = **151**
//         第二行小字「解锁更多小游戏」墨迹下沿 = **y77**
//      ⇒ 不提时 上缝 20px、脚下 **1px** —— 最后那 1px 就是用户说的
//        「脚被压住看不到」（脚正压在格底那条边上）。
//      ⇒ 提出 LIFT 后 上缝 = 20 − LIFT（↓）、脚下 = 1 + LIFT（↑），两件事一起松。
//   ★ 上墙：上缝 ≥ 1 ⇒ **LIFT ≤ 19**。提到 20 就是「猫压住『解锁』俩字」原样回来。
//   ★ 等距点：20 − LIFT = 1 + LIFT ⇒ LIFT = 9.5。四档（0 / 6 / 10 / 14）渲染给用户挑，
//     **用户 2026-09-20 选的是 6**（上缝 14、脚下 7 —— 比等距点保守 3.5px，离字更远一点）。
//   ⚠ 别顺手把下格也提：下格只有 76 高，猫本来就顶着格底、左侧还有「设置」两字，
//     提上去把「一左一右」的错落感弄平了；用户这一轮只点了上格。
#define DEX2_UP_CAT_LIFT 6       // ★ 第二十四轮新增（下格仍是 0）

//   两只猫的**动态**：上格看书（cat_read）、下格用桌子（cat_write）。
//   ★★ 2026-09-20（第二十二轮）用户原话：「这两只猫，可以用不一样的动态表现吗？
//      就是分别设置为看书，还有用桌子的那两只动态猫。」
//   ⇒ 从「静态第 0 帧」改成接 `fa_play_t` 播放器（与主页 s_cat_play / mini / rps
//     同一套 API、同一档帧长）。
//   ⚠ 播放器实例必须**两格各一个**（s_dex2_up_play / s_dex2_dn_play）：
//     共用一个的话两只猫会被推着同帧跳，而且任意一组名一变，另一组也跟着重置。
//   ⚠ 名字要和 fa_sprites.c 里 fa_anims[] 的 id 一字不差（写错 play_set 会
//     静默 return，表现是「猫不动」，编译期一点提示都没有 —— 铁律 20 那一类坑）。
#define DEX2_UP_ANIM   "cat_read"
#define DEX2_DN_ANIM   "cat_write"
#define DEX2_FRAME_MS  220       // 与主页 / mini / rps 同一档（8 帧 ≈ 1.76s 一轮）

// ==================== 两格的光标（第四十五轮） ====================
//
// ★★★ 用户 2026-09-21 原话（问题一的另一半）：「……而且，设置格选不中。」
//   ⇒ 第二十轮那版是**写死的**：橙描边永远画在上格，↑↓ 直接翻页，
//     下格「设置」谁也进不去（见 build_dex 里那段「功能没定之前不做光标」的留痕）。
//     本轮设置页做出来了，那个前提消失，光标必须真做出来。
//
// 走位规则（用户点名）：「↑↓ 先在两格之间走、到边才翻页」。
//   ⇒ 停在上格时按 ↓ = 走到下格；停在下格时按 ↓ 才翻到下一条。
//     反过来同理：停在下格按 ↑ = 回上格；停在上格按 ↑ 才翻回上一条。
//   ⚠ 这条规则**只对「小游戏」那一格成立** —— 别的页只有一件东西，
//     ↑↓ 照旧直接翻页（见 fa_view_dex_move）。
//   ⚠ 光标**不重置**：翻走再翻回来还停在下格。这是有意的 ——
//     翻页本来就会经过好几页，每次都弹回上格会让人以为「设置不见了」。
//     （开册时重置一次，见 fa_view_dex_show。）
static uint8_t s_dex2_cur;      // 0 = 上格「小游戏」 / 1 = 下格「设置」

// 把那一圈橙描边挪到当前这一格上。
//   ★ 用**容器自己的 border** 画，不另建对象（第二十轮就定的写法，见 build_dex）：
//     容器的 radius 只影响它自己那个边框的绘制，**不会**把子对象裁成圆角 ——
//     裁圆角的活儿仍然是 DEX2_*_CV2 那个角标干的，两者互不干涉。
//   ★ 两条一起写、宽度互补（选中的 2、另一个 0）：
//     只写「给选中的设 2」会留下一圈永远不灭的旧描边（宽度不会自己回去）。
//   ⚠ 下格的 radius 必须在这里补 —— build_dex 里那个 mk_box 传的是 0
//     （下格本来就是方角容器，圆角全靠角标遮出来）。不补的话描边是**方角**的，
//     和角标遮出来的圆角对不上，拐角处会露出一小段橙线。
static void dex2_cursor_apply(void)
{
    const bool up = (s_dex2_cur == 0);

    lv_obj_set_style_radius(U.dex2_up_cv, DEX2_CORNER, 0);
    lv_obj_set_style_radius(U.dex2_dn_cv, DEX2_CORNER, 0);
    lv_obj_set_style_border_color(U.dex2_up_cv, lv_color_hex(C_ACCENT), 0);
    lv_obj_set_style_border_color(U.dex2_dn_cv, lv_color_hex(C_ACCENT), 0);
    lv_obj_set_style_border_opa(U.dex2_up_cv, LV_OPA_COVER, 0);
    lv_obj_set_style_border_opa(U.dex2_dn_cv, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(U.dex2_up_cv, up ? 2 : 0, 0);
    lv_obj_set_style_border_width(U.dex2_dn_cv, up ? 0 : 2, 0);
}

// ★ 2026-09-19（第十三轮）删掉 DEX_OVER_W / DEX_OVER_H。
//   那两个数是给第十二轮的封面**位图**用的（176x120），必须和素材 manifest
//   的 w/h 一字不差。现在那一格是「半透明遮罩 + 真字体」（U.dex_mask），
//   铺满整个 176x220 图位，"尺寸必须和素材对齐" 这条约束**跟着位图一起消失了**。
//   ⚠ 素材侧还留着 mini_cover 那条 job（.i8 与图集里都还在）。**不用管它**：
//     它已经没有任何代码引用了，将来重刷图集时会自然被 OFFLINE 名单收走；
//     现在删它反而要多动一次 manifest 与台账。别去追。

// ★ 2026-09-19（第五次）这里删掉了 SOUV_COLS / SOUV_ROWS / SOUV_CW / SOUV_CH /
//   SOUV_GAP / SOUV_ICON / SOUV_GRID_Y 七个数 —— 它们是「12 件纪念品一页合集」
//   那套格子几何，那一页已经下线。

// ------------------------------------------------------------------ 明信片素材表
//
// 24 张明信片素材（176x220）到 24 个目的地的对应表。
//
// ★★ 2026-09-19：这张表现在是**一一对应**的，不再是「就近凑一个」。
//   以前这里全是弱对应 —— 表尾 4 条（苏州 / 青岛 / 西塘 / 武夷山）根本没有
//   对应素材，只能把剩下的填进去：于是「青岛」配的是一张戈壁、「武夷山」配的是
//   一张极光。名字和画面对不上，收集起来就是错位的。
//
//   现在反过来做：**先看素材画的是什么，再给那个景点起名**。
//   素材画的内容存在 03-素材流水线/art/manifest.json 的 subject 字段里
//   （唯一真相），按它把 fa_game.c 的 DEST_NAME 重写一遍，
//   这张表按下标与 DEST_NAME/DEST_VERSE/DEST_HUE 严格对齐。
//
//   ⚠ 顺序即语义 —— 这套顺序同时也是「由近到远」的档位分组
//     （city_* 近郊 → town_* 古镇 → prov_* 名山 → far_* 远方 → edge_* 极边）。
//     改动这张表的任何一行，都必须同步改 fa_game.c 的 DEST_NAME / DEST_VERSE /
//     DEST_HUE / DEST_SLOT 四张表，否则又会出现「名字是西湖、图是黄山」。
// ★★ 2026-09-19（第九轮）：一个景点现在有**两张图**，所以这张表从
//   「一张指针数组」改成了「一行一个景点」的结构体数组。改形状是有理由的：
//      card   176x220 —— 明信片，**画里有猫**。收集册 / 到达卡 / 旅行中铺屏都用它。
//      nocat  240x320 —— 底图，**画里没有猫**。非旅行时铺成背景，上面叠动态小猫。
//   用户原话：「我要明信片有猫，铺成背景的时候用无猫款，然后使用动态猫的图片在上面」。
//
//   ★ 为什么必须并排写在同一行：两张表一旦拆成两个平行数组，
//     「顺序对齐」就变成一条**没人能一眼看出来的隐式约束** ——
//     以前只有一张表时，错位会立刻表现为「名字是西湖、图是黄山」；
//     拆开之后，错位就是静默的（图还是图，只是配错了景点）。
//     写成一行的两个字段，改错在源码里当场就看得出来。
//
//   ⚠ 顺序即语义：这套顺序同时是「由近到远」的档位分组
//     （city_* 近郊 → town_* 古镇 → prov_* 名山 → far_* 远方 → edge_* 极边）。
//     改动这张表的任何一行，都必须同步改 fa_game.c 的 DEST_NAME / DEST_VERSE /
//     DEST_HUE / DEST_SLOT 四张表，否则又会出现「名字和画面对不上」。
typedef struct {
    const lv_image_dsc_t *card;    // 176x220 明信片（有猫）
    const lv_image_dsc_t *nocat;   // 240x320 底图（无猫）
} dest_art_t;

