// ---- 纪念品图鉴的 12 格（建一次，两页共用）----
//
// ★ 只建 **12 格**：翻页时 souv_refresh() 重画，**不重建对象**。
//   ⚠ 这是本轮唯一为 LVGL 池让步的地方 —— 建 24 格要多 24 个常驻对象
//     （12 图 + 12 字 → 24 图 + 24 字），而池只有 80 KB。
// ★ 挂在 U.dex_card 上（**不是** dex_art）—— 网格占的是**整个卡片**，
//   连 dex_img 那个图位一起盖住。所以 SOUV 分支要把 dex_img / dex_art_cv 收掉，
//   并把 dex_name/verse/idx 三行清空（那三行 y215/236/254 正落在网格里）。
static void build_souv(void)
{
    U.souv_grid = mk_box(U.dex_card, SOUV_GX, SOUV_GY,
                         SOUV_COLS * SOUV_CW, SOUV_ROWS * SOUV_CH,
                         C_TRANS, 0, LV_OPA_TRANSP);
    lv_obj_remove_flag(U.souv_grid, LV_OBJ_FLAG_SCROLLABLE);

    for (int i = 0; i < SOUV_PER_PAGE; i++) {
        const int r  = i / SOUV_COLS;
        const int c  = i % SOUV_COLS;
        const int cx = c * SOUV_CW;
        const int cy = r * SOUV_CH;

        U.souv_img[i] = lv_image_create(U.souv_grid);
        lv_obj_remove_flag(U.souv_img[i], LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_size(U.souv_img[i], SOUV_ICON, SOUV_ICON);
        lv_obj_set_pos(U.souv_img[i], cx + (SOUV_CW - SOUV_ICON) / 2,
                       cy + SOUV_ICON_DY);
        // 素材 44x44、对象框也 44x44 ⇒ 这句当前是空操作。和 dex_img 一样**显式钉住**：
        // 哪天有人把对象框改小，不至于悄悄变成「只画左上、裁掉右下」。
        lv_image_set_inner_align(U.souv_img[i], LV_IMAGE_ALIGN_CENTER);
        // 未获得的颜色在这里**设一次**（颜色不变），souv_refresh 只切 recolor_opa。
        lv_obj_set_style_image_recolor(U.souv_img[i], lv_color_hex(C_LOCK_TXT), 0);

        U.souv_name[i] = mk_label(U.souv_grid, &fa_font_small, C_TEXT, "");
        place(U.souv_name[i], cx, cy + SOUV_NAME_DY, SOUV_CW, SOUV_NAME_H);
        lv_obj_set_style_text_align(U.souv_name[i], LV_TEXT_ALIGN_CENTER, 0);
    }

    // 建完即收 —— 和设置页、dex2 两格同一条纪律：谁亮谁灭不散落在各分支里。
    lv_obj_add_flag(U.souv_grid, LV_OBJ_FLAG_HIDDEN);
}

static void build_dex(void)
{
    // ★★ 2026-09-19（第十二轮）两处改动，用户原话：
    //   「收藏界面的底色调整为黑色。」「收藏界面右上角的返回去掉，电量。」
    //   ① 底色 C_HUD(米白) -> C_DARK(暖黑)，并且补上**圆角 + clip_corner**。
    //      圆角那句不是顺手加的：册子是全屏不透明的一层，四角必须是黑的，
    //      否则底下压着什么就露什么 —— 小游戏的四个角正是「透」到这里来的
    //      （见 build_mini 里 ov_mini 那一段）。这一层补齐之后，
    //      「任何全屏层的四角都露出屏幕底色」才真正成立。
    //   ② 右上角那颗橙色「● 返回」删掉，换成电量（图标 + 数字）。
    //      怎么退没有变：● 短按本来就是出册（fa_view_dex_ok）；
    //      原来那颗胶囊只是把这件事写在脸上，现在这个位置让给电量。
    U.ov_dex = mk_box(U.scr, 0, 0, SCR_W, SCR_H, C_DARK, R_CORNER, LV_OPA_COVER);
    // ★★★ 第十三轮：**clip_corner 删除**（第十二轮加的，正是它压垮了 LVGL 堆）。
    //   radius 保留 —— 容器自己的底色是按圆角画的，四角本来就不上色；
    //   剩下的「子对象画到圆角外面」由 build_corners 那个角标统一遮掉。
    //   完整推导见 build_scene 里 bg_cv 上方那段长注释。
    lv_obj_remove_flag(U.ov_dex, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    // ---- 顶栏：左边一行总量，右边电量 ----
    // ★ 底色换成暖黑之后，原来那行深灰字（C_TEXT）等于没写，必须换成反白系。
    //   字号**没动**（还是 11px）：用户只点名了「顶上猫罐头数量和电量」放大变白，
    //   收集册顶栏这一行不在其中 —— 擅自一起放大就是把这块顶栏挤满。
    // ★ 第十三轮：y 5 -> 6、高 14 -> 18（fa_font_tiny 从 11px 提到 13px，
    //   14px 高的框会把 13px 字的下缘切掉一点）。x 10 -> 12 是躲屏幕的圆角弧。
    U.dex_title = mk_label(U.ov_dex, &fa_font_tiny, C_BAR_TXT, "");
    place(U.dex_title, 12, 6, 156, 18);
    lv_obj_set_style_text_align(U.dex_title, LV_TEXT_ALIGN_LEFT, 0);

    // ★ 电量：图标 + 数字，**与主页 HUD 同一个字号、同一个字色**。
    //   右沿 226 和原来那颗「● 返回」对齐，顶栏两头才不歪。
    // ★ 第十三轮：y 6 -> 8（fa_font_ui 16px 的行高是 19，图标 14 高，
    //   8..21 的中心 14.5 才和右边数字那格 5..24 的中心 14.5 对得上）。
    U.dex_batt_ic = lv_image_create(U.ov_dex);
    lv_obj_remove_flag(U.dex_batt_ic, LV_OBJ_FLAG_SCROLLABLE);
    //   ★★★ 2026-09-19（第十七轮）**与主页 HUD 一并对调**：数字在左、图标在右。
    //     ~~旧：图标 152..178 在左，数字框 178..226（右对齐）在右~~
    //   口径（整组占位不变，右沿仍 226）：
    //     · 图标 200..226（`200 + 26 = 226` ✓）
    //     · 数字框右沿 = 200 - 2 = 198，宽 48 ⇒ 框 (150, 6, 48, 20)
    //   ⚠ 主页那一格（build_hud）与本格**必须同改**，否则翻一页就发现顺序反了。
    place(U.dex_batt_ic, 200, 8, BATT_IC_W, BATT_IC_H);
    lv_image_set_src(U.dex_batt_ic, &fa_res_batt_full);

    U.dex_batt = mk_label(U.ov_dex, &fa_font_ui, C_HUD_WT, "");
    // ★★ 第十五轮：框顶 5 -> 6，与主页 HUD 同一口径（见 build_hud 里 lb_clover 那段）。
    //   ⚠ 上面那条注释推的是「框 5..24 的中心 14.5 对上图标 8..21 的中心 14.5」
    //     —— 那个推法**不成立**：label 的墨迹不从框心算，是从**框顶**算。
    //     实测框顶 5 ⇒ 墨迹 8..19（中心 13.5），高 1px；框顶 6 ⇒ 9..20（14.5）✔。
    //   ⚠ 收集册顶栏这一格和主页顶栏是**同一处缺陷**，所以一起改掉，别只改一边
    //     —— 否则下一页又会收到同一句「还是没对齐」。
    //   ⚠ 左沿 178 / 右沿 226 **这一轮不动**：用户点名的是「和猫罐头与侧边的距离」，
    //     而猫罐头只在主页面；册子这页左边是 dex_title（x=12），右沿硬凑 223 反而
    //     两头都不对称。
    //   ★★★ 2026-09-19（第十七轮）框 **(178,6,48,20) -> (150,6,48,20)**：
    //     与上面 dex_batt_ic 对调。右沿 150 + 48 = **198**，图标左沿 200，留 2px。
    //   ⚠ 旧注释说的「左沿 178 / 右沿 226 这一轮不动」已被这一轮推翻 ——
    //     用户这次点名的是「电量标识和电量数字交换位置」，两格都要动。
    place(U.dex_batt, 150, 6, 48, 20);
    lv_obj_set_style_text_align(U.dex_batt, LV_TEXT_ALIGN_RIGHT, 0);
    lv_label_set_long_mode(U.dex_batt, LV_LABEL_LONG_CLIP);
    // ★★ 第十三轮：hud_chip 取消；同时把这一格从 (180,3) 挪到 (180,5) ——
    //   上面的角标（build_corners）在 y=3 处只留到 x≈226，「56%」的右沿 226
    //   正好压在弧线上。挪 2px + 收窄到 44 之后整格都落在弧线内侧。
    //   收集册顶栏那一行同理从 y=5 起。

    // ---- 白卡片：和「到达卡」同一套版式 ----
    U.dex_card = mk_box(U.ov_dex, 12, DEX_CARD_Y, 216, DEX_CARD_H, C_CARD, 12, LV_OPA_COVER);

    // 图位 176x208：明信片按 scale 243 缩到 167x208；家的底图缩到 156x208。
    // ★ 第十三轮从 176x220 缩到 176x208 —— 让出 12px 给放大的四行字
    //   （为什么是「缩」而不是「裁」：见 dex_show_card 上面那段）。
    // ★ 这一层是收集册**唯一**的图 —— 第四次那五块程序化兜底小风景、
    //   纪念品那 12 格合集都已删除（见下面「收集册」那一节开头的说明）。
    U.dex_art = mk_box(U.dex_card, 20, 4, 176, 208, C_TRANS, 8, LV_OPA_TRANSP);
    // ★ 第十三轮：clip_corner 删除（176x8x4 = 5,632 B 的中间图层）。
    // ★★★ 第十四轮：`OVERFLOW_VISIBLE` 反过来**要打开**了。
    //   ~~下面那个四角角标（U.dex_art_cv）是**比图位大一圈**的对象（向上、向下
    //   各外扩 4px），关着 OVERFLOW 的话它外扩出去的那两圈会被父框直接裁掉，
    //   于是角标只剩「图位之内」的部分 —— 而图位之内恰恰是**不需要遮**的中心区，
    //   四个直角一点都盖不到，圆角等于白做（这一脚踩过一次，记着）。~~
    //   ★★★ 第十七轮订正（留痕，铁律 17）：**上面这段推理是错的。**
    //     重读 `lv_refr.c:143-153` + `lv_obj_draw.c:353-396`：
    //     `EXT_DRAW_SIZE` 只由 shadow / outline / drop_shadow / transform 决定，
    //     `mk_box` 造的容器这四样全 0 ⇒ `ext_draw_size == 0`
    //     ⇒ `obj_coords_ext == obj->coords` ⇒ **这个 flag 在 dex_art 上是空操作**。
    //     「开不开，子对象都裁到图位框」才是事实。
    //     那圆角为什么还是生效的？因为**要盖的那四块「曲边三角」本来就在图位之内**
    //     （四个角的弧落在 x∈[4,12] / y∈[4,12] 这类角框里，全在 176x208 内）。
    //     所以老结论「开不开都盖得住」对，理由写反了而已。
    //   ⚠ 那还留着这个 flag 干什么：**留个记号**，让下一个人顺着它读到上面这段推导，
    //     而不是再推一遍「外扩被画出来了」。删不删都不影响画面，别为它纠结。
    //   ⚠ 外扩出去的部分**被硬裁掉**，根本落不到 dex_card 上 —— 所以
    //     「角标不能超出图位」这条约束**不存在**（旧注释里「只能取 4」的根子就是它）。
    //   ⚠ 顺带确认过：图位里另外两个子对象都不超出图位
    //     （dex_img 最大 167x208 居中、dex_mask 正好 176x208），开这个标志不影响它们。
    lv_obj_add_flag(U.dex_art, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    U.dex_img = lv_image_create(U.dex_art);
    lv_obj_remove_flag(U.dex_img, LV_OBJ_FLAG_SCROLLABLE);
    // ★★ 下面这两句和 lv_image_set_scale 的关系，查过 LVGL 源码，记在这儿免得再怀疑：
    //   lv_obj_align / lv_obj_center 写的是**对象自己的 style_align**（内部就三行：
    //   写 style_align + 两个 translate），它**不会**碰 lv_image_t 内部那个 align；
    //   而 lv_image 只在 LV_EVENT_STYLE_CHANGED 里处理 SYMBOL 源（符号字重排），
    //   其余一律只 refresh_ext_draw_size。所以两者互不干扰，set_scale 照常生效。
    //   反过来它**把 x/y 接管了** —— 这个对象的位置从此由尺寸推出来：
    //     167 宽居中 -> x = 4   （明信片；第四十轮起**底图也是 167**，同一行）
    //     156 宽居中 -> x = 10  （~~家的那张底图~~ 第四十轮之前的旧尺寸，已废）
    //   ★★ 第十三轮：**从 lv_obj_center 改成 LV_ALIGN_TOP_MID**。
    //     不是风格问题：图位现在 208 高、缩完的图正好也是 208，但万一以后有人
    //     把图位改矮，居中会让上下**一起**被切（顶部丢天空、底部丢前景），
    //     顶对齐至少只切底部。语义更明确，就换了。
    //   ★ 这一句管的是「**对象**在父框里怎么落位」（167 居中于 176 -> x = 4），
    //     和下面那句管的「**图**在对象框里怎么落位」是两层，互不相干。
    lv_obj_align(U.dex_img, LV_ALIGN_TOP_MID, 0, 0);

    // ★★★ 2026-09-20（第四十轮）：**显式钉住「图在对象框里居中」**。
    //   默认值是 `LV_IMAGE_ALIGN_DEFAULT`，而 `lv_area_align()` 把它落进
    //   `default: x = 0; y = 0;`（`lv_area.c:424`）—— **等价于 TOP_LEFT**。
    //   底图从这一轮起**比对象框大**（178x238 塞进 167x208）：
    //   不居中就会贴住左上角、只裁右下，房子下半截和前景草地整片丢失。
    //   ⚠ 为什么以前一直没露出来：旧的两版底图（156x208）和明信片（167x208）
    //     都是「图 == 对象框」，对齐怎么设都一样 —— **图第一次比框大**才会现形。
    //   ⚠ 完整推导（裁剪边界为什么是对象框、ext_draw_size 为什么是 0）
    //     在 dex_show_bg 上面那段；这里只落这一句。
    //   ★ 两个函数共用这一个对象，所以设一次就够，不必两边都写。
    //     对明信片是空操作（图 == 框），设了无害。
    lv_image_set_inner_align(U.dex_img, LV_IMAGE_ALIGN_CENTER);

    // ★★★ 2026-09-19（第十三轮）**「小游戏」封面图下线，改成黑色遮罩 + 文字。**
    //   用户原话：「小游戏的介绍现在用图片完全看不清楚文字，可以跟去旅行一样，
    //   变成黑色遮罩上面显着文字，不用图片。」
    //   第十二轮那版是一张 176x120 的位图（fa_res_mini_cover），两个硬伤：
    //     ① 它是**位图**，文字只能「画」进像素里 —— 11px 的中文在 240x320 的屏上
    //        再经一次色板量化，糊成一团，用户说「完全看不清楚文字」就是这个；
    //     ② 位图只能用「不透明色块」压字（.i8 的透明度只有 0/255 两档），
    //        做不出半透明遮罩，所以它必须整块不透明 —— 于是**盖不满图位**
    //        就露出风景，用户说的「背景图下面没遮盖住」。
    //   ⇒ 现在：一层真正的半透明黑遮罩（铺满整张图）+ 真字体文字。
    //     颜色/圆角/透明度都跟「去旅行」那块面板是同一套观感（C_PANEL 系）。
    //   ⚠ 透明度用 **LV_OPA_90**，不是 85：其一，LVGL 的 opa 常量只有 10 的整数档，
    //     `LV_OPA_85` **根本不存在**（编译期就报 undeclared，第十三轮踩过）；
    //     其二，用户的原话是「跟去旅行一样」，而去旅行那块面板就是 C_PANEL +
    //     LV_OPA_90。要对齐就对齐到 90。
    //   ⚠ 遮罩和它的字**必须一起**显隐（字是遮罩的子对象，跟着父对象走）。
    //   ★★ 尺寸和圆角是一对，必须一起算 —— 这里踩过一次，记下来：
    //     这一格底下铺的是 `dex_show_bg`（240x320 底图缩到 **156x208**，居中 x=10），
    //     而遮罩**只在**这一格出现。要让"遮罩盖住整张图"和"四角是圆的"同时成立，
    //     遮罩就得是 **176x208、radius <= 10**：
    //       · 遮罩圆角的"切掉区"限定在 x<r 且 y<r 的角框里；
    //       · 图从 x=10 起，只要 r <= 10，图的四个角就落在**直边**上而不是角框里。
    //     ⚠ 反过来写成 156 宽、radius 10（"和图片一样大"）会漏：图的外角
    //       (10,0) 离遮罩圆角圆心 (10,10) 有 14.1px > 10，四个角各露出一小块风景
    //       —— 那正是用户上一轮说的「背景图下面没遮盖住」，别再犯。
    //     字块宽 176 够用：最长一行「接住 10+ 个 得 3 罐」实测 136px。
    U.dex_mask = mk_box(U.dex_art, 0, 0, 176, 208, C_DARK, 8, LV_OPA_90);

    // ---- 标题「接罐头小游戏」：两段不同字号，横排自动居中 ----
    // ★★★ 2026-09-19（第十四轮）用户原话：
    //   「小游戏选第 2 个，把小游戏名字改成『接罐头小游戏』，
    //     把接罐头三个字大一些，小游戏三个字小一些。」
    //   ① 「选第 2 个」= 第十三轮候选图里的 **B 款**（思源黑 Bold + 字距）。
    //      所以标题不再走华文中宋，两段都落在思源黑 Bold 这一族里。
    //   ② 两段字号不同 ⇒ **一个 label 装不下**（LVGL 的一个 label 只能挂
    //      一支字体）。拆成两个 label，塞进一个横排 flex 容器里居中。
    //   ③ 大字那段「接罐头」需要**自己一支字库**（fa_font_game, 24px）：
    //      字面只有这三个字，见 tools/gen_fa_fonts.py 的 GAME_TEXT。
    //      小字那段「小游戏」直接用 fa_font_ui（16px Bold）—— 和底栏「时长
    //      选择」同一支字库，正好落实用户第十三轮那句「字体跟时间选择一致」。
    //
    //   为什么不按实测宽度硬算 x：中文的 advance 会随字库生成时的取整差 1~2px，
    //   硬编码的 x 一旦偏了就是「整行不居中」，而且**改了字号就得重算一遍**。
    //   flex 让 LVGL 自己排，以后改字号只动 font 那一处，位置永远不会歪。
    //
    //   ▼ 已经量过的数（PIL 直接量 Noto Sans SC Bold，与 lv_font_conv 同源）
    //       24px「接罐头」= 72.0px（全角，每字恰好 24）
    //       16px「小游戏」= 48.0px
    //     两段字距各取 6 ⇒ 90 + 66，容器 pad_column 再取 6，
    //     整行 = 90 + 6 + 66 = **162px** ≤ 176，左右各余 7px。
    //     ⚠ 别再往上加字距：B 款原设定是「字距 12」，但那是**单段**排版；
    //       两段拼起来按 12 算是 96 + 72 = 168，再加间隙就顶边了。
    //   ⚠ 两段字色有意不同：大字用 0xFFF6EC（与规则文字同一系的亮米白），
    //     小字压暗到 0xD8CFC0 —— 大小之外再补一层主次，不然两段并排会「打架」。
    //
    //   ▼ 第十六轮改成**单行居中标题**（原来是「接罐头 + 小游戏」两段并排）
    //     · 为什么硬编码 x、不用 flex 自动居中：这份固件的 LVGL 是
    //       **CONFIG_LV_USE_FLEX 关掉**编的（默认就不开），`lv_obj_set_flex_flow`
    //       根本不存在 —— 这一轮试过，编译期直接 undeclared。为一个标题把整个
    //       flex 模块打开、还要连 sdkconfig 与 sdkconfig.defaults 一起改（并触发
    //       全量重建），代价明显大于收益。所以改成**按宽度硬算**。
    //     · 宽度（铁律 15：**每个字后面各加一份字距**，不是 (n-1) 份）
    //         「小游戏」24px 字距 6 ⇒ 视觉宽 3×24 + 3×6 = **90**
    //         ⇒ 左沿 = (176-90)/2 = **43**
    //     · 基线：fa_font_game 24px 实测 line_height 24 / base_line 3
    //         ⇒ 基线 = 框顶 + 21。框顶取 40 ⇒ 基线 61。
    //       ★ 墨迹（**实测**，别按基线推）：「小」box_h 23 ofs_y -3 ⇒ 框顶+1..+23；
    //         「戏」box_h 24 ⇒ 框顶+0..+23。所以这一行落在 **40..63**。
    //       ⚠ 这不是「原来那个 30」—— 规则文字从四条收成两句之后整块变矮，
    //         标题跟着往下放才不至于上密下空（见下面规则那一段）。
    //
    //   ~~旧（第十三~十五轮）：两段并排，「接罐头」24px 左沿 10 + 「小游戏」
    //     16px 左沿 106，整体视觉宽 156 居中 —— 那时这一格是「接猫罐头」的封面。~~
    //   ⚠ 旧注释里「3×24 + 2×6 = 84」这个算法是**错的**（漏了尾随的那一份字距），
    //     正确值是 90。按 90 重算的 43 才是这一版用的数。
    U.dex_mask_t1 = mk_label(U.dex_mask, &fa_font_game, 0xFFF6EC, "小游戏");
    place(U.dex_mask_t1, 43, 40, 90, 24);
    lv_obj_set_style_text_letter_space(U.dex_mask_t1, 6, 0);
    // ★★ 第十六轮：t2 **留空**。它原来是「接罐头 + 小游戏」两段并排里的副段，
    //   现在标题只剩「小游戏」一段，这一格没有内容可放。
    //   ⚠ 是留空、不是 HIDDEN：空字符串已经什么都不画，改标志反而多一次失效重绘
    //     （和 card_gain 那条「留空不 HIDDEN」是同一条纪律）。字段也先留着 ——
    //     删它要连 U 结构体和这里两处一起动，它只是一个小空对象，不值当。
    U.dex_mask_t2 = mk_label(U.dex_mask, &fa_font_ui,   0xD8CFC0, "");
    place(U.dex_mask_t2, 106, 46, 66, 19);
    lv_obj_set_style_text_letter_space(U.dex_mask_t2, 6, 0);

    // 玩法说明。★ 用 fa_font_ui（与底栏「时长选择」同一支字库）——
    //   用户第十三轮原话「字体跟时间选择字体一致吧」。
    // ★★ 2026-09-19（第十六轮）：~~原来写的是「接猫罐头」那四条奖励规则~~
    //   （15 秒一局 / 接住 4-6 个 得 1 罐 / 7-9 得 2 罐 / 10+ 得 3 罐）。
    //   现在这一格是**四个小游戏的入口**，规则一种一套（打兔子 15 秒、
    //   猜拳 5 局、翻牌 20 秒），全写上会挤成一团 ⇒ 改成**两句总说**。
    //   ⚠ 这里（**选择页的封面**）**仍然不写四个游戏的名字**。
    //     ~~第十六轮的理由：用户点名要求「要给人一些神秘感」，名字只写在选择页里，
    //       而且未解锁的那几行连名字都不给，封面先抖出来等于把神秘感拆了。~~
    //     ★★ 第十七轮订正：**「未解锁不给名字」那条已被推翻**（用户改主意，
    //       要求按设计稿把名字都显示出来 —— 见常量块 MENU_CELL_* 那一节），
    //       但**封面这一格照旧不写名字**，理由换成了一个与神秘感无关的：
    //       封面只有 176x104 两行字，而选择页里四格的名字是**横排可读**的；
    //       在封面上再列一遍名字，既挤又和下一页重复，不如留「一共几个、
    //       怎么解锁」这两句总量信息。**这是排版决定，不是保密决定。**
    //   实量：最长一行「收明信片　慢慢解锁」= 8 字 ≈ 128px ≤ 框宽 176；
    //         两行总高 2×19 + 6 = 44 ≤ 104。两样都有余量。
    //   ★ 垂直位置（**实测**墨迹，不是按框高估）：框顶 104，
    //     tiny 汉字墨迹 = 框顶+1..框顶+13 ⇒ 第一行 105..117、
    //     第二行 = 104 + 19 + 6 + 1 = 130..142。
    //     整块内容 40..142 落在 208 高的遮罩里（上留 40、下留 66）——
    //     深色遮罩是给风景压暗的，文字略微偏上比正中更好读。
    U.dex_mask_r = mk_label(U.dex_mask, &fa_font_ui, 0xE8E0D2,
                            "一共四个小游戏\n"
                            "收明信片　慢慢解锁");
    place(U.dex_mask_r, 0, 104, 176, 104);
    lv_obj_set_style_text_align(U.dex_mask_r, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_set_style_text_line_space(U.dex_mask_r, 6, 0);

    // ---- 明信片四角角标：把图位的四个直角遮成圆角 ----
    // ★★★ 2026-09-19（第十四轮）用户原话：
    //   「收藏中的明信片，之前好像是圆角，都改为圆角吧，方角太突兀了。」
    //   第十三轮把 clip_corner 全删之后图位没了裁剪 ⇒ 明信片变回方角。
    //   这里用**和 build_corners 完全同款**的「零图层角标」把它补回来，
    //   一个中间图层都不建（那正是第十三轮卡死的根因）。
    //
    // ================== 几何（改数字前先看懂这一段） ==================
    // 图位 dex_art 是 176x208，而**明信片实际只占 167x208、居中**（x = 4..171）。
    // 圆角要圆的是**图自己的角**，所以角标那圈弧的圆心必须落在图的角上
    // （(4,0)/(171,0)/(4,208)/(171,208)），而不是图位的角上。
    // 这一步是这一轮唯一不直观的地方，走错了会得到「看起来根本没圆」：
    //     · 圆心放在图位角（等价于「直接给图位一个 radius 8」）时，
    //       图的左边界在 x=4，圆角那段弧几乎全落在 x<4 的图外空区里，
    //       图上只剩 x∈[4,8] 一点点斜切 —— 肉眼看不出来。
    //     · 圆心对齐图的角 (4,0) 之后，弧是完整的 1/4 圆，从 (4,8) 走到 (12,0)，
    //       这才是「明信片的圆角」。
    //
    // 参数（IMG_CORNER = 8、IMG_CVR_B = 10）：
    //     对象 x = 4 - 10 = **-6**，y = **-10**（相对图位）
    //     w = 167 + 20 = **187**，h = 208 + 20 = **228**
    //     radius = 8 + 10 = **18**，border_width = **10**
    //     外圆角圆心 = (-6+18, -10+18) = **(12, 8)**   ← 对齐了图的角
    //     内边界矩形 = (-6+10, -10+10) ~ (-6+187-1-10, -10+228-1-10)
    //                = **(4,0) ~ (170,207)**           ← 正好是「明信片那一块」
    //     内圆角半径 = 18 - 10 = **8** = IMG_CORNER ✓
    //     ⇒ 边框环 = 以 (12,8) 为心、半径 **8~18** 的环带，落在图上的那一段就是圆角。
    //   ★★ 注意这两个几何量与 IMG_CVR_B **无关**：
    //     · 圆心 = 对象左上角 + radius = (4-B) + (8+B) = **12**（B 消掉了）；
    //     · 内边界 = 对象左上角 + border_width = (4-B) + B = **4**（B 也消掉了）。
    //     ⇒ 加厚 IMG_CVR_B 只把「外半径 8+B」往外推，**圆心和内轮廓纹丝不动**
    //       —— 所以圆角的**大小**（切深）一个像素都不会变，改的只是「盖得够不够厚」。
    //       （本条是第十七轮才看清楚的，旧注释把「B 越大圆角越大」当成了默认。）
    //
    // 覆盖性判据：要遮的最远点是图的角 (4,0)，到 (12,8) 的距离 = √128 ≈ 11.31，
    // 落在环带 [8,18] 之内 ⇒ **盖得住**，余量 18 - 11.31 = **6.69px**。
    //   ★ 第十七轮之前这个余量只有 0.69px（环带 [8,12]），坐标一舍入就露
    //     —— 那就是用户说的「有时候切的不够准确，留有残余边框」。
    //
    // ⚠ 四条不能动的（前三条和 build_corners 完全一样）：
    //   ① **bg_opa 必须是 TRANSP**。圆角矩形的「背景填充」填的是整个矩形减四角，
    //      不设透明就会画出一大块卡片色把整张明信片糊住（最容易踩的一脚）。
    //   ② **必须先 mk_box 再改 border_width** —— mk_box 内部把 border_width 清成 0。
    //   ③ **必须建在 dex_img 之后**。建序即图层序，早于图就被图盖住了。
    //   ④ ~~**IMG_CVR_B 只能取 4**：图位距卡片上沿正好 4px，取 5 就会有一条卡片色
    //      的白边画到卡片外面的暖黑底上。~~
    //      ★★★ **第十七轮推翻**（留痕，铁律 17）：这条**是错的**。
    //      重读 `lv_refr.c:143-153`：
    //          obj_coords = OVERFLOW_VISIBLE ? obj_coords_ext : obj->coords;
    //          clip_coords_for_children = layer->_clip_area ∩ obj_coords;
    //      `obj_coords_ext` 只比 `obj->coords` 多 **ext_draw_size**，而它由
    //      `lv_obj_calculate_ext_draw_size()`（`lv_obj_draw.c:353-396`）算出来，
    //      **只看 shadow / outline / drop_shadow / transform 四样**。
    //      dex_art 是 `mk_box` 造的空容器：这四样全 0、`border_width` 也被清 0
    //      ⇒ `ext_draw_size == 0` ⇒ `obj_coords_ext == obj->coords`
    //      ⇒ **OVERFLOW_VISIBLE 在 dex_art 上是彻底的空操作。**
    //      ⇒ 角标（dex_art_cv）的可绘区**被硬裁到 dex_art 的框 176x208**。
    //      ⇒ 外扩超过 4px 的那些圈**根本画不出来**，更不可能糊到卡片外面去。
    //      ⇒ **IMG_CVR_B 想取多大取多大**，唯一的实际效果就是把四角那道箍加厚。
    //      ⚠ 别反过来「顺手删掉 OVERFLOW_VISIBLE 这个 flag」：它在这里虽然无效，
    //        但删了也和留着一个样 —— 而留着它能让下一个人读到这段推导。
    //        真正决定角标能不能盖住角的是「**四个角的弧本来就落在图位之内**」
    //        （弧在 y∈[4,12] / y∈[196,207]、x∈[4,12] / x∈[158,166]，全在框内）。
    //
    // ⚠ 上下两条边（y∈[-10,0) 与 y∈[208,217)）**被裁掉了**，这是好事：
    //   它们本来就落在明信片上下方的卡片白底上，画不画都看不见；
    //   而裁掉之后，角标**绝不可能**盖到卡片下部那四行字（dex_name 从 y=215 起）。
    //   ⇒ 「加厚边框会糊到文字上」这个担心不成立。
    //
    // ★★★ 2026-09-20（第四十轮）**这条已经解决，留痕**：
    //   ~~底图那几页（「家」/「小游戏」/「旅行中」走 dex_show_bg，图宽 156）
    //   圆心对不上，圆角会弱一些 —— 那几页本来就不是明信片，可以接受。
    //   要让它们也完美，就得把底图从等比缩改成横向拉伸到 167 宽，会变形，不值当。~~
    //   根因是底图（156）和明信片（167）**不同宽**，角标那圈弧的圆心落不到图的角上。
    //   第四十轮把底图也做成 **167 宽、x = 4**（scale 190，见 dex_show_bg 上面那段），
    //   与明信片同宽同位 ⇒ 圆心正好落在图的角上，**底图那几页的圆角一并正了**。
    //   ⚠ 将来若有人把底图改回 156，圆角会重新变弱（只是不够圆，不会画错）；
    //     要恢复就照 dex_show_bg 那段把 scale 改回 190、size 改回 167x208。
    U.dex_art_cv = mk_box(U.dex_art, 4 - IMG_CVR_B, -IMG_CVR_B,
                          167 + 2 * IMG_CVR_B, 208 + 2 * IMG_CVR_B,
                          C_CARD, IMG_CORNER + IMG_CVR_B, LV_OPA_COVER);
    lv_obj_set_style_bg_opa(U.dex_art_cv, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(U.dex_art_cv, IMG_CVR_B, 0);
    lv_obj_set_style_border_color(U.dex_art_cv, lv_color_hex(C_CARD), 0);
    lv_obj_set_style_border_opa(U.dex_art_cv, LV_OPA_COVER, 0);

    lv_obj_add_flag(U.dex_mask, LV_OBJ_FLAG_HIDDEN);

    // ==================== 「小游戏 / 设置」上下两格（第二十轮） ====================
    // 只在 DEX_ENTRY_PLAY 那一格露脸；其余页由 dex_refresh() 开头统一收。
    // 每一格 = 容器(管裁切) → 图 → [暗底] → 文字 → 猫 → 圆角角标。
    // ★ 建序就是图层序，调整顺序前先想清楚谁压谁。
    {
        // ---- 上格：容器 + 图（当前风景的无猫底图；宽填满、上下居中裁切）----
        //   ★★ 第二十二轮：父对象 **dex_art → dex_card**（几何那段有完整理由）。
        //     换了父之后坐标是**卡片内**的 (30, 10)，不是图位内的 (6, 6)。
        U.dex2_up_cv = mk_box(U.dex_card, DEX2_GX, DEX2_UP_Y, DEX2_W, DEX2_UP_H,
                              C_CARD, 0, LV_OPA_TRANSP);

        // ---- 上格：选中态（一圈橙描边）----
        //   ★ 这一屏有**两个**入口，没有选中态就看不出按 ● 会进哪一个。
        //   ★★★ 2026-09-21（第四十五轮）：~~这三句是写死在**上格**的~~
        //     第二十轮那版写死的理由已经消失（「设置」那一格按下去做什么当时还没定，
        //     见下面那段留痕）。本轮设置页做出来了，改成**两格共用一个光标**：
        //     真正的描边由 build_dex 末尾的 dex2_cursor_apply() 画（那边两格都建好了），
        //     这里不再单独设任何一句 —— 免得出现「一处设死、一处跟着变」的两套真相。
        //     ⚠ 别把 dex2_cursor_apply() 挪到这儿：它要动**下格**那个容器，
        //       而那一刻 U.dex2_dn_cv 还是 NULL（下面才建）。

        //  ⚠ 容器**不能**设 OVERFLOW_VISIBLE：图的 206px 高比格子(168 / 84)高，
        //    靠父框把上下裁掉才是「居中裁切」。开了那个 flag 图就会糊到隔壁格上去。
        U.dex2_up_img = lv_image_create(U.dex2_up_cv);
        lv_obj_remove_flag(U.dex2_up_img, LV_OBJ_FLAG_SCROLLABLE);
        lv_image_set_scale(U.dex2_up_img, DEX2_IMG_SCALE);
        lv_obj_set_size(U.dex2_up_img, DEX2_W, DEX2_IMG_H);
        lv_obj_align(U.dex2_up_img, LV_ALIGN_CENTER, 0, 0);

        // ---- 上格：暗底（整格，见 DEX2_DIM_OPA 那段）----
        //   ★ 从「只盖文字那 84px」改成整格 —— 用户点名两格要统一成一个规格。
        U.dex2_up_dim = mk_box(U.dex2_up_cv, 0, 0, DEX2_W, DEX2_UP_H,
                               C_DARK, 0, DEX2_DIM_OPA);

        // ---- 上格：三行字 ----
        //   「小游戏」用 fa_font_game（24px 思源黑 Bold，字面见 gen_fa_fonts.py）。
        //   字距 2、框宽 155 居中 ⇒ 视觉宽 3*24 + 3*2 = 78 ≤ 155 ✓
        U.dex2_up_t1 = mk_label(U.dex2_up_cv, &fa_font_game, 0xFFF6EC, "小游戏");
        place(U.dex2_up_t1, 0, 8, DEX2_W, 24);
        lv_obj_set_style_text_align(U.dex2_up_t1, LV_TEXT_ALIGN_CENTER, 0);
        lv_obj_set_style_text_letter_space(U.dex2_up_t1, 2, 0);

        //   两行小字走**一个** label（LVGL 的 label 本来就吃 \n）—— 省一个对象。
        //   13px：最长一行「解锁更多小游戏」7 字 ≈ 91px ≤ 155 ✓
        U.dex2_up_t2 = mk_label(U.dex2_up_cv, &fa_font_tiny, 0xE8E0D2,
                                "收集明信片\n解锁更多小游戏");
        place(U.dex2_up_t2, 0, 44, DEX2_W, 40);
        lv_obj_set_style_text_align(U.dex2_up_t2, LV_TEXT_ALIGN_CENTER, 0);
        lv_obj_set_style_text_line_space(U.dex2_up_t2, 3, 0);

        // ---- 上格：猫（左下角，56x56，**看书** cat_read）----
        //   ★★ 第二十二轮：48 → 64；★★ 第二十三轮：64 → **56**（推导见 DEX2_CAT 那段）。
        //      ⚠ 56 之后 `set_scale` / `set_size` 两句**必须补回来**（下面那两行）：
        //        它是「必须成对」的一对，只写一句的后果是猫缩到框正中、脚离容器底
        //        8px、看着浮起来，而且不报任何错。
        //   ★ 静态帧 → **播放器**（s_dex2_up_play，帧长 DEX2_FRAME_MS）。
        //      ~~旧注释：「这一页是『看』的，猫动起来和三行字抢注意力」~~
        //        —— 用户第二十二轮点名要动态，这条口径作废。
        //   ★ 仍然先在创建时塞第 0 帧：dex_show_pair() 里 play_set 只写「要播哪一组」，
        //     把 src 真正换上去要等下一次 tick；不先塞的话，从别的页翻过来的
        //     第一帧会闪一下**上一组留下的图**（静态帧时代没这个问题）。
        //   ★ 对齐：cat_read 帧 0 缩到 56 后可见像素 bbox = (8,1)-(48,55)
        //     ⇒ 框底贴格底时脚底只剩 **1px** 余量（脚像被格底那条边吃掉）。
        //   ★★ 第二十四轮：新增 **DEX2_UP_CAT_LIFT**（y_ofs 由 0 改为 −6，
        //      LVGL 的 y_ofs 正数向下 ⇒ 往上提必须写负号）。
        //      账见 DEX2_UP_CAT_LIFT 那段：上缝 20→**14px**、脚下 1→**7px**；
        //      提到 19 都还不压字（等距点是 9.5，用户 11:11 挑了更保守的 6）。
        //     ⚠ 对齐认的是**对象尺寸**(56)，所以这两句 set 必须写在 align **之前**。
        U.dex2_up_cat = lv_image_create(U.dex2_up_cv);
        lv_obj_remove_flag(U.dex2_up_cat, LV_OBJ_FLAG_SCROLLABLE);
        lv_image_set_scale(U.dex2_up_cat, DEX2_CAT * 256 / 64);   // 56*256/64 = 224
        lv_obj_set_size(U.dex2_up_cat, DEX2_CAT, DEX2_CAT);
        {
            const fa_anim_t *a = fa_anim_find(DEX2_UP_ANIM);
            if (a && a->frames > 0) lv_image_set_src(U.dex2_up_cat, &a->dsc[0]);
        }
        lv_obj_align(U.dex2_up_cat, LV_ALIGN_BOTTOM_LEFT, 4, -DEX2_UP_CAT_LIFT);

        // ---- 上格：圆角角标（零图层，与 U.dex_art_cv 同一套算法）----
        U.dex2_up_cv2 = mk_box(U.dex2_up_cv, -DEX2_CVR_B, -DEX2_CVR_B,
                               DEX2_W + 2 * DEX2_CVR_B, DEX2_UP_H + 2 * DEX2_CVR_B,
                               C_CARD, DEX2_CORNER + DEX2_CVR_B, LV_OPA_COVER);
        //   ⚠ 四条和 dex_art_cv 完全一样，缺一不可：
        //     ① bg_opa 必须 TRANSP（否则一大块卡片色把照片糊死，最容易踩的一脚）
        //     ② 必须先 mk_box 再改 border_width（mk_box 内部把 border_width 清成 0）
        //     ③ 必须建在**图之后**（建序即图层序，早于图就被图盖住）
        //     ④ 对象虽然外扩了 B，但会被父容器 dex2_up_cv 裁掉外扩那一圈 ——
        //        真正落进画面的只剩「四个角的弧」，正是要遮的那四块曲边三角。
        lv_obj_set_style_bg_opa(U.dex2_up_cv2, LV_OPA_TRANSP, 0);
        lv_obj_set_style_border_width(U.dex2_up_cv2, DEX2_CVR_B, 0);
        lv_obj_set_style_border_color(U.dex2_up_cv2, lv_color_hex(C_CARD), 0);
        lv_obj_set_style_border_opa(U.dex2_up_cv2, LV_OPA_COVER, 0);

        // ---- 下格：西湖（固定一张）----
        //   上格铺的是「当前挂着的风景」（所见即所得：按进去看到的背景就是它）；
        //   下格没有这层语义，固定用西湖 —— 与设计稿一致，且和上格冷暖对比。
        U.dex2_dn_cv = mk_box(U.dex_card, DEX2_GX, DEX2_DN_Y, DEX2_W, DEX2_DN_H,
                              C_CARD, 0, LV_OPA_TRANSP);
        U.dex2_dn_img = lv_image_create(U.dex2_dn_cv);
        lv_obj_remove_flag(U.dex2_dn_img, LV_OBJ_FLAG_SCROLLABLE);
        lv_image_set_src(U.dex2_dn_img, &fa_res_nocat_town_lake);
        lv_image_set_scale(U.dex2_dn_img, DEX2_IMG_SCALE);
        lv_obj_set_size(U.dex2_dn_img, DEX2_W, DEX2_IMG_H);
        lv_obj_align(U.dex2_dn_img, LV_ALIGN_CENTER, 0, 0);

        // ---- 下格：暗底（整格，与上格同规格）----
        //   ★ 2026-09-20 新增：原来只有上格有一条暗底，两格看着不是一个规格。
        //   ⚠ 两个高度都用常量（DEX2_UP_H / DEX2_DN_H），**别写死数字** ——
        //     第二十二轮把 127/63 改成 168/84 时，就是因为这里用的是常量，
        //     暗底才自动跟着格子长高；写死数字的话两条暗底会短一截，
        //     表现是「格子下半截变亮」，而且不报任何错。
        U.dex2_dn_dim = mk_box(U.dex2_dn_cv, 0, 0, DEX2_W, DEX2_DN_H,
                               C_DARK, 0, DEX2_DIM_OPA);

        // ---- 下格：「设置」+ 右下角的猫 ----
        //   ⚠ 「设置」走 fa_font_game（24px），而 GAME_TEXT 原来只有
        //     「小游戏新获得？石剪布」—— 这两个字是本轮新加进字表的
        //     （见 gen_fa_fonts.py）。改完**必须重跑 gen_fa_fonts.py**，
        //     否则真机上是两个方框，而且编译期一点提示都没有。
        U.dex2_dn_t1 = mk_label(U.dex2_dn_cv, &fa_font_game, 0xFFF6EC, "设置");
        place(U.dex2_dn_t1, 8, (DEX2_DN_H - 24) / 2, 84, 24);
        lv_obj_set_style_text_align(U.dex2_dn_t1, LV_TEXT_ALIGN_CENTER, 0);
        lv_obj_set_style_text_letter_space(U.dex2_dn_t1, 2, 0);

        //   ★★ 第二十二轮：cat_wave → **cat_write（用桌子）**，并同样接播放器
        //      （s_dex2_dn_play）。两只猫从此**一动一静各不同**：上格捧书看、下格坐桌边。
        //   ★ 第二十三轮：尺寸 64 → **56**，与上格同值 ⇒ 同样要补回
        //      `set_scale` / `set_size` 那一对（理由见上格那一段，一模一样）。
        U.dex2_dn_cat = lv_image_create(U.dex2_dn_cv);
        lv_obj_remove_flag(U.dex2_dn_cat, LV_OBJ_FLAG_SCROLLABLE);
        lv_image_set_scale(U.dex2_dn_cat, DEX2_CAT * 256 / 64);   // 56*256/64 = 224
        lv_obj_set_size(U.dex2_dn_cat, DEX2_CAT, DEX2_CAT);
        {
            const fa_anim_t *a = fa_anim_find(DEX2_DN_ANIM);
            if (a && a->frames > 0) lv_image_set_src(U.dex2_dn_cat, &a->dsc[0]);
        }
        //   「一左一右」：上格猫在左下、下格猫在右下。**不去找朝右的素材** ——
        //   镜像要在 LVGL 层另做（旋转/翻转），为一个 56px 装饰动一次素材流水线不划算；
        //   两只猫朝向一致也不影响「一左一右」这个位置关系。
        lv_obj_align(U.dex2_dn_cat, LV_ALIGN_BOTTOM_RIGHT, -2, 0);

        U.dex2_dn_cv2 = mk_box(U.dex2_dn_cv, -DEX2_CVR_B, -DEX2_CVR_B,
                               DEX2_W + 2 * DEX2_CVR_B, DEX2_DN_H + 2 * DEX2_CVR_B,
                               C_CARD, DEX2_CORNER + DEX2_CVR_B, LV_OPA_COVER);
        lv_obj_set_style_bg_opa(U.dex2_dn_cv2, LV_OPA_TRANSP, 0);
        lv_obj_set_style_border_width(U.dex2_dn_cv2, DEX2_CVR_B, 0);
        lv_obj_set_style_border_color(U.dex2_dn_cv2, lv_color_hex(C_CARD), 0);
        lv_obj_set_style_border_opa(U.dex2_dn_cv2, LV_OPA_COVER, 0);

        // ★★ 2026-09-21（第四十五轮）：**两格都建好之后**才画光标。
        //   它要同时动 up_cv 与 dn_cv 两个容器（选中的 2px、另一个 0），
        //   所以必须等到这两个指针都有效 —— 见上面「别挪到这儿」那条。
        //   ★ 这一次调用只负责「建完就有个正确的初值」（s_dex2_cur 是 0 ⇒ 上格亮）。
        //     之后每次翻页/走位都由 dex_refresh 的 PLAY 分支与 fa_view_dex2_move 重画。
        dex2_cursor_apply();

        // 建完即收：这一组只在 PLAY 那一页露脸。
        lv_obj_add_flag(U.dex2_up_cv, LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(U.dex2_dn_cv, LV_OBJ_FLAG_HIDDEN);
    }

    // ---- 纪念品图鉴的 12 格（2026-09-21 第四十七轮）----
    // ★ 建在**文字那四行之前**：建序即图层序，网格要压在 dex_art（图位）之上。
    //   四行字（dex_name 等）落在网格区里，靠 SOUV 分支**清空**它们规避重叠
    //   （见 dex_refresh 那一段），不是靠图层序 —— 两件事别混。
    // ★ 只建 12 格、两页共用，理由见 build_souv 上面那段。
    build_souv();

    // ---- 地名 / 题词 / 序号 / 提示 ----
    // ★★ 第十三轮：这四行的 y 全部重算过。依据是**实测墨迹**，不是行高：
    //     ui   16px：基线在框顶 +15，墨迹 [框顶, 框顶+18]
    //     tiny 13px：基线在框顶 +12，墨迹 [框顶, 框顶+15]
    //   四行墨迹共 63px。图位缩到 208 之后卡片里能空出 214..289 共 76px，
    //   均分下来每行之间正好留 3px 缝：215 / 236 / 254 / 272，末行落到 286，
    //   离下沿 289 还有 3px。**改任何一个 y 之前先跑 _layout13.py 对一遍。**
    //   ⚠ 上一版（图位 220、四行压在 226..291）末行越出卡片下沿 6px ——
    //     等于把「长按换背景」那半行字直接切掉，这就是这一轮重排的原因。
    U.dex_name = mk_label(U.dex_card, &fa_font_ui, C_TEXT, "");
    place(U.dex_name, 14, 215, 188, 19);
    lv_obj_set_style_text_align(U.dex_name, LV_TEXT_ALIGN_CENTER, 0);

    U.dex_verse = mk_label(U.dex_card, &fa_font_tiny, C_DIM, "");
    place(U.dex_verse, 10, 236, 196, 16);
    lv_obj_set_style_text_align(U.dex_verse, LV_TEXT_ALIGN_CENTER, 0);

    U.dex_idx = mk_label(U.dex_card, &fa_font_tiny, C_ACCENT, "");
    place(U.dex_idx, 10, 254, 196, 16);
    lv_obj_set_style_text_align(U.dex_idx, LV_TEXT_ALIGN_CENTER, 0);

    U.dex_hint = mk_label(U.dex_card, &fa_font_tiny, C_DIM, "");
    place(U.dex_hint, 10, 272, 196, 16);
    lv_obj_set_style_text_align(U.dex_hint, LV_TEXT_ALIGN_CENTER, 0);

    // 兜底的空状态（压在卡片正中，平时隐藏）。
    // ★ 现在它**几乎到不了** —— 「家」永远在序列第一位，序列不可能为空；
    //   留着是为了「位图被擦坏」时界面不会开天窗。
    U.dex_empty = mk_label(U.ov_dex, &fa_font_ui, C_BAR_TXT, "还没有收集到东西");
    place(U.dex_empty, 0, 136, SCR_W, 20);
    lv_obj_set_style_text_align(U.dex_empty, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_add_flag(U.dex_empty, LV_OBJ_FLAG_HIDDEN);

    lv_obj_add_flag(U.ov_dex, LV_OBJ_FLAG_HIDDEN);
}

// ================================================================== 小游戏选择页
//
// ★★★ 2026-09-19（第十七轮）用户原话：
//   「现在小游戏主界面跟之前设定的不一样，要与之前一样，<设计稿截图>
//     按照这里面的来。」+「小游戏主界面要写"长按返回"。」
//   ⇒ 按**设计稿那版 2x2 棋盘**重做，并推翻第十六轮的三条设计：
//     ~~「未解锁不显示游戏名（神秘感）」~~ -> 名字照写，整张卡压暗
//     ~~「竖排 5 行」~~                        -> 2x2 棋盘
//     ~~「第 5 行 = 返回收藏册」~~              -> 删掉，返回改成长按 ●
//   完整留痕与理由见常量块 MENU_CELL_* 那一节，这里不重复。
//
// 布局（240x320）：
//   背景  当前挂着的那处风景（fa_scene），上面压一层 60% 暖黑
//   标题  「小游戏」24px，y 24，居中
//   进度  「明信片 n / 24」13px，y 54，居中
//   四格  2x2，每格 96x96；左上角 = (20+104*(i%2), 80+110*(i/2))
//            i=0 (20,80)  i=1 (124,80)  i=2 (20,190)  i=3 (124,190)
//         卡内：主行 16px（框顶 26，墨迹 29..41）
//               副行 13px（框顶 54，墨迹 55..67）
//         选中态 = **橙色描边 3px**（不填充，照设计稿）
//   提示  「↑↓ 选择　● 开始　长按返回」13px，y 292，居中
//
// 三档配色（只有这三种，别再加）：
//   锁着        —— 卡片 C_PANEL 70%、字 0x8A8078 / 0x6E6658（灰）
//   已解锁      —— 卡片 C_PANEL 80%（MENU_ROW_OPA；见那个宏的说明，
//                  LVGL 没有 85 这一档，写 85 是编译期 undeclared）、
//                  字 0xE8E0D2 / 0xA8A088（亮米）
//   已解锁+选中 —— 卡片不变，加一圈 C_ACCENT 描边，字 0xFFF6EC / 0xFFE4C0

// 四个游戏的名字。
// ★★ 第十七轮：这张表**已解锁和未解锁两处都用**（按设计稿，名字都看得见）。
//   ~~第十六轮：只用在已解锁的行上，未解锁的行写「未解锁 / 再收 N 张明信片」~~
//   ⚠ 留痕：第十六轮那条「神秘感」要求真的提过，原话在常量块 MENU_CELL_* 里；
//     要回去的话，改 menu_refresh 锁着那一支即可，这张表不用动。
static const char *const GAME_NAME[GAME_COUNT] = {
    "接猫罐头", "打兔子", "剪刀石头布", "记忆翻牌",
};
// ★★★ 第十七轮：**GAME_DESC[] 整张删除。**
//   ~~它原来是卡片副行（「15 秒　接住猫罐头」那种玩法说明）。~~
//   设计稿上副行写的是**解锁状态**（「已解锁」/「6 张解锁」），不是玩法，
//   所以改版后这张表没有任何调用点 —— 留着就是一条 unused variable。
//   ⚠ 玩法说明并没有丢：进游戏之后顶栏会写（「打中 3」「第 3/5 局」「配成 1/3」），
//     而卡片上本来就有游戏名。真要恢复，把下面这四句加回来即可：
//       接猫罐头   "15 秒　接住猫罐头"
//       打兔子     "15 秒　打冒头的兔子"
//       剪刀石头布 "5 局　和猫猜拳"
//       记忆翻牌   "20 秒　翻出三对"

// 四个游戏的门槛（**要收够多少张明信片**）。
// ★ 门槛表写成文件级 static const，是为了让「改门槛只改一处」成立 ——
//   常量区那四个 GAME_NEED_* 是它的唯一来源。
// ★★ 第十七轮从 game_need() 的**函数内** static 提到文件级：
//   因为这一轮多了一个读「门槛总数」的地方（卡片副行的「N 张解锁」），
//   两处必须共用同一张表 —— 在函数里各写一份迟早会改漏一处。
static const uint8_t s_game_need[GAME_COUNT] = {
    0, GAME_NEED_RABBIT, GAME_NEED_RPS, GAME_NEED_MEMORY,
};

// 这个游戏**还差几张**明信片才解锁。返回 0 = 已解锁。
static int game_need(int g)
{
    if (g < 0 || g >= GAME_COUNT) return 999;
    const int n = (int)s_game_need[g] - fa_postcards_have();
    return (n > 0) ? n : 0;
}

// 这个游戏的**门槛总数**（与「还差几张」相对）。卡片副行「N 张解锁」用它。
static int game_need_total(int g)
{
    if (g < 0 || g >= GAME_COUNT) return 0;
    return (int)s_game_need[g];
}

// 前置声明：下面 menu_refresh / fa_view_menu_ok 都要用 dex_refresh()，
//   而它的定义在「收集册」那一节 —— 也就是本节的**后面**。
static void dex_refresh(void);

// 选择页的游标。**不进存档**：它只是个光标，重开停在第一格反而更好用
// （第一格「接猫罐头」永远解锁，闭着眼按 ● 也不会按空）。
static int s_menu_cur;

// 提示气泡用的静态缓冲。★ 定义提到这里（原来在收集册那一节），
//   是因为 fa_view_menu_ok 也要用它 —— fa_view_msg() **不拷贝字符串**，
//   整句必须一直活在同一个 static 缓冲里。
static char s_toast_buf[48];

static void build_menu(void)
{
    U.ov_menu = mk_box(U.scr, 0, 0, SCR_W, SCR_H, C_DARK, R_CORNER, LV_OPA_COVER);
    // ★ 和 ov_dex / ov_mini 同一条纪律：不打开 OVERFLOW_VISIBLE，
    //   四角交给 build_corners() 那个角标统一遮（它是全屏 z 序最高的一层）。
    lv_obj_remove_flag(U.ov_menu, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    // 背景 = 玩家当前挂着的那处风景（和游戏里铺的是同一张，所见即所得）
    U.menu_bg = lv_image_create(U.ov_menu);
    lv_obj_remove_flag(U.menu_bg, LV_OBJ_FLAG_SCROLLABLE);
    place(U.menu_bg, 0, 0, SCR_W, SCR_H);
    lv_image_set_src(U.menu_bg, &fa_res_home);
    lv_image_set_scale(U.menu_bg, 256);

    // 压暗层。★ 透明度取 LV_OPA_60：低到 50 时浅色天空那一侧的白字开始发灰；
    //   高到 70 就只剩一块黑板、玩家看不出底下挂着哪张风景。
    U.menu_dim = mk_box(U.ov_menu, 0, 0, SCR_W, SCR_H, C_DARK, 0, LV_OPA_60);

    // 标题：「小游戏」24px + 字距 6 ⇒ 视觉宽 3*24 + 3*6 = 90（铁律 15：每个字后面都加）
    //   ⇒ 左沿 (176 不行，这里容器是整屏) —— 按整屏居中：(240-90)/2 = 75。
    //   ⚠ 上面那个 43 是「相对 176 宽图位」的数，这里用的是整屏，别抄错。
    U.menu_title = mk_label(U.ov_menu, &fa_font_game, 0xFFF6EC, "小游戏");
    place(U.menu_title, 75, 24, 90, 24);
    lv_obj_set_style_text_letter_space(U.menu_title, 6, 0);

    U.menu_prog = mk_label(U.ov_menu, &fa_font_tiny, 0xD0C8B8, "");
    place(U.menu_prog, 0, 54, SCR_W, 16);
    lv_obj_set_style_text_align(U.menu_prog, LV_TEXT_ALIGN_CENTER, 0);

    // ★★ 第十七轮：**竖排 5 行胶囊 -> 2x2 卡片**（96x96）。
    //   几何全在 MENU_CELL_* 那几个宏里，这里只按 i 取左上角。
    //   卡片圆角 14（比原来的 12 略大 —— 96 的方块用 12 会显得方）。
    //   ⚠ 描边（选中态）不能在这里设：mk_box 把 border_width 清成 0，
    //     而选中态是**每次 menu_refresh 都可能变**的，所以统一放在那边设。
    for (int i = 0; i < MENU_CELL_N; i++) {
        U.menu_row[i] = mk_box(U.ov_menu, MENU_CELL_X(i), MENU_CELL_Y(i),
                               MENU_CELL_W, MENU_CELL_H,
                               C_PANEL, 14, MENU_ROW_OPA);
        // 主行（游戏名）：框顶 26，ui 16px ⇒ 墨迹 29..41
        U.menu_row_lb[i] = mk_label(U.menu_row[i], &fa_font_ui, 0xE8E0D2, "");
        place(U.menu_row_lb[i], 0, MENU_CELL_LB_Y, MENU_CELL_W, 20);
        lv_obj_set_style_text_align(U.menu_row_lb[i], LV_TEXT_ALIGN_CENTER, 0);
        // 副行（解锁状态）：框顶 54，tiny 13px ⇒ 墨迹 55..67
        U.menu_row_sb[i] = mk_label(U.menu_row[i], &fa_font_tiny, 0xA8A090, "");
        place(U.menu_row_sb[i], 0, MENU_CELL_SB_Y, MENU_CELL_W, 16);
        lv_obj_set_style_text_align(U.menu_row_sb[i], LV_TEXT_ALIGN_CENTER, 0);
        // ★ 长名字（「剪刀石头布」5 字 = 80px）必须能一行放下：
        //   框宽 = 卡片宽 96 ✓ 够。但要显式 CLIP —— 默认 WRAP 会在放不下时
        //   折成两行，而框只有 20 高，第二行会被切掉（顶栏电量那格踩过同一个坑）。
        lv_label_set_long_mode(U.menu_row_lb[i], LV_LABEL_LONG_CLIP);
        lv_label_set_long_mode(U.menu_row_sb[i], LV_LABEL_LONG_CLIP);

        // ★★ 第十八轮：图标容器（44x44 透明）。子件一律挂在它里面，坐标相对它。
        U.menu_ic[i] = mk_box(U.menu_row[i], MENU_IC_X, MENU_IC_Y,
                              MENU_IC_SIZE, MENU_IC_SIZE, C_TRANS, 0, LV_OPA_TRANSP);
    }

    // ---- 四枚图标（第十八轮新增，几何与出处见常量区 MENU_IC_*）----
    //   ⚠ 全部建在**同一个循环之后**：建序 = 图层序，图标要压在卡片底色上。
    {
        lv_obj_t *p;

        // ① 接猫罐头：把 HUD 那只罐头的 7 块图元**放大一倍**再拼一遍。
        //    原本是 20x20 里的 16x16（相对坐标见 build_hud / build_mini 那两处），
        //    这里 ×2 再居中到 44x44（偏移 (6,6)）⇒ 罐体 32x32。
        //    ⚠ 这是同一只罐头的**第三份副本**（HUD / 小游戏顶栏 / 下落罐头之外），
        //      改坐标时四份要一起改，否则「卡片上那只」和「天上掉那只」长得不一样。
        p = U.menu_ic[GAME_CAN];
        {
            const int ox = 6, oy = 6;
            U.menu_ic_can[0] = mk_box(p, ox + 6,  oy + 10, 28, 26, C_CAN_STEEL, 4, LV_OPA_COVER);
            lv_obj_set_style_border_width(U.menu_ic_can[0], 2, 0);
            lv_obj_set_style_border_color(U.menu_ic_can[0], lv_color_hex(C_CAN_EDGE), 0);
            U.menu_ic_can[1] = mk_box(p, ox + 4,  oy + 4,  32, 14, C_CAN_LID, LV_RADIUS_CIRCLE, LV_OPA_COVER);
            lv_obj_set_style_border_width(U.menu_ic_can[1], 2, 0);
            lv_obj_set_style_border_color(U.menu_ic_can[1], lv_color_hex(C_CAN_EDGE), 0);
            U.menu_ic_can[2] = mk_box(p, ox + 10, oy + 8,  20,  8, 0xD8DDE4, LV_RADIUS_CIRCLE, LV_OPA_COVER);
            U.menu_ic_can[3] = mk_box(p, ox + 6,  oy + 20, 28, 10, C_CAN_LABEL, 0, LV_OPA_COVER);
            lv_obj_set_style_border_width(U.menu_ic_can[3], 2, 0);
            lv_obj_set_style_border_color(U.menu_ic_can[3], lv_color_hex(C_CAN_EDGE), 0);
            U.menu_ic_can[4] = mk_box(p, ox + 16, oy + 24, 10,  6, 0xFFF6EC, LV_RADIUS_CIRCLE, LV_OPA_COVER);
            for (int k = 0; k < 3; k++)
                U.menu_ic_can[5 + k] = mk_box(p, ox + 14 + k * 6, oy + 20, 4, 4,
                                              0xFFF6EC, LV_RADIUS_CIRCLE, LV_OPA_COVER);
        }

        // ② 打兔子：bee_a 帧 0。★ 取单帧必须走 fa_anim_find()->dsc[0]（铁律 20）。
        //    scale 必须显式给：lv_image 不自动适配，不给就是 256（48px 塞进 44 的框，
        //    右边和下边各被裁掉 4px）。234 = 256 * 44/48，与打兔子游戏里那张同值。
        p = U.menu_ic[GAME_RABBIT];
        U.menu_ic_rab = lv_image_create(p);
        lv_obj_remove_flag(U.menu_ic_rab, LV_OBJ_FLAG_SCROLLABLE);
        place(U.menu_ic_rab, 0, 0, MENU_IC_SIZE, MENU_IC_SIZE);
        lv_image_set_scale(U.menu_ic_rab, 234);
        {
            const fa_anim_t *a = fa_anim_find("bee_a");
            if (a && a->frames > 0) lv_image_set_src(U.menu_ic_rab, &a->dsc[0]);
        }

        // ③ 剪刀石头布：三张小牌。14 宽 = tiny 一个字（13px）刚好放得下，
        //    x = 0 / 15 / 30 ⇒ 0..14 / 15..29 / 30..44 正好铺满 44 宽。
        //    中间那张（石头）涂橙 —— 和游戏里「选中的那张」是同一个信号。
        p = U.menu_ic[GAME_RPS];
        for (int k = 0; k < 3; k++) {
            U.menu_ic_rps[k] = mk_box(p, k * 15, 11, 14, 22,
                                      (k == 1) ? C_ACCENT : C_PANEL, 5, LV_OPA_COVER);
            lv_obj_set_style_border_width(U.menu_ic_rps[k], 1, 0);
            lv_obj_set_style_border_color(U.menu_ic_rps[k],
                                          lv_color_hex(k == 1 ? 0xFFE0B0 : 0x6A5C4A), 0);
            U.menu_ic_rps_lb[k] = mk_label(U.menu_ic_rps[k], &fa_font_tiny,
                                           (k == 1) ? 0xFFF6EC : 0xE8E0D2, RPS_NAME[k]);
            place(U.menu_ic_rps_lb[k], 0, 3, 14, 16);
            lv_obj_set_style_text_align(U.menu_ic_rps_lb[k], LV_TEXT_ALIGN_CENTER, 0);
        }

        // ④ 记忆翻牌：三张小牌，一张翻开（蝴蝶）+ 两张扣着（？）——
        //    「翻开一张、还扣着两张」正是这个游戏的画面语言。
        p = U.menu_ic[GAME_MEMORY];
        for (int k = 0; k < 3; k++) {
            U.menu_ic_mem_cv[k] = mk_box(p, k * 15, 11, 14, 22, C_PANEL, 5, LV_OPA_90);
            lv_obj_set_style_border_width(U.menu_ic_mem_cv[k], 1, 0);
            lv_obj_set_style_border_color(U.menu_ic_mem_cv[k], lv_color_hex(0x6A5C4A), 0);
        }
        // 翻开的那张：蝴蝶（butterfly_a 帧 0，双翅完全张开那帧）。14x14 ⇒ scale 74。
        U.menu_ic_mem[0] = lv_image_create(U.menu_ic_mem_cv[0]);
        lv_obj_remove_flag(U.menu_ic_mem[0], LV_OBJ_FLAG_SCROLLABLE);
        place(U.menu_ic_mem[0], 0, 4, 14, 14);
        lv_image_set_scale(U.menu_ic_mem[0], 74);
        {
            const fa_anim_t *a = fa_anim_find("butterfly_a");
            if (a && a->frames > 0) lv_image_set_src(U.menu_ic_mem[0], &a->dsc[0]);
        }
        // 扣着的两张：一个「？」（走 tiny 字库，13px 在 14 宽的框里放得下）
        for (int k = 1; k < 3; k++) {
            U.menu_ic_mem[k] = mk_label(U.menu_ic_mem_cv[k], &fa_font_tiny, 0xD8D0C0, "？");
            place(U.menu_ic_mem[k], 0, 3, 14, 16);
            lv_obj_set_style_text_align(U.menu_ic_mem[k], LV_TEXT_ALIGN_CENTER, 0);
        }
    }

    // ★★ 第十七轮：提示行加「长按返回」，并把 y 从 290 挪到 292。
    //   卡片第 2 行下沿 285，留 7px 缝。
    //   ⚠ 「长按返回」是**这一页独有的**：收藏册的返回仍是 ● 短按
    //     （见 main.c 里 on_release 那段），两者不要混。
    U.menu_hint = mk_label(U.ov_menu, &fa_font_tiny, 0xC0B8A8,
                           "↑↓ 选择　● 开始　长按返回");
    place(U.menu_hint, 0, 292, SCR_W, 16);
    lv_obj_set_style_text_align(U.menu_hint, LV_TEXT_ALIGN_CENTER, 0);

    lv_obj_add_flag(U.ov_menu, LV_OBJ_FLAG_HIDDEN);
}

// 把一枚图标整体压暗 / 还原（★★ 第十八轮新增）。
//
// ★ 递归走 menu_ic[g] 的整棵子树，**逐件设 opa**；不给容器挂 style_opa。
//   理由（第十三轮那次爆堆的教训）：`lv_obj_set_style_opa()` 会让 LVGL 为这个
//   对象**再开一层 draw layer**（44x44 就要 7.7 KB，而且是被脏区触发的、
//   不是开机付一次）。这里只是「暗一点」，四件 style 足够表达，不必动图层。
// ⚠ 四件 style 一起设是**故意的**：盒子忽略 image_opa、图片忽略 bg_opa，
//   多设几次的开销可以忽略，换来的是「以后往图标里加什么都不会漏压暗」。
static void menu_icon_dim_walk(lv_obj_t *o, lv_opa_t opa)
{
    const uint32_t n = lv_obj_get_child_count(o);
    for (uint32_t i = 0; i < n; i++) {
        lv_obj_t *c = lv_obj_get_child(o, i);
        lv_obj_set_style_bg_opa    (c, opa, 0);
        lv_obj_set_style_border_opa(c, opa, 0);
        lv_obj_set_style_image_opa (c, opa, 0);
        lv_obj_set_style_text_opa  (c, opa, 0);
        menu_icon_dim_walk(c, opa);          // 里层也走一遍（牌 + 牌上的字）
    }
}

static void menu_icon_dim(int g, bool dim)
{
    if (g < 0 || g >= MENU_CELL_N) return;
    menu_icon_dim_walk(U.menu_ic[g], dim ? MENU_IC_DIM : LV_OPA_COVER);
}

// 画选择页。★ 和 dex_refresh 同一个模式：**只有一个「画」的地方**，
//   开页、移游标、玩完一局回来，都只调它一次。
static void menu_refresh(void)
{
    char buf[48];

    snprintf(buf, sizeof(buf), "明信片 %d / %d", fa_postcards_have(), FA_DEST_COUNT);
    lv_label_set_text(U.menu_prog, buf);

    // 背景跟着当前风景走。★ 每次刷新都设一遍是**故意的**：
    //   玩家可以在册子里换背景之后再进来，而这一层是开着的（不是重建）。
    const uint8_t sc = fa_scene();
    lv_image_set_src(U.menu_bg, (sc < FA_DEST_COUNT) ? DEST_ART[sc].nocat : &fa_res_home);

    // ★★ 第十七轮：**2x2 四格**（第 5 格「返回收藏册」已删，返回改成长按 ●）。
    //   三档配色照设计稿：锁着 / 已解锁 / 已解锁+选中（橙色**描边**）。
    //   ⚠ 名字**两档都写** —— 这是本轮推翻第十六轮「神秘感」那一版的地方，
    //     原委见常量块 MENU_CELL_* 与 GAME_NAME 那两段注释。
    for (int i = 0; i < MENU_CELL_N; i++) {
        const bool sel  = (i == s_menu_cur);
        const int  need = game_need(i);            // 还差几张；0 = 已解锁

        // 主行：★★ 第十八轮 —— **未解锁的写「未解锁」，不写游戏名**。
        //   用户原话：「未解锁的不显示名称，比如『剪刀石头布』改为『未解锁』，
        //   但是保留图标。」⇒ 名字那一栏换成「未解锁」，图标照留（只压暗一半）。
        //   ⚠ 留痕：第十七轮曾经明确要求「未解锁也照写游戏名」（照当时那张设计稿），
        //     本轮以这次的点名为准改回来。要回去只改这一行。
        lv_label_set_text(U.menu_row_lb[i], need > 0 ? "未解锁" : GAME_NAME[i]);
        menu_icon_dim(i, need > 0);

        // 副行：解锁状态。★ 口径照设计稿 —— 写**门槛总数**（「6 张解锁」），
        //   不是「还差几张」。已解锁的写「已解锁」。
        if (need > 0) snprintf(buf, sizeof(buf), "%d 张解锁", game_need_total(i));
        else          snprintf(buf, sizeof(buf), "已解锁");
        lv_label_set_text(U.menu_row_sb[i], buf);

        // 底：锁着更暗（70%），已解锁 80%；**选中不改底色**
        lv_obj_set_style_bg_color(U.menu_row[i], lv_color_hex(C_PANEL), 0);
        lv_obj_set_style_bg_opa  (U.menu_row[i],
                                  need > 0 ? LV_OPA_70 : MENU_ROW_OPA, 0);

        // 描边 = 选中。★ 锁着的格子**不给描边**（没解锁就没什么可选的），
        //   否则玩家会以为「圈住的那格是可以按的」。光标仍然会停在它上面 ——
        //   那时副行会弹一句「还差 N 张」把他劝回来（见 fa_view_menu_ok）。
        lv_obj_set_style_border_width(U.menu_row[i], sel ? MENU_CELL_SEL_BW : 0, 0);
        lv_obj_set_style_border_color(U.menu_row[i], lv_color_hex(C_ACCENT), 0);
        lv_obj_set_style_border_opa  (U.menu_row[i], LV_OPA_COVER, 0);

        // 字色三档
        if (need > 0) {
            lv_obj_set_style_text_color(U.menu_row_lb[i],
                                        lv_color_hex(sel ? 0x9A8F84 : 0x8A8078), 0);
            lv_obj_set_style_text_color(U.menu_row_sb[i],
                                        lv_color_hex(sel ? 0x7E7568 : 0x6E6658), 0);
        } else if (sel) {
            lv_obj_set_style_text_color(U.menu_row_lb[i], lv_color_hex(0xFFF6EC), 0);
            lv_obj_set_style_text_color(U.menu_row_sb[i], lv_color_hex(0xFFE4C0), 0);
        } else {
            lv_obj_set_style_text_color(U.menu_row_lb[i], lv_color_hex(0xE8E0D2), 0);
            lv_obj_set_style_text_color(U.menu_row_sb[i], lv_color_hex(0xA8A088), 0);
        }
    }
}

bool fa_view_menu_open(void) { return !lv_obj_has_flag(U.ov_menu, LV_OBJ_FLAG_HIDDEN); }

void fa_view_menu_show(void)
{
    if (s_card_up || seq_departing()) return;
    // 不重置 s_menu_cur：再次进来还停在上次选的那一行
    menu_refresh();
    lv_obj_remove_flag(U.ov_menu, LV_OBJ_FLAG_HIDDEN);
}

// 收掉选择页。**内部函数** —— 出口有两个：
//   ① 「进游戏」那一支（fa_view_menu_ok，先把菜单收掉，游戏压在上面）；
//   ② **长按 ●**（fa_view_menu_back，第十七轮新增）。
//   ~~③ 「返回收藏册」那一行（fa_view_menu_ok）~~ —— 第十七轮把那一格删了，
//      返回整条挪到长按上（用户要求，原委见常量块 MENU_CELL_* 那一节）。
static void menu_close(void)
{
    lv_obj_add_flag(U.ov_menu, LV_OBJ_FLAG_HIDDEN);
}

// ★★★ 2026-09-19（第十七轮）新增：选择页**长按 ● = 返回收藏册**。
//   用户原话：「小游戏主界面要写"长按返回"。」
//   为什么必须是长按：这一页的 ● **短按**已经被「开始游戏」占掉了，
//   板上又只有三颗键 ⇒ 返回只剩长按这一条路。
//   ⚠ 这与「收藏册的返回是 ● 短按」**不矛盾**（那条没动）：
//     两者是不同层级 —— 长按从选择页退回册子，短按再从册子退回主页。
//   ⚠ 必须判 `fa_view_menu_open()` 再动手：main.c 的 on_long 已经挡了一道
//     （那里不挡住的话长按会漏到 dex_ok_long 去把主页背景换掉），
//     这里再判一次是为了让这个函数**自己就是安全的**，不依赖调用方的顺序。
void fa_view_menu_back(void)
{
    if (!fa_view_menu_open()) return;
    menu_close();
    dex_refresh();      // 册子还开着（我们只是盖住它），收掉游戏页要把它重画回原样
}

// ★★ 第十七轮：**游标移动改成 4 格线性序**（0→1→2→3→0）。
//   为什么不是「上下左右」：板上只有 ↑↓ 两颗方向键，2x2 的天然四向走不通。
//   线性序至少保证「按一下必换一格」—— 绕圈走法（按两下才动）在实机上
//   会被当成按键失灵，第十六轮就是为这个才做的竖排。
//   ⚠ 格的视觉位置由 MENU_CELL_X/Y(i) 决定 (i%2 定列、i/2 定行)，
//     所以线性序在屏幕上读出来是：左上 → 右上 → 左下 → 右下。
void fa_view_menu_move(int delta)
{
    s_menu_cur = (s_menu_cur + delta) % MENU_CELL_N;
    if (s_menu_cur < 0) s_menu_cur += MENU_CELL_N;
    menu_refresh();
}

void fa_view_menu_ok(void)
{
    // ~~第 5 行 = 出册回收藏册~~ —— 第十七轮删掉了这一格：现在四格全是游戏，
    //   出册改走**长按 ●**（fa_view_menu_back）。所以这里不再有「按 i 分流」，
    //   索引用的是 MENU_CELL_N（=4 = GAME_COUNT），可以直接当游戏号。

    // ★ 没解锁就**明说还差几张**，而不是静默无反应 —— 沉默会让人以为按键坏了。
    const int need = game_need(s_menu_cur);
    if (need > 0) {
        snprintf(s_toast_buf, sizeof(s_toast_buf), "再收 %d 张明信片解锁", need);
        fa_view_msg(s_toast_buf);
        return;
    }

    menu_close();                       // 游戏层压在菜单上面，菜单先收掉
    fa_view_mini_show(s_menu_cur);
}

// ------------------------------------------------------------------ 小游戏「接猫罐头」
//
// 玩法与参数的来龙去脉全在文件上方那个常量块里，这里只说实现上的四件事。
//
// 一局的完整生命周期：
//     fa_view_mini_show()   进游戏 —— 铺当前风景的背景、清池子、满 15 秒
//     mini_tick(dt)         每帧推：猫位移 → 生成罐头 → 下落 / 碰撞 / 回收 → 倒计时
//     mini_finish()         结算 —— 算奖励、发猫罐头、亮结算面板、锁住操作
//     fa_view_mini_ok()     收下结算面板 -> 回收藏册
//
// ★ 四条纪律：
//   ① 罐头是**对象池**（MINI_MAX_CANS 组，建一次就不再建）。一局里创建再销毁
//      15~20 个对象，在 C3 上是实打实的堆抖动；池子只改 x/y 和显隐。
//   ② 移动的是**罐子的容器**，不是它的三个图元 —— 一帧 1 次 set_pos 而不是 3 次。
//      这就是把它做成容器的唯一理由。
//   ③ 全整数，不用浮点。速度按 px/s 存，每帧 `vy * dt / 1000`。C3 没有 FPU，
//      而这里跑在 20fps 的渲染主循环里。
//   ④ 游戏期间**不跑**主页那套（猫溜达 / 旅行面板 / HUD / 云）——
//      fa_view_tick 里直接 return，和开场剧情同一个写法。被全屏盖住的界面
//      没必要白烧一遍渲染。
//
// ★ 为什么落空不扣分：这是个「旅行等待时有的玩」的消遣，不是竞技。
//   扣分制会让人为了一分较劲，跟这个定位相冲。15 秒里接不满就是没奖励，
//   这已经是足够的反馈了。
//
// ★ 按键：↑ = 往左，↓ = 往右（板子上没有左右键，理由见上方常量块）。
//   实现靠 press/release 两个事件维护一个 s_mini_dir —— 按住时每帧推着走。
//   ⚠ 关键在于 main.c 那边**必须**在 was_long 判断之前处理小游戏的抬手事件：
//     长按 ↑ 会先触发 EV_LONG，抬手时 was_long 为真；若按常规流程直接 return，
//     「松开方向键」这件事就丢了，猫会朝那个方向一直走到局终。

// 前置声明：下面 fa_view_mini_close() 要重刷册子，而 dex_refresh 的定义
// 在收集册那一节 —— 也就是本节的**后面**。
static void dex_refresh(void);

// 罐子主体 + 顶盖 + 标签带。三个都建在**容器** U.mini_can[i] 里，
// 相对坐标固定，所以每帧只需要移动容器。
static void build_mini(void)
{
    U.ov_mini = mk_box(U.scr, 0, 0, SCR_W, SCR_H, C_DARK, R_CORNER, LV_OPA_COVER);
    // ★★★ 第十三轮：**clip_corner 删除**。它原来是**每秒钟**都要付一次的钱 ——
    //   顶栏那三格字落在上 26 行里，倒计时每秒一变就重新分配一次
    //   240 x 26 x 4 = 24,960 B 的中间图层。四角改由 build_corners 统一遮。
    lv_obj_remove_flag(U.ov_mini, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    // ---- 背景：和主页完全同一张底图、同一个缩放 ----
    // ★ 进游戏时才 set_src（见 fa_view_mini_show）—— 玩家可以在册子里换风景，
    //   每开一局都要按当时挂着的那张重新铺一次。
    U.mini_bg = lv_image_create(U.ov_mini);
    lv_obj_remove_flag(U.mini_bg, LV_OBJ_FLAG_SCROLLABLE);
    place(U.mini_bg, 0, 0, SCR_W, SCR_H);
    lv_image_set_src(U.mini_bg, &fa_res_home);
    lv_image_set_scale(U.mini_bg, 256);

    // ---- 四个游戏各自的容器（第十六轮）----
    // ★ 全是 0,0 全屏的**透明**容器，所以搬进来的对象坐标一个都不用改。
    //   ⚠ 容器要关掉 OVERFLOW_VISIBLE（默认就是关的，这里写明是为了别有人顺手打开）：
    //     打兔子那 6 个「裁切容器」就建在 pane 里，父层一旦允许溢出，
    //     整个「从洞里冒出来」的效果会连着一起失效 —— 而且不报错。
    for (int g = 0; g < GAME_COUNT; g++) {
        U.pane[g] = mk_box(U.ov_mini, 0, 0, SCR_W, SCR_H, C_TRANS, 0, LV_OPA_TRANSP);
        lv_obj_remove_flag(U.pane[g], LV_OBJ_FLAG_OVERFLOW_VISIBLE);
        lv_obj_add_flag(U.pane[g], LV_OBJ_FLAG_HIDDEN);
    }
    lv_obj_remove_flag(U.pane[GAME_CAN], LV_OBJ_FLAG_HIDDEN);   // 默认显示接罐头

    // ---- 顶栏（第十二轮重排）----
    // ★★ 用户原话：「小游戏里面，左侧也要显示出现在有多少猫罐头，把字体也要跟
    //   主界面一致。右侧为剩余时间，字体与猫罐头字体一致。」
    //   ⇒ 左 = 猫罐头图标 + 数量，右 = 剩余时间；两者都用 fa_font_ui(15px)
    //     + 纯白 + hud_chip() 那层淡衬底 —— 和主页 HUD **同一套参数**，
    //     这就是「字体跟主界面一致」的落地方式（不是「看起来差不多」）。
    //   「接住 N」没有消失，只是退成中间一行 11px 小字：左右两格是用户点名的，
    //   而接住数在结算面板里本来就会再报一次。
    // ⚠ 图标本身是**图元拼的**，坐标逐块照抄 build_hud() —— 那 7 个对象
    //   （罐身/顶盖/内盖/标签带/掌垫/三个脚趾点）在两边必须一模一样，
    //   改一边就要改另一边，否则「主界面那只」和「游戏里那只」又会对不上。
    U.mini_ic_body   = mk_box(U.ov_mini, 18, 10, 14, 13, C_CAN_STEEL, 2, LV_OPA_COVER);
    lv_obj_set_style_border_width(U.mini_ic_body, 1, 0);
    lv_obj_set_style_border_color(U.mini_ic_body, lv_color_hex(C_CAN_EDGE), 0);
    U.mini_ic_lid    = mk_box(U.ov_mini, 17, 7, 16, 7, C_CAN_LID, LV_RADIUS_CIRCLE, LV_OPA_COVER);
    lv_obj_set_style_border_width(U.mini_ic_lid, 1, 0);
    lv_obj_set_style_border_color(U.mini_ic_lid, lv_color_hex(C_CAN_EDGE), 0);
    U.mini_ic_lid_in = mk_box(U.ov_mini, 20, 9, 10, 4, 0xD8DDE4, LV_RADIUS_CIRCLE, LV_OPA_COVER);
    U.mini_ic_label  = mk_box(U.ov_mini, 18, 15, 14, 5, C_CAN_LABEL, 0, LV_OPA_COVER);
    lv_obj_set_style_border_width(U.mini_ic_label, 1, 0);
    lv_obj_set_style_border_color(U.mini_ic_label, lv_color_hex(C_CAN_EDGE), 0);
    U.mini_ic_pad    = mk_box(U.ov_mini, 23, 17, 5, 3, 0xFFF6EC, LV_RADIUS_CIRCLE, LV_OPA_COVER);
    for (int i = 0; i < 3; i++)
        U.mini_ic_toe[i] = mk_box(U.ov_mini, 22 + i * 3, 15, 2, 2, 0xFFF6EC,
                                  LV_RADIUS_CIRCLE, LV_OPA_COVER);

    // ★★ 第十三轮：三处 hud_chip 全部取消（用户：「黑色背景太丑了，去掉」）。
    //   同时把原来 11px 的「接住 N」提到与左右两格同一个 15px 字库 ——
    //   用户第十三轮原话「尽可能的把字体再放大一些…字体跟时间选择字体一致吧」。
    //   ⚠ 三格的 y 统一从 5 挪到 6、高 18 -> 20：16px 的 line_height 是 19，
    //     18 的框会切掉下缘。三格**必须一起改**，否则顶栏那行会歪。
    U.mini_cnt = mk_label(U.ov_mini, &fa_font_ui, C_HUD_WT, "0");
    place(U.mini_cnt, 40, 6, 44, 20);

    U.mini_score = mk_label(U.ov_mini, &fa_font_ui, C_HUD_WT, "接住 0");
    place(U.mini_score, 84, 6, 70, 20);
    lv_obj_set_style_text_align(U.mini_score, LV_TEXT_ALIGN_CENTER, 0);

    // ★ 只剩时间，不再带「还剩」两个字 —— 右边这一格现在跟电量一样是「数值位」，
    //   15px 下「还剩 00:15」会顶到 100px 宽，把中间那格挤没。
    //   语义仍然清楚：一局 15 秒的倒计时，写在最右边。
    U.mini_time = mk_label(U.ov_mini, &fa_font_ui, C_HUD_WT, "00:15");
    place(U.mini_time, 156, 6, 62, 20);
    // ★★ 2026-09-19（第十六轮）：RIGHT -> **CENTER**。
    //   用户原话「所有小游戏，打中几个，第几局，配成几个的这种，全部居中」。
    //   这一格现在有两种内容：限时游戏的倒计时，和剪刀石头布的「赢 N 局」——
    //   后者正是「第几局/赢几局」那一类，必须居中；两副内容共用一个对象，
    //   所以对齐方式只能挑一个，挑**居中**既满足用户要求、两种内容也都站得住。
    //   ~~原来靠右是有理由的：那时它是一个纯数值位，靠着右边像电量。~~
    //     但它现在同时承担一句中文短语，右对齐会让「赢 0 局」看着要掉出屏幕。
    lv_obj_set_style_text_align(U.mini_time, LV_TEXT_ALIGN_CENTER, 0);
    // ⚠ 左边那一格 (mini_cnt) 保持默认的左对齐**是故意的**，不是漏改：
    //   它是「图标 + 数字」的一个整体（和主界面左上的猫罐头读法完全一致），
    //   数字居中会在图标和数字之间撕开一道 20px 的空。
    //   用户点名要居中的是**得分类**文字（打中几个 / 第几局 / 配成几个），
    //   钱包余额不在那一类里。

    // ---- 开局提示 ----
    // ★ 垫一块半透面板：提示压在画面正中，那里的底色可能是浅天也可能是深草，
    //   纯色字在某一半上一定读不清。面板给 80% 不透明就两头都能读。
    U.mini_tipbox = mk_box(U.ov_mini, 20, 118, 200, 56, C_PANEL, 10, LV_OPA_80);
    U.mini_tip = mk_label(U.mini_tipbox, &fa_font_tiny, 0xFFF6EC,
                          "↑ 往左　↓ 往右\n接住掉下来的猫罐头");
    // ★ y 给 8 而不是 0：两行 11px 字 + 5px 行距约 37px，容器高 56px，
    //   从 8 起上下各留一点，看着才是居中的。给 0 会明显偏上。
    place(U.mini_tip, 0, 8, 200, 40);
    lv_obj_set_style_text_align(U.mini_tip, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_set_style_text_line_space(U.mini_tip, 5, 0);

    // ---- 猫 ----
    // ★ 和主页那只**共用同一套动画帧**（fa_anim_find("cat_walk"/"cat_idle")），
    //   只是这里另开一个 fa_play_t —— 两边各有各的帧计数，互不干扰。
    //   共用帧的好处是零额外 flash；另开播放器的好处是切进切出不会把主页那边
    //   的动画帧号带歪（那是全局唯一一个 s_cat_play）。
    // ★ 第十六轮：parent 从 ov_mini 换成 pane[GAME_CAN]（见上面 pane 那一段）。
    //   pane 是 0,0 全屏透明容器 ⇒ 坐标、缩放、显隐全都不受影响。
    U.mini_cat = lv_image_create(U.pane[GAME_CAN]);
    lv_obj_remove_flag(U.mini_cat, LV_OBJ_FLAG_SCROLLABLE);
    place(U.mini_cat, MINI_CAT_X0, MINI_CAT_Y, MINI_CAT_W, MINI_CAT_H);
    // ★★ 必须显式设缩放，否则猫会被**裁掉右下角**：
    //   精灵素材是 64x64，而这里的框只有 56x56；lv_image 不会自动适配 ——
    //   它是按 scale 画图、由对象矩形裁掉超出的部分。
    //   224 = 256 * 56/64，正好把 64 缩到 56，一个像素不多不少。
    //   ⚠ 改 MINI_CAT_W/H 的话，这个数要跟着改，否则要么被裁、要么周围留空。
    lv_image_set_scale(U.mini_cat, 224);

    // ---- 罐头池 ----
    // ★★ 2026-09-19（第十二轮）：形状从「3 个图元」改成**与 HUD 那只逐块一致**的
    //   7 个图元。用户原话：「下落的猫罐头，与之前主界面使用的猫罐头要是同一张图」。
    //   下面每组的相对坐标 = build_hud() 里那一组**减去图标原点 (15,5)**：
    //       罐身 (3,5) 14x13 ／ 顶盖 (2,2) 16x7 ／ 内盖 (5,4) 10x4 ／
    //       标签带 (3,10) 14x5 ／ 掌垫 (8,12) 5x3 ／ 脚趾点 (7+3i,10) 2x2
    //   容器本身就是 HUD 图标的尺寸（20x20），所以两处画出来是同一只。
    //   ⚠ 这三套（HUD / 小游戏顶栏 / 下落罐头）是同一只罐头的三个副本，
    //     改任何一套的坐标，另外两套要一起改。
    for (int i = 0; i < MINI_MAX_CANS; i++) {
        // 容器是**透明**的：它只负责「一次 set_pos 带走整只罐头」，
        // 本身一个像素都不画（原来那个银灰大圆角矩形是旧版三件套的底）。
        U.mini_can[i] = mk_box(U.pane[GAME_CAN], 0, 0, MINI_CAN_W, MINI_CAN_H,
                               C_TRANS, 0, LV_OPA_TRANSP);

        U.mini_can_body[i] = mk_box(U.mini_can[i], 3, 5, 14, 13,
                                    C_CAN_STEEL, 2, LV_OPA_COVER);
        lv_obj_set_style_border_width(U.mini_can_body[i], 1, 0);
        lv_obj_set_style_border_color(U.mini_can_body[i], lv_color_hex(C_CAN_EDGE), 0);

        U.mini_can_lid[i] = mk_box(U.mini_can[i], 2, 2, 16, 7,
                                   C_CAN_LID, LV_RADIUS_CIRCLE, LV_OPA_COVER);
        lv_obj_set_style_border_width(U.mini_can_lid[i], 1, 0);
        lv_obj_set_style_border_color(U.mini_can_lid[i], lv_color_hex(C_CAN_EDGE), 0);

        U.mini_can_lid_in[i] = mk_box(U.mini_can[i], 5, 4, 10, 4,
                                      0xD8DDE4, LV_RADIUS_CIRCLE, LV_OPA_COVER);

        U.mini_can_label[i] = mk_box(U.mini_can[i], 3, 10, 14, 5,
                                     C_CAN_LABEL, 0, LV_OPA_COVER);
        lv_obj_set_style_border_width(U.mini_can_label[i], 1, 0);
        lv_obj_set_style_border_color(U.mini_can_label[i], lv_color_hex(C_CAN_EDGE), 0);

        U.mini_can_pad[i] = mk_box(U.mini_can[i], 8, 12, 5, 3,
                                   0xFFF6EC, LV_RADIUS_CIRCLE, LV_OPA_COVER);
        for (int k = 0; k < 3; k++)
            U.mini_can_toe[i][k] = mk_box(U.mini_can[i], 7 + k * 3, 10, 2, 2,
                                          0xFFF6EC, LV_RADIUS_CIRCLE, LV_OPA_COVER);

        lv_obj_add_flag(U.mini_can[i], LV_OBJ_FLAG_HIDDEN);
        // ★ 只藏容器：LVGL 的子对象跟随父对象的 HIDDEN 标志，不用逐个 add。
    }

    // ================= 打兔子（第十六轮）=================
    // ★★ 每洞三件，**建序不能改**（建序 = 图层序）：
    //     box（裁切容器）→ img（兔子）→ hole（洞口椭圆）
    //   最后那件洞口椭圆压在兔子上面，把兔子的下截盖成椭圆弧 —— 见常量块那一段。
    for (int i = 0; i < RAB_N; i++) {
        const int cx = RAB_CX(i), cy = RAB_CY(i);

        // ① 兔子裁切容器。★ 容器默认就裁子对象，这里再确认一次
        //    （**不打开** OVERFLOW_VISIBLE）—— 打开它兔子就整只露出来，
        //    「从洞里冒出来」会退化成一整只兔子从下往上飘过去。
        U.rab_box[i] = mk_box(U.pane[GAME_RABBIT], cx - RAB_BOX_W / 2,
                              cy + RAB_BOX_DY - RAB_BOX_H, RAB_BOX_W, RAB_BOX_H,
                              C_TRANS, 0, LV_OPA_TRANSP);
        lv_obj_remove_flag(U.rab_box[i], LV_OBJ_FLAG_OVERFLOW_VISIBLE);

        // ② 兔子：bee_a 帧 0（长耳正面兔，只画了头和耳朵）。48 -> 44 ⇒ scale 234。
        //    ⚠ scale 必须显式给：lv_image 不自动适配容器尺寸，不给就是 256
        //      （1:1 = 48px）塞进 44 的框，右边和下边各被裁掉 4px。
        U.rab_img[i] = lv_image_create(U.rab_box[i]);
        lv_obj_remove_flag(U.rab_img[i], LV_OBJ_FLAG_SCROLLABLE);
        place(U.rab_img[i], 0, RAB_BOX_H, RAB_BOX_W, RAB_BOX_H);
        lv_image_set_scale(U.rab_img[i], 234);
        {
            const fa_anim_t *a = fa_anim_find("bee_a");
            if (a && a->frames > 0) lv_image_set_src(U.rab_img[i], &a->dsc[0]);
        }

        // ③ 洞口椭圆。★ 用 LV_RADIUS_CIRCLE 把 56x22 做成「胶囊」（两端半圆），
        //    小屏上读起来就是一枚卧着的洞。深棕 + 一圈浅棕描边 = 洞口边沿。
        U.rab_hole[i] = mk_box(U.pane[GAME_RABBIT], cx - RAB_HOLE_RX,
                               cy - RAB_HOLE_RY, RAB_HOLE_RX * 2, RAB_HOLE_RY * 2,
                               0x241C14, LV_RADIUS_CIRCLE, LV_OPA_COVER);
        lv_obj_set_style_border_width(U.rab_hole[i], 2, 0);
        lv_obj_set_style_border_color(U.rab_hole[i], lv_color_hex(0x746046), 0);
    }

    // ================= 剪刀石头布（第十六轮新增，第十八轮照设计稿重做）=================
    // 建序 = 图层序，这一页的顺序是：猫 → 黑框 → 提示行 → 三张牌 → 结果行 → 副行 → 底栏。
    // 全部坐标在常量区（RPS_* 那几个宏，含「怎么从设计稿量出来的」那段）。

    // ① 左边那只猫。★ 和主页 / 小游戏里那只**同一套帧**（fa_anim_find("cat_idle")），
    //    另开一个 fa_play_t —— 两边各有各的帧计数，互不干扰（理由同 mini_cat）。
    //    ⚠ 用户点名的第一件事就是「没看到猫」：上一版这一页确实一个猫的对象都没有。
    U.rps_cat_img = lv_image_create(U.pane[GAME_RPS]);
    lv_obj_remove_flag(U.rps_cat_img, LV_OBJ_FLAG_SCROLLABLE);
    place(U.rps_cat_img, RPS_IMG_X, RPS_IMG_Y, RPS_IMG_W, RPS_IMG_H);
    // 素材就是 64x64 ⇒ scale 256（1:1）。这一句**不能省**：精灵对象会被复用，
    // 不显式写就会沿用上一次的值（本工程里 mini_cat 是 224）—— 猫会被缩小。
    lv_image_set_scale(U.rps_cat_img, 256);

    // ② 「猫出了X」黑框。★ 用户点名的第二件事。
    //    揭晓之前框里是「猫在想…」+「？」，揭晓之后是「猫出了」+ 那个拳的字面。
    //    （口径没变：**不到揭晓一个字都不显示** —— 见下面 rps_begin_round 的注释。）
    U.rps_cat_cv = mk_box(U.pane[GAME_RPS], RPS_CAT_X, RPS_CAT_Y,
                          RPS_CAT_W, RPS_CAT_H, C_PANEL, 12, MENU_ROW_OPA);
    lv_obj_set_style_border_width(U.rps_cat_cv, 2, 0);
    lv_obj_set_style_border_color(U.rps_cat_cv, lv_color_hex(C_ACCENT), 0);

    U.rps_cat_k = mk_label(U.rps_cat_cv, &fa_font_tiny, 0xD8D0C0, "");
    place(U.rps_cat_k, 0, RPS_KV_KW_Y, RPS_CAT_W, 16);
    lv_obj_set_style_text_align(U.rps_cat_k, LV_TEXT_ALIGN_CENTER, 0);

    U.rps_cat_lb = mk_label(U.rps_cat_cv, &fa_font_game, 0xFFF6EC, "？");
    place(U.rps_cat_lb, 0, RPS_KV_BIG_Y, RPS_CAT_W, 24);
    lv_obj_set_style_text_align(U.rps_cat_lb, LV_TEXT_ALIGN_CENTER, 0);

    // ③ 提示行「▼ 你出什么？」。★ 原来这一行在 y=30，和顶栏那三格挤在一起；
    //    设计稿上它在牌的上方（墨迹 155..167）⇒ 挪到 RPS_ASK_Y。
    U.rps_tip = mk_label(U.pane[GAME_RPS], &fa_font_tiny, 0xE8E0D2, RPS_ASK_TEXT);
    place(U.rps_tip, 0, RPS_ASK_Y, SCR_W, 16);
    lv_obj_set_style_text_align(U.rps_tip, LV_TEXT_ALIGN_CENTER, 0);

    // ④ 玩家三张牌：石 / 剪 / 布（0 / 1 / 2，与 rps_judge 的顺序一致）
    //   ★★ 牌面的字**从 RPS_NAME[i] 取**：牌面的字和判据的下标必须是同一个来源，
    //      两处各写一遍迟早对不上（第十六轮踩过：三张牌全长一样）。
    //   ★ 底色与描边不在这里定 —— 它们随「选中 / 已出手」每局都变，
    //     统一由 rps_paint_cards() 一处刷（和 bar_refresh / dex_refresh 同一个模式）。
    for (int i = 0; i < 3; i++) {
        const int x = RPS_CARD_X0 + i * (RPS_CARD_W + RPS_GAP);
        U.rps_card[i] = mk_box(U.pane[GAME_RPS], x, RPS_CARD_Y,
                               RPS_CARD_W, RPS_CARD_H, C_PANEL, 10, MENU_ROW_OPA);
        lv_obj_set_style_border_width(U.rps_card[i], 2, 0);
        lv_obj_set_style_border_color(U.rps_card[i], lv_color_hex(0x6A5C4A), 0);
        U.rps_card_lb[i] = mk_label(U.rps_card[i], &fa_font_game, 0xFFF6EC, RPS_NAME[i]);
        place(U.rps_card_lb[i], 0, (RPS_CARD_H - 24) / 2, RPS_CARD_W, 24);
        lv_obj_set_style_text_align(U.rps_card_lb[i], LV_TEXT_ALIGN_CENTER, 0);
    }

    // ⑤ 结果行（设计稿：橙金色大粗字，墨迹 y 245..261 ⇒ 框顶 242）
    U.rps_res = mk_label(U.pane[GAME_RPS], &fa_font_ui, C_ACCENT, "");
    place(U.rps_res, 0, RPS_RES_Y, SCR_W, 20);
    lv_obj_set_style_text_align(U.rps_res, LV_TEXT_ALIGN_CENTER, 0);

    // ⑥ 副行：这一页的「玩法与奖励」说明。★ 文案是常量 RPS_SUB_TEXT，
    //    数字必须和 mini_finish 的档位对得上（赢 1 / 2-3 / 4-5 局给 1/2/3 个）。
    U.rps_sub = mk_label(U.pane[GAME_RPS], &fa_font_tiny, 0xD0C8B8, RPS_SUB_TEXT);
    place(U.rps_sub, 0, RPS_SUB_Y, SCR_W, 16);
    lv_obj_set_style_text_align(U.rps_sub, LV_TEXT_ALIGN_CENTER, 0);

    // ⑦ 底栏：通栏 + 圆角 0（照第十五轮主页那条底栏的口径）。
    //    两端会探到屏幕圆角外面 —— 由 build_corners() 那个角标遮掉（它建在最后）。
    //    ⚠ 别为了「保险」把 x 往里缩，那就又不是通栏了。
    U.rps_bar = mk_box(U.pane[GAME_RPS], 0, RPS_BAR_Y, SCR_W, RPS_BAR_H,
                       C_PANEL, 0, MENU_ROW_OPA);
    U.rps_hint = mk_label(U.pane[GAME_RPS], &fa_font_tiny, C_BAR_TXT, RPS_HINT_TEXT);
    place(U.rps_hint, 0, RPS_HINT_Y, SCR_W, 16);
    lv_obj_set_style_text_align(U.rps_hint, LV_TEXT_ALIGN_CENTER, 0);

    // ================= 记忆翻牌（第十六轮）=================
    // 牌面三种**轮廓差异最大**的帧（按轮廓挑的，不是按名字 —— 见常量块那一段）：
    //     idx 0 = snail_b  帧 1（圆形螺旋）
    //     idx 1 = butterfly_a 帧 0（双翅完全张开，最宽）
    //     idx 2 = turtle_b 帧 0（扁长甲壳）
    // ⚠ 取单帧必须走 fa_anim_find()->dsc[i]（**铁律 20**）——
    //   这几条在 fa_anims[] 里、**不在** fa_res_* 里，按单图去找永远找不到。
    for (int i = 0; i < MEM_N; i++) {
        const int x = MEM_X0 + (i % MEM_COLS) * (MEM_CARD_W + MEM_GAP_X);
        const int y = MEM_Y0 + (i / MEM_COLS) * (MEM_CARD_H + MEM_GAP_Y);
        U.mem_cv[i] = mk_box(U.pane[GAME_MEMORY], x, y, MEM_CARD_W, MEM_CARD_H,
                             C_PANEL, 10, LV_OPA_90);
        lv_obj_set_style_border_width(U.mem_cv[i], 2, 0);
        lv_obj_set_style_border_color(U.mem_cv[i], lv_color_hex(0x6A5C4A), 0);

        // 牌面图 44x44 居中（48 -> 44 ⇒ scale 235）
        U.mem_img[i] = lv_image_create(U.mem_cv[i]);
        lv_obj_remove_flag(U.mem_img[i], LV_OBJ_FLAG_SCROLLABLE);
        place(U.mem_img[i], (MEM_CARD_W - 44) / 2, (MEM_CARD_H - 44) / 2, 44, 44);
        lv_image_set_scale(U.mem_img[i], 235);
        lv_obj_add_flag(U.mem_img[i], LV_OBJ_FLAG_HIDDEN);
    }

    // 光标框：**只有边框、没有填充**（和四角角标、明信片角标同一套技巧）。
    //   ⚠ 两条不能动：① bg_opa 必须是 TRANSP，否则一大块橙把整张牌糊住；
    //                 ② 必须先 mk_box 再改 border_width（mk_box 内部会把它清成 0）。
    U.mem_cur = mk_box(U.pane[GAME_MEMORY], MEM_X0 - 3, MEM_Y0 - 3,
                       MEM_CARD_W + 6, MEM_CARD_H + 6, C_ACCENT, 12, LV_OPA_COVER);
    lv_obj_set_style_bg_opa(U.mem_cur, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(U.mem_cur, 3, 0);
    lv_obj_set_style_border_color(U.mem_cur, lv_color_hex(C_ACCENT), 0);
    lv_obj_set_style_border_opa(U.mem_cur, LV_OPA_COVER, 0);

    // ---- 结算面板 ----
    U.mini_over = mk_box(U.ov_mini, 20, 104, 200, 112, C_PANEL, 14, LV_OPA_90);

    U.mini_over_t = mk_label(U.mini_over, &fa_font_ui, 0xFFF6EC, "接住 0 个");
    place(U.mini_over_t, 0, 16, 200, 22);
    lv_obj_set_style_text_align(U.mini_over_t, LV_TEXT_ALIGN_CENTER, 0);

    U.mini_over_d = mk_label(U.mini_over, &fa_font_tiny, C_ACCENT, "");
    place(U.mini_over_d, 0, 46, 200, 16);
    lv_obj_set_style_text_align(U.mini_over_d, LV_TEXT_ALIGN_CENTER, 0);

    // ★★ 2026-09-19（第十六轮）：~~「● 回收藏」~~ -> 「● 回到选择页」。
    //   收下这一局之后回的是**选择页**（还能接着挑下一个），不是收藏册 ——
    //   文案写「回收藏」会让人以为按一下直接出到册子里，
    //   结果看到又一个菜单，像是按错了。
    //   ⚠ 出册的唯一口子在选择页第 5 行「返回收藏册」。
    U.mini_over_h = mk_label(U.mini_over, &fa_font_tiny, 0xC8C0B2, "● 回到选择页");
    place(U.mini_over_h, 0, 76, 200, 16);
    lv_obj_set_style_text_align(U.mini_over_h, LV_TEXT_ALIGN_CENTER, 0);

    lv_obj_add_flag(U.mini_over, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_flag(U.ov_mini, LV_OBJ_FLAG_HIDDEN);
}

// ---- 小游戏的运行期状态 ----
// ★ 全部是文件级 static，**不进存档**：这是个消遣，丢了就丢了。
//   唯一可惜的是 s_mini_best —— 它是「本次开机的最好成绩」，
//   重启归零。要落盘得开一个新的 NVS 键（参考 fa_scene 的写法），
//   现在的收益不值这一个键。
static bool    s_mini_on;                              // 是否在游戏里
static int     s_mini_ms;                              // 本局剩余毫秒
static int     s_mini_score;                           // 接住个数
static int     s_mini_spawn_ms;                        // 距离下一次生成还有多久
static int     s_mini_over_ms;                         // 非 0 = 已结算，面板亮着
static int     s_mini_dir;                             // -1 往左 / +1 往右 / 0 停
static int32_t s_mini_cat_x;
static bool    s_mini_can_on[MINI_MAX_CANS];
static int32_t s_mini_can_x [MINI_MAX_CANS];
static int32_t s_mini_can_y [MINI_MAX_CANS];
static int32_t s_mini_can_vy[MINI_MAX_CANS];
static int     s_mini_last_score = -1;
static int     s_mini_last_cnt   = -1;                 // 上次画过的猫罐头余额（第十二轮）
static bool    s_mini_tip_up;                          // 开局提示还亮着吗
static int     s_mini_best;                            // 本次开机的最好成绩
static fa_play_t s_mini_play;                          // 游戏里那只猫的播放器
static fa_play_t s_rps_play;                           // 剪刀石头布那只猫的播放器（第十八轮）
// ★★ 2026-09-20（第二十二轮）收藏册「小游戏 / 设置」两格各一只猫，各一个播放器：
//    上格看书（cat_read）、下格用桌子（cat_write）。
//    ⚠ **不能共用实例**：共用一个的话 play_set 会被两边轮流改，
//      表现是两只猫互相打断、帧号乱跳（而且两组名不同，谁 set 谁就把对方重置成第 0 帧）。
static fa_play_t s_dex2_up_play;                       // 上格「小游戏」那只（看书）
static fa_play_t s_dex2_dn_play;                       // 下格「设置」那只（用桌子）
static int       s_mini_tip_ms;                        // 开局提示自己的倒计时（第十八轮）
static int     s_mini_game;                            // 当前玩的是哪一个（GAME_*）
static int     s_mini_last_right = -1;                 // 上次画过的右格（第十轮那格，第十六轮加）

// ---- 打兔子（第十六轮）----
// ★ 每个洞一个四态机，六份独立跑。用**数组**而不是「一个全局的当前兔」，
//   是因为这样将来想改洞的布局（RAB_COLS/RAB_ROWS）时逻辑一行都不用动。
//   现在的生成器一次只选一个空位（见 rab_spawn），所以同时最多一只 ——
//   这不是结构限制，是**手感取舍**：板子上只有 ↑↓ 两颗键，
//   同一排同时冒两只的话，按一次只能打掉一只，玩家读到的却是「按了没反应」。
static int     s_rab_ms  [RAB_N];   // 该洞当前阶段的剩余毫秒
static int     s_rab_ph  [RAB_N];   // 0 空 / 1 升起中 / 2 停留（可打）/ 3 缩回中
static int32_t s_rab_y   [RAB_N];   // 兔子在裁切容器里的 y（RAB_BOX_H .. 0）
static int     s_rab_hit [RAB_N];   // 命中闪光剩余毫秒（> 0 时洞口画成橙色）
static int     s_rab_next;          // 距下一只冒头还有多久
static int     s_rab_hurt;          // 空挥冷却剩余毫秒（> 0 时按键无效）

// ---- 剪刀石头布（第十六轮）----
// ★ 猫的拳在这组状态里**没有单独的「已揭晓」标志**：定好之后它就写进 s_rps_cat，
//   而「什么时候把它画出来」由 s_rps_phase 决定 —— 见常量块那段的三阶段说明。
//   ⚠ 别顺手在这里加一个「猫出拳了没有」的 bool：那会和 phase 表达同一件事，
//     两个真相来源迟早对不上（表现是「明明该藏着却显示出来了」）。
static int     s_rps_round;          // 当前第几局（1..RPS_ROUNDS，**平局不 ++**）
static int     s_rps_sel;            // 玩家光标：0 石 / 1 剪 / 2 布
static int     s_rps_cat;            // 猫出的拳（同一套取值；-1 = 还没定）
static int     s_rps_phase;          // RPS_PICK / RPS_REVEAL / RPS_SHOW
static int     s_rps_ms;             // 当前阶段的剩余毫秒
static bool    s_rps_draw;           // 刚结束的这一局是平局（决定要不要占局数）

// ---- 记忆翻牌（第十六轮）----
static int     s_mem_cur;            // 光标（0..MEM_N-1）
static uint8_t s_mem_kind[MEM_N];    // 每张牌的「动物」（0/1/2，各两张）
static uint8_t s_mem_open[MEM_N];    // 1 = 这一张正翻开
static uint8_t s_mem_done[MEM_N];    // 1 = 已配对（永久正面）
static int     s_mem_a, s_mem_b;     // 本回合翻开的两张（-1 = 还没翻）
static int     s_mem_wait;           // > 0 = 两张都翻开了，等判定

// 藏一个罐头（回到池子）。★ 只藏容器，子对象跟着走。
static void mini_can_hide(int i)
{
    s_mini_can_on[i] = false;
    lv_obj_add_flag(U.mini_can[i], LV_OBJ_FLAG_HIDDEN);
}

// 顶栏那三格。★ 只有值真的变了才 set_text —— 每帧无条件写 label 会让 LVGL
// 反复重排文本，C3 上直接掉帧（主页那边 s_last_recall_cost 是同一个道理）。
//
// ★★ 第十六轮：这一节从「接罐头专用」升级成**四个游戏共用**。
//   三格的含义随游戏变，唯一不变的是这一条纪律：每个游戏的三格文字都**居中**。
//   （用户第十六轮原话：「所有小游戏，打中几个，第几局，配成几个的这种，全部居中。」）
static void mini_hud_paint(void)
{
    char buf[28];

    // ---- 左格：猫罐头余额（四个游戏共用）----
    // ★★ 这一格显示的是**账上的余额**（g_fa.clover），不是本局得分 ——
    //   用户原话就是「显示出现在有多少猫罐头」。局中赚到的要到结算才入账
    //   （只有 mini_finish 会调 fa_award_clover），所以它在整局里是恒定的，
    //   进局时刷一次、拿到奖励前都不会变。这是对的：**没结算就不算拿到手**。
    if ((int)g_fa.clover != s_mini_last_cnt) {
        s_mini_last_cnt = (int)g_fa.clover;
        snprintf(buf, sizeof(buf), "%u", (unsigned)g_fa.clover);
        lv_label_set_text(U.mini_cnt, buf);
    }

    // ---- 中格：四个游戏各写各的 ----
    // ★ 脏判据把 s_rps_round 也掺进来：剪刀石头布的局数会变，而 score 可能一直不动
    //   （连输五局的中途就是这种情况，只看 score 那一格会停在「第 1/5 局」）。
    const int mid = s_mini_score * 100 + s_rps_round;
    if (mid != s_mini_last_score) {
        s_mini_last_score = mid;
        switch (s_mini_game) {
        case GAME_RABBIT: snprintf(buf, sizeof(buf), "打中 %d", s_mini_score);    break;
        case GAME_RPS:    snprintf(buf, sizeof(buf), "第 %d/%d 局",
                                   s_rps_round, RPS_ROUNDS);                      break;
        case GAME_MEMORY: snprintf(buf, sizeof(buf), "配成 %d 对", s_mini_score);  break;
        default:          snprintf(buf, sizeof(buf), "接住 %d", s_mini_score);    break;
        }
        lv_label_set_text(U.mini_score, buf);
    }

    // ---- 右格：限时游戏是倒计时；剪刀石头布没有限时，那一格写「赢 N 局」----
    // ★ 用一个**编码过的整数**当去重依据（100+N 给「赢 N 局」、3000+秒给倒计时），
    //   而不是给两种含义各开一个变量 —— 多一个变量就多一处要复位的地方。
    //   ⚠ 编码值必须**远离初值 -1**：RPS 赢 0 局时 100+0 = 100 ≠ -1 ✔
    //     （这就是不写 `-1 - score` 那种写法 的原因：score=0 时会撞上初值，
    //       右格第一次画不出来，而且只在「一局没赢」这条路上显形。）
    int right;
    if (s_mini_game == GAME_RPS) {
        right = 100 + s_mini_score;
    } else {
        int sc = (s_mini_ms + 999) / 1000;    // 向上取整：剩 0.4 秒还显示 00:01
        if (sc < 0) sc = 0;
        right = 3000 + sc;
    }
    if (right != s_mini_last_right) {
        s_mini_last_right = right;
        if (s_mini_game == GAME_RPS) {
            snprintf(buf, sizeof(buf), "赢 %d 局", s_mini_score);
        } else {
            const int sc = right - 3000;
            snprintf(buf, sizeof(buf), "%02d:%02d", sc / 60, sc % 60);
        }
        lv_label_set_text(U.mini_time, buf);
    }
}

// 从池子里拿一个空位放新罐头。★ 池子满了就**丢掉这一次** ——
// MINI_MAX_CANS(5) 是按「下落 2.5 秒穿越全屏 + 最短 1050ms 生成一个」
// 算出来的上界，实际同时在场最多 3 个，够用。
static void mini_can_spawn(void)
{
    for (int i = 0; i < MINI_MAX_CANS; i++) {
        if (s_mini_can_on[i]) continue;

        s_mini_can_on[i] = true;
        s_mini_can_x [i] = (int32_t)lv_rand(4, SCR_W - MINI_CAN_W - 4);
        s_mini_can_y [i] = -(int32_t)MINI_CAN_H;
        s_mini_can_vy[i] = MINI_FALL_MIN + (int32_t)lv_rand(0, MINI_FALL_RAND);

        lv_obj_set_pos(U.mini_can[i], s_mini_can_x[i], s_mini_can_y[i]);
        lv_obj_remove_flag(U.mini_can[i], LV_OBJ_FLAG_HIDDEN);
        return;
    }
}

// ================= 打兔子（第十六轮）=================

// 把兔子挪到容器内的某个 y。★ 值没变就不 set_pos —— 每帧无条件写会让 LVGL
// 重算坐标并置脏；在 6 个洞的循环里，这种多余写会实打实吃掉帧率。
static void rab_set_y(int i, int32_t y)
{
    if (s_rab_y[i] == y) return;
    s_rab_y[i] = y;
    lv_obj_set_y(U.rab_img[i], y);
}

// 藏一只兔子（回空位）。★ 必须把**阶段**清成 0，不能只藏图 ——
//   只藏图的话 rab_spawn 会把它当成「这个洞还占着」，
//   六个洞会一个接一个卡死，最后再也不出兔子（而且是静默的）。
static void rab_hide(int i)
{
    s_rab_ph[i] = 0;
    s_rab_ms[i] = 0;
    s_rab_y [i] = RAB_BOX_H;
    lv_obj_add_flag(U.rab_img[i], LV_OBJ_FLAG_HIDDEN);
}

// 找一个空位放一只新兔子。★ 一次只出一只（理由见状态变量那一节）。
static void rab_spawn(void)
{
    int cand[RAB_N], n = 0;
    for (int i = 0; i < RAB_N; i++)
        if (s_rab_ph[i] == 0) cand[n++] = i;
    if (n == 0) return;                       // 六个洞都占着（正常到不了）

    const int i = cand[(int)lv_rand(0, n - 1)];
    s_rab_ph[i] = 1;
    s_rab_ms[i] = RAB_RISE_MS;
    rab_set_y(i, RAB_BOX_H);
    lv_obj_remove_flag(U.rab_img[i], LV_OBJ_FLAG_HIDDEN);
}

// 玩家按了某一排：row 0 = 上排（↑），1 = 下排（↓）。
//   ★ 打的是该排**任一**洞里的兔子，优先「停留中」的、其次「升起中」的。
//     为什么不去挑「最靠前的那只」：三键硬件上玩家能表达的只有「这一排有没有」，
//     让他去瞄具体某一个洞，是 240px 屏上做不到的精细操作。
//   ★ 空挥（该排没兔子）给 RAB_HURT_MS 的「手酸」冷却，
//     防的是全程无脑上下轮流按 —— 那样子游戏就退化成「按得快就赢」。
static void rab_swing(int row)
{
    if (s_rab_hurt > 0) return;               // 手酸中，这一下不算

    int pick = -1;
    for (int i = 0; i < RAB_N; i++) {
        if ((i / RAB_COLS) != row) continue;
        if (s_rab_ph[i] == 0) continue;
        pick = i;
        if (s_rab_ph[i] == 2) break;          // 停留中的优先
    }

    if (pick < 0) { s_rab_hurt = RAB_HURT_MS; return; }

    s_mini_score++;
    rab_hide(pick);
    // 命中闪光：只改样式、不建对象（建对象就会引入一帧的堆分配）
    s_rab_hit[pick] = RAB_FLASH_MS;
    lv_obj_set_style_bg_color(U.rab_hole[pick], lv_color_hex(C_ACCENT), 0);
}

static void rab_tick(uint32_t dt)
{
    if (s_rab_hurt > 0) s_rab_hurt -= (int)dt;

    for (int i = 0; i < RAB_N; i++) {
        // 命中闪光到点，把洞口颜色还回去
        if (s_rab_hit[i] > 0) {
            s_rab_hit[i] -= (int)dt;
            if (s_rab_hit[i] <= 0) {
                s_rab_hit[i] = 0;
                lv_obj_set_style_bg_color(U.rab_hole[i], lv_color_hex(0x241C14), 0);
            }
        }

        if (s_rab_ph[i] == 0) continue;

        s_rab_ms[i] -= (int)dt;
        if (s_rab_ms[i] <= 0) {
            if (s_rab_ph[i] == 1) {                 // 升起完 -> 停留
                s_rab_ph[i] = 2;
                s_rab_ms[i] = RAB_HOLD_MS;
                rab_set_y(i, 0);
            } else if (s_rab_ph[i] == 2) {          // 停留完 -> 缩回
                s_rab_ph[i] = 3;
                s_rab_ms[i] = RAB_FALL_MS;
            } else {                                 // 缩回完 -> 空
                rab_hide(i);
            }
            continue;
        }

        // 阶段中途：按进度算 y。★ 全整数 —— C3 没有 FPU，别在这里引浮点。
        if (s_rab_ph[i] == 1) {
            const int t = RAB_RISE_MS - s_rab_ms[i];
            rab_set_y(i, RAB_BOX_H - (int32_t)RAB_BOX_H * t / RAB_RISE_MS);
        } else if (s_rab_ph[i] == 3) {
            const int t = RAB_FALL_MS - s_rab_ms[i];
            rab_set_y(i, (int32_t)RAB_BOX_H * t / RAB_FALL_MS);
        }
    }

    if (s_mini_ms > 0) {
        s_rab_next -= (int)dt;
        if (s_rab_next <= 0) {
            rab_spawn();
            s_rab_next = RAB_GAP_MIN + (int)lv_rand(0, RAB_GAP_RAND);
        }
    } else {
        // 收尾：把还露在外面的兔子一起收掉再结算，
        //   否则结算面板背后还挂着几只半截的兔子（很脏）。
        for (int i = 0; i < RAB_N; i++) rab_hide(i);
        mini_finish();
    }
}

// ================= 剪刀石头布（第十六轮）=================

// ★ RPS_NAME[3] 的**定义**已挪到常量区（RPS_CAT_Y 之后，约 460 行）——
//   build_mini 建三张牌时要拿它当牌面的字，晚于使用就是 undeclared。
//   这里只留说明，别再加一份（两份同名表迟早走岔）。

// 1 = 玩家赢 / -1 = 猫赢 / 0 = 平。取值同上。
//   闭环：石 > 剪 > 布 > 石。
static int rps_judge(int p, int c)
{
    if (p == c) return 0;
    if ((p == 0 && c == 1) || (p == 1 && c == 2) || (p == 2 && c == 0)) return 1;
    return -1;
}

// 画三张牌。active=false 时整体压暗，表示「这一局已经出手了、改不了了」。
//
// ★★ 第十八轮照设计稿换了配色：**选中的那张整块变橙**（原来是「白卡 + 深字 +
//   一圈橙描边」）。旧配色在浅色天空那半屏上几乎看不出哪张选着 ——
//   设计稿上那一格就是实心橙 + 白字，这是「我选了哪张」最直接的表达。
static void rps_paint_cards(bool active)
{
    for (int i = 0; i < 3; i++) {
        const bool sel = active && (i == s_rps_sel);

        lv_obj_set_style_bg_color(U.rps_card[i],
                                  lv_color_hex(sel ? C_ACCENT : C_PANEL), 0);
        lv_obj_set_style_bg_opa  (U.rps_card[i],
                                  sel ? LV_OPA_COVER
                                      : (active ? MENU_ROW_OPA : LV_OPA_60), 0);
        lv_obj_set_style_border_color(U.rps_card[i],
                                      lv_color_hex(sel ? 0xFFE0B0 : 0x6A5C4A), 0);
        lv_obj_set_style_text_color(U.rps_card_lb[i],
                                    lv_color_hex(sel ? 0xFFF6EC
                                                     : (active ? 0xE8E0D2 : 0x9A9080)), 0);
    }
}

// 开一局：回到「等玩家出拳」。
//   ★ 平局之后也走这里 —— 那时 s_rps_round **没有 ++**（见 rps_tick），
//     所以这一句「第 N/M 局」打的还是同一局，正是想要的。
static void rps_begin_round(void)
{
    s_rps_phase = 0;                    // RPS_PICK
    s_rps_ms    = 0;
    s_rps_sel   = 0;
    s_rps_cat   = -1;
    s_rps_draw  = false;

    // 揭晓之前：黑框里是「猫在想…」+「？」。★ 两句话的字面都取常量区那对宏，
    //   和 rps_reveal 成对 —— 两处各写一遍迟早对不上（表现是「该藏着的却显示出来」）。
    lv_label_set_text(U.rps_cat_k,  RPS_KV_HIDE);
    lv_label_set_text(U.rps_cat_lb, "？");
    lv_label_set_text(U.rps_res, "");
    rps_paint_cards(true);

    // ★ 局数写在**顶栏中间那一格**（mini_hud_paint 的「第 N/5 局」），
    //   这一行只留给「你要做什么」——设计稿上就是「▼ 你出什么？」。
    lv_label_set_text(U.rps_tip, RPS_ASK_TEXT);
}

static void rps_move(int d)
{
    if (s_rps_phase != 0) return;               // 只有 PICK 阶段能改
    s_rps_sel = (s_rps_sel + d) % 3;
    if (s_rps_sel < 0) s_rps_sel += 3;
    rps_paint_cards(true);
}

// ● 短按 = 出拳。
// ★★ 猫的拳在这一刻就定好（写进 s_rps_cat），但**一个字都不显示** ——
//   用户原话：「不要直接先告诉我，猫出了什么，要最后再揭晓。」
//   先定后画、而不是等到揭晓那一刻再摇随机数：那样会让「摇数」和「这一帧要重画」
//   搅在一起，两个东西一起变脏；提前定死，揭晓那一帧就只是一次 set_text。
static void rps_ok(void)
{
    if (s_rps_phase != 0) return;

    char buf[48];
    s_rps_cat   = (int)lv_rand(0, 2);
    s_rps_phase = 1;                            // RPS_REVEAL
    s_rps_ms    = RPS_HIDE_MS;

    rps_paint_cards(false);                     // 已出手：三张牌整体压暗
    snprintf(buf, sizeof(buf), "▼ 你出了「%s」，猫在想…", RPS_NAME[s_rps_sel]);
    lv_label_set_text(U.rps_tip, buf);
    lv_label_set_text(U.rps_res, "");
}

// 揭晓：把猫的拳画出来 + 写判定结果。
// ★ 这是**整个游戏里唯一**把猫的拳显示出来的地方 —— 想加「提前看一眼」
//   之类的功能，改的也是这里，改完这个游戏的核心规则就没了。
static void rps_reveal(void)
{
    char buf[64];
    const int r = rps_judge(s_rps_sel, s_rps_cat);

    // 黑框：小字换成「猫出了」，大字换成那个拳的字面。
    lv_label_set_text(U.rps_cat_k,  RPS_KV_SHOW);
    lv_label_set_text(U.rps_cat_lb, RPS_NAME[s_rps_cat]);
    snprintf(buf, sizeof(buf), "▼ 猫出了「%s」", RPS_NAME[s_rps_cat]);
    lv_label_set_text(U.rps_tip, buf);

    // 结果行的字面照设计稿：橙金色一句「这一局　你赢了！」
    //   ★ 用全角空格而不是两个半角 —— 中间那道缝在 16px 下正好一个字的宽度。
    if (r > 0) {
        s_mini_score++;
        lv_label_set_text(U.rps_res, "这一局　你赢了！");
    } else if (r < 0) {
        lv_label_set_text(U.rps_res, "这一局　猫赢了");
    } else {
        s_rps_draw = true;
        lv_label_set_text(U.rps_res, "平局　再来一次");
    }
}

static void rps_tick(uint32_t dt)
{
    // ★★ 第十八轮：猫的待机动画**必须放在最前面**。
    //   它在整个「等你出拳」的阶段都要动，而下面第一句就是「phase == 0 直接 return」——
    //   放后面等于只在揭晓那一瞬间动一帧（这正是用户说「没看到猫」的一半原因：
    //   另一半是上一版压根没建猫这个对象）。
    play_set (&s_rps_play, "cat_idle");
    play_tick(&s_rps_play, dt, U.rps_cat_img, 220);

    if (s_rps_phase == 0) return;               // 等玩家按 ●，没有倒计时要推

    s_rps_ms -= (int)dt;
    if (s_rps_ms > 0) return;
    s_rps_ms = 0;

    if (s_rps_phase == 1) {                     // 空窗结束 -> 揭晓
        rps_reveal();
        s_rps_phase = 2;                        // RPS_SHOW
        s_rps_ms    = RPS_SHOW_MS;
        return;
    }

    // 这一局的停留结束 -> 进下一局，或者结算
    // ★ 平局**不占局数**（见常量块那一段）：round 不动，重出同一局。
    if (!s_rps_draw) {
        if (s_rps_round >= RPS_ROUNDS) { mini_finish(); return; }
        s_rps_round++;
    }
    rps_begin_round();
}

// ================= 记忆翻牌（第十六轮）=================
//
// 三种牌面：动画 id + 取第几帧。挑的都是**轮廓最清楚**的那一帧，不是随手取 0 ——
// 比如 snail_b 的第 0 帧身体全露在壳外，第 1 帧才是一个完整的螺旋壳。
//   ⚠ id 名与画面对不上是本工程的老坑（这几条画的是「兔子 + 某小动物」），
//     详见 gen_fa_sprites.py 的 OFFLINE 那一段。
static const char *const MEM_ANIM [3] = { "snail_b", "butterfly_a", "turtle_b" };
static const uint8_t     MEM_FRAME[3] = { 1, 0, 0 };

// 画全部六张牌 + 光标。**整个游戏只有这一个「画」的地方** ——
// 翻牌、移动、判定之后都只调它一次（和 dex_refresh / menu_refresh 同一个模式）。
static void mem_paint(void)
{
    for (int i = 0; i < MEM_N; i++) {
        const bool face = s_mem_done[i] || s_mem_open[i];
        // 配对成功的牌底色比普通翻开亮一点，一眼能扫出「这几张已经成了」
        lv_obj_set_style_bg_color(U.mem_cv[i],
                                  lv_color_hex(s_mem_done[i] ? 0x4E4538 : C_PANEL), 0);
        if (face) lv_obj_remove_flag(U.mem_img[i], LV_OBJ_FLAG_HIDDEN);
        else      lv_obj_add_flag   (U.mem_img[i], LV_OBJ_FLAG_HIDDEN);
    }

    // 光标跟着走。★ 位置每次显式算，不用 lv_obj_align —— 六张牌是 2x3 网格，
    //   对齐 API 只能表达「相对父对象居中 / 靠边」，表达不了网格。
    lv_obj_set_pos(U.mem_cur,
                   MEM_X0 + (s_mem_cur % MEM_COLS) * (MEM_CARD_W + MEM_GAP_X) - 3,
                   MEM_Y0 + (s_mem_cur / MEM_COLS) * (MEM_CARD_H + MEM_GAP_Y) - 3);
}

// 发牌：三对洗匀 + 绑定牌面图。
static void mem_deal(void)
{
    // i/2 造出「0,0,1,1,2,2」再洗牌 —— 保证正好三对，不会出现「某只动物只有一张」。
    uint8_t deck[MEM_N];
    for (int i = 0; i < MEM_N; i++) deck[i] = (uint8_t)(i / 2);
    for (int i = MEM_N - 1; i > 0; i--) {          // Fisher-Yates
        const int j = (int)lv_rand(0, i);
        const uint8_t t = deck[i]; deck[i] = deck[j]; deck[j] = t;
    }

    for (int i = 0; i < MEM_N; i++) {
        s_mem_kind[i] = deck[i];
        s_mem_open[i] = 0;
        s_mem_done[i] = 0;

        // ★ 取单帧必须走 fa_anim_find()->dsc[k]（**铁律 20**）——
        //   这几条在 fa_anims[] 里、**不在** fa_res_* 里，按单图去找永远找不到。
        const fa_anim_t *a = fa_anim_find(MEM_ANIM[s_mem_kind[i]]);
        const int fr = (int)MEM_FRAME[s_mem_kind[i]];
        if (a && fr < (int)a->frames) lv_image_set_src(U.mem_img[i], &a->dsc[fr]);
    }

    s_mem_cur  = 0;
    s_mem_a    = -1;
    s_mem_b    = -1;
    s_mem_wait = 0;
    mem_paint();
}

static void mem_move(int d)
{
    if (s_mem_wait > 0) return;                // 等判定，不接受输入
    s_mem_cur = (s_mem_cur + d) % MEM_N;
    if (s_mem_cur < 0) s_mem_cur += MEM_N;
    mem_paint();
}

// ● 短按 = 翻牌。
static void mem_flip(void)
{
    if (s_mem_wait > 0) return;                // 前一对还在判定，这一下不算
    const int i = s_mem_cur;
    if (s_mem_done[i] || s_mem_open[i]) return;   // 已配 / 已翻开：按了不算

    if (s_mem_a < 0) {                            // 第一张
        s_mem_a = i;
        s_mem_open[i] = 1;
        mem_paint();
        return;
    }

    s_mem_b = i;                                  // 第二张：亮着等判定
    s_mem_open[i] = 1;
    s_mem_wait = MEM_FLIP_MS;
    mem_paint();
}

// 判定这一对。
static void mem_judge(void)
{
    const int a = s_mem_a, b = s_mem_b;
    s_mem_a = -1;
    s_mem_b = -1;
    if (a < 0 || b < 0) return;

    if (s_mem_kind[a] == s_mem_kind[b]) {
        s_mem_done[a] = 1;
        s_mem_done[b] = 1;
        s_mini_score++;
    } else {
        s_mem_open[a] = 0;                        // 不一样：两张都盖回去
        s_mem_open[b] = 0;
    }
    mem_paint();

    // 三对全配完就提前结束 —— 剩下的时间已经没有任何事可做，
    // 让人干等 20 秒倒数完是没道理的。
    if (s_mini_score >= MEM_TIER_3) mini_finish();
}

static void mem_tick(uint32_t dt)
{
    if (s_mem_wait > 0) {
        s_mem_wait -= (int)dt;
        if (s_mem_wait <= 0) {
            s_mem_wait = 0;
            mem_judge();
        }
    }
    if (s_mini_ms <= 0) mini_finish();
}

// 结算。★ 这一段是**唯一**发猫罐头的地方 —— 四个游戏的三个出口
// （倒计时归零 / 长按 ● 早退 / 记忆翻牌提前配完）都汇到这里，奖励口径不会出现两套。
// ★★ 第十六轮：档位改成**按游戏查**。四个游戏的门槛本来就不同
//   （剪刀石头布是「赢了几局」、记忆翻牌是「配成几对」，都不是「打中几个」），
//   但发钱仍然只有这一处 —— 出口只有一个，档位表多几行不叫两套口径。
static void mini_finish(void)
{
    // ★ 幂等闸门：三个出口可能在同一帧里撞上（比如倒计时归零那一帧同时配成了第三对），
    //   而「发一次猫罐头」这件事只能做一次。mem_judge 之后 mem_tick 还会往下走，
    //   就是靠这一行挡住的。
    if (s_mini_over_ms) return;

    s_mini_dir = 0;

    int award = 0;
    char buf[48];

    switch (s_mini_game) {
    case GAME_RABBIT:
        if      (s_mini_score >= RAB_TIER_3) award = 3;
        else if (s_mini_score >= RAB_TIER_2) award = 2;
        else if (s_mini_score >= RAB_TIER_1) award = 1;
        snprintf(buf, sizeof(buf), "打中 %d 只", s_mini_score);
        lv_label_set_text(U.mini_over_t, buf);
        break;

    case GAME_RPS:
        // ★ 档位是用户给的：赢 1 局 = 1、2-3 局 = 2、4-5 局 = 3。
        if      (s_mini_score >= 4) award = 3;
        else if (s_mini_score >= 2) award = 2;
        else if (s_mini_score >= 1) award = 1;
        snprintf(buf, sizeof(buf), "5 局赢了 %d 局", s_mini_score);
        lv_label_set_text(U.mini_over_t, buf);
        break;

    case GAME_MEMORY:
        // ★★ 第十八轮：奖励**翻倍**（用户原话「另外这个游戏奖励翻倍」）。
        //   档位还是「配成几对」，只是每个数都乘 2 ⇒ 2 / 4 / 6 个猫罐头。
        //   翻倍的理由是这一局要 30 秒（别的游戏 15 秒）—— 单位时间的收益
        //   不翻倍的话，这个游戏会比别的游戏差一半，没人愿意玩。
        if      (s_mini_score >= MEM_TIER_3) award = 6;
        else if (s_mini_score >= MEM_TIER_2) award = 4;
        else if (s_mini_score >= MEM_TIER_1) award = 2;
        snprintf(buf, sizeof(buf), "配成 %d 对", s_mini_score);
        lv_label_set_text(U.mini_over_t, buf);
        break;

    default:
        if      (s_mini_score >= MINI_TIER_3) award = 3;
        else if (s_mini_score >= MINI_TIER_2) award = 2;
        else if (s_mini_score >= MINI_TIER_1) award = 1;
        snprintf(buf, sizeof(buf), "接住 %d 个", s_mini_score);
        lv_label_set_text(U.mini_over_t, buf);
        break;
    }

    (void)fa_award_clover(award);      // award 为 0 时它自己忽略，不用先判

    // ★ 最好成绩只统计接罐头那一个 —— 另外三个游戏的「分」量纲不同
    //   （赢的局数 / 配成的对数），混进同一个变量里那个数就没有意义了。
    if (s_mini_game == GAME_CAN && s_mini_score > s_mini_best) s_mini_best = s_mini_score;

    // 清池子：结算面板后面不该还挂着几个半空的罐头，也不该挂着半截的兔子。
    for (int i = 0; i < MINI_MAX_CANS; i++) mini_can_hide(i);
    for (int i = 0; i < RAB_N; i++)        rab_hide(i);

    if (award > 0)
        snprintf(buf, sizeof(buf), "拿到 %d 个猫罐头", award);
    else
        snprintf(buf, sizeof(buf), "还差一点点，再试一次");
    lv_label_set_text(U.mini_over_d, buf);

    s_mini_tip_up = false;
    lv_obj_add_flag(U.mini_tipbox, LV_OBJ_FLAG_HIDDEN);
    lv_obj_remove_flag(U.mini_over, LV_OBJ_FLAG_HIDDEN);

    s_mini_over_ms = 1;          // 非 0 = 已结算，操作锁住
}

// 接猫罐头：猫位移 → 生成 → 下落 / 碰撞 / 回收 → 到点结算。
// ★ 第十六轮从 mini_tick 里拆出来的 —— 那里现在只做分派。
static void can_tick(uint32_t dt)
{
    // ---- 猫 ----
    if (s_mini_dir) {
        int32_t step = (int32_t)((uint32_t)MINI_CAT_SPEED * dt / 1000u);
        if (step < 1) step = 1;      // dt 很小时也得动，否则手感会「粘住」
        s_mini_cat_x += s_mini_dir * step;
        if (s_mini_cat_x < MINI_CAT_MIN_X) s_mini_cat_x = MINI_CAT_MIN_X;
        if (s_mini_cat_x > MINI_CAT_MAX_X) s_mini_cat_x = MINI_CAT_MAX_X;
        lv_obj_set_x(U.mini_cat, s_mini_cat_x);
    }
    play_set (&s_mini_play, s_mini_dir ? "cat_walk" : "cat_idle");
    play_tick(&s_mini_play, dt, U.mini_cat, 220);

    // ---- 生成 ----
    if (s_mini_ms > 0) {
        s_mini_spawn_ms -= (int)dt;
        if (s_mini_spawn_ms <= 0) {
            mini_can_spawn();
            s_mini_spawn_ms = MINI_SPAWN_MIN + (int)lv_rand(0, MINI_SPAWN_RAND);
        }
    }

    // ---- 下落 / 碰撞 / 回收 ----
    // ★ 接取框比 56x56 的精灵格**收进来一点**：cat_idle 的实体像素只占中间那一片，
    //   四周是透明的。按整格判会让人觉得「明明没碰到也算接到了」。
    const int32_t cx = s_mini_cat_x + 7;
    const int32_t cw = MINI_CAT_W - 14;
    const int32_t cy = MINI_CAT_Y + 8;
    const int32_t ch = MINI_CAT_H - 8;

    for (int i = 0; i < MINI_MAX_CANS; i++) {
        if (!s_mini_can_on[i]) continue;

        int32_t step = s_mini_can_vy[i] * (int32_t)dt / 1000;
        if (step < 1) step = 1;
        s_mini_can_y[i] += step;

        const bool hit = (s_mini_can_x[i] + MINI_CAN_W > cx) &&
                         (s_mini_can_x[i] < cx + cw) &&
                         (s_mini_can_y[i] + MINI_CAN_H > cy) &&
                         (s_mini_can_y[i] < cy + ch);
        if (hit) {
            s_mini_score++;
            mini_can_hide(i);
            continue;
        }

        if (s_mini_can_y[i] > SCR_H) {      // 掉出屏幕：回收，**不扣分**
            mini_can_hide(i);
            continue;
        }

        lv_obj_set_y(U.mini_can[i], s_mini_can_y[i]);
    }

    if (s_mini_ms <= 0) mini_finish();
}

// 一帧的推进入口：四个游戏共用开头的两段（开局提示 / 倒计时），
// 然后按 s_mini_game 分派到各自的 tick。
static void mini_tick(uint32_t dt)
{
    // 结算面板亮着：这一局已经结束了，什么都不用推。
    if (s_mini_over_ms) return;

    // ---- 开局提示：2.5 秒后自己收掉（四个游戏共用）----
    // ★ 必须收。那块面板在画面正中，不收就会一直挡着掉下来的罐头 / 冒出来的兔子 ——
    //   开局的 2.5 秒是「还没开始」的窗口期，正好够看两眼。
    //   ⚠ 剪刀石头布进局时 tipbox 本来就是收着的（见 fa_view_mini_show），
    //     这一段对它等于空转 —— 无害，别指望它显示。
    //
    // ★★★ 2026-09-20（第十八轮）判据从「本局剩余时间」改成**自己的倒计时**。
    //   旧写法是 `s_mini_ms <= MINI_SECS*1000 - 2500` —— 拿**接罐头那一档的 15 秒**
    //   当尺子去量四个游戏。记忆翻牌这一轮改成 30 秒之后，那条不等式要跑到
    //   「还剩 12.5 秒」才成立，也就是开局提示会**挂 17.5 秒**，把整个牌面挡掉一大半。
    //   这种「借用别人的时长」的写法迟早出问题，所以给提示自己一个 2.5 秒计时器 ——
    //   多一个变量，但换来的是一条对四个游戏都成立的不变式。
    if (s_mini_tip_up) {
        s_mini_tip_ms -= (int)dt;
        if (s_mini_tip_ms <= 0) {
            s_mini_tip_up = false;
            lv_obj_add_flag(U.mini_tipbox, LV_OBJ_FLAG_HIDDEN);
        }
    }

    // ---- 倒计时 ----
    // ★★ 只有**限时**的那三个游戏走这一条。剪刀石头布没有限时
    //   （它的节奏是「5 局打完」，不是「N 秒内打多少」）：
    //   rps_tick 不看 s_mini_ms，减了不会误触发，但会让「s_mini_ms 只在限时游戏里
    //   有意义」这条不变式破掉 —— 省下的是将来「为什么剪刀石头布的剩余时间是 0
    //   却不结算」这种疑问。
    if (s_mini_game != GAME_RPS)
        s_mini_ms = (s_mini_ms > (int)dt) ? (s_mini_ms - (int)dt) : 0;

    switch (s_mini_game) {
    case GAME_RABBIT: rab_tick(dt); break;
    case GAME_RPS:    rps_tick(dt); break;
    case GAME_MEMORY: mem_tick(dt); break;
    default:          can_tick(dt); break;
    }

    // ★ 结算那一帧仍然要刷一次顶栏：倒计时要落到 00:00，
    //   不然它会停在 00:01（最后一帧的值）。脏判据会把之后的重刷都挡掉。
    mini_hud_paint();
}

bool fa_view_mini_open(void) { return s_mini_on; }

// 开一局。★ 第十六轮加了 game 参数 —— 四个游戏共用这一层（ov_mini），
//   用 pane[game] 决定显示哪一套对象。入口只有两个：
//     · 小游戏选择页的 fa_view_menu_ok（正常路径）
//     · 启动自检 / 将来可能的调试入口
void fa_view_mini_show(int game)
{
    if (s_card_up || seq_departing()) return;
    if (game < 0 || game >= GAME_COUNT) return;

    // ★ 背景 = 玩家**当前挂着的那处风景**（没挂就是家的底图）。
    //   用户原话「小游戏就使用用户选择的背景」—— 而玩家的"选择"只有一个入口：
    //   收藏册里长按 ● 换背景（fa_scene_set）。所以这里直接跟着 fa_scene() 走，
    //   不再另存一份「游戏背景」，否则就出现两个"背景"概念，
    //   迟早出现「册子里换了风景，游戏里还是旧的」这种对不上的事。
    //   ★ 四个游戏共用这一张 —— 用户第十六轮重申过「所有小游戏的背景图，
    //     用的是用户设置的背景」。
    const uint8_t sc = fa_scene();
    lv_image_set_src(U.mini_bg,
                     (sc < FA_DEST_COUNT) ? DEST_ART[sc].nocat : &fa_res_home);

    // 只显示当前这个游戏的层。★ 收放各只有这一处，和 dex_mask / dex_art_cv
    // 一样的模式：分散到各分支里各写一遍迟早漏一个，而漏了是静默的。
    for (int i = 0; i < GAME_COUNT; i++) {
        if (i == game) lv_obj_remove_flag(U.pane[i], LV_OBJ_FLAG_HIDDEN);
        else           lv_obj_add_flag   (U.pane[i], LV_OBJ_FLAG_HIDDEN);
    }

    s_mini_game       = game;
    s_mini_on         = true;
    s_mini_ms         = MINI_SECS * 1000;
    s_mini_score      = 0;
    s_mini_dir        = 0;
    s_mini_over_ms    = 0;
    s_mini_cat_x      = MINI_CAT_X0;
    s_mini_last_score = -1;
    s_mini_last_right = -1;
    s_mini_last_cnt   = -1;      // 逼着左上角那一格在进局时重画一次
    // ★ 开局先等 0.7 秒再出第一个：一进来就有东西砸下来 / 冒出来，
    //   会让人来不及看清画面。
    s_mini_spawn_ms   = 700;

    // 开局提示。★ 剪刀石头布**不给提示**：它的流程自带引导
    //   （顶部那行「第 1/5 局　你先出」就是引导），再压一块面板反而挡着猫。
    s_mini_tip_up = (game != GAME_RPS);
    s_mini_tip_ms = MINI_TIP_MS;                 // ★ 第十八轮：自己的倒计时，见 mini_tick
    if (s_mini_tip_up) lv_obj_remove_flag(U.mini_tipbox, LV_OBJ_FLAG_HIDDEN);
    else               lv_obj_add_flag   (U.mini_tipbox, LV_OBJ_FLAG_HIDDEN);

    switch (game) {
    case GAME_RABBIT:
        for (int i = 0; i < RAB_N; i++) {
            s_rab_hit[i] = 0;
            lv_obj_set_style_bg_color(U.rab_hole[i], lv_color_hex(0x241C14), 0);
            rab_hide(i);
        }
        s_rab_next = 700;
        s_rab_hurt = 0;
        lv_label_set_text(U.mini_tip, "↑ 打上排　↓ 打下排\n兔子冒头时按那排的键");
        break;

    case GAME_RPS:
        s_rps_round = 1;
        rps_begin_round();
        break;

    case GAME_MEMORY:
        mem_deal();
        lv_label_set_text(U.mini_tip, "↑↓ 选牌　● 翻开\n把三对小伙伴配起来");
        break;

    default:            // GAME_CAN
        lv_obj_set_x(U.mini_cat, s_mini_cat_x);
        for (int i = 0; i < MINI_MAX_CANS; i++) mini_can_hide(i);
        play_set(&s_mini_play, "cat_idle");     // 别接着主页那边的帧号乱跳
        lv_label_set_text(U.mini_tip, "↑ 往左　↓ 往右\n接住掉下来的猫罐头");
        break;
    }

    lv_obj_add_flag(U.mini_over, LV_OBJ_FLAG_HIDDEN);
    mini_hud_paint();
    lv_obj_remove_flag(U.ov_mini, LV_OBJ_FLAG_HIDDEN);
}

// 退出游戏（**内部**函数 —— 头文件里没有它，唯一的出口是 fa_view_mini_ok）。
// ★ 必需的一步：小游戏是盖在收藏册**上面**的一层，进游戏时并没有关册子 ——
//   所以这里只要把这一层收掉，底下那一层原样露出来。
// ★★ 第十六轮：底下那一层现在是**选择页**（不是收藏册）——
//   玩完一个还能接着选下一个。出册的唯一口子是选择页第 5 行「返回收藏册」。
static void fa_view_mini_close(void)
{
    s_mini_on  = false;
    s_mini_dir = 0;
    lv_obj_add_flag(U.ov_mini, LV_OBJ_FLAG_HIDDEN);
    fa_view_menu_show();
}

// ↑ / ↓ 的按下与抬手。★ 由 main.c 的 press/release 维护，见本节开头那条 ⚠。
//
// ★★ 第十六轮：这一支从「接罐头的方向键」升级成**四个游戏共用的方向输入**。
//   四个游戏对 ↑↓ 的用法完全不同，所以按 s_mini_game 分派：
//     接猫罐头   按住 = 往左 / 往右走（**需要抬手事件**，松手要停）
//     打兔子     按下 = 打那一排（一下就是一次出手）
//     剪刀石头布 按下 = 换一张牌
//     记忆翻牌   按下 = 移光标
//   ⚠ 后三个只在 down == true 时动作。要是把抬手也接上，
//     一次按键会被处理两次（按下换一张、抬手又换一张），手感是「跳着走」，
//     而且只在实机上试得出来。
void fa_view_mini_hold(int dir, bool down)
{
    if (!s_mini_on || s_mini_over_ms) return;

    switch (s_mini_game) {
    case GAME_RABBIT:
        if (down) rab_swing(dir < 0 ? 0 : 1);   // ↑ 上排 / ↓ 下排
        break;
    case GAME_RPS:
        if (down) rps_move(dir);
        break;
    case GAME_MEMORY:
        if (down) mem_move(dir);
        break;
    default:
        s_mini_dir = down ? dir : 0;            // 接猫罐头：按住才走
        break;
    }
}

// ● 短按。三种含义，按游戏分派：
//   结算面板亮着    —— 四个游戏一律「收掉面板，回选择页」
//   剪刀石头布      —— 出拳（每局一次）
//   记忆翻牌        —— 翻牌
//   接罐头 / 打兔子 —— 什么都不做：玩到一半误触 ● 不该把这一局弄没，
//                     所以这两个游戏进行中一律吞掉。
void fa_view_mini_ok(void)
{
    if (!s_mini_on) return;

    if (s_mini_over_ms) { fa_view_mini_close(); return; }

    if (s_mini_game == GAME_RPS)    { rps_ok();   return; }
    if (s_mini_game == GAME_MEMORY) { mem_flip(); return; }
}

// ● 长按 = 不想玩了，**按现在的分数结算**（奖励照给）。
// ★ 它不是「放弃」：提前结束拿到的奖励和跑满全程是一样的。
//   15~20 秒不长，但不给一条早退的路，玩家被困在里面就只能干等 —— 这不合理。
// ★★ 第十六轮：这个键对**四个游戏都开着**。剪刀石头布与记忆翻牌的
//   **短按** ● 另有用途（出拳 / 翻牌），而短按不会触发 EV_LONG，
//   所以两种语义挂在同一个键上并不冲突。
void fa_view_mini_end_now(void)
{
    if (!s_mini_on || s_mini_over_ms) return;
    mini_finish();
}

// ------------------------------------------------------------------ 开场剧情

// 3 页。第 1 页交代「想走但走不了」，第 2 页猫请缨，第 3 页说会带礼物回来。
// 文案与 fa_font_title 的字符集有耦合 —— 标题用 24px 字面，
// 改了标题必须同步 tools/gen_fa_fonts.py 的 TITLE_TEXT，否则屏幕上是大方框。
static void build_intro(void)
{
    // ★★ 2026-09-19（第十二轮）：补上圆角 + clip_corner。
    //   开场剧情也是一层**全屏不透明**的界面，四角不切的话就露出底下的主页 ——
    //   同一个毛病（用户报的是小游戏和旅行中，这一层是顺着一并收口的）。
    //   严格说这是**用户没要求的一处**改动，但它是同一类缺陷：
    //   只要有一层全屏不透明的东西不切圆角，「四角永远是黑的」就不成立。
    U.ov_intro = mk_box(U.scr, 0, 0, SCR_W, SCR_H, C_INTRO_BG, R_CORNER, LV_OPA_COVER);
    // ★ 第十三轮：clip_corner 删除。开场这一层的子对象全在中部（标题 y=28 起、
    //   猫 y=192、三个圆点 y=274、提示 y=294 且居中），够不到圆角弧 ——
    //   单靠 radius 就够了。四角同样交给 build_corners。
    lv_obj_remove_flag(U.ov_intro, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    U.intro_title = mk_label(U.ov_intro, &fa_font_title, C_TEXT, "");
    place(U.intro_title, 0, 28, SCR_W, 34);
    lv_obj_set_style_text_align(U.intro_title, LV_TEXT_ALIGN_CENTER, 0);

    U.intro_body = mk_label(U.ov_intro, &fa_font_ui, C_TEXT, "");
    // ★★ 第十三轮：x 16 -> 12、宽 208 -> **216**。fa_font_ui 提到 16px Bold 之后，
    //   最长那句「攒下的猫罐头，能早些回家。」实测正好 **208px** —— 和原来的框宽
    //   一模一样，也就是**再宽一个像素就会折行**。折行后 4 行 > 100px 高，会被切。
    //   216 留了 8px 余量。⚠ 改这三句文案之前先跑 tools/_measure_fonts.py。
    place(U.intro_body, 12, 88, 216, 100);
    lv_obj_set_style_text_align(U.intro_body, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_set_style_text_line_space(U.intro_body, 10, 0);

    U.intro_img = lv_image_create(U.ov_intro);
    lv_obj_remove_flag(U.intro_img, LV_OBJ_FLAG_SCROLLABLE);
    place(U.intro_img, 88, 192, CAT_W, CAT_H);

    for (int i = 0; i < 3; i++)
        U.intro_dot[i] = mk_box(U.ov_intro, 108 + i * 12, 274, 7, 7,
                                C_LOCKED, LV_RADIUS_CIRCLE, LV_OPA_COVER);

    U.intro_hint = mk_label(U.ov_intro, &fa_font_tiny, C_ACCENT, "● 继续");
    place(U.intro_hint, 0, 294, SCR_W, 16);
    lv_obj_set_style_text_align(U.intro_hint, LV_TEXT_ALIGN_CENTER, 0);

    lv_obj_add_flag(U.ov_intro, LV_OBJ_FLAG_HIDDEN);
}

static void build_toast(void)
{
    U.toast = mk_box(U.scr, 30, 258, 180, 26, C_PANEL, 13, LV_OPA_90);
    U.toast_lb = mk_label(U.toast, &fa_font_tiny, 0xFFF6EC, "");
    lv_obj_center(U.toast_lb);
    lv_obj_add_flag(U.toast, LV_OBJ_FLAG_HIDDEN);
}

// ------------------------------------------------------------------ 四角角标
//
// ★★★ 2026-09-19（第十三轮）**整个工程的四角只由这一个对象负责。**
//   它必须建在最后（z 序最高），也必须是一个**只有边框、没有填充**的圆角矩形。
//
// ▼ 为什么不能用 clip_corner：见 build_scene 里那段长注释（会爆 64 KB 的 LVGL 堆）。
// ▼ 为什么不能只靠 radius：子对象不吃父对象的 radius。`bg_img` / `mini_bg` /
//   `dex_art` 这些**铺满全屏或接近全屏的子对象**会把父级切好的圆角重新涂死。
//   只有「盖在所有东西之上的一层」才能一次性解决 —— 就是这里。
//
// ================== 几何推导（改任何数字前先看懂这一段）==================
//
// 屏幕 240x320 放在 (0,0)。外壳的圆角半径 = R_CORNER = 26，所以四个角要遮掉的
// 区域是「屏幕矩形 减去 以 (26,26)/(214,26)/(26,294)/(214,294) 为心、r=26 的圆」。
// 以左上角为例，要遮的集合 = { (x,y) : 0<=x<26, 0<=y<26, dist((x,y),(26,26)) > 26 }。
//
// 现在做一个矩形对象，参数是：
//     x = -CVR_B, y = -CVR_B      w = SCR_W + 2*CVR_B      h = SCR_H + 2*CVR_B
//     radius = R_CORNER + CVR_B   border_width = CVR_B      bg_opa = TRANSP
//
// LVGL 画圆角边框的方式（lv_draw_sw_border.c:54-84）是：
//     外边界 = 这个矩形的圆角矩形，圆角半径 rout = radius
//     内边界 = 同一个矩形**四边各缩进 border_width**，圆角半径 rin = rout - border_width
//     涂色区域 = 外边界以内 ∩ 内边界以外（draw_border_complex，两个 radius mask 相减）
// 代入数字（CVR_B = 14）：
//     外圆角圆心 = (-14 + 40, -14 + 40) = **(26, 26)**  ← 和屏幕左上角的圆心重合
//     内边界矩形 = (-14+14, -14+14) ~ (253-14, 333-14) = **(0,0) ~ (239,319)** ← 正好是屏幕
//     内圆角半径 rin = 40 - 14 = **26**                  ← 和屏幕圆角半径一致
//     ⇒ 内边界就是「屏幕矩形、r=26 的圆角矩形」本身，也就是**该留下的那块**。
//     ⇒ 边框环 = 以 (26,26) 为心、半径 26 到 40 之间的那条环带。
//
// 覆盖性判据：要遮的最远点是屏幕角 (0,0)，它到 (26,26) 的距离是 26√2 ≈ 36.77，
// 落在环带 [26, 40] 之内 ⇒ **盖得住**。余量 40 - 36.77 = 3.23px。
// 这就是 `CVR_B >= R_CORNER * (√2 - 1)` 那条不等式的来历（见文件上方定义处）。
//
// ⚠ 三条不能动的：
//   ① **bg_opa 必须是 TRANSP**。圆角矩形的「背景填充」填的是**整个矩形减四角**，
//      不设透明就会画出一大块黑把整个屏幕罩住（这是最容易踩的一脚）。
//   ② **必须先 mk_box 再改 border_width** —— mk_box 内部把 border_width 清成 0 了。
//   ③ **必须最后建**。建序即图层序，它得压在 bg_cv / ov_dex / ov_mini / ov_intro
//      以及 toast 之上。少压一层，那一层的角就漏。
static void build_corners(void)
{
    U.corners = mk_box(U.scr, -CVR_B, -CVR_B,
                       SCR_W + 2 * CVR_B, SCR_H + 2 * CVR_B,
                       C_DARK, R_CORNER + CVR_B, LV_OPA_COVER);

    // ① 只留边框：填充全透明，否则整屏被罩黑。
    lv_obj_set_style_bg_opa(U.corners, LV_OPA_TRANSP, 0);
    // ② 边框就是那圈角带。颜色 = 屏幕底色，和真正的圆角外面看起来是同一个色。
    lv_obj_set_style_border_width(U.corners, CVR_B, 0);
    lv_obj_set_style_border_color(U.corners, lv_color_hex(C_DARK), 0);
    lv_obj_set_style_border_opa(U.corners, LV_OPA_COVER, 0);
}

// ------------------------------------------------------------------ 选择器（对外）

void fa_view_sel_move(int delta)
{
    // ★ 用 seq_departing() 而不是 s_seq != SEQ_NONE —— 猫在家溜达时也要能选档位
    if (g_fa.state != FA_HOME || s_card_up || seq_departing()) return;
    if (fa_view_dex_open()) return;

    const int n = FA_SLOT_COUNT + 1;      // 5 档时长 + 收集
    int s = s_sel + delta;
    if (s < 0)  s = n - 1;                 // 绕回：从「试玩」往上就是「收集」
    if (s >= n) s = 0;
    s_sel = s;

    // 选到时长档才动存档里的档位；停在「收集」上不动 g_fa.slot。
    if (s_sel < FA_SLOT_COUNT) {
        fa_set_slot(s_sel);
        // ★ 2026-09-19：这里原来有一段「换档了就退掉上一站指定」的回滚代码。
        //   「花三叶草指定下一站」整套功能（fa_target_* / DEX_ENTRY_GO）已按
        //   用户要求删除，换档从此没有任何需要回滚的副作用 —— 它就只是换档。
    }
    bar_refresh();
}

bool fa_view_sel_is_dex(void) { return s_sel == FA_SLOT_COUNT; }

// ------------------------------------------------------------------ 旅行遮罩 / 猫显隐
//
// ★★ 2026-09-19 第四次改版把整个「昼夜系统」删掉了。
//   原来这里是一个 apply_night(bool)：逐层把天空/太阳/三道山/远岸/小溪/近岸/草地/
//   灌木/云/屋子/风景换成夜色值（N_* 那 14 个常量），一共二十多行 bg_color 写操作。
//   它有两个结构性问题，第四次改版一个都绕不过：
//     ① 每加一处地景就得配一个夜间色，漏一个就会在暗画面里露出一块白天的亮色
//        （底栏草地底衬那次就是这么漏的）；
//     ② 首页换成整幅底图之后，「改 bg_color」这条路直接断了 —— 图片没有 bg_color，
//        只能走 image_recolor，那就得给每一层再配一套着色参数，比原来更绕。
//   用户的原话是「旅行的时候去掉夜间的感觉，直接加个遮罩就行」，正好是最省事
//   也最稳的那条路：**一层半透明矩形**，和底图是什么、有几层全都无关。
//
// ★ 遮罩建在 build_scene 的最后 —— 位置即图层：压住底图 / 风景 / 小屋 / 小院 / 猫，
//   但被 HUD、底栏、旅行面板、提示气泡压住（那几样建得比它晚）。
// ★ 平时整块 HIDDEN：全屏半透明混合是每帧成本最高的绘制之一，能不用就不用。
static void travel_mask(bool on)
{
    if (on) lv_obj_remove_flag(U.travel, LV_OBJ_FLAG_HIDDEN);
    else    lv_obj_add_flag(U.travel, LV_OBJ_FLAG_HIDDEN);

    // ★ 2026-09-19（第五次）：顶栏没有底色了，文字直接压在底图上。遮罩一压上去
    //   整屏变暗，深灰字就糊没了 —— 所以这里要把顶栏那三处的颜色跟着换一遍。
    //   只在真的翻转时调 hud_paint()：它是纯样式写操作，但也是「每帧都改样式
    //   就等于每帧失效重绘」那条纪律的适用对象，能不调就不调。
    if (s_hud_dark != on) {
        s_hud_dark = on;
        hud_paint();
    }
}

// 猫什么时候出面 —— 2026-09-19（第九轮）起，判据只剩**一条**：不在旅行中就有猫。
//
// ★★ 旧判据是 `风景 == 家 && 不在旅行中`，理由是「明信片画里本来就画着一只猫，
//   铺满整屏之后俩猫同框一眼假」。那个理由在第九轮**失效了**：
//   用户改了口径 ——「明信片有猫，铺成背景的时候用无猫款，然后使用动态猫的图片在上面」。
//   挂风景时铺的是 fa_res_nocat_*（画里**没有**猫），所以猫必须出来，
//   而且它成了画面里**唯一**的那一只。
//
// ★★ 2026-09-19（第十轮）：**猫从此永远在场**，这个函数不再有分支。
//   第九轮时它还判 `g_fa.state != FA_AWAY` —— 因为旅行中铺的是**带猫**明信片，
//   再叠一只上去就成了「俩猫」。第十轮旅行中也换成无猫底图（见 scene_apply），
//   于是「旅行中」和「不旅行」的画面完全同类：**一张底图 + 我们自己的猫**。
//   猫在旅行期间照样溜达、照样坐下 —— 它就是留在家里等你的那只。
//
// ★ 函数保留、没删：它是全文件**唯一**碰 LV_OBJ_FLAG_HIDDEN 的地方，
//   开机、状态翻转、换风景三条路径都调它。哪天又需要藏猫，只改这里一处，
//   三个调用点一行都不用动。
static void cat_sync(void)
{
    lv_obj_remove_flag(U.cat, LV_OBJ_FLAG_HIDDEN);
}

// ------------------------------------------------------------------ 主页面风景（第十轮定型）
//
// **一层、一张图、一只猫。** 全屏只有 bg_cv/bg_img 这一张底图在铺，
// 区别只在铺的是哪一张：
//     没挂风景             -> fa_res_home（家的底图：有房子、没有猫）
//     挂着风景             -> fa_res_nocat_<景点>（那张**无猫**底图）
//     挂着风景 **且旅行中** -> 同上，一模一样
//
// ★★ 第十轮删掉了「旅行中铺 176x220 带猫明信片 ×1.5」那一层。
//   用户实机看下来的结论是效果不好（原话见文件上方 SCENE_SCALE 那段），
//   改成一律「无猫底图 + 我们自己的猫」—— 猫是活的，走、停、坐下都在。
//   ⚠ 这条同时意味着：**旅行中看到的就是猫留在原地的那处风景**，
//     它不再「跟着去远方」。这是刻意的取舍 —— 用户要的是画面好看，
//     而不是叙事上「明信片替你去了」。将来若想恢复，别只加回一个图层：
//     先想清楚「画面里那只猫是明信片里的，还是我们这只」。
//
// ★ 换 src 的纪律：**值没变就不 set_src**（set_src 会让整块区域失效重绘）。
//
// 把存档里挂着的风景应用到屏幕上。**无参、幂等** —— 开机、换完风景、
// 收下收获卡、从休眠回来都可以直接调一次，不用管当前是什么状态。
// ★ 它顺手把**猫**也同步一遍（末尾一句）：这两件事合起来才是「把主页画面拉齐」，
//   调用方不该为了同一个目的去记两个函数名。
static void scene_apply(void)
{
    const uint8_t s   = fa_scene();
    const bool    has = (s < FA_DEST_COUNT);      // 挂着别处的风景

    // ★ 这里**不再看 g_fa.state** —— 上面那段说的就是这件事。
    //   顺带得到一个好性质：换风景、出发、归来三个动作互不干扰。
    //   旧版 `card = has && away` 那套判据连同它的两个分支一起没了。
    const lv_image_dsc_t *bgsrc = has ? DEST_ART[s].nocat : &fa_res_home;
    if (lv_image_get_src(U.bg_img) != (const void *)bgsrc)
        lv_image_set_src(U.bg_img, bgsrc);
    lv_obj_remove_flag(U.bg_cv, LV_OBJ_FLAG_HIDDEN);

    // 猫跟着一起刷。★ 顺手调一次，保证「换完风景猫就到位」，不用等下一帧。
    cat_sync();
}

// ------------------------------------------------------------------ 收集册
//
// ★★ 2026-09-19（第五次）整节重写。用户原话：
//   「收藏里面就是明信片和家，把家当成一种一张明信片。」
//
//   于是册子里只剩两样东西，而且**只有一种页面**：
//     家      —— 排在序列第一格，永远有（你总能在家里）
//     明信片  —— 已经到手的那几张，按景点号排在后面
//   一页 = 一张 176x220 的真图 + 地名 + 题词 + 一行序号 / 说明。
//
//   键位（一套，不分页）：
//     ↑ / ↓  翻上一条 / 下一条（翻到头绕回）
//     ● 短按 出册
//     ● 长按 **把这一条设成主页的风景** —— 翻到「家」就是回家（fa_scene_clear），
//            翻到某张明信片就是把它挂到主页。用户原话：
//            「短按返回，长按更换为主页风景。」
//   ★ 这么一来「回家」和「换风景」成了**同一个动作的两个结果**，不用再有一页
//     菜单，也不会有「在菜单项之间跳来跳去」那种别扭感。
//
// ★ 删掉的三样（第五次），都别再抄回来：
//   ① 「家」那一页的三格菜单（回家 / 布置小院 / 返回）—— 布置小院整块下线，
//      「回家」并进了长按 ●；
//   ② 纪念品的一页合集 —— 用户明确说册子里只留明信片和家。
//      ⚠ 纪念品**照常发**（归来卡片上那行「带回桂花糕」还在，fa_souv_name 仍在用），
//        只是不再有展示页。这一条是本轮唯一一处「功能还在、界面没了」的地方，
//        要恢复就把那一页加回来，素材（souvenir_a 那 12 帧）没动过。
//   ③ 那五块程序化兜底小风景（dex_sky/sun/hill/hill_box/water）——
//      现在每一页都有真图，兜底没有出现的场合。
//
// ★★ 明信片这一页的呈现**必须和「到达卡」一字不差**（同样 176x220 原图、
//   同样 scale 256、同样显式给尺寸）：实机反馈「地点到达的时候，那种卡片处理
//   方式就比较好」。两边共用同一套数字，才不会出现「到达卡能显示、册子里显示
//   不出来」这种只在一处显形的差异。这也是本节的**唯一**画法。
#define DEX_ENTRY_HOME  0xFD
// ★ 2026-09-19（第九轮）新增：旅行中那一格。**只在 FA_AWAY 期间进序列**。
//   0xFD / 0xFE 都是「不可能和景点号撞车」的哨兵值（FA_DEST_COUNT 是 24）。
#define DEX_ENTRY_AWAY  0xFE
// ★ 2026-09-19（第十轮）新增：小游戏那一格。
//   用户原话：「设计一个小游戏，放在收藏，跟明信片一样，可以让人选」——
//   「跟明信片一样」= 它是序列里**真正的一格**，翻得到、按得进去，
//   而不是顶栏上的一行提示。
//   排位：**紧跟「家」之后**。它是日常最高频的一个去处（闲着就能玩一局），
//   而明信片是「看」的，翻起来没有时效性。
#define DEX_ENTRY_PLAY  0xFF
// ★★ 2026-09-21（第四十七轮）新增：**纪念品图鉴**那一格（两页 3x4）。
//   用户原话：「加到游戏里面吧，放在收藏里面，用两页展示一下，每页都是 3*4 就行，
//   现在一共 24 个纪念品。」
//   ★ 和 PLAY / HOME 一样是**固定条目**（永远在序列里，不等你收到第一件才出现）——
//     不然「没获得时那个位置是灰的」就无处可放。
//   ★ 排位：**紧跟在「家」之后、24 张明信片之前**。它是「收集物」里最固定的那一类，
//     而明信片是动态列表（收到一张多一格），排在一起会把它挤得到处跑。
//   ⚠ 0xFC 与 0xFD/0xFE/0xFF 三个哨兵不冲突，也和 0..23 的景点号不冲突。
#define DEX_ENTRY_SOUV  0xFC

// ★ 序列容量 = 「旅行中」1 + 「家」1 + 「小游戏」1 + 「纪念品」1 + 24 张明信片 = **最多 28**。
//   ⚠ 这个数被加过三次，每次都是因为往序列里塞了新条目：
//     第九轮 +1(26) 塞进「旅行中」，第十轮 +1(27) 塞进「小游戏」，
//     第四十七轮 +1(28) 塞进「纪念品」。
//     带着全部 24 张明信片去旅行、再打开册子时，序列正好是 28 条；
//     数给小了 dex_build_list() 会**越界写**——而那是全局数组旁边的内存，
//     表现是「别的东西莫名其妙坏掉」，不会当场报错。**再加条目记得一起加这个数。**
static uint8_t s_dex_list[FA_DEST_COUNT + 4];
static int     s_dex_n;
static int     s_dex_cur;
// ★★ 2026-09-21（第四十七轮）：纪念品图鉴当前看的是第几页（0 / 1）。
//   ⚠ 它和 s_dex2_cur 是**同一类东西**（「光标停在哪一格里」），所以待遇也一样：
//     翻走再翻回来不重置，只有**开册**才归零（见 fa_view_dex_show）。
static uint8_t s_souv_page;
// 顶栏那行进度用（fa_view_msg 不拷贝字符串，所以两个缓冲必须分开，
// 借错了会把进度那行字写成提示语）。
// ★ s_toast_buf 的**定义**已挪到「小游戏选择页」那一节（第十六轮）——
//   fa_view_menu_ok 也要用它。这里只剩 s_msg_buf。
static char    s_msg_buf[48];

// ★ 序列：**家在最前**，然后是已到手的明信片。
//   家放第一位而不是最后一位，两个理由：
//     ① 它是唯一一个「永远有」的条目 —— 册子一打开就是它，哪怕一张明信片
//        都没有，这一页也不是空的；
//     ② 「回家」是最高频的动作，离手最近。
static void dex_build_list(void)
{
    s_dex_n = 0;

    // ★★ 2026-09-19（第十二轮）用户点名：「收藏中，小游戏放在第一个」。
    //   ⇒ 顺序 = 小游戏 →（旅行中）→ 家 → 明信片…
    //   ⚠ 「旅行中」因此从第一位退到第二位。它并没有变得没用：
    //     ● 短按出册本来就会回到旅行界面（FA_AWAY 状态自己会把面板亮出来），
    //     它仍然是把「怎么回去」写在脸上的一格，只是不再排最前。
    //   ⚠ 序列容量（见 s_dex_list 上方那段）第四十七轮已由 **+3 改为 +4**
    //     （新塞进「纪念品」那一格）：
    //     这次只是**换了顺序**，没有新增条目，所以那个数不用动。
    s_dex_list[s_dex_n++] = DEX_ENTRY_PLAY;
    // ★ 2026-09-19（第九轮）：旅行中时插进「旅行中」这一格。
    //   它不是明信片也不是家，是一格「动作入口」（见 dex_refresh 的页零）。
    if (g_fa.state == FA_AWAY) s_dex_list[s_dex_n++] = DEX_ENTRY_AWAY;
    // ★ 「家」永远在（唯一一个不可能缺的条目），排在动作入口之后。
    s_dex_list[s_dex_n++] = DEX_ENTRY_HOME;

    // ★★ 2026-09-21（第四十七轮）：纪念品图鉴，**紧跟在「家」之后**。
    //   和 PLAY / HOME 一样是固定条目 —— 一件都没收到时它也在，
    //   那一页就是 12 个灰格子（用户要的正是这个：「没获得时那个位置是灰的」）。
    s_dex_list[s_dex_n++] = DEX_ENTRY_SOUV;

    for (int i = 0; i < FA_DEST_COUNT; i++)
        if ((g_fa.postcards >> i) & 1u) s_dex_list[s_dex_n++] = (uint8_t)i;

    // 收藏变少（理论上不会，但擦过 flash 就会）时把游标夹回合法范围
    if (s_dex_cur >= s_dex_n) s_dex_cur = s_dex_n - 1;
    if (s_dex_cur < 0)        s_dex_cur = 0;
}

// 顶栏那行进度。
// ★★ 2026-09-21（第四十七轮）：**按当前页分派** —— 停在纪念品图鉴那一格时报纪念品，
//   别的地方一律报明信片。
//   ~~旧口径：一律报明信片~~（那时纪念品没有展示页，「报一个看得到数、点不进去的
//   数只会让人满册子找入口」—— 现在有地方看了，就该报）。
//   ⚠ 它和 dex_build_list 的调用顺序不能反：本函数要读 s_dex_list[s_dex_cur]。
static void dex_progress_text(void)
{
    const int cur = (s_dex_n > 0) ? (int)s_dex_list[s_dex_cur] : -1;

    if (cur == DEX_ENTRY_SOUV)
        snprintf(s_msg_buf, sizeof(s_msg_buf), "纪念品 %d / %d",
                 fa_souvenirs_have(), FA_SOUV_COUNT);
    else
        snprintf(s_msg_buf, sizeof(s_msg_buf), "明信片 %d / %d",
                 fa_postcards_have(), FA_DEST_COUNT);

    lv_label_set_text(U.dex_title, s_msg_buf);
}

// 显示一张 **240x320 的底图**（家的底图，或某张无猫底图）。
// ★ 它和明信片一样是**预览**：这里只看，不上主页 —— 主页画面由 scene_apply() 管。
// ★ 2026-09-19（第九轮）：从「只会显示家的底图」放宽成「显示传进来的任何一张」——
//   新增的「旅行中」那一页要拿**当前挂着风景的无猫底图**当封面（那正是你回去之后
//   会看到的画面），而它和家的底图尺寸完全一样，共用这一套缩放数字。
//   ⚠ 名字里的 home 去掉是有意的：函数不再假设画的是「家」。
//
// ★★★ 2026-09-20（第四十轮）：**156x208（scale 167）→ 167x208（scale 190）**。
//   用户拍板的是「① 满幅 · 居中裁」：底图也铺满图位内轮廓，和明信片页一样齐整。
//   旧版整张缩进去只有 156 宽，左右各露 5~6px 白卡，整格显「空」——那是老毛病。
//   （沿革：第十三轮之前图位 176x220、用 scale 176 = 11/16 -> 165x220；
//     第四次用的 0.75 = 180x240，上下各被切 10px，天空和前景草地都没了。
//     这两版都是「比图位矮一截」的思路，跟满幅无关，留在这里当反例。）
//
//   ▼ 为什么是 190（这个数不能随手改）：
//       240 x 190 >> 8 = **178** —— 比内轮廓宽 167 多 11px、比高 208 多 30px，盖得住；
//       而 178 只比 167 多 11px，**裁掉的量最小**，再多就是白丢画面。
//       ⚠ 不能取 178：240 x 178 >> 8 = **166** < 167，左右各差 1px 又露白卡。
//       ⚠ 也别直接写 LV_IMAGE_ALIGN_COVER 让 LVGL 自己算：那条路会**改写 scale**
//         （`lv_image.c:894` 与 `update_align`），数字就不在这份代码里了。
//
//   ▼ 超出对象框的部分会被裁掉，裁在哪儿 —— 查过源码，别再怀疑：
//       `lv_refr.c:120`：**对象自己**的绘制裁剪区 = `layer->_clip_area ∩ obj_coords_ext`；
//       而 `obj_coords_ext` 只比 `obj->coords` 多一个 `ext_draw_size`，
//       `lv_image` 的 `LV_EVENT_REFR_EXT_DRAW_SIZE`（`lv_image.c:735-749`）
//       在 scale < 256 时算出来是负数 ⇒ `ext_draw_size == 0`
//       ⇒ 裁剪边界就是 **167x208 这个对象框本身**，
//         图 178x238 多出去的部分被**均匀裁掉**（上下各 15、左右各 5~6）。
//
//   ★★★ 但这个「均匀」有个前提：**`lv_image` 的对齐必须是 CENTER**。
//       它默认是 `LV_IMAGE_ALIGN_DEFAULT`，而 `lv_area_align()`（`lv_area.c:424`）
//       把 DEFAULT 落进 `default: x = 0; y = 0;` —— **等价于 TOP_LEFT**：
//       图会贴住对象左上角、只裁右下，房子下半截和前景草地整片丢失。
//       ⚠ 为什么以前从没暴露：156x208 和 167x208 那两版都是「图 == 对象框」，
//         怎么对齐全一样。**这一轮图第一次比框大**，默认值才第一次露出来。
//       ⇒ 所以在 build_dex 建对象时**显式钉了 CENTER**，那句别删。
//         两处是有依赖关系的，改这里之前先把 build_dex 里那段读完。
//
//   ★ 顺带解决一个老问题：2185 行那段写着「底图那几页圆心对不上，圆角会弱一些」
//     —— 那是因为底图只有 156 宽、和明信片（167）不同宽，角标那圈弧的圆心
//     落不到图的角上。**现在底图也是 167 宽、x 同样是 4，圆角跟着一起正了。**
//
//   ⚠ 它和明信片（dex_show_card，243 / 167x208）**共用同一个 dex_img**：
//     两个函数都必须把自己那套 scale + size **完整写回来**，
//     谁少写一句，下一页就会拿着上一页的数字画（第十三轮立过这条，别拆）。
static void dex_show_bg(const lv_image_dsc_t *dsc)
{
    lv_image_set_src(U.dex_img, dsc);
    lv_image_set_scale(U.dex_img, 190);
    lv_obj_set_size(U.dex_img, 167, 208);
    lv_obj_remove_flag(U.dex_img, LV_OBJ_FLAG_HIDDEN);
}

// 显示一张明信片 —— **和到达卡一字不差的三个数字**。
// ★ 尺寸和缩放每次都要显式写回来：这两张图**共用同一个 dex_img**，
//   谁改了不还回去，下一页就会拿着上一页的缩放画（明信片 243 / 家 167）。
// ★ 第十三轮：256 -> **243**。原因不在图，在字 —— 字放大之后卡片里装不下
//   四行，只能让图位让出 12px。走的是「整张等比缩」而不是「裁一刀」：
//   切底部会削到猫的爪子，切顶部会削到雨崩的雪峰尖；缩 5.1% 什么都不丢。
//   ⚠ 243 不是随手取的：220 x 243 >> 8 = 208，正好等于图位高度。
static void dex_show_card(const lv_image_dsc_t *dsc)
{
    lv_image_set_src(U.dex_img, dsc);
    lv_image_set_scale(U.dex_img, 243);
    lv_obj_set_size(U.dex_img, 167, 208);
    lv_obj_remove_flag(U.dex_img, LV_OBJ_FLAG_HIDDEN);
}

// 「小游戏」那一页：上格铺**当前挂着的风景**（无猫底图），下格固定西湖。
// ★ 它和 dex_show_bg / dex_show_card 是**同一个位置的三选一**：三个函数都往
//   那个图位画东西，谁都不会替你收拾另外两个。所以约定是 ——
//     · 走这里：由本函数把 U.dex_img 收起来（两格盖的是同一块地方）
//     · 走上头两个：dex_refresh() 开头统一把两格收掉
//   ⚠ 下格的图是固定的，在 build_dex 里设过一次就不再动；这里只换**上格**那张。
static void dex_show_pair(const lv_image_dsc_t *up)
{
    lv_image_set_src(U.dex2_up_img, up);
    lv_image_set_scale(U.dex2_up_img, DEX2_IMG_SCALE);
    lv_obj_set_size(U.dex2_up_img, DEX2_W, DEX2_IMG_H);
    // 对齐在 build_dex 里设过（居中）就不动了 —— 重复 set 只会白触发一次重绘。
    lv_obj_add_flag(U.dex_img, LV_OBJ_FLAG_HIDDEN);
    lv_obj_remove_flag(U.dex2_up_cv, LV_OBJ_FLAG_HIDDEN);
    lv_obj_remove_flag(U.dex2_dn_cv, LV_OBJ_FLAG_HIDDEN);

    // ★★ 2026-09-20（第二十二轮）：两只猫的动画在这里**各认一次名**。
    //   `play_set` 内部有「同一条就不动」的短路 ⇒ 一次翻页来回（翻走再翻回来）
    //   不会把已经跑了几帧的动画重置回第 0 帧，猫不会「每次都从头开始动」。
    //   ⚠ 这里只写「要播哪一组」，**不动 src** —— 真正的换帧在 fa_view_tick()
    //     的收藏册那一支里（play_tick）。所以创建时先塞过第 0 帧（见 build_dex）。
    play_set(&s_dex2_up_play, DEX2_UP_ANIM);
    play_set(&s_dex2_dn_play, DEX2_DN_ANIM);
}

// 刷新当前这一页。**整个收集册只有这一个「画」的地方** ——
// 翻页、开页、长按换风景之后，都只是调它一次。
// ---- 纪念品图鉴：把**当前那一页**的 12 格填出来 ----
//
// ★ 两页共用这 12 个对象，翻页只是重画一遍（见 SOUV_PER_PAGE 那段）。
// ★ 「已获得 / 未获得」两种画法**都在这里一处决定**，别散到别处去：
//     已获得 → 原图 + 名字
//     未获得 → **灰色剪影**（recolor 到 C_LOCK_TXT、recolor_opa 拉满）+ 名字留空
//   ⚠ 颜色在 build_souv 里设一次、这里只切 recolor_opa —— 一个判据一个赋值点，
//     换成「两套色各写一遍」迟早会出现某格忘了改回来（症状是拿到手了还是灰的）。
//   ⚠ 名字用 HIDDEN **并且**清空字符串，两件都做：HIDDEN 是「这一格没有名字」的
//     唯一表达（和设置页/PLAY 页同一条纪律），清空是防止哪天有人把 HIDDEN 收回来
//     之后残留上一页的字符串（翻页时对象是复用的，不清就会串字）。
static void souv_refresh(void)
{
    if (s_souv_page >= SOUV_PAGES) s_souv_page = SOUV_PAGES - 1;

    const int base = (int)s_souv_page * SOUV_PER_PAGE;

    for (int i = 0; i < SOUV_PER_PAGE; i++) {
        const int k = base + i;                 // 全局纪念品号 0..23

        // 末页不满 12 格时的尾巴。24 件正好两页、当前走不到，
        // 但留着 —— 以后改 FA_SOUV_COUNT 不必回来补这一段。
        if (k >= FA_SOUV_COUNT) {
            lv_obj_add_flag(U.souv_img[i],  LV_OBJ_FLAG_HIDDEN);
            lv_obj_add_flag(U.souv_name[i], LV_OBJ_FLAG_HIDDEN);
            continue;
        }

        // ★ 两套素材：0..11 在 souvenir_a、12..23 在 souvenir_b，
        //   **帧号 = k % 12**，与 fa_game.c 的 SOUV_NAME 顺序一一对应。
        //   ⚠ 这两个 id 必须和 gen_fa_sprites.py 的 OFFLINE 名单对得上：
        //     第四十七轮把它俩从名单里挪出来了，谁再挪回去这里就是一片空白。
        const char *kit = (k < 12) ? "souvenir_a" : "souvenir_b";
        const int   fr  = (k < 12) ? k : (k - 12);
        const fa_anim_t *an = fa_anim_find(kit);

        if (!an || fr >= (int)an->frames) {     // 素材缺失：宁可不画，也不画错一件
            lv_obj_add_flag(U.souv_img[i],  LV_OBJ_FLAG_HIDDEN);
            lv_obj_add_flag(U.souv_name[i], LV_OBJ_FLAG_HIDDEN);
            continue;
        }
        lv_image_set_src(U.souv_img[i], &an->dsc[fr]);
        lv_obj_remove_flag(U.souv_img[i], LV_OBJ_FLAG_HIDDEN);

        const bool has = ((g_fa.souvenirs >> k) & 1u) != 0;

        lv_obj_set_style_image_recolor_opa(U.souv_img[i],
                                           has ? LV_OPA_TRANSP : LV_OPA_COVER, 0);
        if (has) {
            lv_label_set_text(U.souv_name[i], fa_souv_name(k));
            lv_obj_remove_flag(U.souv_name[i], LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_label_set_text(U.souv_name[i], "");
            lv_obj_add_flag(U.souv_name[i], LV_OBJ_FLAG_HIDDEN);
        }
    }
}

static void dex_refresh(void)
{
    char buf[64];

    dex_build_list();
    dex_progress_text();

    // ★★ 「小游戏」那一格的遮罩在这里**统一收一次**（第十二轮立、第十三轮沿用）。
    //   它是那一格专属的，翻到任何别的页都必须先藏起来。
    //   只在这一处收、只在 PLAY 那支放，是为了保证「谁亮谁灭」永远只有两个点；
    //   分散到各分支里各写一遍 add_flag，迟早漏一个 —— 那种漏是静默的
    //   （黑遮罩压在别人的明信片上），而且只在特定翻页顺序下出现。
    //   ★ 遮罩上的两行字是它的子对象，跟着一起藏，不用单独管。
    lv_obj_add_flag(U.dex_mask, LV_OBJ_FLAG_HIDDEN);

    // ★★ 2026-09-20（第二十轮）：上下两格**也是同一套收放纪律** ——
    //   它俩是 PLAY 那一格独享的，收在这一处、放在 dex_show_pair() 里那两行。
    //   ⚠ 别把这两句挪进下面各分支：那种写法在「翻页顺序一变」时会漏，
    //     症状是两格照片压在别人的明信片上，静默、而且只在特定路径下出现。
    //     （U.dex_mask 已经保不住这种场面了 —— 它现在常年 HIDDEN，见 build_dex。）
    lv_obj_add_flag(U.dex2_up_cv, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_flag(U.dex2_dn_cv, LV_OBJ_FLAG_HIDDEN);

    // ★★ 2026-09-21（第四十七轮）：纪念品图鉴的 12 格**也是同一套纪律** ——
    //   收在这一处、只放 SOUV 分支一处。它盖的是整个卡片，比 dex2 那两格更大，
    //   漏收的症状同样静默（一页灰格子压在别人的明信片上）。
    lv_obj_add_flag(U.souv_grid, LV_OBJ_FLAG_HIDDEN);

    // ★★ 第十四轮：明信片四角角标**默认显示**，只在那一个「序列为空」的
    //   兜底分支里收起来（那里连图都不铺，四个卡片色的角会白站着）。
    //   跟 dex_mask 用同一个模式：收 / 放**各只有一个点**，
    //   这样翻页顺序再怎么变都不可能漏掉某一支。
    lv_obj_remove_flag(U.dex_art_cv, LV_OBJ_FLAG_HIDDEN);

    const int cur_code = (s_dex_n > 0) ? (int)s_dex_list[s_dex_cur] : -1;

    // ---- 页零：旅行中（只在旅行期间出现在序列里）----
    // ★ 用户原话：「短按进入收藏，此时收藏里面设置一个回到旅行界面」。
    //   它是**一格真正的条目**，不是顶栏上的一句提示 —— 用户要的是「翻得到、按得到」。
    // ★ 「回到旅行」不需要任何额外动作：FA_AWAY 状态自己会把旅行面板亮出来，
    //   而 ● 短按本来就是出册（见 fa_view_dex_ok）。所以这一页的**全部**内容
    //   就是把这个动作写在脸上 —— 用户按下去不会按空。
    // ★ 封面用**当前挂着风景的那张无猫底图**；没挂风景就退回家的底图。
    //   那张正是你回去之后会看到的画面，比放一张无关的明信片有信息量。
    // ★ 排在**第一条**：从旅行里进来的人，十有八九就是想回去。
    if (cur_code == DEX_ENTRY_AWAY) {
        lv_obj_add_flag(U.dex_empty, LV_OBJ_FLAG_HIDDEN);
        const uint8_t sc = fa_scene();
        dex_show_bg((sc < FA_DEST_COUNT) ? DEST_ART[sc].nocat : &fa_res_home);

        const int remain = fa_remain_secs();
        if (remain >= 3600)
            snprintf(buf, sizeof(buf), "还剩 %d:%02d:%02d",
                     remain / 3600, (remain / 60) % 60, remain % 60);
        else
            snprintf(buf, sizeof(buf), "还剩 %02d:%02d", remain / 60, remain % 60);

        lv_label_set_text(U.dex_name,  "旅行中");
        lv_label_set_text(U.dex_verse, "小猫还在路上");
        lv_label_set_text(U.dex_idx,   buf);
        lv_label_set_text(U.dex_hint,     "● 回到旅行");
        return;
    }

    // ---- 页一：家 ----
    // ★ 用户原话：「只是收藏里面增加一个家，如果选择家，小猫可以动态。」
    //   长按 ● 那一格就把主页风景设回「家」，猫立刻恢复动态
    //   （猫的显隐只有一个判据，见 cat_sync）。
    if (cur_code == DEX_ENTRY_HOME) {
        lv_obj_add_flag(U.dex_empty, LV_OBJ_FLAG_HIDDEN);
        dex_show_bg(&fa_res_home);

        const bool at_home = (fa_scene() >= FA_DEST_COUNT);   // FA_SCENE_NONE 也走这支
        lv_label_set_text(U.dex_name,  "家");
        // ★★ 2026-09-19（第十七轮）用户原话：
        //   「收藏里面，加下面写"小猫喜欢在院子里溜达"。」
        //   ~~旧：「小猫在院子里溜达」（8 字）~~ -> 现在 **10 字**。
        //   宽度复核：tiny 13px 汉字 = 13px/字 ⇒ 10×13 = **130px ≤ 框宽 196** ✓
        //   （这一格是 C_DIM 的题词行，居中；加两个字不会顶到边。）
        lv_label_set_text(U.dex_verse, "小猫喜欢在院子里溜达");
        lv_label_set_text(U.dex_idx, at_home ? "现在就在家" : "长按 ● 回家");
        // ★ 第十三轮：这条文案**被字号逼短了**。原文「上下翻　短按 ● 返回　长按 ● 换背景」
        //   在 tiny 13px 下要 221px，而这一格只有 196px ⇒ 必然折成两行，
        //   而卡片底部只剩 16px 高（下面就是卡片下沿）⇒ 第二行会被切掉。
        //   新文案实测 172px ≤ 196，一行放得下。**别再改回去。**
        lv_label_set_text(U.dex_hint,     "上下翻　● 返回　长按去游玩");
        return;
    }

    // ---- 页四：纪念品图鉴（2026-09-21 第四十七轮新增）----
    // ★ 用户原话：「加到游戏里面吧，放在收藏里面，用两页展示一下，每页都是 3*4 就行，
    //   现在一共 24 个纪念品。就是如果没有获得时候，所在位置是灰色的，也没有名字，
    //   获得后会出现并显示名称。」
    // ★ 它和别的页有一个本质差别：**↑↓ 不是翻条目，是翻这两页**。
    //   走位规则与 PLAY 那两格同构（先在本页内走、到边才翻条目），写在
    //   fa_view_dex_move 里；这里只管画。
    // ★ 网格盖的是**整个卡片**，所以除 dex_empty 之外还要收三样：
    //     dex_img（图位）、dex_art_cv（图位四角的角标）、以及下面三行字。
    //   ⚠ 三行字用**清空**而不是 HIDDEN —— 和 PLAY 页同一条纪律，
    //     理由见那边那段长注释（免得出现「哪一页该把 HIDDEN 收回来」这个清单）。
    if (cur_code == DEX_ENTRY_SOUV) {
        lv_obj_add_flag(U.dex_empty,  LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(U.dex_img,    LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(U.dex_art_cv, LV_OBJ_FLAG_HIDDEN);

        lv_obj_remove_flag(U.souv_grid, LV_OBJ_FLAG_HIDDEN);
        souv_refresh();

        lv_label_set_text(U.dex_name,  "");
        lv_label_set_text(U.dex_verse, "");
        lv_label_set_text(U.dex_idx,   "");

        // ★ 提示行：这一格**没有**「长按换背景」那条（它不是风景，没有图可挂），
        //   所以只写翻页 + 返回。长按在这一格 = 出册（见 fa_view_dex_ok_long）。
        //   页码摆最前面：两页是这一格独有的结构，不写出来人不会知道还有一页。
        // ⚠ 宽度复核：tiny 13px，「1/2 页　上下翻页　● 返回」约 153px ≤ 196 ✓
        snprintf(buf, sizeof(buf), "%d/%d 页　上下翻页　● 返回",
                 (int)s_souv_page + 1, SOUV_PAGES);
        lv_label_set_text(U.dex_hint, buf);
        return;
    }

    // ---- 页三：小游戏入口（2026-09-19 第十轮新增，第十六轮扩成四个游戏）----
    // ★ 这一页和别的页有一个本质差别：**短按 ● 不是出册，是进小游戏**。
    //   分派写在 fa_view_dex_ok() 里（那边只多一个 if），这里只管画。
    // ★★ 第十六轮：这一格从「接猫罐头」升级成**小游戏总入口** ——
    //   短按 ● 不再是直接开一局，而是先开**选择页**（fa_view_menu_show），
    //   四个游戏（接猫罐头 / 打兔子 / 剪刀石头布 / 记忆翻牌）在里面选，
    //   后三个要收够明信片才解锁。所以名字、题词、提示行三处都跟着改了。
    // ★ 封面铺的还是**当前挂着的那张风景** —— 那正是按下去之后会看到的背景，
    //   所见即所得。要是这里放一张固定图，人会以为「背景能在册子里选」，
    //   而实际上换背景的唯一入口是「翻到某张明信片长按 ●」（见 dex_ok_long）。
    if (cur_code == DEX_ENTRY_PLAY) {
        lv_obj_add_flag(U.dex_empty, LV_OBJ_FLAG_HIDDEN);

        const uint8_t sc  = fa_scene();
        const bool    has = (sc < FA_DEST_COUNT);
        // ★★ 2026-09-20（第二十轮）：~~dex_show_bg(...)~~ -> **dex_show_pair(...)**
        //   这一格不再铺「一整张风景 + 黑遮罩」，改成**上下两张小照片**
        //   （上 2/3「小游戏」· 下 1/3「设置」，各自圆角 10）。
        //   ★ 上格铺的仍然是「当前挂着的风景」—— 那正是按下去之后会看到的背景，
        //     「所见即所得」这一条**没变**，变的只是它现在只占 2/3 格、上面没有遮罩。
        //   ⚠ 下格固定西湖，已在 build_dex 里设好，这里不用传。
        //   ⚠ 本函数里会自己把 U.dex_img 收起来（两格盖的是同一个图位）。
        dex_show_pair(has ? DEST_ART[sc].nocat : &fa_res_home);

        // ★★ 2026-09-21（第四十五轮）：每次刷这一页都把光标**重画一遍**。
        //   为什么收在这一处：dex_refresh 是「这一页长什么样」的唯一出口，
        //   光标也属于「这一页长什么样」。放进 fa_view_dex_move 里的话，
        //   开册、翻页回来、任何别的路径进到这一页都会带着旧描边。
        //   ⚠ 它必须在 dex_show_pair() **之后** —— 那个函数会把两格 remove_flag，
        //     顺序反了没有错，只是白设一次（对象还没显示）。
        dex2_cursor_apply();

        // ★★★ 2026-09-21（第四十四轮，实机反馈）：**这两行必须清空。**
        //   用户原话：「首先这一页，好像设置下面还压住之前的字，没删干净的样子。」
        //   根因（不是「没删干净」，是**位置重叠**）：
        //     dex_name  y=215、dex_verse y=236，而下格 dex2_dn_cv 是 y168..244
        //     ⇒ 这两行**整行落在下格里面**；
        //     而它俩建在 dex2_dn_cv（2793 行）**之后** ⇒ 建序即图层序 ⇒ 字在下格**之上**，
        //     于是 C_DIM 的暗灰字压在 60% 黑底上 = 一行「脏影」浮在『设置』下方。
        //   ⇒ 这一页卡片下部只剩 dex_hint（y272，在两格之外 244 之后），
        //     所以前三行全部留空 —— 与 dex_idx 早就留空（见下面那段）同一个道理。
        //   ⚠ 别改成 `lv_obj_add_flag(HIDDEN)`：别的页靠 `set_text` 覆盖，
        //     统一用清空这一种写法，才不会有「哪一页该把 HIDDEN 收回来」这个清单。
        lv_label_set_text(U.dex_name,  "");
        lv_label_set_text(U.dex_verse, "");
        // ★★ 第十四轮：**「背景：X　最高 N 个」这一行整行删掉了。**
        //   用户原话：「然后『背景：长城　最高 5 个』这一行字去掉。」
        //   删掉之后 dex_idx 在这一页留空，卡片上只剩三行
        //   （~~接猫罐头 / 小猫接住掉下来的猫罐头 / 上下翻 ● 开始玩~~）。
        //   ★ 第十六轮那三行的**内容**都换了（小游戏 / 四个小游戏 慢慢解锁 /
        //     上下翻 ● 选游戏），但「只剩三行、dex_idx 留空」这个结构没变。
        //   · 背景是谁本来就**看遮罩后面透出来那张图就知道** ——
        //     dex_show_bg 铺的正是当前挂着的风景，写出来是重复的；
        //   · 「最高 N 个」跟着一起下线（用户点名的是整行）。
        //   ⚠ `s_mini_best` 这个变量**保留**：mini_finish 仍在维护它，
        //     别因为这里不再读就当死代码删掉 —— 删了那边会编译不过（好事），
        //     但更可能是有人顺手用 0 顶掉，那就静默丢了最好成绩。
        //   ⚠ 上面那个 `const char *bg` 也必须一起删：它的唯一用途就是
        //     拼这一行，留着就是一条 unused variable 警告。
        lv_label_set_text(U.dex_idx,  "");
        // ★ 第十六轮：~~"上下翻　● 开始玩"~~ -> 「选游戏」。
        //   「开始玩」是「按下去直接开一局」的说法，现在按下去只是**开选择页**，
        //   还得在里面挑一个 —— 写「开始玩」会让人以为按错了（怎么多出一页）。
        // ★★ 2026-09-19（第十七轮）用户原话：
        //   「小游戏主界面要写"长按返回"收藏的也是写"长按返回"。」
        //   ~~第十六轮：「上下翻　● 选游戏」~~
        //   ⇒ 这一页补上「长按返回」——它**本来就是**这一格该有的说法：
        //     长按在别页是「去游玩」，在这一页却什么都做不了（那一格不是风景，
        //     fa_view_dex_ok_long 走到 `code >= FA_DEST_COUNT` 就 return 了），
        //     等于多出一个没标注的死键。现在把它明确成「出册」。
        //   ⚠ 宽度：tiny 13px 下「上下翻　● 选游戏　长按返回」约 172px
        //     ≤ 框宽 196 ✓ 一行放得下。
        // ★★★ 2026-09-21（第四十五轮）：~~「上下翻　● 选游戏　长按返回」~~
        //   -> **「上下翻　● 进入　长按返回」**。
        //   为什么：「● 选游戏」现在只描述了**上格**。下格「设置」也按得进去了，
        //   提示行再写「选游戏」就是骗人（人按下格会以为按错）。
        //   ⇒ 两格共用一句不偏不倚的「进入」。
        //   ⚠ 宽度复核：tiny 13px，「上下翻　● 进入　长按返回」= 9 个全角 + 一个 ●
        //     约 158px ≤ 196 ✓（比旧文案还短 14px）。
        lv_label_set_text(U.dex_hint, "上下翻　● 进入　长按返回");

        // ★★★ 2026-09-20（第二十轮）：~~这里曾把 U.dex_mask（半透明黑遮罩 +
        //   「小游戏」三个字 + 两句总说）放出来~~
        //   现在这一格的内容改由 **dex2_up_cv / dex2_dn_cv 两格真控件**承担
        //   （图 + 暗底 + 真字体 + 猫），那层遮罩连同它的三个 label 一并下线。
        //   ⚠ 它常年 HIDDEN 之后，这里就**不能再有第二个「放」的点** ——
        //     否则会出现「一层黑遮罩压在新照片上」：既不是设计稿的样子，
        //     也不报任何错，只有肉眼能发现。
        //   ⚠ U.dex_mask 这个对象本轮**没有删**（字段留着，建完即 HIDDEN）：
        //     先把它从「谁亮谁灭」的名单里摘出来。真要清干净，
        //     得把 build_dex 里那段创建 + U 结构体那三行一起删，别只删一半。
        return;
    }

    // ---- 页二：明信片 ----
    if (cur_code >= 0 && cur_code < FA_DEST_COUNT) {
        lv_obj_add_flag(U.dex_empty, LV_OBJ_FLAG_HIDDEN);
        // ★ 第九轮：表改成了 DEST_ART[]（一行一个景点、两张图并排），
        //   取明信片要写明是 .card —— 底图那张是给主页铺屏用的。
        dex_show_card(DEST_ART[cur_code].card);

        const bool is_cur = (fa_scene() == (uint8_t)cur_code);
        lv_label_set_text(U.dex_name,  fa_dest_name(cur_code));
        lv_label_set_text(U.dex_verse, fa_dest_verse(cur_code));
        // ★★ 2026-09-19（第十七轮）用户原话：
        //   「明信片下面的"现在挂着"改成"正在此游玩"。」
        //   ~~「　现在挂着」（4 字）~~ -> 「　正在此游玩」（5 字），多 13px。
        //   ⚠ 宽度复核（tiny 13px，框宽 196，**最坏情形 = 「第 24 / 24 张明信片」**）：
        //       「第」13 +「 」3.25 +「24」14.4 +「 」3.25 +「/」3.6 +「 」3.25
        //       +「张明信片」52 +「　」13 +「正在此游玩」65 ≈ **181px ≤ 196** ✓
        //     余量 15px，安全。但**这是这一行最长的情形**，再往这行加字前先算一遍。
        snprintf(buf, sizeof(buf), "第 %d / %d 张明信片%s",
                 cur_code + 1, FA_DEST_COUNT, is_cur ? "　正在此游玩" : "");
        lv_label_set_text(U.dex_idx,  buf);
        // ★ 第十三轮：与「家」那一页同一条，因字号放大而缩短（见那边的说明）。
        lv_label_set_text(U.dex_hint,     "上下翻　● 返回　长按去游玩");
        return;
    }

    // ---- 兜底：序列为空（理论上到不了 —— 「小游戏」和「家」永远在）----
    lv_obj_add_flag(U.dex_img, LV_OBJ_FLAG_HIDDEN);
    // ★ 第十四轮：图都不铺了，角标也要跟着收 —— 否则卡片上会白站四个角。
    lv_obj_add_flag(U.dex_art_cv, LV_OBJ_FLAG_HIDDEN);
    lv_obj_remove_flag(U.dex_empty, LV_OBJ_FLAG_HIDDEN);
    lv_label_set_text(U.dex_hint,    "短按 ● 返回");
}

bool fa_view_dex_open(void) { return !lv_obj_has_flag(U.ov_dex, LV_OBJ_FLAG_HIDDEN); }

void fa_view_dex_show(void)
{
    if (s_card_up || seq_departing()) return;
    // 不重置 s_dex_cur：再次进来还停在上次看的那一张
    // ★★ 2026-09-21（第四十五轮）：**光标要重置**（回到上格「小游戏」）。
    //   为什么它和 s_dex_cur 待遇不同：s_dex_cur 是「你上次在看哪件东西」，
    //   记住它是对的；而光标是「你手上那个高亮圈在哪」，册子都关了、
    //   人已经从别的地方回来，还停在下格只会让人一进来就以为
    //   「咦，小游戏怎么不亮」——那一格才是这一页的主入口。
    //   ⚠ 写在 dex_refresh() **之前**：那边 PLAY 分支末尾会照 s_dex2_cur 画描边。
    s_dex2_cur = 0;

    // ★★ 2026-09-21（第四十七轮）：纪念品图鉴那一格也回到**第 1 页**。
    //   和 s_dex2_cur 同一条纪律 —— 册子关过、人从别处回来，还停在第 2 页
    //   会让人以为「怎么少了 12 件」。而 s_dex_cur（看的是哪一件）照旧不重置。
    //   ⚠ 同样必须在 dex_refresh() 之前：那边 SOUV 分支会照它填格子。
    s_souv_page = 0;

    dex_refresh();
    lv_obj_remove_flag(U.ov_dex, LV_OBJ_FLAG_HIDDEN);
}

void fa_view_dex_close(void)
{
    lv_obj_add_flag(U.ov_dex, LV_OBJ_FLAG_HIDDEN);
    // ★★ 2026-09-21（第四十五轮）：**设置页也要一起收**。
    //   它盖在册子上面（U.ov_set 建在 U.ov_dex 之后）。正常路径上它总是先被
    //   fa_view_set_close() 收掉；但册子还有几条**不由人手**关掉的路 ——
    //   出发序列开始（fa_view_dex_show 里那句 seq_departing 挡的是「打开」，
    //   而已经开着的册子在出发那一刻是别的代码收的）。漏掉这一句，
    //   症状是「出发动画底下压着一整张设置页」，静默、而且只在特定时序下出现。
    lv_obj_add_flag(U.ov_set, LV_OBJ_FLAG_HIDDEN);
    // ★ 出册时统一把风景重刷一遍。理由：册子是**全屏盖住**的，
    //   在里面换了风景、或者刚好看完某处明信片，退出来必须立刻看到正确画面。
    //   scene_apply() 无参且幂等（没换图就不调 set_src），随手调不心疼。
    scene_apply();
}

void fa_view_dex_move(int delta)
{
    if (s_dex_n <= 0) return;

    // ★★ 2026-09-21（第四十五轮）：停在「小游戏」那一页时，↑↓ **先在两格之间走**，
    //   顶到边了才翻页。用户原话：「↑↓ 先在两格之间走、到边才翻页」。
    //   ⚠ 只对 PLAY 那一页成立 —— 别的页只有一件东西，↑↓ 照旧直接翻页。
    //   ⚠ 「到边」的判据就是 s_dex2_cur 自己：它是 0 还按 ↑（= 上边）、
    //     是 1 还按 ↓（= 下边），两种情况**都不 return**，落下去执行翻页。
    //     写成两个大 if/else 会很容易把「到底哪边算边」写反 ——
    //     反了的症状是「怎么按都不翻页」/「怎么按都在两格间弹」，都不报错。
    if (s_dex_list[s_dex_cur] == DEX_ENTRY_PLAY) {
        if (delta > 0 && s_dex2_cur == 0) {          // ↓ 且在上格 -> 走到下格
            s_dex2_cur = 1;
            dex2_cursor_apply();
            return;
        }
        if (delta < 0 && s_dex2_cur == 1) {          // ↑ 且在下格 -> 回上格
            s_dex2_cur = 0;
            dex2_cursor_apply();
            return;
        }
        // 走到这里 = 已经顶到边，往下执行翻页。
        // ★ 光标**故意不重置**：翻走再翻回来还停在原来那一格（用户要的是
        //   「选得中」，不该因为中间看了两张明信片就把它弹回上格）。
        //   回到上格的唯一时机是**开册**，见 fa_view_dex_show。
    }

    // ★★ 2026-09-21（第四十七轮）：**纪念品图鉴**那一格同构 —— ↑↓ 先在两页之间走，
    //   顶到边了才翻条目。用户原话：「用两页展示一下」（两页 = 一页 3x4 = 12 格）。
    //   ⚠ 「到边」的判据就是 s_souv_page 自己：它是 0 还按 ↑、是 1 还按 ↓，
    //     两种情况都**不 return**，落下去执行翻页。
    //   ⚠ 只有两页，所以「走」一步就换页 —— 这不是 bug，是 SOUV_PAGES 决定的。
    //     以后件数多到三页，这段不用改（「到边才落」的逻辑与页数无关）。
    //   ⚠ 页码**不重置**，和 s_dex2_cur 一样（开册才归零，见 fa_view_dex_show）。
    if (s_dex_list[s_dex_cur] == DEX_ENTRY_SOUV) {
        if (delta > 0 && s_souv_page == 0) {
            s_souv_page = 1;
            souv_refresh();
            return;
        }
        if (delta < 0 && s_souv_page == 1) {
            s_souv_page = 0;
            souv_refresh();
            return;
        }
    }

    // 翻到头绕回另一端。只有一两条收藏时（最常见：只有「家」）绕回比卡住舒服。
    int c = s_dex_cur + delta;
    if (c < 0)        c = s_dex_n - 1;
    if (c >= s_dex_n) c = 0;
    s_dex_cur = c;
    dex_refresh();
}

// ● 短按在看收集册时 = **出册**。唯一的例外：停在小游戏那一格时是**进游戏**。
// ★ 为什么「返回」是出册而不是「退回上一条」：这个册子的翻动是无级的
//   （翻到头会绕回最前面），做「退回」就得再记一个层级；一步出册最省事，
//   也永远出得来。
//
// ★ 第十轮加的这一个例外，就是用户那句「放在收藏，跟明信片一样，可以让人选」
//   的落点：那一格必须**按得进去**，否则它只是一张说明图。
//   ⚠ 分派放在这里、而不是 fa_view_dex_move() 里：翻页和动作是两回事。
//     混在一起就会变成「翻到它就自动进游戏」，连封面都来不及看。
// ★★ 第十六轮：进去之后**落在选择页，不是某一局**。
//   `fa_view_menu_show()` 会在 `s_card_up || seq_departing()` 时自己退回去
//   （和 fa_view_dex_show 同一条纪律），所以这里不用重复判。
//   ⚠ 别再改回 `fa_view_mini_show(GAME_CAN)` —— 那样四个游戏里
//     只有接猫罐头进得去，另外三个永远没人能玩到。
void fa_view_dex_ok(void)
{
    // ★★★ 2026-09-21（第四十五轮）：这一页现在有**两个**入口，● 按光标分派。
    //   用户原话（问题一）：「设置格选不中。」
    //   ⇒ 上格「小游戏」= 开选择页（第十六轮起的口径，没变）；
    //     下格「设置」= 开设置页（本轮新增，fa_view_set_show）。
    //   ⚠ 分派放在这里、而不是 fa_view_dex_move() 里：翻页和动作是两回事
    //     （第十六轮立过的纪律）。混在一起会变成「光标走到就自动进去」。
    //   ⚠ 光标值只有 0/1，且 dex2_cursor_apply() 是它唯一的表现 ——
    //     所以「光标在哪」和「● 会进哪里」永远一致，不会出现两套真相。
    if (s_dex_n > 0 && s_dex_list[s_dex_cur] == DEX_ENTRY_PLAY) {
        if (s_dex2_cur == 1) fa_view_set_show();
        else                 fa_view_menu_show();
        return;
    }
    fa_view_dex_close();
}

// ● **长按**在看收集册时 = **把这一条设成主页的风景**。
//   翻到「家」→ 回家（猫恢复动态）；翻到某张明信片 → 把它挂到主页。
//
// ★ 用户原话：「短按返回，长按更换为主页风景。」
// ★ 定完**直接出册**：风景是整屏铺满的，留在册里被册子盖着，换了什么根本看不见；
//   退出去才谈得上「立刻在眼前变」。
// ★ 已经是当前风景时不折腾：只弹一句、留在册里继续翻 ——
//   否则「长按了但家里本来就挂着它」会莫名其妙把人弹出册子。
void fa_view_dex_ok_long(void)
{
    const int code = (s_dex_n > 0) ? (int)s_dex_list[s_dex_cur] : -1;

    // ★ 2026-09-19（第九轮）：「旅行中」那一格不是景点，不能当风景挂上去。
    //   这里给一句解释而不是静默无反应 —— 沉默会让人以为长按坏了。
    //   ★ 第十二轮：用词跟着「换风景 -> 换背景」一起改。
    if (code == DEX_ENTRY_AWAY) {
        fa_view_msg("回去之后再换背景");
        return;
    }

    if (code == DEX_ENTRY_HOME) {
        if (fa_scene() >= FA_DEST_COUNT) {          // 已经在家
            fa_view_msg("已经在家了");
            return;
        }
        fa_scene_clear();
        fa_view_dex_close();
        fa_view_msg("小猫回家了");
        return;
    }

    // ★★★ 2026-09-19（第十七轮）新增：**「小游戏」那一格长按 = 出册**。
    //   用户原话：「……收藏的也是写"长按返回"。」
    //   为什么这一格原来什么都没做：它不是风景，下面那句
    //   `if (code < 0 || code >= FA_DEST_COUNT) return;` 会把它挡掉，
    //   于是这一格的长按是个**没有任何标注的死键**（而提示行现在写着「长按返回」，
    //   不接上就是骗人）。接上之后这一格的两个键都说得通了：
    //     ● 短按 = 进选择页（fa_view_dex_ok），● 长按 = 出册。
    //   ⚠ 别把它挪到 DEX_ENTRY_HOME 那一段**之前**：三支是互斥的 if，
    //     顺序不影响结果，但按「旅行中 -> 家 -> 小游戏 -> 明信片」的既有顺序
    //     读起来最顺（这一函数开头那两段的顺序就是这么排的）。
    // ★★ 2026-09-21（第四十七轮）：**纪念品图鉴**也接上同一条 —— 长按 ● = 出册。
    //   它和 PLAY 那一格是同一类（都不是风景，下面那句 `code >= FA_DEST_COUNT`
    //   会把它们挡掉）。不接的话这一格的长按就是个**没有任何标注的死键**。
    //   ⚠ 提示行这一格写的是「1/2 页　上下翻页　● 返回」，没写长按 —— 但出册
    //     是安全动作（不改变任何状态），按了不会出事，所以照样接上。
    if (code == DEX_ENTRY_PLAY || code == DEX_ENTRY_SOUV) {
        fa_view_dex_close();
        return;
    }

    if (code < 0 || code >= FA_DEST_COUNT) return;

    if (fa_scene() == (uint8_t)code) {
        // ★ 第十二轮：原来这句是「家里已经挂着它了」—— 用户说别再用「挂在家里」
        //   这个说法（见下面成功那一支），所以这里也统一成「已经在 X」系。
        // ★★ 第十六轮：~~「已经是 X 背景了」~~ -> 「已经在 X 了」。
        //   用户这一轮把「背景」这个说法整条线拿掉了（见下一段），
        //   这里留着「背景」两个字就不齐了；而且「已经到了某地」本来就是
        //   这个按钮在做的事 —— 换背景 = 去那个地方玩。
        //   ⚠ 和下面成功那一支**必须区分开**：那支是「到（刚抵达）」，
        //     这支是「在（本来就在）」—— 两句一样的话，人分不清有没有生效。
        snprintf(s_toast_buf, sizeof(s_toast_buf), "已经在%s了", fa_dest_name(code));
        fa_view_msg(s_toast_buf);
        return;
    }

    if (!fa_scene_set((uint8_t)code)) {
        // 理论上到不了：序列里只放已经拿到的明信片。
        // 留着是为了万一 fa_scene_set 的内部校验（postcards 位图）把某张判成
        // 没去过时，玩家看到的是「一句解释」而不是「按了没反应」。
        fa_view_msg("这张还没到手");
        return;
    }

    // ★★ 2026-09-19（第十六轮）：成功提示再改口径。
    //   ~~「XX的风景挂到家里了」~~（第十二轮前）
    //   ~~「已换成 XXXX 背景」~~（第十二轮，例如「已换成婺源背景」）
    //   -> **「已经到 XXXX」**（用户原话：「然后更换背景后，写"已经到XX"」）
    //   这一改和提示行那两处是**同一件事的两半**：按钮上写「长按去游玩」，
    //   按下之后回一句「已经到婺源」—— 一句承诺、一句回执，都在讲「你去了那儿」。
    //   旧写法两头都提「背景」，是把它当设置项在做；现在它是**一个去处**。
    //   ⚠ 不要再往这句里加「背景」两个字，否则又回到第十二轮那套说法上去了。
    snprintf(s_toast_buf, sizeof(s_toast_buf), "已经到%s", fa_dest_name(code));
    fa_view_dex_close();
    fa_view_msg(s_toast_buf);
}

// ★ 2026-09-19（第五次）这里删掉了「家」那一页的三格菜单状态（s_home_cur /
//   HOME_MENU_N）与纪念品合集页（DEX_ENTRY_SOUV）。两个前任都别再加回来。
// ★ 第四次这里删过「更换风景」选择页（s_scene_pick / s_scene_cur / s_scene_list /
//   s_scene_n + scene_pick_build()）—— 换风景改成明信片页上长按 ●。
// ★ 更早（同一天）还删过一整段「指定下一站」：dex_build_pick() / dex_pick_enter()
//   和它专用的 s_dex_pick / s_pick_cur / s_pick_n / s_pick_list。
//   三个前任，一个都别加回来。

// ================================================================== 设置页（第四十五轮）
//
// 这一段的完整来历、为什么单独一层浮层、为什么只有亮度一项 —— 全写在
// 常量块（SET_CARD_X 那一段）的头上，这里不重复。
//
// 三个函数的分工（和收藏册那套一一对应，读的时候可以对着看）：
//     build_set()          —— 建对象，只跑一次（fa_view_init）
//     set_refresh()        —— 「这一页长什么样」的唯一出口（数字 + 五格条）
//     fa_view_set_*()      —— 给 main.c 用的四个口：查询 / 开 / 关 / 调亮度
//   ★ 谁亮谁灭**只有两个点**：fa_view_set_show 里放、fa_view_set_close 里收。
//     和 dex_mask / 两格用的是同一条纪律（分散写迟早漏一个，而且静默）。

// 把 tb_bright() 的百分数**收拢到 5 档里的第几档**（1..5）。
//   ★ 用四舍五入而不是向下取整：NVS 是跨固件共享的，里面可能留着别的入口
//     写进去的奇数（这个工程有过 ±10 的旧调整格）。向下取整会把 30% 显示成
//     1/5（差一档），四舍五入才是「肉眼看到的那一档」。
//   ⚠ 结果一定夹在 1..SET_LV_N：上面那一步只保证「大致对」，
//     返回 0 或 6 会让调用方的下标越界（set_bar[] 只有 5 个）。
static int set_bright_lv(void)
{
    int lv = (tb_bright() + SET_LV_STEP / 2) / SET_LV_STEP;
    if (lv < 1)        lv = 1;
    if (lv > SET_LV_N) lv = SET_LV_N;
    return lv;
}

// 把「当前亮度」画到这一页上：**只有那五格条的颜色**。
//   ★ 第四十六轮起右上角那个「N/5」没了（它和第一格**压在一起**，见 SET_CARD_* 常量块）。
//     代价钉在这儿：档位现在**只**由亮格数表达，没有第二处冗余。
//     哪天觉得条子不够清楚、想把数字加回来，先给它找到一段**不压格子的空位**
//     —— 卡片右侧只留了 12px（212..224），放不下一个「4/5」。
static void set_refresh(void)
{
    const int lv = set_bright_lv();

    // ★ 五格只改**颜色**，不改尺寸也不切显隐 ——
    //   「亮格 / 空格两套对象切 HIDDEN」那种写法要多 5 个对象，
    //   而且「谁亮谁灭」从 1 个判据变成 10 个赋值点，迟早漏一格。
    for (int i = 0; i < SET_LV_N; i++)
        lv_obj_set_style_bg_color(U.set_bar[i],
                                  lv_color_hex(i < lv ? C_ACCENT : C_PILL_BG), 0);
}

// 三块按键表的**两列文本**，各 14 行、逐行一一对应。
//   左列 = 键名，右列 = 说明。两个 label 各装一列 —— 行距天然一致（见 build_set）。
//
//   ★★ 行数纪律（这一段最容易出静默错）：**两张表必须都是 14 行**。
//      少一行或多一行，整块的左右对应关系就全歪了，而且看起来只是「有点不齐」，
//      很难一眼发现。改完数一遍：每个 \n 断一行，**最后一行不带 \n**。
//   ★ 空行填**全角空格 U+3000**，不是空串：
//      「\n\n」这种「行尾空行」会不会被 label 吞掉要看实现，而全角空格必然占一行；
//      它正好一个汉字宽，和人眼看到的缩进也是同一个量级。全角空格在字库里（已核对）。
//   ★ 键名行前面垫一个**全角空格** = 比分组标题缩进一个字。
//   ★ 分组标题用【】（U+3010/3011）—— 用户指定。这两个字原来**不在任何字表里**，
//     第四十六轮为此重跑了 gen_fa_fonts.py（并顺带新开 fa_font_small 这支 12px 字库）。
#define SET_TAB_L_TXT                                   \
    "【设置页面】\n"                                     \
    "　电源键\n"                                         \
    "　上下键\n"                                         \
    "　● 键\n"                                           \
    "【主页页面】\n"                                     \
    "　电源键\n"                                         \
    "　上下键\n"                                         \
    "　● 键\n"                                           \
    "　\n"                                              \
    "【旅游页面】\n"                                     \
    "　电源键\n"                                         \
    "　上下键\n"                                         \
    "　● 键\n"                                           \
    "　"

#define SET_TAB_R_TXT                                   \
    "　\n"                                              \
    "开关机\n"                                           \
    "调节屏幕亮度\n"                                      \
    "返回\n"                                             \
    "　\n"                                              \
    "开关机\n"                                           \
    "选择\n"                                             \
    "短按为确认\n"                                        \
    "长按为关闭屏幕\n"                                    \
    "　\n"                                              \
    "开关机\n"                                           \
    "关闭屏幕\n"                                         \
    "短按为进入收藏\n"                                    \
    "长按为快速回家"

static void build_set(void)
{
    // 全屏一层不透明暖黑 —— 和册子/小游戏那几层同一个做法（C_DARK + R_CORNER）。
    // ⚠ 四角由 build_corners() 那个角标统一遮（它是全屏 z 序最高的一层），
    //   这里**不要**加 clip_corner：第十三轮就是它把 LVGL 的堆压爆的。
    U.ov_set = mk_box(U.scr, 0, 0, SCR_W, SCR_H, C_DARK, R_CORNER, LV_OPA_COVER);
    lv_obj_remove_flag(U.ov_set, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    // 白卡。圆角 14 —— 比收藏册（12）和里面两格（10）都大一点，
    // 它是一张「独立的纸」，不是册子里的格子。
    // ★ 第四十六轮：216x298 -> **224x309**，y 16 -> 5（整体上移，让上下留白拉平）。
    U.set_card = mk_box(U.ov_set, SET_CARD_X, SET_CARD_Y, SET_CARD_W, SET_CARD_H,
                        C_CARD, 14, LV_OPA_COVER);

    // ---- 标题 ----
    // ★ 走 fa_font_game（24px 思源黑 Bold）—— 和收藏册两格里「小游戏 / 设置」
    //   是同一支字库、同一号字，这一页和那一格在视觉上是同一件东西。
    //   ⚠ 「设置」两个字已经在 GAME_TEXT 里（第二十轮加过），不用再改字表。
    U.set_title = mk_label(U.set_card, &fa_font_game, C_TEXT, "设置");
    place(U.set_title, 0, 8, SET_CARD_W, 30);
    lv_obj_set_style_text_align(U.set_title, LV_TEXT_ALIGN_CENTER, 0);

    // ---- 两条分隔线 ----
    // ★ 用 1px 高的 mk_box 画，不用 lv_line —— 本工程的 lv_line 只在曲线上用过，
    //   水平线用一个矩形最省事，也不吃 points 数组。
    // ⚠ 两条线的 y 是常量（SET_RULE_Y1/2），见常量块里那一段 y 布局。
    {
        const int ys[SET_RULE_N] = { SET_RULE_Y1, SET_RULE_Y2 };
        for (int i = 0; i < SET_RULE_N; i++)
            U.set_rule[i] = mk_box(U.set_card, 12, ys[i], SET_CARD_W - 24, 1,
                                   C_PILL_BG, 0, LV_OPA_COVER);
    }

    // ---- 亮度那一段（左标签 + 五格条；**没有**右上角那个「N/5」）----
    U.set_br_lb = mk_label(U.set_card, &fa_font_ui, C_TEXT, "屏幕亮度");
    place(U.set_br_lb, 12, 43, 90, 21);

    // 五格条。x 用表达式算：改 SET_BAR_W / GAP 时右沿自动跟着走，
    // 不会出现「改了宽度、第 5 格顶出卡片」这种要拿眼睛才发现的事。
    for (int i = 0; i < SET_LV_N; i++)
        U.set_bar[i] = mk_box(U.set_card,
                              SET_BAR_X + i * (SET_BAR_W + SET_BAR_GAP), SET_BAR_Y,
                              SET_BAR_W, SET_BAR_H, C_PILL_BG, 4, LV_OPA_COVER);

    // ---- 三块按键表 ----
    // ★ 两列**各一个 label 装 14 行**（LVGL 的 label 本来就吃 \n）——
    //   28 个对象变 2 个。而且两列的**行距天然一致**：同一个字体、同一个行高，
    //   分成 28 个 label 反而要手工保证每行 y 对齐。
    //   ⚠ 行距来自 text_line_space(SET_TAB_LS)；它和 SET_TAB_STEP 是同一个数，
    //     改一个必须改另一个（不然第 14 行会跑到卡片外面去）。
    //   ⚠ 字库是 fa_font_small（**12px**），不是 fa_font_tiny（13px）——
    //     换字号之前先重跑 gen_fa_fonts.py，并核对它的 .line_height 还是不是 15。
    U.set_key_rows = mk_label(U.set_card, &fa_font_small, C_TEXT, SET_TAB_L_TXT);
    place(U.set_key_rows, SET_TAB_LX, SET_TAB_Y, SET_TAB_LW, SET_TAB_H);
    lv_obj_set_style_text_line_space(U.set_key_rows, SET_TAB_LS, 0);

    U.set_key_vals = mk_label(U.set_card, &fa_font_small, C_DIM, SET_TAB_R_TXT);
    place(U.set_key_vals, SET_TAB_RX, SET_TAB_Y, SET_TAB_RW, SET_TAB_H);
    lv_obj_set_style_text_line_space(U.set_key_vals, SET_TAB_LS, 0);

    // 建完即收：只有从收藏册「设置」那一格按 ● 进来才露脸。
    lv_obj_add_flag(U.ov_set, LV_OBJ_FLAG_HIDDEN);
}

bool fa_view_set_open(void) { return !lv_obj_has_flag(U.ov_set, LV_OBJ_FLAG_HIDDEN); }

void fa_view_set_show(void)
{
    // 和 fa_view_dex_show 同一道闸：收获卡亮着 / 出发序列在跑，一律不开。
    // （正常路径上到不了这儿 —— 那两种情况下册子本身就不该开着；留着是防守。）
    if (s_card_up || seq_departing()) return;
    set_refresh();                 // 先照当前亮度画好，再露脸（避免第一帧是空的）
    lv_obj_remove_flag(U.ov_set, LV_OBJ_FLAG_HIDDEN);
}

void fa_view_set_close(void)
{
    lv_obj_add_flag(U.ov_set, LV_OBJ_FLAG_HIDDEN);
    // ★ 这里**不调 dex_refresh()**：册子一直开着（我们只是盖住它），
    //   底下那一页（PLAY）自始至终没变过，重刷一遍纯属白干。
    //   ⚠ 也**不要**在这里收 ov_dex —— 设置页是「回到册子」，不是「出册」；
    //     出册是下一句 ●（在册子上按）的事。收错了的表现是「从设置页回来直接到了主页」。
}

// ↑ / ↓ 调亮度：delta > 0 = 亮一格，< 0 = 暗一格。
void fa_view_set_move(int delta)
{
    if (delta == 0) return;

    int lv = set_bright_lv() + (delta > 0 ? 1 : -1);
    if (lv < 1)        lv = 1;
    if (lv > SET_LV_N) lv = SET_LV_N;

    // ★ 只在**档位真的变了**时才写 —— tb_bright_set() 每次都开 NVS、
    //   commit、关句柄（几十毫秒）。顶到 5/5 之后还一直按 ↑，
    //   每一按都白写一次 NVS，而画面一点变化都没有。
    const int nv = lv * SET_LV_STEP;
    if (nv != tb_bright()) tb_bright_set(nv);

    // 无论写没写，都把这一页重画一遍：顶到边时「数字不变」本身就是反馈
    // （省掉这一步的话，人不知道自己是不是按到了头）。
    set_refresh();
}

// ------------------------------------------------------------------ 开场剧情

#define INTRO_PAGES 3
// ------------------------------------------------------------------ 开场剧情

#define INTRO_PAGES 3

static const char *const INTRO_TITLE[INTRO_PAGES] = {
    "又是一天", "小猫站了出来", "它会带礼物回来",
};
static const char *const INTRO_BODY[INTRO_PAGES] = {
    "窗外的云在飘。\n想去的地方还很远，\n班，还是要上。",
    "它背上书包，\n抬头看了你一眼。\n“让我替你去吧。”",
    // ★ 「攒够三叶草，能点名下一站」已于 2026-09-19 作废 ——
    //   指定下一站整套功能被用户删掉了。三叶草现在唯一的用处是
    //   旅行中花几棵**快速返回**，所以开场这句改成那个。
    //   ⚠ 正文走 fa_font_ui（15px，字符集是扫源码自动收的），改正文不用动
    //     gen_fa_fonts.py，但必须重跑它；**标题**才进 TITLE_TEXT。
    "每走一趟，\n就寄一张明信片回来。\n攒下的猫罐头，能早些回家。",
};
static const char *const INTRO_ANIM[INTRO_PAGES] = {
    "cat_sleep", "cat_walk", "cat_carry",
};

static void intro_refresh(void)
{
    if (s_intro_page < 0)            s_intro_page = 0;
    if (s_intro_page >= INTRO_PAGES) s_intro_page = INTRO_PAGES - 1;

    lv_label_set_text(U.intro_title, INTRO_TITLE[s_intro_page]);
    lv_label_set_text(U.intro_body,  INTRO_BODY [s_intro_page]);
    lv_label_set_text(U.intro_hint,
                      (s_intro_page == INTRO_PAGES - 1) ? "● 开始" : "● 继续");

    for (int i = 0; i < 3; i++)
        lv_obj_set_style_bg_color(U.intro_dot[i],
                                  lv_color_hex(i == s_intro_page ? C_ACCENT : C_LOCKED), 0);

    play_set(&s_intro_play, INTRO_ANIM[s_intro_page]);
}

bool fa_view_intro_active(void) { return !lv_obj_has_flag(U.ov_intro, LV_OBJ_FLAG_HIDDEN); }

void fa_view_intro_next(void)
{
    if (s_intro_page + 1 < INTRO_PAGES) {
        s_intro_page++;
        intro_refresh();
        return;
    }

    // 最后一页再按一次就进游戏。★ 必须把 s_seen_state 弄脏：
    //   状态翻转那一段是按「state 变了」触发的，开场期间它一次都没跑过，
    //   不弄脏的话回来会以为自己已经处理过当前状态，画面停在开场前的样子。
    fa_intro_mark();
    lv_obj_add_flag(U.ov_intro, LV_OBJ_FLAG_HIDDEN);
    s_seen_state = 0xFF;
    bar_refresh();
}

// ------------------------------------------------------------------ 选择器 / 状态栏

static void bar_refresh(void)
{
    // ★ 2026-09-19（第九轮）：底色从米白（C_PILL_BG）换成暖黑（C_PANEL，
    //   与旅行面板是同一支），字色跟着从深灰 C_DIM 换成反白系 C_BAR_TXT ——
    //   深灰压在黑底上等于没写。选中那一格不变：实心橙 + 奶白字。
    for (int i = 0; i <= FA_SLOT_COUNT; i++) {
        bool sel = (i == s_sel);
        // ★★ 第十五轮：底栏改成「通栏遮罩 + 选中格橙胶囊」之后，**未选中的格必须
        //   把 bg_opa 一并关掉**（TRANSP）—— 只改 bg_color 的话，那一格会变成
        //   一块实心暖黑，把通栏那 80% 的透明度整块盖死（看着像贴了块补丁）。
        //   选中那格用 COVER：橙胶囊要压在暖黑条上跳出来；跟着一起 80% 会发褐，
        //   不是用户要的那个橙。
        lv_obj_set_style_bg_opa(U.pill[i], sel ? LV_OPA_COVER : LV_OPA_TRANSP, 0);
        lv_obj_set_style_bg_color(U.pill[i], lv_color_hex(C_ACCENT), 0);
        lv_obj_set_style_text_color(U.pill_lb[i],
                                    lv_color_hex(sel ? 0xFFF6EC : C_BAR_TXT), 0);
    }
    // 旅行中 / 归来 / 出发序列播放 / 收获卡 / 收集册里都不给选，选择器收起来。
    // ★ 判定必须是 seq_departing()：猫在家溜达、坐着歇的时候底栏要一直亮着。
    bool show = (g_fa.state == FA_HOME) && !seq_departing() &&
                !s_card_up && !fa_view_dex_open();
    if (show) lv_obj_remove_flag(U.bar, LV_OBJ_FLAG_HIDDEN);
    else      lv_obj_add_flag(U.bar, LV_OBJ_FLAG_HIDDEN);
}

// 把电量写进 HUD。soc < 0 = 没读到，那一格清空。
// ★ 只在**值真的变了**才 lv_label_set_text —— 每帧无条件写会让 LVGL 反复重排
//   （C3 上会掉帧），这条纪律和 s_last_clover 那几处是一样的。
// ★ 写在 hud_refresh 旁边而不是 tick 里：开机（fa_view_init）和每 10 秒的轮询
//   都要用同一套格式化逻辑，抄两份迟早有一份忘了夹 0..100。
// 顶栏那三处的配色。**只写样式、不读硬件**。
//
// ★ 为什么要单独一个函数（而不是在 batt_show 里顺手写完）：颜色取决于
//   「底下亮不亮」（旅行遮罩压没压上）和「电量掉到 15% 以下没有」这两个状态，
//   而这两个状态是**分别**变化的 —— 旅行翻转时电量没变，电量变化时旅行状态没变。
//   各写一份迟早会漏掉一边（顶栏没有底色之后，漏掉的后果是「字看不见」）。
// ★ 只在真的翻转时调（travel_mask / batt_show 里都带判断），不挂在每帧上。
static void hud_paint(void)
{
    // ★★ 2026-09-19（第十二轮）：字色**恒定纯白**。
    //   用户原话：「把顶上猫罐头数量和电量的字体放大，调整为白色」。
    //   白 + hud_chip() 那层淡衬底（40% 暖黑）在浅蓝天空和暗蓝遮罩下都立得住，
    //   于是原来那套「遮罩压上就换成暖白」的分支自然退休了：两档本来都是白系，
    //   留着只是多一处「迟早忘记同步」的地方。
    lv_obj_set_style_text_color(U.lb_clover, lv_color_hex(C_HUD_WT), 0);

    // ★ 猫罐头图标**不参与**这套配色（2026-09-19 第九轮）。
    //   原来的三叶草是一片实心绿叶子，压到暗底上必须提亮一档才不糊进遮罩，
    //   所以这里曾有一个 `for (i<3) set_bg_color(clover_dot[i])`。
    //   罐头是「银灰罐身 + 橙标签 + 深灰描边」三件套，在浅蓝天空和暗蓝遮罩下
    //   都立得住 —— 描边本身就把轮廓交代清楚了，不需要第二条配色分支。
    //   ⚠ 真要加分支的话记住：这一段是在**状态翻转时**被调的（travel_mask），
    //     不是每帧；但别把那个 `for` 抄回来 —— 那三个圆已经不存在了。

    // 电量：读到了才配色（读不到时那一格是空的，配了也看不见）。
    // ★ 低电量这一档**仍然要分两种底**：白字系里没有「警告」这个语义，
    //   而红色是这套界面里唯一的告警色，不能丢。
    if (s_batt_soc >= 0) {
        uint32_t c = (s_batt_soc <= 15) ? (s_hud_dark ? 0xFF9A86 : 0xD84A32) : C_HUD_WT;
        lv_obj_set_style_text_color(U.lb_batt, lv_color_hex(c), 0);
        // ★ 收藏册顶栏那一格跟主 HUD 是同一份状态，一起改 ——
        //   它俩永远显示同一个数，分开写迟早出现「册子里红、主页上白」。
        lv_obj_set_style_text_color(U.dex_batt, lv_color_hex(c), 0);
    }
}

// 电量图标选哪一张。★ 用户只给了三档：「一个满电，一个一半电，一个只剩下一点点电」——
//   所以判据就是两个阈值，**别实现成五档**，图上只有三张。
//   · ≤15%  -> 一点点（和 hud_paint 里「转红告警」用的是同一个门槛，
//              图标变红和数字变红必须同时发生，否则一眼看上去是两回事）
//   · ≤60%  -> 一半
//   · 其余  -> 满
//   ⚠ 60 这个数是「一半」的语义位，不是 50 —— 电池图标里那一半的填充条
//     本身画的就是半格多一点，数字和图形对不齐比不精确更难受。
static const lv_image_dsc_t *batt_icon_of(int soc)
{
    if (soc <= 15) return &fa_res_batt_low;
    if (soc <= 60) return &fa_res_batt_half;
    return &fa_res_batt_full;
}

static void batt_show(int soc)
{
    if (soc < 0) {
        // ★ 只在「上一帧还显示着数字」时清一次，不然每 30 秒都白写一遍。
        //   s_last_batt 弄脏成 -1：下次读到了才会重写那一格。
        // ★ 图标**不清**：读不到电（CW2017 未贴装的批次）时留上一张，
        //   总比留一块空白好 —— 字没了已经足够说明「这一格现在是空的」。
        if (s_last_batt != -1) {
            s_last_batt = -1;
            lv_label_set_text(U.lb_batt, "");
            lv_label_set_text(U.dex_batt, "");
        }
        s_batt_ok  = false;
        s_batt_soc = -1;               // hud_paint 据此跳过这一格
        return;
    }
    s_batt_ok  = true;
    s_batt_soc = (soc > 100) ? 100 : soc;
    if (s_batt_soc == s_last_batt) return;
    // ★ 缓冲给 12 而不是 8：GCC 的 -Wformat-truncation 是按「int 最多 10 位数字
    //   + % + 结尾」去算的，我们明知 soc 已经夹到 0..100 也没用，它不认；
    //   而 IDF 默认把警告当错误（-Werror=all），一个 HUD 上的百分比能让整次构建失败。
    char buf[12];
    snprintf(buf, sizeof(buf), "%u%%", (unsigned)s_batt_soc);
    // ★ 五处一起改：主 HUD 的数字 / 收藏册顶栏的数字 / 两处的图标。
    //   它们永远显示同一个数 —— 分开写迟早出现「册子里满格、主页上一半」。
    lv_label_set_text(U.lb_batt,  buf);
    lv_label_set_text(U.dex_batt, buf);
    lv_image_set_src(U.batt_ic,     batt_icon_of(s_batt_soc));
    lv_image_set_src(U.dex_batt_ic, batt_icon_of(s_batt_soc));
    hud_paint();                       // 颜色（含低电量转红）跟着一起算
    s_last_batt = s_batt_soc;
}

static void hud_refresh(void)
{
    if (g_fa.clover != s_last_clover) {
        char buf[16];
        snprintf(buf, sizeof(buf), "%u", (unsigned)g_fa.clover);
        lv_label_set_text(U.lb_clover, buf);
        s_last_clover = g_fa.clover;
    }

    // ★ 时钟显示已下线（2026-09-19，用户要求），所以这里不再读 tb_clock_local()。
    // ★★ 2026-09-19（第十三轮）：**校时状态点也一起下线**，这一整段因此清空。
    //   原来这里按 tb_clk_state_t 给 U.wifi_dot 换颜色（绿=已校时 / 黄=正在对 /
    //   灰=没凭据），用户实机认不出它是什么（「电量旁边有个点，是什么，去掉」）。
    //   注意：**校时本身没动** —— tb_clock 照旧跑，行程倒计时照旧依赖系统时钟，
    //   只是不再有一颗不说话的点待在顶栏上。想报状态就长按 ↑（有文字的那种）。
}

// ------------------------------------------------------------------ 收获卡

static void card_fill(void)
{
    // ★ 越界兜底：两条分支现在都要拿 d 去索引 DEST_CARD[]，所以先夹一次。
    //   正常情况下 d 一定是合法的（fa_finish 只在挑到牌时才写它，
    //   挑不到就保持 0），这一行是防着将来有人改 DEST_SLOT / got_dest 的写法。
    int d  = (g_fa.got_dest < FA_DEST_COUNT) ? (int)g_fa.got_dest : 0;
    int hu = fa_dest_hue(d);

    lv_obj_set_style_bg_color(U.card_sky,     lv_color_hex(HUE_SKY[hu]), 0);
    lv_obj_set_style_bg_color(U.card_sun,     lv_color_hex(HUE_SUN[hu]), 0);
    lv_obj_set_style_bg_color(U.card_hill[0], lv_color_hex(HUE_HILL[hu]), 0);
    lv_obj_set_style_bg_color(U.card_hill[1], lv_color_hex(HUE_HILL2[hu]), 0);
    lv_obj_set_style_bg_color(U.card_water,   lv_color_hex(HUE_WATER[hu]), 0);

    // ★★ 2026-09-19 改口径：快速返回这趟**照常给明信片和纪念品，只是不给三叶草**。
    //   用户原话：「用三叶草返回，可以给明信片和纪念品，但是不给三叶草，
    //   相当于用三叶草买的道具。」
    //
    //   ⚠ 所以这里**不能再**用 bit1 去把明信片藏起来。bit1 现在的含义只剩
    //     「这趟是花三叶草提前回来的」，用来换掉那一行三叶草文案 ——
    //     写「三叶草 ＋0」看着像系统算错了，写清楚是买来的才对得上账。
    //     （上一版 bit1 = 半路折返、什么收获都没有，那个口径已经作废。）
    if (g_fa.got_flags & 1u) {
        // ★ 拿到新明信片 —— 直接把那张真图铺上去（2026-09-19）。
        //   这层压在程序化小风景之上，一显示就把它整个盖住。
        lv_image_set_src(U.card_img, DEST_ART[d].card);
        lv_obj_remove_flag(U.card_img, LV_OBJ_FLAG_HIDDEN);

        lv_label_set_text(U.card_name,  fa_dest_name(d));
        lv_label_set_text(U.card_verse, fa_dest_verse(d));
        // ★★ 第十六轮：「长按设背景」-> 「长按去游玩」（用户点名，见 build_card 那段）
        lv_label_set_text(U.card_hint,  "● 收下　长按去游玩");

        // ★★ 第十八轮：判据从「只看 bit0」改成「bit0 **且非** bit2」。
        //   用户实测原话：「如果明信片已经在收藏里面有了，
        //   就不要再获得的相同明信片上打上『新获得』了。」
        //   根因在 fa_game.c 的 fa_finish：本档全拿到之后会**照样抽一张已有的**
        //   （第五次改的口径：「又见旧地也要把明信片显示出来」），那一条路径上
        //   bit0 和 bit2 是**一起**置的 ⇒ bit0 的语义早就变了，
        //   它现在只表示「有明信片可显示」，不再等于「新到手」。
        //   ⇒ 分工：bit0 管「画不画图」，bit2 管「亮不亮那三个字」。
        //   ⚠ 别把这一行简化回 `true`：那正是这次报的 bug。
        s_nb_on = ((g_fa.got_flags & 1u) && !(g_fa.got_flags & 4u));
    } else {
        // ★★ 2026-09-19（第五次）改口径：**又见旧地也要把明信片显示出来**。
        //   用户原话：「如果旅行结束，碰到与之前相同的明信片的时候，
        //   同样要显示出来，不要只说一句相同。」
        //   旧写法是收起图片层、只留一句「又见旧地 / 这一档的明信片都到手了」——
        //   跑了五个小时回来，看到的是一块没有画面的兜底色块。
        //   现在 fa_finish() 会照样抽一张**本档已有**的明信片（got_flags bit2），
        //   所以这一支和拿到新卡走**同一套画法**；「这张已经有了」写在按钮那行。
        lv_image_set_src(U.card_img, DEST_ART[d].card);
        lv_obj_remove_flag(U.card_img, LV_OBJ_FLAG_HIDDEN);

        lv_label_set_text(U.card_name,  fa_dest_name(d));
        lv_label_set_text(U.card_verse, fa_dest_verse(d));
        // ★ 第十三轮：原来这里是两行（「● 收下　长按设背景」+「这张已经有了」）。
        //   tiny 提到 13px 之后两行要 30px，而图位下面只剩 72px 放四行 ——
        //   差 7px 塞不下（不是想省，是物理上放不下，见 build_card 那段）。
        //   ⇒ 合并成一行，实测 172px ≤ 184。
        //   ★ 第十六轮只换了中间那五个字（设背景 -> 去游玩），**字数没变**，
        //     所以上面那个 172 依然成立，place() 一个字都不用动。
        lv_label_set_text(U.card_hint,  "● 收下　长按去游玩（已有）");

        s_nb_on = false;
    }

    // ---- 「新获得」+ 全解锁横条的显隐（第十六轮）----
    // ★ 显隐只在这**一处**决定（开页时 card_fill 必然被调一次），
    //   tick 那边只负责翻闪烁的相位，不碰显隐 —— 两个地方各管一半会打架。
    if (s_nb_on) {
        lv_obj_remove_flag(U.nb_bg, LV_OBJ_FLAG_HIDDEN);
        lv_obj_remove_flag(U.nb_in, LV_OBJ_FLAG_HIDDEN);
        lv_obj_remove_flag(U.nb_lb, LV_OBJ_FLAG_HIDDEN);
        for (int i = 0; i < 3; i++)
            lv_obj_remove_flag(U.nb_star[i], LV_OBJ_FLAG_HIDDEN);
        // ★ 相位复位成「亮着」。不复位的话这一张会串上一张卡残留的相位，
        //   实机上就是「明明是新的，字却是暗的」—— 看着像漏了半截动画。
        s_nb_ph = true;
        s_nb_ms = 0;
        lv_obj_set_style_text_opa(U.nb_lb, LV_OPA_COVER, 0);
        for (int i = 0; i < 3; i++)
            lv_obj_set_style_bg_opa(U.nb_star[i], LV_OPA_COVER, 0);
    } else {
        lv_obj_add_flag(U.nb_bg, LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(U.nb_in, LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(U.nb_lb, LV_OBJ_FLAG_HIDDEN);
        for (int i = 0; i < 3; i++)
            lv_obj_add_flag(U.nb_star[i], LV_OBJ_FLAG_HIDDEN);
    }

    // ★ 全解锁横条：判据是**收下这张之后**的总数 —— card_fill 是在 fa_claim 之后
    //   才调的（见 fa_view_card_claim 与 fa_view_init 两个调用点），所以这里读到的
    //   fa_postcards_have() 已经把手上这张算进去了，收到第 24 张时正好等于总数。
    //   ⚠ 别把它挪到 fa_claim 之前去判断 —— 那样永远差一张，横条一辈子不亮。
    if (fa_postcards_have() >= FA_DEST_COUNT) {
        lv_obj_remove_flag(U.allbar, LV_OBJ_FLAG_HIDDEN);
        lv_obj_remove_flag(U.allbar_lb, LV_OBJ_FLAG_HIDDEN);
    } else {
        lv_obj_add_flag(U.allbar, LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(U.allbar_lb, LV_OBJ_FLAG_HIDDEN);
    }

    char buf[48];
    // ★ 字号从 ui 降到 tiny（明信片占了 220px），所以文案要短一点。
    // ★★ 2026-09-19（第九轮）：bit1（花猫罐头提前回来的那趟）那一支**改成留空**。
    //   用户原话：「收到明信片的时候，如果是因为快速返回的，不要加那句不给猫罐头，
    //   直接不写就行了」。
    //   原来这里写的是「这趟不给三叶草」。现在一行都不写 —— 价钱早在旅行面板上
    //   报过了（「长按 ● 花 X 个猫罐头回来」），卡上再补一句是重复。
    //   ⚠ 是**留空**，不是写「猫罐头 ＋0」：那个看着像系统算错了。
    //   ⚠ 也别顺手把 card_gain 整个 HIDDEN 掉 —— 它是定长对象，
    //     空字符串已经什么都不画，改标志反而多一次失效重绘。
    if (g_fa.got_flags & 2u)
        lv_label_set_text(U.card_gain, "");
    else {
        snprintf(buf, sizeof(buf), "猫罐头 ＋%u", (unsigned)g_fa.got_clover);
        lv_label_set_text(U.card_gain, buf);
    }

    if (g_fa.got_souv != 255) {
        snprintf(buf, sizeof(buf), "带回%s", fa_souv_name(g_fa.got_souv));
        lv_label_set_text(U.card_souv, buf);
    } else {
        lv_label_set_text(U.card_souv, "");
    }

    // ★ 提示行（第五次改成**按分支写在上面**的两处）：
    //     新到手    -> 「● 收下　长按去游玩」
    //     又见旧地  -> 「● 收下　长按去游玩（已有）」
    //   ★★ 2026-09-19（第十六轮）文案改口径：「设背景」-> 「去游玩」。
    //     ~~新到手 -> 「● 收下　长按设背景」~~
    //     ~~又见旧地 -> 「● 收下　长按设背景（已有）」~~
    //     ⚠ 留痕是**故意的**（铁律 17）：这一行的前身叫「长按设背景」，
    //       旧交接说明里也是这个说法；只留新结论的话，下次看到旧的说明
    //       会以为哪边写错了，然后把它改回去。
    //   ⚠ 原来这里有一句无条件的复位（old 写法是给「半路回来」那条旧分支兜底的），
    //     现在**不能再写** —— 写上去会把上面那两句当场覆盖掉。
    //   ★ 2026-09-19（第九轮）：两处都加了「长按…背景」，对应新增的
    //     fa_view_card_claim_bg()。用户原话：「要加入长按直接设为背景。
    //     可以让收到之后立马设置为背景。」
    //   ★ 第二处改成两行，是因为「这张已经有了」和那一句加起来
    //     一行写不下（184px 塞不下 14 个汉字）—— 把 card_hint 的高度
    //     从 14 放到 24（见 build_card），第二行才落得下。
}

// ------------------------------------------------------------------ 对外

void fa_view_msg(const char *msg)
{
    if (!msg) return;
    lv_label_set_text(U.toast_lb, msg);
    lv_obj_remove_flag(U.toast, LV_OBJ_FLAG_HIDDEN);
    s_toast_ms = 2500;
}

// ------------------------------------------------------------------ 猫咪对我说的话
//
// ★★ 2026-09-20（第十八轮新增）用户原话：
//   「我希望你设计50句猫咪对我说的话，在主界面间隔几秒，比如5-30秒弹出来一句，
//     然后如果背景是各处，为每个地方再单独设计10句话，当挂上某个背景的时候，
//     就在50句里面交替出现单独设计的话。」
//
//   290 句（50 句通用 + 24 处风景各 10 句）住在 main/fa_talk.c ——
//   那个文件由 _dl/_talk18.py 产出，**句子的顺序即语义**（景点那一段按下标
//   对应 fa_game.c 的 DEST_NAME），所以别在这里手改句子。
//
// ★ 交替口径：挂着风景时 **一句通用、一句当地，轮流来**（s_talk_turn 翻牌）；
//   没挂风景（在家）时只走通用那 50 句。
// ★ 不重复：两个池子各有一张**开机时洗好的顺序表**，逐个走完再重新洗。
//   比「每句现随机取一条」多花 50+10 字节的静态内存，换来的是
//   「连着两句一模一样」不会发生（50 句里随机取，平均 25 次就会撞一次，实机很扎眼）。
// ★ 显隐判据集中在 talk_gate()：只有「没有浮层」时气泡才出来。
//   把它写在一处的理由是：这个话题在别的地方已经踩过 —— 判据散在几处，
//   迟早出现「小游戏里猫还在说话」这种漏网。
//
// ★★ 2026-09-20（第十八轮·续）用户原话：
//   「旅行界面也按照这样弹出来这些话吧。」
//   ~~本条原来写的是「只有『在家』时气球才出来」、talk_gate() 里第一句就是
//     `if (g_fa.state != FA_HOME) return false;`，注释理由是「旅行中那块面板
//     正占着气泡的位置」。~~ **那条被推翻了** —— 位置冲突是真的，但解法是
//     **给旅行中换一个 y**，不是「干脆不说」。留痕的理由见铁律 17：
//     只看到新结论的人会以为旅行里本来就不该说话。
//
//   旅行中的位置约束（三个硬边界，都是从实机布局量下来的）：
//     · 旅行面板 ov_away = y **44..180**（build_away，200x136）
//     · 猫                = y **200..264**（CAT_Y=200）
//     · 底栏              = y **292..320**（BAR_Y=292）
//   44..180 被面板吃掉、180..200 只有 20px、200..264 是猫、264..292 只有 28px
//   ⇒ **没有任何 52px 的空档**。所以只能在三种「压住谁」里挑一个：
//     (a) 压面板下半（面板上有倒计时、进度条、两行提示 —— 全是要读的）
//     (b) 压猫下半身 28px（猫是纯图形，且第十轮起「让猫显示出来」是用户点名的）
//     (c) 压猫的脚下 → 没有空间
//   取 (b)：气泡 **y=236**（底沿 288，离底栏留 4px）。它压住猫的 y 236..264
//   那一段（下半身），换来的是「面板上一个字都没挡住」+「两行句子照样放得下」。
//   ★ 这一条与铁律 13 的取舍同源：**挡住的必须是不承载信息的那部分**。
// ★★★ 2026-09-20（第二十五轮）**气泡整块换皮**：深暖黑面板 →「黑描边 + 白底半透明」。
//   用户原话：「现在的对话框不好看，根据我给你的改一下，主界面用这样的就行，
//     旅行界面因为说的话放下面了，对话框垂直翻转一下，让对话箭头有对着小猫的感觉。
//     对话框边缘是黑色的，内部是白底透明，可以稍微看到一些后面的背景图案。」
//   （附了一张参考图：大圆角矩形、粗黑描边、内部白底透出背景、左下角一个尖角。）
// ★★★ 2026-09-20（第二十六轮）**撤掉尾巴 + 压低高度**（用户看完预览后拍板）：
//   用户原话：「你先给我个效果图，没有尾巴的，对话框的高度不要太高。」→
//             「高都按照44，把这 1 句改短（只此一句），直接按照这个来改源码吧」。
//   ① 第二十五轮那条「转 45° 的方块」尾巴**整块撤掉** —— `TIP_*` 常量、`U.talk_tip`
//      字段、建/收/放/换边四处代码一起删。顺带把「旋转要建临时 layer、
//      每次重绘分配约 3KB」那个隐患也一起拆掉了（这条减法不是没代价的）。
//   ② 高度 52 → **44**。
//   ③ ★ **`TALK_Y` 的 136 必须跟着尾巴一起作废**：那个值是第二十五轮**专为尾巴
//      腾出 12px** 定的（下沿 188 + 尾巴尖 12px = 正好落在猫头顶 200）。
//      尾巴一撤，那 12px 就成了一段没来由的空隙 ⇒ 改成**按「下沿」定位**：
//          TALK_BOTTOM_HOME = 194（猫头顶 CAT_Y = 200 上方 6px）
//          TALK_Y = TALK_BOTTOM_HOME - TALK_H
//      好处是换高度时**底边不动、只有上边在动**，和猫的关系一眼就稳。
//      ⚠ 别再退回「写死一个 y」：那是尾巴时代的口径，现在唯一的锚点是下沿。
//   ④ 高度也不是随手压的，它被真实句子的字数卡着 —— 推导见下面 TALK_LB_Y 那段。
#define TALK_W        216
#define TALK_H        44                              // ★ 52 -> 44（第二十六轮）
#define TALK_X        ((SCR_W - TALK_W) / 2)          // 12
#define TALK_BOTTOM_HOME 194                          // 在家：气泡**下沿**（猫头顶 200 上方 6px）
#define TALK_Y        (TALK_BOTTOM_HOME - TALK_H)     // = 150；换档只动上边
#define TALK_Y_AWAY   236                             // 旅行中：**上沿不动**（气泡在下方 ⇒ 高度往下收）
#define TALK_LB_Y     12                              // 框内文字顶：**按一行垂直居中** =(44-19)/2

// ---- 新皮肤的三个数（第二十五轮）----
//   ⚠ 描边必须写在 mk_box **之后** —— mk_box 内部把 border_width 清成 0（见它的注释）。
#define TALK_R        16                              // 圆角：12 -> 16（参考图的圆角接近半高）
#define TALK_BW       2                               // 黑描边宽
#define TALK_OPA      LV_OPA_80                       // 白底不透明度：90 -> 80（要透出背景图案）
#define TALK_INK      C_DARK                          // 描边色 = 屏幕底色那支暖黑 0x1B1917

// ---- 为什么高度是 44、不是 40 也不是 52（第二十六轮唯一要算的东西）----
//   气泡内宽 = TALK_W − 8×2 = **200px**；16px 全角字宽 16px ⇒ **一行最多 12 字**。
//   把 `fa_talk.c` 的 50 + 240 句全扫了一遍，**只有敦煌那一句 13 字会折成两行**
//   —— 第二十六轮已把它改短（「爪印在沙上，风一吹就散。」12 字）
//   ⇒ **现在 250 句全部一行放得下**。于是：
//       高 44：一行字（行高 19）上下各留 12px，正好；
//       高 40：只剩 10px，且万一有句子折行就只剩 2px 缝 —— 不能用了。
//   ⚠ 上面那句「垂直居中」是**按一行算的**（`TALK_LB_Y = (44−19)/2 = 12`）。
//     这份 LVGL **关掉了 FLEX**，label 只能顶对齐，没法按内容行数自动居中；
//     也就是说「一行」这个前提**必须**由句子保证。
//   ⚠ 往 `fa_talk.c` 加句子时：**连标点在内不超过 12 字**（逗号句号也是全角，一样占 16px）。
//     超了不会报错，只是折成两行、下面那行被框裁掉 —— 又是一种静默失效。
#define TALK_FIRST_MS 8000                            // 开机后第一句
#define TALK_SHOW_MS  5000                            // 每句亮多久
#define TALK_GAP_MIN  5000                            // 收掉之后至少隔这么久
#define TALK_GAP_RAND 20000                           // …再加 0~20 秒的随机

static uint8_t s_talk_ord_base [FA_TALK_BASE_N];      // 通用 50 句的洗牌顺序
static uint8_t s_talk_ord_scene[FA_TALK_SCENE_N];     // 当地 10 句的洗牌顺序
// ★★ 2026-09-20（第四十二轮）：第三只池子 —— **当时那个天气的 10 句**。
//   它和上面两只的关系见 talk_pick()：天气句**插队说一次**，不参与通用/当地的轮转。
//   （「有待说的天气句吗」那个标记 s_wx_talk_kind 定义在**天气**那一节 ——
//     wx_begin() 要写它，而那个函数在本节之前。）
static uint8_t s_talk_ord_wx  [FA_TALK_WX_N];         // 当前天气 10 句的洗牌顺序
static uint8_t s_talk_next_wx;                        // 走到第几张
static uint8_t s_talk_next_base, s_talk_next_scene;   // 各自走到第几张
static bool    s_talk_turn;                           // false = 该通用那句 / true = 该当地那句
static int     s_talk_scene = -1;                     // 上次洗牌时的风景号（换风景要重洗）
static bool    s_talk_on;                             // 气泡亮着吗
static int     s_talk_ms = TALK_FIRST_MS;             // 亮着 = 还剩多久收；没亮 = 还有多久弹
static bool    s_talk_away;                           // 气泡当前摆在「旅行中」那个位置吗（TALK_Y_AWAY）

// 洗牌 + 复位游标。★ 只在开机和「换风景」时调，不在每句之间调 ——
//   每句都重洗的话就退化成「随机取」，正是上面要避免的那件事。
static void talk_shuffle(uint8_t *ord, int n)
{
    for (int i = 0; i < n; i++) ord[i] = (uint8_t)i;
    for (int i = n - 1; i > 0; i--) {
        const int j = (int)lv_rand(0, i);
        const uint8_t t = ord[i]; ord[i] = ord[j]; ord[j] = t;
    }
}

static void talk_hide(void)
{
    s_talk_on = false;
    // ~~★ 第二十五轮：**两个一起收**（气泡 + 尾巴）~~
    //   **第二十六轮撤掉尾巴** ⇒ 又只剩一个对象。原来那条 ⚠ 还成立，留着当教训：
    //   成对的开关就**在同一处**写全 —— 只在一边收、另一边留着，
    //   错了不报错、只是「屏上有个多余的脏点」。
    lv_obj_add_flag(U.talk, LV_OBJ_FLAG_HIDDEN);
}

// 现在能不能说话。★ 一条「没有浮层」的清单，别在别处再抄一遍。
// ★★ 第十八轮·续：**旅行中（FA_AWAY）也放行**。用户原话：「旅行界面也按照这样
//   弹出来这些话吧。」
//   ~~原来第一句是 `if (g_fa.state != FA_HOME) return false;`，注释理由是
//     「旅行中：那块面板正占着气泡的位置」。~~ 位置冲突是真的，但**解法是给
//     旅行中换一个 y**（TALK_Y_AWAY），不是「干脆不说」——为什么是 236、
//     为什么只能压猫，见常量区那一段（TALK_Y_AWAY 上面）。
//   ⚠ FA_BACK 仍然不放行：那一段要么猫正从左边走回来（SEQ_WALKIN，下面
//     seq_departing() 已经拦了），要么到达卡正摊着（s_card_up）。两个都拦完
//     就没什么「安静的 FA_BACK」了 —— 多放行一个状态只会多一条要单独测的路径。
//   ⚠ 这里是**唯一**的口子：气泡该不该说话只认这一处，别在 tick 里再抄一份判断。
// ★★ 2026-09-20（第四十二轮）：那张清单**搬进了 overlay_busy()**（在天气那一节里，
//   见 build_weather 上面）—— 因为天气（weather_tick）要用一份**一模一样**的判据
//   （浮层开着时天气整个冻住）。两处各写一份的话，将来加一个新浮层必然漏掉其中一处，
//   而症状是静默的。本函数现在就只是它的反义；名字留着，是因为
//   「气泡该不该说话」这个语义在此处最清楚，而调用点也全挂在这个名字上。
static bool talk_gate(void) { return !overlay_busy(); }

// 取下一句。★ 挂着风景时「通用 / 当地」交替；当地池子走完一轮就重洗。
static const char *talk_pick(void)
{
    // ★★ 2026-09-20（第四十二轮）：天气句**插队**。
    //   用户原话：「再为每个天气加 10 句话，让小猫在所属天气的时候说一下」——
    //   落脚点在「**在所属天气的时候**」。所以它不是第三只轮转池：
    //   轮转意味着每三句才轮到一次天气，而一场天气只持续 25 秒，
    //   按 5~25 秒的说话间隔，很可能一直等到雨停了都没轮到 —— 那就白加了。
    //   改成：**天气一来就优先说一句**，说完立刻回到原来那套通用 / 当地的轮转。
    //   ⚠ 挂号的是 wx_begin()，这里取用一次就清掉（见 s_wx_talk_kind 的说明）。
    //   ⚠ 先清再取：万一句子取不到（k 越界），也不至于把标记永远挂着。
    if (s_wx_talk_kind >= 0) {
        const int k = s_wx_talk_kind;
        s_wx_talk_kind = -1;                       // 「只说一句」
        if (k < WX_KIND_N) {
            if (s_talk_next_wx >= FA_TALK_WX_N) {
                talk_shuffle(s_talk_ord_wx, FA_TALK_WX_N);
                s_talk_next_wx = 0;
            }
            return FA_TALK_WX[k][s_talk_ord_wx[s_talk_next_wx++]];
        }
    }

    const uint8_t sc = fa_scene();
    const bool has = (sc < FA_DEST_COUNT);

    if (has && sc != (uint8_t)s_talk_scene) {
        // 换了一处风景：当地池子重洗，并把「该说当地那句」提上来 ——
        //   刚换完风景第一句就是当地的话，读起来才像「猫真到了那儿」。
        talk_shuffle(s_talk_ord_scene, FA_TALK_SCENE_N);
        s_talk_next_scene = 0;
        s_talk_scene      = (int)sc;
        s_talk_turn       = true;
    }

    const bool scene_turn = has && s_talk_turn;

    if (scene_turn) {
        if (s_talk_next_scene >= FA_TALK_SCENE_N) {
            talk_shuffle(s_talk_ord_scene, FA_TALK_SCENE_N);
            s_talk_next_scene = 0;
        }
        return FA_TALK_SCENE[sc][s_talk_ord_scene[s_talk_next_scene++]];
    }

    if (s_talk_next_base >= FA_TALK_BASE_N) {
        talk_shuffle(s_talk_ord_base, FA_TALK_BASE_N);
        s_talk_next_base = 0;
    }
    return FA_TALK_BASE[s_talk_ord_base[s_talk_next_base++]];
}

static void talk_show(void)
{
    lv_label_set_text(U.talk_lb, talk_pick());
    lv_obj_remove_flag(U.talk, LV_OBJ_FLAG_HIDDEN);   // ~~第二十五轮曾与尾巴成对放~~ 第二十六轮只剩气泡
    s_talk_on = true;
    s_talk_turn = !s_talk_turn;                 // 下一句轮到另一个池子
}

static void build_talk(void)
{
    // 216 宽、**44 高**：一行 16px 中文（行高 19）加**上下各 12px** 留白。
    // ★★★ 2026-09-20（第二十六轮）从「换皮 + 长尾巴」改成「**没有尾巴 + 压薄**」：
    //   ① 尾巴那一整段（旋转方块 + 4 条样式的设置）**删掉** ⇒ 这一屏少一个
    //      走 LVGL 临时 layer 的对象（原注释：对象 bg_opa < COVER ⇒ ARGB8888，
    //      20px 约 3KB，**每次重绘都要分配/释放一次**）。现在这一屏没有任何旋转/变换对象。
    //   ② 高度 52 -> 44，`TALK_Y` 改成表达式 `TALK_BOTTOM_HOME - TALK_H`（见常量区）。
    //   ③ 字色仍是第二十五轮换上的深色 `C_TEXT` —— 白底上再写米白 0xFFF6EC 等于没写。

    // ---- ① 气泡本体（现在是**唯一**的对象，不再有「先建尾巴」这一步）----
    U.talk = mk_box(U.scr, TALK_X, TALK_Y, TALK_W, TALK_H, 0xFFFFFF, TALK_R, TALK_OPA);
    //   ⚠ 黑边必须写在 mk_box **之后** —— mk_box 内部把 border_width 清成 0。
    lv_obj_set_style_border_width(U.talk, TALK_BW, 0);
    lv_obj_set_style_border_color(U.talk, lv_color_hex(TALK_INK), 0);

    // ---- ② 文字（深色 —— 白底上再写米白就看不见了）----
    U.talk_lb = mk_label(U.talk, &fa_font_ui, C_TEXT, "");
    //   左右各留 8px 内边距 ⇒ 内宽 200px（= 一行 12 个全角字的宽度，见常量区那段）。
    //   ⚠ `TALK_LB_Y = 12` 是按**一行**算的垂直居中口诀：(44 − 19) / 2 = 12.5 ⇒ 12。
    //     这份 LVGL 没开 FLEX，label 只能顶对齐，**没有**「按内容行数自动居中」这回事；
    //     所以「一定是一行」这个前提必须由 fa_talk.c 的句子保证（≤ 12 字，含标点）。
    place(U.talk_lb, 8, TALK_LB_Y, TALK_W - 16, TALK_H - TALK_LB_Y - 4);
    lv_obj_set_style_text_align(U.talk_lb, LV_TEXT_ALIGN_CENTER, 0);
    // ★ 超长句子允许折成两行（现在 250 句都 ≤ 12 字，这一条只是兜底，别删）：
    //   默认就是 WRAP，这里写明是为了别有人顺手改成 CLIP（那会切掉半句）。
    lv_label_set_long_mode(U.talk_lb, LV_LABEL_LONG_WRAP);

    // ---- ③ 建完就收（「放」在 talk_show / 「收」在 talk_hide）----
    lv_obj_add_flag(U.talk, LV_OBJ_FLAG_HIDDEN);
}

// 一帧的推进。★ 两个池子各洗一次牌就够，放在第一次进 tick 时做（见下）。
static void talk_tick(uint32_t dt)
{
    // 洗牌只做一次。★ 用 s_talk_scene 当「洗过没有」的哨兵：初值 -1
    //   ⇒ 第一次进来必洗，且不会和任何真实风景号（0..23）撞上。
    if (s_talk_scene < 0) {
        talk_shuffle(s_talk_ord_base, FA_TALK_BASE_N);
        talk_shuffle(s_talk_ord_scene, FA_TALK_SCENE_N);
        // ★ 天气那只池子也一起洗（第四十二轮）。它和风景无关，本来可以在
        //   wx_begin 里洗，但放在这里和另外两只**并排**更好读：
        //   三只池子的第一次洗牌都在同一处，将来加第四只也不会漏。
        talk_shuffle(s_talk_ord_wx, FA_TALK_WX_N);
        s_talk_next_base  = 0;
        s_talk_next_scene = 0;
        s_talk_next_wx    = 0;
        s_talk_scene      = (int)fa_scene();     // 别忘了再走一遍「换风景」那条分支
        if (s_talk_scene >= FA_DEST_COUNT) s_talk_scene = -2;   // 在家：记一个「洗过了」的标记
        else                               s_talk_turn  = true;
    }

    // ★ 摆在哪儿：家里在猫上方（`TALK_Y = TALK_BOTTOM_HOME − TALK_H = 150`），
    //   旅行中挪到面板与底栏之间（`TALK_Y_AWAY = 236`，为什么是这三个数见常量区那段注释）。
    //   只在**变了**的时候调 lv_obj_set_y —— 它会失效一次布局，
    //   每帧无脑调一遍就是每秒 30 次无意义重排。
    //   放在 talk_gate() **之前**：这样即使这一刻被 gate 挡住（出发序列里），
    //   位置也已经摆好，等门槛放开不会先闪一下旧位置。
    // ★ 第二十六轮：这里原来还要搬尾巴（`set_pos` + `set_rotation` 两句），
    //   尾巴撤掉后**只剩这一句 set_y**。
    //   ⚠ 两个数都只是 y —— 主界面那个是表达式（下沿固定 194，高度变了它自己跟着走），
    //     所以「压高度」和「换位置」现在是同一套口径，不会再各算一遍。
    {
        const bool away = (g_fa.state == FA_AWAY);
        if (away != s_talk_away) {
            s_talk_away = away;
            lv_obj_set_y(U.talk, away ? TALK_Y_AWAY : TALK_Y);
        }
    }

    if (!talk_gate()) {
        if (s_talk_on) talk_hide();
        // ★ 离开这几秒里不攒时间：门槛一恢复，重新从「至少 5 秒」开始等，
        //   否则从收藏册一出来就立刻冒一句，像被打断。
        if (s_talk_ms < TALK_GAP_MIN) s_talk_ms = TALK_GAP_MIN;
        return;
    }

    // ★★ 2026-09-20（第四十二轮）：有天气句等着说，就把**下一句提前到最短间隔**。
    //   一次天气只有 25 秒，按正常间隔（收掉后 5~25 秒）很可能等到雨停了才轮到，
    //   那句天气话就白挂了。压到 TALK_GAP_MIN（5 秒），保证「雨一下起来，猫很快
    //   就开口」，而不是「雨都快停了猫才提一句」。
    //   ⚠ 只压上限、**不归零**：正在说的那一句让它说完，不要从中间截断 ——
    //     打断半句话比晚说 5 秒难看得多。
    if (s_wx_talk_kind >= 0 && s_talk_ms > TALK_GAP_MIN) s_talk_ms = TALK_GAP_MIN;

    s_talk_ms -= (int)dt;
    if (s_talk_ms > 0) return;

    if (s_talk_on) {
        talk_hide();
        s_talk_ms = TALK_GAP_MIN + (int)lv_rand(0, TALK_GAP_RAND);
    } else {
        talk_show();
        s_talk_ms = TALK_SHOW_MS;
    }
}

bool fa_view_card_visible(void) { return s_card_up; }
// ★ 只有出发/归来序列算「忙」。猫在家溜达不算 —— 见 seq_departing() 的说明：
//   这个函数的结果被 main.c 的按键派发直接用来「吞掉一切按键」，
//   要是把溜达也算进去，猫一走开，手柄三个键就整个失灵了。
bool fa_view_busy(void)         { return seq_departing(); }

void fa_view_sync(void)
{
    bar_refresh();
    hud_refresh();
    // ★ 原来这里是 target_refresh()（刷新「下一站 xxx」小牌子）。
    //   指定下一站已下线，换成 scene_apply() —— 它无参且幂等，
    //   正好承担「外部状态变了、把主画面同步一遍」这件事：
    //   从休眠/暂停回来、亮度或方向刚变过，都能靠它一句话搞定。
    scene_apply();
    if (s_card_up) card_fill();
}

void fa_view_start_depart(void)
{
    // 猫正在溜达 / 坐着也允许出发：它就地背上包，然后从**当前站位**往右走。
    // 不做「先走回正中再出发」—— 那要多等两秒，而且看着像卡了一下。
    if (g_fa.state != FA_HOME || s_card_up || seq_departing()) return;
    s_seq    = SEQ_PACK;
    s_seq_ms = 0;
    play_set(&s_cat_play, "cat_pack");
    bar_refresh();
}

void fa_view_card_claim(void)
{
    if (!s_card_up) return;
    s_card_up = false;
    lv_obj_add_flag(U.ov_card, LV_OBJ_FLAG_HIDDEN);
    fa_claim();
    // 刚回家先站着喘口气，别一收下卡就立刻开始溜达
    s_idle_ms = 4000 + lv_rand(0, 4000);
    bar_refresh();
    // ★ 收下卡 = 这张明信片正式到手。如果玩家正挂着别处的风景，
    //   顺手重刷一遍没坏处；不挂风景时这个调用等于什么都不做。
    scene_apply();
}

// ● **长按**在看收获卡时 = 收下这张明信片，并**立刻把它设成主页背景**。
//
// ★ 用户原话：「要加入长按直接设为背景。可以让收到之后立马设置为背景。」
//   场景：跑完一趟回来，画面上正是刚拿到的那张明信片 —— 想把它挂在家里，
//   不必先进收集册翻到它再长按，卡上直接就能办。
//
// ★★ 顺序不能反：**先 claim，再 set**。
//   fa_claim() 才会把这张写进 postcards 位图，而 fa_scene_set() 第一件事就是
//   校验那个位 —— 先设后收会被判成「这张还没到手」，风景挂不上去。
//   所以先把 dest 记进局部变量，再 claim，最后 scene_set。
//
// ★ 设不上（越界 / 校验没过）也不能把卡吞掉：该收下的照常收下，
//   只是不换风景 —— 玩家看到的是「正常收下」，而不是「按了没反应」。
//   ⚠ 这就是为什么失败分支里还要再调一次 scene_apply()：
//     fa_claim() 之后画面必须回到主页的正确样子，不能停在收获卡那一帧。
void fa_view_card_claim_bg(void)
{
    if (!s_card_up) return;

    // ★ 先记下来 —— fa_claim() 跑完之后 got_dest 就不再是「这张」了。
    const uint8_t d = g_fa.got_dest;

    s_card_up = false;
    lv_obj_add_flag(U.ov_card, LV_OBJ_FLAG_HIDDEN);
    fa_claim();
    // 刚回家先站着喘口气，别一收下卡就立刻开始溜达（和 fa_view_card_claim 一致）
    s_idle_ms = 4000 + lv_rand(0, 4000);
    bar_refresh();

    scene_apply();                       // 先把「收下」这个结果落到画面上

    if (d < FA_DEST_COUNT && fa_scene_set(d)) {
        scene_apply();                   // 再叠上「换成这张风景」这一步
        // ★★★ 2026-09-19（第十七轮）用户原话：
        //   「把"设为背景"改为"已经到XX"。」
        //   ~~「设为背景了」~~ -> **「已经到 XXXX」**。
        //   ★ 这句话与 `fa_view_dex_ok_long` 成功那一支**逐字一致**
        //     —— 两处干的是同一件事（把某处挂成主页风景），回执当然要一样；
        //     以前一处写「已经到婺源」、一处写「设为背景了」，同一动作两种说法。
        //   ⚠ 必须用 s_toast_buf：fa_view_msg() **不拷贝字符串**，
        //     传字面量以外的临时串会指向栈上（这条纪律见 s_toast_buf 的声明处）。
        //   ⚠ 不要再往这句里加「背景」两个字（第十六轮已把这条线整条拿掉）。
        snprintf(s_toast_buf, sizeof(s_toast_buf), "已经到%s", fa_dest_name(d));
        fa_view_msg(s_toast_buf);
    }
}

void fa_view_init(void)
{
    memset(&U, 0, sizeof(U));
    memset(&s_cat_play, 0, sizeof(s_cat_play));

    // ★★ 2026-09-20（第四十三轮）：**天气那几个 static 也要一起归零**。
    //   为什么这条不能省：上面那句 `memset(&U, ...)` 会把 U.wx_cv / U.wx_obj[]
    //   抹成 NULL，而天气那几个 static **不在 U 里**（它们是文件级 static，
    //   本来就是有初值的）。两者一旦不同步，就会出现「指针全空、状态却还是
    //   『正在下雨』」—— weather_tick 会照样去 lv_obj_set_pos(NULL, ...)，
    //   当场炸。现在只调用一次所以没暴露，但只要将来多一处 fa_view_init
    //   （重进界面 / 切用户 / 软件复位后重建），这就是一个必炸的坑。
    //   ★ 原则：**凡是「U 里存指针、static 里存状态」的成对变量，
    //     归零必须写在一起**，别指望有初值就安全。
    memset(s_wx_p, 0, sizeof(s_wx_p));
    memset(s_wx_play, 0, sizeof(s_wx_play));
    // ★★ 2026-09-21（第四十五轮）：雾那条通路的成对变量 —— U.wx_fog[]（在 U 里）
    //   配 s_wx_fogp[]（static）。同上，两者必须一起归零。
    //   雾比粒子那套更怕不同步：wx_fog_tick 里**没有** wx_out 那种「出界就重生」
    //   的兜底判断，它只是闷头把 x 往前加、然后 lv_obj_set_pos(U.wx_fog[i], ...)。
    //   U.wx_fog[] 是 NULL 而 s_wx_fogp[] 还有旧值时，就是一次空指针解引用。
    memset(s_wx_fogp, 0, sizeof(s_wx_fogp));
    // ★★ 2026-09-21（第四十五轮）：两格光标的成对变量。
    //   U.dex2_up_cv / U.dex2_dn_cv 刚被上面那句 memset(&U,...) 抹成 NULL，
    //   而 s_dex2_cur 不在 U 里 —— 和天气那批是同一个坑（见上面那段原则）。
    //   今天 dex2_cursor_apply() 只在 build_dex 末尾与 dex_refresh 里调，
    //   两处都晚于 build_dex()，所以 NULL 解引用不会发生；
    //   但「有初值就安全」这条理由本身不成立，还是写在这儿。
    s_dex2_cur     = 0;
    s_wx_n         = 0;
    s_wx_kind      = WX_NONE;
    s_wx_left      = 0;
    s_wx_wait      = WX_FIRST_MS;
    s_wx_talk_kind = -1;
    s_wx_ov        = false;

    s_last_clover = 0xFFFF;
    s_last_wifi   = 0xFFFFFFFF;
    s_last_batt   = -2;
    s_batt_ms     = 0;

    U.scr = lv_screen_active();
    // ★ 2026-09-19（第九轮）：屏幕底色从 C_HUD（米白）换成 C_DARK（暖黑）。
    //   底图和明信片做了 26px 圆角裁切（见 build_scene），四角露出来的就是这一层 ——
    //   米白会让四个角发亮、像图没铺满；暖黑才像「屏幕自己的圆角」。
    //   ⚠ 这是全屏唯一一处「没有任何图层盖在上面」的颜色，改之前先想清楚四角长什么样。
    lv_obj_set_style_bg_color(U.scr, lv_color_hex(C_DARK), 0);
    lv_obj_remove_flag(U.scr, LV_OBJ_FLAG_SCROLLABLE);

    build_scene();
    build_hud();
    build_bar();
    build_away();
    // ★ 第十八轮：猫咪说的话（气泡）。★ 建在 away 之后、card 之前 ——
    //   它只会在「在家且没有任何浮层」时出现，图层顺序到这里其实已经不重要，
    //   放在这一行只是让建序读起来和版面从上到下一致。
    build_talk();
    build_card();
    build_dex();
    // ★★ 2026-09-21（第四十五轮）：**设置页建在 dex 之后**。
    //   它是从收藏册「设置」那一格按 ● 进来的、盖在册子上面的**第二层**，
    //   建序 = 图层序 ⇒ 必须晚于 dex。插到 dex 之前，表现是「按了没反应」
    //   （其实开了，被册子整层压住）——不报错，而且很容易往按键那边查。
    //   ⚠ 它和下面的 menu 是**两条独立的链**，别以为有递进关系：
    //     册子 → 选择页 → 游戏（menu/mini 那条），
    //     册子 → 设置页（这条，只有一层）。
    build_set();
    // ★★ 第十六轮：选择页建在 dex 之后、mini 之前。三层的关系是**递进**的：
    //     册子（选到「小游戏」那一格）-> 选择页（挑一个游戏）-> 游戏本身。
    //   建序 = 图层序 ⇒ 选择页必须晚于 dex（要能盖住册子）、早于 mini
    //   （游戏要能盖住选择页）。插错任意一处，表现都是「上面那层看不见」。
    build_menu();
    // ★ 第十轮：小游戏建在 dex **之后** —— 它是从册子里按进去的，
    //   必须能压住册子；而下面的开场剧情要压住一切（含游戏本身）。
    //   建序 = 图层序，这条在本文件里是硬约定，别在这里图省事乱插。
    build_mini();
    build_intro();     // ★ 建在 dex/mini 之后、toast 之前：开场要压住所有界面
    build_toast();
    // ★★ 第十三轮：四角角标**建在最后** = z 序最高 —— 它必须压过上面每一层
    //   （bg_cv / travel / ov_card / ov_away / ov_dex / ov_mini / ov_intro / toast）。
    //   这条不能图省事往前挪：少压一层，那一层的直角就露出来。
    build_corners();

    s_cat_x      = CAT_X;
    s_stroll_tx  = CAT_X;
    s_sit_ms     = SIT_MIN_MS;
    s_seen_state = g_fa.state;
    s_idle_ms    = 6000;
    s_sel        = g_fa.slot;      // 选择器从存档里记的档位开始
    s_intro_page = 0;
    play_set(&s_cat_play, "cat_idle");

    // 开机时若正卡在「刚回来」（重启前没来得及收下），直接把卡补上，
    // 不重播走路 —— 重播会让玩家以为又出了一趟。
    if (g_fa.state == FA_BACK) {
        s_card_up = true;
        card_fill();
        lv_obj_remove_flag(U.ov_card, LV_OBJ_FLAG_HIDDEN);
    }
    if (g_fa.state == FA_AWAY) {
        // ★ 重启前正在路上：开机就要是「旅行中」那个样子 ——
        //   遮罩压上、旅行面板亮出来，猫的显隐交给 cat_sync()。
        travel_mask(true);
        cat_sync();
        lv_obj_remove_flag(U.ov_away, LV_OBJ_FLAG_HIDDEN);
    }

    // 电量计可能不在总线上（CW2017 未贴装的批次）—— 读不到就把这一格留空。
    // ★ 这里只决定「开机第一眼那一格空不空」，**不决定后面读不读**：
    //   真正的轮询在 fa_view_tick 里，读不到也只是把间隔放到 30 秒。
    batt_show(bsp_battery_soc());
    s_batt_ms = 0;

    dex_refresh();
    bar_refresh();
    hud_refresh();
    // ★ 开机就把存档里挂着的风景铺上（没挂就是「家」那张底图 + 猫）。
    //   放在这里而不是 build_scene() 里：build 阶段只负责**建**出图层，
    //   「该显哪一层」是运行期状态，交给 scene_apply() 一处决定，
    //   免得建的时候和后面换风景的时候是两套逻辑。
    scene_apply();

    // 开场只播一次。看完写一个 NVS 标记，之后开机直接进游戏。
    // 想再看一遍就擦掉 NVS：idf.py -p COMx erase-flash
    if (!fa_intro_done()) {
        intro_refresh();
        lv_obj_remove_flag(U.ov_intro, LV_OBJ_FLAG_HIDDEN);
    }

    // ★★ 第四十三轮：开机打一行内存账。
    //   位置在**整个 fa_view_init 的最后** —— 界面全部建完之后，也就是
    //   「常驻占用」最全的那一刻。拿它和 overlay-ON 那一行对比，
    //   就知道「打开收藏册 / 开始旅行」的那一帧到底多吃多少。
    //   ⚠ 别往前挪：挪到 build_corners() 之前，后面建的对象就没算进去。
    wx_mem_log("boot");
}

// 待机动作轮转：猫不能永远同一个循环，否则十秒就看腻了
static const char *const IDLE_POOL[5] = {
    "cat_idle", "cat_idle", "cat_read", "cat_write", "cat_eat",
};

// 走到地方「坐下」之后播的。cat_sleep 是蜷着的那一条 ——
// 读起来就是「走累了，坐下歇会儿」，正好对上实机要求的「坐下等等」。
static const char *const SIT_POOL[4] = {
    "cat_sleep", "cat_idle", "cat_read", "cat_write",
};

void fa_view_tick(uint32_t dt_ms)
{
    const uint32_t dt = dt_ms;

    // ---------------- 开场剧情 ----------------
    // 开场期间只跑剧情自己的动画，主界面整套动画停掉 ——
    // C3 没有 PSRAM，没必要在被全屏盖住的界面上白烧一遍渲染。
    if (fa_view_intro_active()) {
        play_tick(&s_intro_play, dt, U.intro_img, 260);
        return;
    }

    // ---------------- 猫咪对我说的话（第十八轮）----------------
    // ★ 放在这里（开场之后、小游戏之前）就行：它自带 talk_gate()，
    //   浮层一开就会把气泡收掉，所以不需要在上层再抄一遍判据。
    talk_tick(dt);

    // ---------------- 天气图层（第四十二轮）----------------
    // ★ 紧接着 talk_tick 调：wx_begin() 会给猫挂一句天气话，而 talk_tick 负责
    //   把那句话提前到最短间隔。这一帧先天气、下一帧气泡就轮到 —— 顺序反过来的话
    //   那句只晚一帧被加速，其实无所谓，但这样排读起来顺（先有天气，后有反应）。
    // ★ 它内部自带 overlay_busy()（和气泡共用同一份判据）：浮层一开，天气整个冻住。
    // ⚠ 开场剧情和小游戏两条路在上面就 return 了，所以那两种状态下这里根本不执行。
    weather_tick(dt);

    // ---------------- 小游戏「接猫罐头」----------------
    // ★ 和上面开场同一个道理：游戏期间整块主页都不跑（猫溜达、旅行面板、
    //   HUD、状态翻转一律跳过）。它是全屏盖住的一层，底下那些算了也看不见。
    // ⚠ 有一件事因此会**延后**到退出游戏才处理：旅行倒计时到点时
    //   FA_AWAY -> FA_BACK 的状态翻转和那段走路动画。这是可接受的 ——
    //   fa_poll() 在 main 里独立跑，存档该变的早就变了，界面补上就行；
    //   反过来在游戏中途插一段「猫从屏幕外走回来」只会更乱。
    if (s_mini_on) {
        mini_tick(dt);
        return;
    }

    // ---------------- 收藏册「小游戏 / 设置」两格上的猫（第二十二轮）----------------
    // 上格看书（cat_read）、下格用桌子（cat_write）—— 两只各一个播放器。
    //   ★ 判据用 fa_view_dex_open()：册子没开时两格本来就是 HIDDEN 的，
    //     让它们空转几个加法没有意义。
    //   ⚠ 这里**不能 return** —— 收藏册是压在主界面之上的一层，底下的主页
    //     仍然要跑（猫溜达、旅行倒计时、HUD 都在这条路上）。
    //   ★ 第二个判据「两格是不是露着」直接用**它俩自己的 HIDDEN 标志**，
    //     不去查「当前页是不是 DEX_ENTRY_PLAY」—— 那等于把 dex_refresh()
    //     那套「谁亮谁灭」的判断在这里再抄一遍，抄漏了就是静默失效。
    //     用标志本身：翻到别的明信片页 ⇒ 两格隐藏 ⇒ 动画就地停住，
    //     翻回来时从停住的那一帧接着走（不是从头开始，因为帧号没被重置）。
    if (fa_view_dex_open() && !lv_obj_has_flag(U.dex2_up_cv, LV_OBJ_FLAG_HIDDEN)) {
        play_tick(&s_dex2_up_play, dt, U.dex2_up_cat, DEX2_FRAME_MS);
        play_tick(&s_dex2_dn_play, dt, U.dex2_dn_cat, DEX2_FRAME_MS);
    }

    // ★ 2026-09-19（第五次）这一段原来跑的是「布置模式里那个闪烁的位置框」
    //   （每 420ms 翻一次 border_opa）。布置模式整块下线，这一段跟着删 ——
    //   顺带省掉每秒 20 次的样式失效重绘。

    // ---------------- 状态翻转 ----------------
    if (g_fa.state != s_seen_state) {
        s_seen_state = g_fa.state;

        if (g_fa.state == FA_AWAY) {
            // ★ 出发了：一层遮罩压暗整个画面（不是「换成夜景」，见 travel_mask）。
            //   猫由 cat_sync() 一处决定显隐 —— 这里不要再自己 add HIDDEN。
            travel_mask(true);
            cat_sync();
            lv_obj_remove_flag(U.ov_away, LV_OBJ_FLAG_HIDDEN);
            // ★★ 2026-09-19（第十一轮）：**把猫搬回画面里**。
            //   出发那一趟走完时，SEQ_WALKOUT 把 s_cat_x 停在 SCR_W(=240) ——
            //   也就是**整只猫在屏幕右外侧**。那一瞬间这个位置是对的（它出门了），
            //   可旅行中原本没有任何一段代码会把它搬回来：
            //   default 分支只认 FA_HOME，序列机里也没有第二个地方碰 s_cat_x。
            //   ⇒ 实机反馈「旅行时候动态小猫没有出现」的根因就是这一条，
            //     猫一直老老实实待在 x=240，一帧都没进过画面。
            //   （第九轮之前看不出来：那会儿旅行中铺的是带猫明信片，
            //     我们自己的猫本来就是藏着的，这个漏洞被盖住了。）
            //
            //   为什么就地归位、而不是「从左边走进来」：
            //   从左走进画面是**归来**动画（SEQ_WALKIN）的语义，用在这里
            //   会和「到点了猫从左边回家」撞成同一个画面语言。
            //   旅行中要讲的是「猫在家等着」，画面换的是遮罩与面板，
            //   猫同一时刻出现在正中、继续做它自己的动作，读起来才顺。
            s_cat_x   = CAT_X;
            s_seq     = SEQ_NONE;
            s_idle_ms = 3000 + lv_rand(0, 3000);
            play_set(&s_cat_play, "cat_idle");
        } else if (g_fa.state == FA_BACK) {
            travel_mask(false);
            lv_obj_add_flag(U.ov_away, LV_OBJ_FLAG_HIDDEN);
            cat_sync();
            // ★ 这一句是「从屏幕**左**边缘走进来」的起点（见 SEQ_WALKIN 的说明）。
            //   ⚠ 它和 SEQ_WALKOUT 结尾的 `s_cat_x = SCR_W` 是一对：
            //     出发把猫送出**右**边、归来从**左**边接回来，整套动作里猫永远往右走。
            s_cat_x  = -CAT_W;
            s_seq    = SEQ_WALKIN;
            s_seq_ms = 0;
            play_set(&s_cat_play, "cat_walk");
        } else {
            travel_mask(false);
            lv_obj_add_flag(U.ov_away, LV_OBJ_FLAG_HIDDEN);
            cat_sync();
            // ★ 站回正中，并把「下一次溜达」的计时重置。
            //   溜达途中被按下出发、一趟旅行回来之后，那个旧计时可能早就归零了，
            //   不重置的话猫刚进门就往外走，看着像没停过。
            s_cat_x   = CAT_X;
            s_seq     = SEQ_NONE;
            s_idle_ms = 4000 + lv_rand(0, 4000);
            play_set(&s_cat_play, "cat_idle");
        }
        bar_refresh();
    }

    // ---------------- 猫的动作序列 ----------------
    s_seq_ms += dt;

    switch (s_seq) {
    case SEQ_PACK:
        if (s_seq_ms >= 1400) {
            s_seq = SEQ_WALKOUT;
            s_seq_ms = 0;
            play_set(&s_cat_play, "cat_walk");
        }
        break;

    // ★★ 出门方向 = 往**右**（2026-09-17 第一轮实机反馈）。
    //   旧版是 s_cat_x -= 60*dt：猫从正中一路往左退出画面。
    //   两个问题：① 左边是小屋所在的一侧，往左走等于朝屋子退，语义上不像「去远方」；
    //   ② 猫的精灵是正面朝向（两只眼睛都朝观众），往左滑动最像「倒着退出画面」。
    //
    // ★★ 归来方向 = 从**左**往右（同一天第二轮反馈「回来的时候是从右往左退回啦」）。
    //   第一轮把归来也改成了「从右边缘退回来」，实机看着更不对 ——
    //   同一侧进、同一侧出，等于把出门那一段原路倒放，「退回」的观感反而更强。
    //   现在定成「出门往右、归来从左」：猫绕过屏幕外那一圈，从另一头重新出现，
    //   朝右走回正中。整套动作里猫**永远在往右走**，精灵又是正面朝向，
    //   所以怎么走都不像倒着退。
    case SEQ_WALKOUT:
        s_cat_x += (int32_t)(60 * dt / 1000);           // 60 px/s，向右
        if (s_cat_x >= SCR_W) {
            // ★★ 这里 s_cat_x 落在 240 = 屏幕右**外侧**（240..304 全在画面外）。
            //   它是**故意**的（猫出门了），但由此产生一条必须成对维护的约定：
            //   **谁把状态翻进 FA_AWAY，谁负责把 s_cat_x 搬回画面里** ——
            //   这一条现在写在 fa_view_tick 的 FA_AWAY 分支里（第十一轮补）。
            //   漏掉它的后果是静默的：旅行中一只猫都看不见，且不报任何错。
            s_cat_x = SCR_W;
            s_seq   = SEQ_NONE;
            fa_depart();                                // ★ 走出画面之后才开始计时
        }
        break;

    case SEQ_WALKIN:
        s_cat_x += (int32_t)(64 * dt / 1000);           // 从左边缘往右走回正中
        if (s_cat_x >= CAT_X) {
            s_cat_x  = CAT_X;
            s_seq    = SEQ_GREET;
            s_seq_ms = 0;
            play_set(&s_cat_play, (g_fa.got_souv != 255) ? "cat_carry" : "cat_wave");
        }
        break;

    case SEQ_GREET:
        if (s_seq_ms >= 900) {
            s_seq     = SEQ_NONE;
            s_card_up = true;
            card_fill();
            lv_obj_remove_flag(U.ov_card, LV_OBJ_FLAG_HIDDEN);
            bar_refresh();
        }
        break;

    // ---------------- 在家溜达 ----------------
    // ★ 实机反馈「猫咪可以左右走动，坐下等等，有些动作，不要一直停留在一个地方」。
    //   旧版只有「原地换动画」：猫从头到尾钉在 x=88，换的只是动作。
    //   现在在家闲着时，到点在「原地换个动作」和「走两步换个地方坐坐」之间二选一。
    case SEQ_STROLL: {
        int32_t dir  = (s_stroll_tx > s_cat_x) ? 1 : -1;
        int32_t step = (int32_t)((uint32_t)STROLL_SPEED * dt / 1000u);
        if (step < 1) step = 1;      // dt 很小时也得动，否则永远走不到目的地
        s_cat_x += dir * step;
        if ((dir > 0 && s_cat_x >= s_stroll_tx) ||
            (dir < 0 && s_cat_x <= s_stroll_tx)) {
            s_cat_x  = s_stroll_tx;
            s_seq    = SEQ_SIT;
            s_seq_ms = 0;
            s_sit_ms = SIT_MIN_MS + lv_rand(0, SIT_MAX_MS - SIT_MIN_MS);
            play_set(&s_cat_play, SIT_POOL[(int)lv_rand(0, 3)]);
        }
        break;
    }

    case SEQ_SIT:
        if (s_seq_ms >= s_sit_ms) {
            s_seq     = SEQ_NONE;
            s_idle_ms = 5000 + lv_rand(0, 5000);
        }
        break;

    default:
        // ★★ 2026-09-19（第十一轮）：判据从「在家」放宽到「在家**或**旅行中」。
        //   用户原话：「旅行中也换成无猫版吧，跟小猫在家的时候一样，
        //   把小猫的动态效果放上面」—— 要的就是**在家那一套**动作。
        //   所以这里不是新写一套「旅行版」，而是把同一个状态机同时开给两种状态：
        //   猫会在 STROLL_MIN..STROLL_MAX 之间溜达、走到地方坐下、轮换待机动作。
        //   位置全部落在旅行面板（底沿 170）之下、底栏（y=292）之上。
        //   ⚠ 不要为了让旅行里「安静一点」把猫在这里钉死 —— 那正好违反用户的要求。
        //   ⚠ 也不要在这里加 state 判据去禁掉 SEQ_STROLL：这一段是**唯一**
        //     推 s_stroll_tx 的地方，禁掉之后猫会永远停在 CAT_X 原地换动作，
        //     那就是第五轮之前的旧版行为，用户当时报过「不要一直停留在一个地方」。
        if (g_fa.state == FA_HOME || g_fa.state == FA_AWAY) {
            if (s_idle_ms > dt) s_idle_ms -= dt;
            else {
                // 55% 概率走两步，其余原地换个动作。
                // 目标点固定选「正中点的另一边」，保证每次真的挪了窝 ——
                // 要是纯随机取点，很可能在原点 ±10px 里来回蹭，看着像抽搐。
                // 猫的精灵全是正面朝向，所以左右走都不需要镜像翻转。
                if (lv_rand(0, 99) < 55) {
                    s_stroll_tx = (s_cat_x < CAT_X)
                                ? CAT_X + 8 + (int32_t)lv_rand(0, 72)
                                : CAT_X - 8 - (int32_t)lv_rand(0, 72);
                    if (s_stroll_tx < STROLL_MIN) s_stroll_tx = STROLL_MIN;
                    if (s_stroll_tx > STROLL_MAX) s_stroll_tx = STROLL_MAX;
                    s_seq    = SEQ_STROLL;
                    s_seq_ms = 0;
                    play_set(&s_cat_play, "cat_walk");
                } else {
                    s_idle_ms = 6000 + lv_rand(0, 6000);
                    play_set(&s_cat_play, IDLE_POOL[(int)lv_rand(0, 4)]);
                }
            }
        }
        break;
    }

    lv_obj_set_x(U.cat, s_cat_x);
    play_tick(&s_cat_play, dt, U.cat, 220);

    // ---------------- 访客已下线，这一段整块删除（见文件上方说明）----------------
    // ---------------- 云 / 波纹的漂移同样整块删除（2026-09-19 第四次改版）--------
    //   原来这里每帧推两朵云（3 / 5 px/s）和三条波纹（±8~11 px/s）。
    //   云和波纹都是程序化地景的一部分，跟着那 12 组对象一起没了；
    //   首页现在是一张静态底图 —— 想让它动起来得换一张带动画的素材，
    //   不是在这里加两行 x 偏移能解决的事（底图是**一张**图，切不开）。

    // ---------------- 旅行中面板 ----------------
    if (g_fa.state == FA_AWAY) {
        int remain = fa_remain_secs();
        uint32_t total = fa_slot_secs(g_fa.slot);
        char buf[32];
        if (remain >= 3600)
            snprintf(buf, sizeof(buf), "%d:%02d:%02d",
                     remain / 3600, (remain / 60) % 60, remain % 60);
        else
            snprintf(buf, sizeof(buf), "%02d:%02d", remain / 60, remain % 60);
        lv_label_set_text(U.away_time, buf);

        int w = 0;
        if (total > 0)
            w = (int)((uint32_t)BAR_W * (total - (uint32_t)remain) / total);
        if (w < 0) w = 0;
        if (w > BAR_W) w = BAR_W;
        lv_obj_set_width(U.away_bar_fg, w);

        // ---- 快速返回的价钱（2026-09-19）----
        // 按剩余时长计价，所以这行字会**随剩余时间往下跳档**。算一次很便宜
        // （只是个减法加几次比较），但仍然只有值真的变了才 set_text ——
        // 每帧无条件写 label 会让 LVGL 反复重排，C3 上会掉帧。
        int rc = fa_recall_cost();
        if (rc != s_last_recall_cost) {
            s_last_recall_cost = rc;
            // ★ 缓冲给足：IDF 默认把 -Wformat-truncation 当错误（-Werror=all），
            //   而编译器是按「%d 最多 11 个字符（-2147483648）」+ 这串汉字的最坏
            //   编码长度去算的 —— 我们明知 rc 只可能是 0..5 也没用，它不认。
            //   ★ 2026-09-19（第九轮）：从 64 加到 **128**。这一版多了一整行
            //     「短按进入收藏」（+1 换行 + 18 字节）和「个猫罐头」，
            //     按最坏情况算到 100 字节上下，64 已经不够了。
            //   ★★ 第四十六轮：128 -> **160**。再往上加了一整行
            //     「↑↓ 键关闭屏幕」（+1 换行 + 22 字节），最坏算到 **112** 字节 ——
            //     128 其实还压得住，但只剩 16 字节余量，下次再动这行文案就要炸。
            //     反正只是栈上多 32 字节，留够一步的余地。
            char hb[160];
            // ★ 报价要说清代价（2026-09-19 第二次改口径）。
            //   现在的规则是「花猫罐头买的道具」：明信片和纪念品**照给**，
            //   不给的是三叶草本身。
            //   ★★ 第九轮再改两处：
            //     ① 「三叶草」-> 「猫罐头」（HUD 图标整个换掉了，文案必须跟上）；
            //     ② 删掉「（不给三叶草）」那半句，补上第二行「短按进入收藏」。
            //        用户原话：「不写（不给三叶草）这句话，改为
            //        长按 花 X 个猫罐头回来，短按进入收藏」。
            //        那句「不给」是**收获卡上**才需要交代的事，旅行面板上报价就够了。
            //   ★★ 第十二轮用户点名改第二行：
            //     「旅行中界面，改一下，"短按 进入收藏，打小游戏获得猫罐头"」——
            //     把小游戏这个去处写在脸上（它是第十轮才有的，很多人不知道册子里有）。
            //     ★ 试玩档（15 秒）那一支同时改了口径：原来写「立刻回来（免费）」，
            //       现在写「无需猫罐头，立刻返回」—— 同一个意思，但和用户的说法一致，
            //       而且点出了**为什么免费**（这一档本来就不收），比「免费」更像一句解释。
            //       ⚠ 这一档免费是**既有行为**（fa_recall_cost 第一件事就是
            //         `if (fa_slot_is_trial(g_fa.slot)) return 0;`），不是本轮新加的。
            //   ★★★ 第十三轮：第二行的文案**被迫改短**。原文
            //     「短按进入收藏，打小游戏获得猫罐头」17 个字，在 tiny 13px 下要 221px，
            //     而面板只有 200px 宽 ⇒ 必然折成两行；折行后三行文字 60px，
            //     而这一格只有 52px 高 ⇒ 第三行被切掉。
            //     新文案「短按进收藏，打小游戏赚猫罐头」14 个字实测 182px，
            //     一行放得下，三个分支共用。**别再改回去**（除非同时放大这一格）。
            //   ★★★ 第四十六轮：三个分支**统一加第三行**「↑↓ 键关闭屏幕」。
            //     用户原话：「帮我在"旅行中"界面上，加一句话，↑↓键关闭屏幕」
            //     —— 这就是**旅游页面**那张按键表的第三条，原文「上下键 关闭屏幕」。
            //     ⚠ 三个分支都要加。漏一个就是「某一档看不到这句」，
            //       而且只有那一档出错（试玩档 / 免费档平时很少遇到，最难发现）。
            //     ⚠ 行数一变，U.away_hint 的高度（54）与行距（4）要跟着复核 ——
            //       3 行 53px 是这一格的上限，见 build_away 里那段记账。
            if (rc < 0)
                snprintf(hb, sizeof(hb),
                         "长按 ● 还不能召回\n短按进收藏，打小游戏赚猫罐头\n↑↓ 键关闭屏幕");
            else if (rc == 0)
                snprintf(hb, sizeof(hb),
                         "长按 ● 无需猫罐头，立刻返回\n短按进收藏，打小游戏赚猫罐头\n↑↓ 键关闭屏幕");
            else
                snprintf(hb, sizeof(hb),
                         "长按 ● 花 %d 个猫罐头回来\n短按进收藏，打小游戏赚猫罐头\n↑↓ 键关闭屏幕", rc);
            lv_label_set_text(U.away_hint, hb);
        }
    }

    // ---------------- 「新获得」闪字（第十六轮）----------------
    // ★ 闪烁 = 每 NB_BLINK_MS 翻一次相位：字的 text_opa 和三颗星的 bg_opa 一起翻。
    //   ⚠ **显隐不在这里管** —— 那是 card_fill 的事（它只在开卡那一瞬间跑一次）。
    //     两处都管必然打架：这里刚把字藏起来，card_fill 那边又放出来，
    //     表现是「刚弹出来闪一下，然后永久消失」。
    //   ⚠ 只在卡亮着时跑。卡一收（s_card_up 变 false）就停 ——
    //     否则会在一个没人看得见的对象上没完没了地做样式失效重绘，白烧帧。
    if (s_card_up && s_nb_on) {
        s_nb_ms += dt;
        if (s_nb_ms >= NB_BLINK_MS) {
            s_nb_ms = 0;
            s_nb_ph = !s_nb_ph;
            lv_obj_set_style_text_opa(U.nb_lb, s_nb_ph ? LV_OPA_COVER : LV_OPA_40, 0);
            for (int i = 0; i < 3; i++)
                lv_obj_set_style_bg_opa(U.nb_star[i],
                                        s_nb_ph ? LV_OPA_COVER : LV_OPA_30, 0);
        }
    }

    // ---------------- 提示气泡 ----------------
    if (s_toast_ms) {
        s_toast_ms = (s_toast_ms > dt) ? (s_toast_ms - dt) : 0;
        if (!s_toast_ms) lv_obj_add_flag(U.toast, LV_OBJ_FLAG_HIDDEN);
    }

    // 电量每 10 秒读一次 —— I2C 读是阻塞的，挂在每帧上会拖慢渲染。
    // ★ 读不到时改成 30 秒后再试，**不是永远不试**（见 s_batt_ok 的说明）。
    s_batt_ms += dt;
    if (s_batt_ms >= (s_batt_ok ? 10000u : 30000u)) {
        s_batt_ms = 0;
        batt_show(bsp_battery_soc());
    }

    hud_refresh();
}
